INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (8, 'hSD01-008', 'hSD01-008 はこに JP 0期生 歌 AZKi #JP #0期生 #歌 がんばれてえらい！ AZKi #JP #0th Gen #Singing You Did Great, Good Job! AZKi #JP #0期生 #歌唱 努力了真棒！ AZKi #JP #Gen 0 #Menyanyi Hebat, kamu sudah berusaha! AZKi #JP #0기생 #노래 열심히 해서 기특해! AZKi #JP #รุ่น 0 #เพลง พยายามเก่งมากเลย! AZKi #JP #0th Gen #Singing ¡Te esfuerzas y eso es genial!', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('9', 'hSD01-009', 'character', 'R', 'debut', 'hSD01/hSD01-009_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-009_R.png', 60, NULL, 1, '["null"]', 'ヒノ', 'AZKi', '{"arts":[{"cost_types":["null"],"damage":10}],"card_sets":["スタートデッキ「ときのそら＆AZKi」"],"color_codes":["green"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"And then, and then"}],"keyword":{"effect":"You may roll a die once: If the result is 4 or less, send the top card of your Cheer Deck to one of your Back holomems. If the result is 1, you may also move this holomem to the Back Position.","name":"An Expanding Map"},"name":"AZKi","tags":["#JP","#0th Gen","#Singing"]},"es":{"arts":[{"name":"Y luego y luego"}],"keyword":{"effect":"Puedes lanzar 1 dado: si sale 4 o menos, envía la carta superior de tu mazo de Cheer a 1 de tus holomen de atrás. Si sale 1, además, puedes mover este holomen a la posición de atrás.","name":"El mapa que se expande"},"name":"AZKi","tags":["#JP","#0th Gen","#Singing"]},"id":{"arts":[{"name":"Terus terus"}],"keyword":{"effect":"Kamu boleh melempar dadu 1 kali: jika hasilnya 4 atau kurang, kirim 1 kartu teratas dari Deck Cheer milikmu ke Back holomen milikmu. Jika hasilnya 1, sebagai tambahan, kamu boleh memindahkan holomen ini ke Posisi Belakang.","name":"Peta yang terbentang"},"name":"AZKi","tags":["#JP","#Gen 0","#Menyanyi"]},"ja":{"arts":[{"name":"ほいでほいで"}],"keyword":{"effect":"サイコロを1回振れる:４以下の時、自分のエールデッキの上から1枚を、自分のバックホロメンに送る。１の時、さらに、このホロメンをバックポジションに移動できる。","name":"広がる地図"},"name":"AZKi","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"name":"그러고 그러고"}],"keyword":{"effect":"주사위를 1번 굴릴 수 있다: 4 이하라면, 자신의 엘 덱 위에서 1장을 자신의 백 홀로멤에게 보낸다. 1이라면, 추가로 이 홀로멤을 백 포지션으로 이동시킬 수 있다.","name":"펼쳐지는 지도"},"name":"AZKi","tags":["#JP","#0기생","#노래"]},"tc":{"arts":[{"name":"然後然後"}],"keyword":{"effect":"可以擲1次骰子：若為4以下，將自己應援牌庫頂的1張卡，送給自己的後場Holomen。若為1，則可以再將這位Holomen移動到後場位置。","name":"展開的地圖"},"name":"AZKi","tags":["#JP","#0期生","#歌唱"]},"th":{"arts":[{"name":"แล้วก็แล้วก็"}],"keyword":{"effect":"คุณสามารถทอยลูกเต๋า 1 ครั้ง: ถ้าออก 4 หรือน้อยกว่า ให้นำการ์ด 1 ใบจากบนสุดของเด็คเยลของคุณไปติดให้แบ็กโฮโลเมนของคุณ ถ้าออก 1 เพิ่มเติม คุณสามารถย้ายโฮโลเมนนี้ไปที่ตำแหน่งแบ็กได้","name":"แผนที่ที่แผ่ขยาย"},"name":"AZKi","tags":["#JP","#รุ่น 0","#เพลง"]}}}', '{}', '139c5d435d4a8338920c08b6a4aae0d0e3e8d63ceed8ff02d63037d0c4a917d0', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
