INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('11', 'hSD01-011', 'character', 'RR', 'second', 'hSD01/hSD01-011_RR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-011_RR.png', 190, NULL, 2, '["null","null"]', 'I☆LA', 'AZKi', '{"arts":[{"cost_types":["green"],"damage":60,"special_targets":["blue"],"special_values":[50]},{"cost_types":["green","green","null"],"damage":100,"is_plus":true,"special_targets":["blue"],"special_values":[50]}],"card_sets":["スタートデッキ「ときのそら＆AZKi」"],"color_codes":["green"],"translations":{"en":{"arts":[{"effect":"When you have a holomem with 〈Tokino Sora〉 on your Stage, send the top card of your Cheer Deck to one of your holomem.","name":"SorAZ Gravity"},{"effect":"You may roll a die once: if the result is odd, this Arts gains +50. If the result is 1, additionally, this Arts gains +50.","name":"Destiny Song"}],"name":"AZKi","tags":["#JP","#0th Gen","#Singing"]},"es":{"arts":[{"effect":"Si hay un 〈Tokino Sora〉 de holomem en tu Escenario, envía la carta superior de tu Mazo de Cheer a uno de tus holomems.","name":"Gravedad SorAZ"},{"effect":"Puedes lanzar 1 dado: si sale un número impar, esta Art +50. Si sale 1, además, esta Art +50.","name":"Canción del destino"}],"name":"AZKi","tags":["#JP","#0th Gen","#Singing"]},"id":{"arts":[{"effect":"Saat ada 〈Tokino Sora〉 holomen di Stage milikmu, kirim 1 kartu teratas dari Cheer Deck milikmu kepada holomen milikmu.","name":"SorAZ Gravity"},{"effect":"Kamu boleh melempar dadu 1 kali: jika hasilnya ganjil, Arts ini +50. Jika hasilnya 1, tambahan lagi, Arts ini +50.","name":"Destiny Song"}],"name":"AZKi","tags":["#JP","#Gen 0","#Menyanyi"]},"ja":{"arts":[{"effect":"自分のステージにホロメンの〈ときのそら〉がいる時、自分のエールデッキの上から1枚を、自分のホロメンに送る。","name":"SorAZ グラビティ"},{"effect":"サイコロを1回振れる:奇数の時、このアーツ+50。１の時、さらに、このアーツ+50。","name":"デスティニーソング"}],"name":"AZKi","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"effect":"자신의 스테이지에 홀로멘의 〈토키노 소라〉가 있을 때, 자신의 에일 덱 맨 위에서 1장을 자신의 홀로멘에게 보낸다.","name":"SorAZ 그래비티"},{"effect":"주사위를 1번 굴릴 수 있다: 홀수라면, 이 아츠+50. 1이라면, 추가로 이 아츠+50.","name":"데스티니 송"}],"name":"AZKi","tags":["#JP","#0기생","#노래"]},"tc":{"arts":[{"effect":"當自己的舞台上有Holo成員的〈時乃空〉時，將自己應援牌庫頂的1張卡附加到自己的Holo成員上。","name":"SorAZ Gravity"},{"effect":"可以擲1次骰子：為奇數時，這個藝術+50。若為1，則再使這個藝術+50。","name":"Destiny Song"}],"name":"AZKi","tags":["#JP","#0期生","#歌唱"]},"th":{"arts":[{"effect":"เมื่อบนสเตจของคุณมี〈โตกิโนะ โซระ〉ของโฮโลเมนอยู่ ส่งการ์ดใบบนสุดจากเด็คพลังงานของคุณไปให้โฮโลเมนของคุณ","name":"SorAZ แรงโน้มถ่วง"},{"effect":"คุณสามารถทอยลูกเต๋า 1 ครั้งได้: ถ้าออกเลขคี่ อาร์ตนี้ +50 ถ้าออก 1 เพิ่มอีก อาร์ตนี้ +50","name":"เพลงแห่งโชคชะตา"}],"name":"AZKi","tags":["#JP","#รุ่น 0","#เพลง"]}}}', '{}', '158e06af0a7b3ffe6d30d0c22dac03a9a209f0246687dbc48632d6c9725bdf8e', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
