INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (12, 'hSD01-012', 'hSD01-012 ID ID1期生 絵 アイラニ・イオフィフティーン #ID #ID1期生 #絵 お絵かきたのしー！ 一緒にお絵かき！ 自分のアーカイブの[白エールか緑エール]1枚を自分のセンターホロメンに送れる。 Airani Iofifteen #ID #ID 1st Gen #Art Drawing Is So Fun! Let''s Draw Together! You may send 1 [White Cheer or Green Cheer] from your Archive to your Center holomem. 艾拉妮・伊歐菲芙汀 #ID #ID1期生 #繪畫 畫畫好開心！ 一起畫畫！ 可以將自己存檔區的1張[白色應援或綠色應援]送給自己的中心Holomen。 Airani Iofifteen #ID #ID Gen 1 #Seni Menggambar itu seru! Menggambar bareng! Kamu boleh mengirim 1 kartu [Yell Putih atau Yell Hijau] dari Arsip milikmu ke Center holomen milikmu. 아이라니 이오피피틴 #ID #ID 1기생 #그림 그림 그리기 재밌어! 같이 그림 그리기! 자신의 아카이브의 [화이트 옐 또는 그린 옐] 1장을 자신의 센터 홀로멤에게 보낼 수 있다. ไอราณี ไอโอฟิฟตีน #ID #ID รุ่น 1 #ศิลปะ วาดรูปสนุกจังเลย! มาวาดรูปด้วยกัน! คุณสามารถนำ [เยลสีขาว หรือ เยลสีเขียว] 1 ใบจากอาร์ไคฟ์ของคุณไปติดให้เซ็นเตอร์โฮโลเมนของคุณ Airani Iofifteen #ID #ID 1st Gen #Art ¡Dibujar es divertidísimo! ¡Dibujemos juntas! Puedes enviar 1 [White Cheer o Green Cheer] de tu archivo a tu holomen del centro.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('15', 'hSD01-015', 'character', 'U', 'spot', 'hSD01/hSD01-015_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-015_U.png', 50, NULL, 1, '["null"]', NULL, '博衣こより', '{"arts":[{"cost_types":["null"],"damage":10}],"card_sets":["スタートデッキ「ときのそら＆AZKi」"],"color_codes":["null"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Pure Pure Pure~"}],"keyword":{"effect":"■ When collabing with 〈Tokino Sora〉, draw 1 card from your deck.\r\n■ When collabing with 〈AZKi〉, send the top card of your Cheer Deck to your Center holomem.","name":"SoAzKo"},"name":"Hakui Koyori","tags":["#JP","#Secret Society holoX","#Animal Ears"]},"es":{"arts":[{"name":"Pure pure pure～"}],"keyword":{"effect":"■ Cuando Colabora con 〈Tokino Sora〉, roba 1 carta de tu mazo.\r\n■ Cuando Colabora con 〈AZKi〉, envía la carta superior de tu mazo de Cheer a tu holomember central.","name":"SoAzKo"},"name":"Hakui Koyori","tags":["#JP","#Secret Society holoX","#Animal Ears"]},"id":{"arts":[{"name":"Pure pure pure～"}],"keyword":{"effect":"■ Saat ber-Collab dengan 〈Tokino Sora〉, tarik 1 kartu dari dekmu.\r\n■ Saat ber-Collab dengan 〈AZKi〉, kirim 1 kartu teratas dari Cheer Deck milikmu ke Center holomen milikmu.","name":"SoAzKo"},"name":"Hakui Koyori","tags":["#JP","#Organisasi Rahasia holoX","#Telinga Hewan"]},"ja":{"arts":[{"name":"ピュアピュアピュア～"}],"keyword":{"effect":"■〈ときのそら〉とコラボした時、自分のデッキを1枚引く。\r\n■〈AZKi〉とコラボした時、自分のエールデッキの上から1枚を、自分のセンターホロメンに送る。","name":"SoAzKo"},"name":"博衣こより","tags":["#JP","#秘密結社holoX","#ケモミミ"]},"ko":{"arts":[{"name":"퓨어퓨어퓨어~"}],"keyword":{"effect":"■ 〈토키노 소라〉와 콜라보했을 때, 자신의 덱을 1장 뽑는다.\r\n■ 〈AZKi〉와 콜라보했을 때, 자신의 엘 덱 맨 위에서 1장을 자신의 센터 홀로멘에게 보낸다.","name":"SoAzKo"},"name":"하쿠이 코요리","tags":["#JP","#비밀결사 holoX","#수인귀"]},"tc":{"arts":[{"name":"Pure Pure Pure～"}],"keyword":{"effect":"■當與〈時乃空〉合作時，自己抽1張牌。\r\n■當與〈AZKi〉合作時，將自己應援牌庫頂1張附加給自己的Center holomen。","name":"SoAzKo"},"name":"博衣こより","tags":["#JP","#秘密結社holoX","#獸耳"]},"th":{"arts":[{"name":"เพียวเพียวเพียว~"}],"keyword":{"effect":"■เมื่อโคลาโบกับ 〈โตกิโนะ โซระ〉 ให้จั่ว 1 ใบจากเด็คของคุณ\r\n■เมื่อโคลาโบกับ 〈AZKi〉 ให้นำการ์ดใบบนสุดของเยลเด็คของคุณส่งไปยังเซ็นเตอร์โฮโลเมนของคุณ","name":"SoAzKo"},"name":"ฮากุย โคโยริ","tags":["#JP","#องค์กรลับ holoX","#หูสัตว์"]}}}', '{}', 'f72dfe5af50a7e3105f6300be6e995a4e01b3ae3f2ae3203c7ecee58748f678f', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
