INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('22', 'hBP01-001', 'oshiCharacter', 'OSR', NULL, 'hBP01/hBP01-001_OSR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-001_OSR.png', NULL, 5, NULL, NULL, 'Hiroko', '天音かなた', '{"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["white"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Amane Kanata","oshi_skill":{"effect":"[Once per turn] Set your opponent''s Center holomem''s remaining HP to 50.","name":"Squeeze Squeeze","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] During this turn, 1 of your holomem gets +50 Arts. If that holomem''s color is white, it gets an additional +50 Arts.","name":"I''ll crush you in my grip!","timing":"Once per game"}},"es":{"name":"Amane Kanata","oshi_skill":{"effect":"[Una vez por turno] Los PS restantes del holomen central de tu oponente pasan a ser 50.","name":"Apretujón, apretujón","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Durante este turno, las artes de 1 de tus holomen obtienen +50. Si el color de ese holomen es blanco, además, esas artes obtienen +50.","name":"¡Te aplastaré con mi mano!","timing":"Una vez por partida"}},"id":{"name":"Amane Kanata","oshi_skill":{"effect":"[Sekali per giliran] Jadikan sisa HP Center Holomen lawan menjadi 50.","name":"Peluk erat erat","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per permainan] Selama giliran ini, Arts 1 holomen milikmu +50. Jika warna holomen itu putih, tambahan Arts itu +50 lagi.","name":"Akan kuhancurkan dalam genggamanku","timing":"Sekali per permainan"}},"ja":{"name":"天音かなた","oshi_skill":{"effect":"[ターンに1回]相手のセンターホロメンの残りHPを50にする。","name":"ぎゅっぎゅっ","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]このターンの間、自分のホロメン1人のアーツ+50。そのホロメンの色が白の時、さらに、そのアーツ+50。","name":"握りつぶしちゃうぞ","timing":"ゲームに1回"}},"ko":{"name":"아마네 카나타","oshi_skill":{"effect":"[턴에 1번]상대의 센터 홀로멤의 남은 HP를 50으로 한다.","name":"꼬옥꼬옥","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번]이번 턴 동안 자신의 홀로멘 1명의 아츠+50. 그 홀로멘의 색이 흰색일 때 추가로 그 아츠+50.","name":"꽉 쥐어뭉개버릴 거야","timing":"게임에 1번"}},"tc":{"name":"天音彼方","oshi_skill":{"effect":"[每回合1次]將對手Center Holomen的剩餘HP變成50。","name":"緊緊抱抱","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場對戰1次]在這個回合期間，自己的1名holomen的藝術+50。當該holomen的顏色為白色時，則再使其藝術+50。","name":"我要把你捏碎喔","timing":"每場對戰1次"}},"th":{"name":"อามาเนะ คานาตะ","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] ทำให้ HP ที่เหลือของเซ็นเตอร์โฮโลเม็มเบอร์ของฝ่ายตรงข้ามเป็น 50","name":"กอดแน่นๆ","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] ในเทิร์นนี้ อาร์ตของโฮโลเมนของคุณ 1 คน +50 ถ้าโฮโลเมนนั้นมีสีขาว อาร์ตนั้นจะ +50 เพิ่มเติม","name":"จะบีบให้แหลกเลยนะ","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{}', '612d1acff58ebd60d861c485673d11a49ff055e620599aeb363e5aa409df1cbb', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
