INSERT INTO card_sets (set_name, card_id) VALUES ('ブースターパック「ブルーミングレディアンス」', '36');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (36, 'hBP01-007', 'hBP01-007 水鈴 星街すいせい ほうき星 [ターンに1回]この推しホロメンか自分の青ホロメンが相手のバックホロメンにダメージを与えた時に使える:その相手のバックホロメン1人に特殊ダメージ50を与える。 シューティングスター [ゲームに1回]自分の青ホロメンが相手のセンターホロメンかコラボホロメンにダメージを与えた時に使える:相手のバックホロメン1人にそれと同じ数値の特殊ダメージを与える。 Hoshimachi Suisei Broom Star [Once per turn] Usable when this Oshi holomem or your blue holomem deals damage to your opponent''s Back holomem: Deal 50 special damage to 1 of those opponent''s Back holomem. Shooting Star [Once per game] Usable when your blue holomem deals damage to the opponent''s Center holomem or Collab holomem: Deal special damage equal to that amount to 1 opponent''s Back holomem. 星街彗星 掃帚星 [每回合1次]可在這位推Holo成員或自己的藍色Holo成員對對手的後台Holo成員造成傷害時使用：對該對手的1位後台Holo成員造成50特殊傷害。 流星射擊 [每場對戰1次]可在自己的藍色holomen對對手的中心holomen或合作holomen造成傷害時使用：對對手1名後台holomen造成與該數值相同的特殊傷害。 Hoshimachi Suisei Bintang Sapu [Sekali per giliran] Dapat digunakan saat oshi holomem ini atau holomem biru milikmu memberikan damage kepada Back holomem lawan: berikan 50 damage spesial kepada 1 Back holomem lawan itu. Bintang Jatuh [Sekali per permainan] Dapat digunakan saat holomen biru milikmu memberikan damage kepada holomen center atau holomen collab lawan: berikan special damage dengan nilai yang sama kepada 1 back holomen lawan. 호시마치 스이세이 빗자루별 [턴에 1번] 이 오시 홀로멘 또는 자신의 파란색 홀로멘이 상대의 백 홀로멘에게 데미지를 주었을 때 사용할 수 있다: 그 상대의 백 홀로멘 1명에게 특수 데미지 50을 준다. 슈팅 스타 [게임에 1번]자신의 파란 홀로멘이 상대의 센터 홀로멘 또는 콜라보 홀로멘에게 대미지를 주었을 때 사용할 수 있다: 상대의 백 홀로멘 1명에게 그와 같은 수치의 특수 대미지를 준다. โฮชิมาชิ สุยเซย ดาวไม้กวาด [ใช้ได้ 1 ครั้งต่อเทิร์น] ใช้ได้เมื่อโอชิโฮโลเมนนี้หรือโฮโลเมนสีน้ำเงินของคุณสร้างความเสียหายแก่แบ็กโฮโลเมนของคู่ต่อสู้: สร้างความเสียหายพิเศษ 50 แก่แบ็กโฮโลเมนของคู่ต่อสู้คนนั้น 1 คน ดาวตกพุ่ง [ใช้ได้ 1 ครั้งต่อเกม] ใช้ได้เมื่อโฮโลเมนสีน้ำเงินของคุณสร้างแดเมจให้เซ็นเตอร์โฮโลเมนหรือโคลาโบโฮโลเมนของคู่แข่ง: มอบแดเมจพิเศษจำนวนเท่ากันนั้นให้แบ็กโฮโลเมนของคู่แข่ง 1 คน Hoshimachi Suisei Estrella fugaz [Una vez por turno] Se puede usar cuando este Oshi holomen o uno de tus holomen azules haga daño a un Back holomen del oponente: inflige 50 de daño especial a ese 1 Back holomen del oponente. Estrella fugaz [Una vez por partida] Puedes usar esto cuando uno de tus holomen azules inflija daño al holomen central o al holomen de colaboración de tu oponente: inflige a 1 holomen de apoyo de tu oponente una cantidad igual de daño especial.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('37', 'hBP01-007', 'oshiCharacter', 'SEC', NULL, 'hBP01/hBP01-007_SEC', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-007_SEC.png', NULL, 5, NULL, NULL, '水鈴', '星街すいせい', '{"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["blue"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Hoshimachi Suisei","oshi_skill":{"effect":"[Once per turn] Usable when this Oshi holomem or your blue holomem deals damage to your opponent''s Back holomem: Deal 50 special damage to 1 of those opponent''s Back holomem.","name":"Broom Star","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] Usable when your blue holomem deals damage to the opponent''s Center holomem or Collab holomem: Deal special damage equal to that amount to 1 opponent''s Back holomem.","name":"Shooting Star","timing":"Once per game"}},"es":{"name":"Hoshimachi Suisei","oshi_skill":{"effect":"[Una vez por turno] Se puede usar cuando este Oshi holomen o uno de tus holomen azules haga daño a un Back holomen del oponente: inflige 50 de daño especial a ese 1 Back holomen del oponente.","name":"Estrella fugaz","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Puedes usar esto cuando uno de tus holomen azules inflija daño al holomen central o al holomen de colaboración de tu oponente: inflige a 1 holomen de apoyo de tu oponente una cantidad igual de daño especial.","name":"Estrella fugaz","timing":"Una vez por partida"}},"id":{"name":"Hoshimachi Suisei","oshi_skill":{"effect":"[Sekali per giliran] Dapat digunakan saat oshi holomem ini atau holomem biru milikmu memberikan damage kepada Back holomem lawan: berikan 50 damage spesial kepada 1 Back holomem lawan itu.","name":"Bintang Sapu","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per permainan] Dapat digunakan saat holomen biru milikmu memberikan damage kepada holomen center atau holomen collab lawan: berikan special damage dengan nilai yang sama kepada 1 back holomen lawan.","name":"Bintang Jatuh","timing":"Sekali per permainan"}},"ja":{"name":"星街すいせい","oshi_skill":{"effect":"[ターンに1回]この推しホロメンか自分の青ホロメンが相手のバックホロメンにダメージを与えた時に使える:その相手のバックホロメン1人に特殊ダメージ50を与える。","name":"ほうき星","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]自分の青ホロメンが相手のセンターホロメンかコラボホロメンにダメージを与えた時に使える:相手のバックホロメン1人にそれと同じ数値の特殊ダメージを与える。","name":"シューティングスター","timing":"ゲームに1回"}},"ko":{"name":"호시마치 스이세이","oshi_skill":{"effect":"[턴에 1번] 이 오시 홀로멘 또는 자신의 파란색 홀로멘이 상대의 백 홀로멘에게 데미지를 주었을 때 사용할 수 있다: 그 상대의 백 홀로멘 1명에게 특수 데미지 50을 준다.","name":"빗자루별","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번]자신의 파란 홀로멘이 상대의 센터 홀로멘 또는 콜라보 홀로멘에게 대미지를 주었을 때 사용할 수 있다: 상대의 백 홀로멘 1명에게 그와 같은 수치의 특수 대미지를 준다.","name":"슈팅 스타","timing":"게임에 1번"}},"tc":{"name":"星街彗星","oshi_skill":{"effect":"[每回合1次]可在這位推Holo成員或自己的藍色Holo成員對對手的後台Holo成員造成傷害時使用：對該對手的1位後台Holo成員造成50特殊傷害。","name":"掃帚星","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場對戰1次]可在自己的藍色holomen對對手的中心holomen或合作holomen造成傷害時使用：對對手1名後台holomen造成與該數值相同的特殊傷害。","name":"流星射擊","timing":"每場對戰1次"}},"th":{"name":"โฮชิมาชิ สุยเซย","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] ใช้ได้เมื่อโอชิโฮโลเมนนี้หรือโฮโลเมนสีน้ำเงินของคุณสร้างความเสียหายแก่แบ็กโฮโลเมนของคู่ต่อสู้: สร้างความเสียหายพิเศษ 50 แก่แบ็กโฮโลเมนของคู่ต่อสู้คนนั้น 1 คน","name":"ดาวไม้กวาด","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] ใช้ได้เมื่อโฮโลเมนสีน้ำเงินของคุณสร้างแดเมจให้เซ็นเตอร์โฮโลเมนหรือโคลาโบโฮโลเมนของคู่แข่ง: มอบแดเมจพิเศษจำนวนเท่ากันนั้นให้แบ็กโฮโลเมนของคู่แข่ง 1 คน","name":"ดาวตกพุ่ง","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{}', '79a07b83a383912582a4713edf8b80ec5c85274b811e59c69d35840791dc7514', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
