INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('40', 'hBP01-009', 'character', 'C', 'debut', 'hSD08/hBP01-009_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD08/hBP01-009_C.png', 90, NULL, 1, '["null"]', NULL, '天音かなた', '{"arts":[{"cost_types":["white"],"damage":40}],"card_sets":["ブースターパック「ブルーミングレディアンス」","スタートデッキ 白 天音かなた"],"color_codes":["white"],"translations":{"en":{"arts":[{"effect":"This Art can target only your opponent''s Center holomem.","name":"Konkanata~"}],"name":"Amane Kanata","tags":["#JP","#4th Gen","#Singing"]},"es":{"arts":[{"effect":"Este Arte solo puede elegir como objetivo al holomen central del oponente.","name":"¡Konkanata~!"}],"name":"Amane Kanata","tags":["#JP","#4th Gen","#Singing"]},"id":{"arts":[{"effect":"Arts ini hanya bisa menargetkan Center holomen lawan.","name":"Konkanata～"}],"name":"Amane Kanata","tags":["#JP","#Gen 4","#Menyanyi"]},"ja":{"arts":[{"effect":"このアーツは、相手のセンターホロメンしか対象にできない。","name":"こんかなた～"}],"name":"天音かなた","tags":["#JP","#4期生","#歌"]},"ko":{"arts":[{"effect":"이 아츠는 상대의 센터 홀로멘만 대상으로 할 수 있다.","name":"콘카나타~"}],"name":"아마네 카나타","tags":["#JP","#4기생","#노래"]},"tc":{"arts":[{"effect":"此藝術只能以對手的中心Holo成員為對象。","name":"Konkanata～"}],"name":"天音彼方","tags":["#JP","#4期生","#歌唱"]},"th":{"arts":[{"effect":"ศิลปะนี้สามารถเลือกเซ็นเตอร์โฮโลเมนของฝ่ายตรงข้ามเป็นเป้าหมายได้เท่านั้น","name":"คงคานาตะ~"}],"name":"อามาเนะ คานาตะ","tags":["#JP","#รุ่น 4","#เพลง"]}}}', '{}', 'aa3126c6311c5d68756a94738639c79be6b39543b80d229555774b3b1d49adcb', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
