INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (40, 'hBP01-009', 'hBP01-009 JP 4期生 歌 天音かなた #JP #4期生 #歌 こんかなた～ このアーツは、相手のセンターホロメンしか対象にできない。 Amane Kanata #JP #4th Gen #Singing Konkanata~ This Art can target only your opponent''s Center holomem. 天音彼方 #JP #4期生 #歌唱 Konkanata～ 此藝術只能以對手的中心Holo成員為對象。 Amane Kanata #JP #Gen 4 #Menyanyi Konkanata～ Arts ini hanya bisa menargetkan Center holomen lawan. 아마네 카나타 #JP #4기생 #노래 콘카나타~ 이 아츠는 상대의 센터 홀로멘만 대상으로 할 수 있다. อามาเนะ คานาตะ #JP #รุ่น 4 #เพลง คงคานาตะ~ ศิลปะนี้สามารถเลือกเซ็นเตอร์โฮโลเมนของฝ่ายตรงข้ามเป็นเป้าหมายได้เท่านั้น Amane Kanata #JP #4th Gen #Singing ¡Konkanata~! Este Arte solo puede elegir como objetivo al holomen central del oponente.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('41', 'hBP01-010', 'character', 'U', 'debut', 'hBP01/hBP01-010_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-010_U.png', 60, NULL, 1, '["null"]', 'さとうぽて', '天音かなた', '{"arts":[{"cost_types":["null"],"damage":20}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["white"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"I''m Off~"}],"keyword":{"effect":"During this turn, your Center holomem gets +10 Arts. If your Center holomem has #4th Gen, it gets +20 Arts instead.","name":"Angel on an Outing"},"name":"Amane Kanata","tags":["#JP","#4th Gen","#Singing"]},"es":{"arts":[{"name":"¡Allá voy!"}],"keyword":{"effect":"Durante este turno, las Arts de tu holomen central obtienen +10. Si tu holomen central tiene #4th Gen, además, las Arts de tu holomen central obtienen +20.","name":"Ángel de paseo"},"name":"Amane Kanata","tags":["#JP","#4th Gen","#Singing"]},"id":{"arts":[{"name":"Aku pergi duluu"}],"keyword":{"effect":"Selama giliran ini, Arts Center Holomen milikmu +10. Jika Center Holomen milikmu memiliki #Gen 4, sebagai tambahan, Arts Center Holomen milikmu +20.","name":"Malaikat yang jalan-jalan"},"name":"Amane Kanata","tags":["#JP","#Gen 4","#Menyanyi"]},"ja":{"arts":[{"name":"行ってきまーす"}],"keyword":{"effect":"このターンの間、自分のセンターホロメンのアーツ+10。自分のセンターホロメンが#4期生を持つ時、さらに、自分のセンターホロメンのアーツ+20。","name":"お出かけ天使"},"name":"天音かなた","tags":["#JP","#4期生","#歌"]},"ko":{"arts":[{"name":"다녀오겠습니다"}],"keyword":{"effect":"이번 턴 동안, 자신의 센터 홀로멘의 아츠+10. 자신의 센터 홀로멘이 #4기생를 가지고 있을 때, 추가로 자신의 센터 홀로멘의 아츠+20.","name":"외출 천사"},"name":"아마네 카나타","tags":["#JP","#4기생","#노래"]},"tc":{"arts":[{"name":"我出門啦"}],"keyword":{"effect":"本回合內，自己的中心holomen的藝能+10。若自己的中心holomen持有#4期生，則再追加自己的中心holomen的藝能+20。","name":"出遊天使"},"name":"天音彼方","tags":["#JP","#4期生","#歌唱"]},"th":{"arts":[{"name":"ไปล่ะนะ~"}],"keyword":{"effect":"จนจบเทิร์นนี้ Arts ของเซ็นเตอร์โฮโลเมนของคุณ +10 ถ้าเซ็นเตอร์โฮโลเมนของคุณมี #รุ่น 4 ให้เพิ่มอีก Arts ของเซ็นเตอร์โฮโลเมนของคุณ +20","name":"นางฟ้าออกนอกบ้าน"},"name":"อามาเนะ คานาตะ","tags":["#JP","#รุ่น 4","#เพลง"]}}}', '{}', '334bb927a88d6f1d4b08be61e78aa067dde0575ad3607e593eb8ef5a0d042350', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
