INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (44, 'hBP01-013', 'hBP01-013 須王 彩 JP 4期生 歌 天音かなた #JP #4期生 #歌 エンジェルステージ 天使のお仕事 相手のセンターホロメンに特殊ダメージ30を与える（ダウンしても相手のライフは減らない）。 Amane Kanata #JP #4th Gen #Singing Angel Stage An Angel''s Work Deal 30 special damage to your opponent''s Center holomem (even if it is downed, your opponent does not lose Life). 天音彼方 #JP #4期生 #歌唱 天使舞台 天使的工作 對對手的中心holomen造成30點特殊傷害（即使倒下，對手的生命值也不會減少）。 Amane Kanata #JP #Gen 4 #Menyanyi Angel Stage Pekerjaan malaikat Berikan 30 Special Damage kepada Center Holomen lawan (meskipun Down, Life lawan tidak berkurang). 아마네 카나타 #JP #4기생 #노래 엔젤 스테이지 천사의 일 상대의 센터 홀로멘에게 특수 대미지 30을 준다(다운되어도 상대의 라이프는 줄지 않는다). อามาเนะ คานาตะ #JP #รุ่น 4 #เพลง แองเจิลสเตจ งานของนางฟ้า มอบแดเมจพิเศษ 30 ให้แก่เซ็นเตอร์โฮโลเมนของคู่ต่อสู้ (แม้ดาวน์แล้ว Life ของคู่ต่อสู้ก็ไม่ลด) Amane Kanata #JP #4th Gen #Singing Escenario angelical Trabajo angelical Inflige 30 de daño especial al holomen central del oponente (aunque quede Fuera de combate, la Vida del oponente no disminuye).', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('45', 'hBP01-014', 'character', 'RR', 'second', 'hBP01/hBP01-014_RR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-014_RR.png', 200, NULL, 2, '["null","null"]', '須王 彩', '天音かなた', '{"arts":[{"cost_types":["white","white","white"],"damage":100,"special_targets":["red"],"special_values":[50]}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["white"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"effect":"When this Arts knocks out your opponent''s holomem, if the damage dealt exceeds its remaining HP by 50 or more, your opponent''s Life -1.","name":"♰Jet-Black Wings♰"}],"keyword":{"effect":"Deal 50 special damage to your opponent''s Center holomem.","name":"Fallen Angel"},"name":"Amane Kanata","tags":["#JP","#4th Gen","#Singing"]},"es":{"arts":[{"effect":"Cuando esta Art derribe a un holomen del oponente, si el daño infligido excedía los HP restantes por 50 o más, la Vida del oponente -1.","name":"♰Alas azabache♰"}],"keyword":{"effect":"Inflige 50 de daño especial al holomen central del oponente.","name":"Ángel caído"},"name":"Amane Kanata","tags":["#JP","#4th Gen","#Singing"]},"id":{"arts":[{"effect":"Saat Arts ini membuat holomen lawan Knock Out, jika damage yang diberikan melebihi HP tersisa sebesar 50 atau lebih, Life lawan -1.","name":"♰Sayap Hitam Legam♰"}],"keyword":{"effect":"Berikan 50 Special Damage kepada Center Holomen lawan.","name":"Malaikat yang jatuh"},"name":"Amane Kanata","tags":["#JP","#Gen 4","#Menyanyi"]},"ja":{"arts":[{"effect":"このアーツで相手のホロメンをダウンさせた時、与えたダメージが残りHPを50以上オーバーしていれば、相手のライフ-1。","name":"♰漆黒の翼♰"}],"keyword":{"effect":"相手のセンターホロメンに特殊ダメージ50を与える。","name":"堕ちた天使"},"name":"天音かなた","tags":["#JP","#4期生","#歌"]},"ko":{"arts":[{"effect":"이 아츠로 상대의 홀로멘을 다운시켰을 때, 준 대미지가 남은 HP를 50 이상 초과했다면, 상대의 라이프-1.","name":"♰칠흑의 날개♰"}],"keyword":{"effect":"상대의 센터 홀로멘에게 특수 대미지 50을 준다.","name":"타락한 천사"},"name":"아마네 카나타","tags":["#JP","#4기생","#노래"]},"tc":{"arts":[{"effect":"當以這個藝術使對手的holomen倒下時，若給予的傷害超過其剩餘HP 50以上，則對手的生命值-1。","name":"♰漆黑之翼♰"}],"keyword":{"effect":"對對手的中心holomen造成50點特殊傷害。","name":"墮天使"},"name":"天音彼方","tags":["#JP","#4期生","#歌唱"]},"th":{"arts":[{"effect":"เมื่ออาร์ตนี้ทำให้โฮโลเมนของคู่ต่อสู้ดาวน์ หากดาเมจที่สร้างเกิน HP ที่เหลืออยู่ตั้งแต่ 50 ขึ้นไป คู่ต่อสู้เสียไลฟ์ -1","name":"♰ปีกสีดำสนิท♰"}],"keyword":{"effect":"มอบแดเมจพิเศษ 50 ให้แก่เซ็นเตอร์โฮโลเมนของคู่ต่อสู้","name":"นางฟ้าตกสวรรค์"},"name":"อามาเนะ คานาตะ","tags":["#JP","#รุ่น 4","#เพลง"]}}}', '{}', '3bf302dae2a93108cb807162ce7d3021176f62de2760604618b016bfbd3a723f', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
