INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (49, 'hBP01-017', 'hBP01-017 WERI EN Promise トリ 絵 七詩ムメイ #EN #Promise #トリ #絵 一緒にお出かけ コーヒーブレイク Nanashi Mumei #EN #Promise #Bird #Art Going Out Together Coffee Break 七詩ムメイ #EN #Promise #小鳥 #繪畫 一起出門 咖啡時光 Nanashi Mumei #EN #Promise #Burung #Seni Pergi jalan bersama Coffee Break 나나시 무메이 #EN #Promise #새 #그림 같이 외출 커피 브레이크 นานาชิ มุเมอิ #EN #Promise #นก #ศิลปะ ออกไปข้างนอกด้วยกัน พักดื่มกาแฟ Nanashi Mumei #EN #Promise #Bird #Art Salir juntas Pausa para el café', '');
