INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (51, 'hBP01-019', 'hBP01-019 EN Promise トリ 絵 七詩ムメイ #EN #Promise #トリ #絵 いつも応援してくれてありがとう！ みんなと歌って踊りたい！ DebutからBloomした時、自分のデッキから、#Promiseを持つBuzz以外の[Debutホロメンか1stホロメン]1枚を公開し、手札に加える。そしてデッキをシャッフルする。 Nanashi Mumei #EN #Promise #Bird #Art Thank You for Always Supporting Me! I Want to Sing and Dance With Everyone! When Blooming from Debut, reveal 1 [Debut holomem or 1st holomem] other than Buzz with #Promise from your deck and add it to your hand. Then shuffle your deck. 七詩ムメイ #EN #Promise #小鳥 #繪畫 謝謝大家一直以來的支持！ 想和大家一起唱歌跳舞！ 從Debut Bloom時，從自己的牌庫中公開1張持有#Promise且不是Buzz的[Debut Holomen或1st Holomen]，加入手牌。然後將牌庫洗牌。 Nanashi Mumei #EN #Promise #Burung #Seni Terima kasih selalu mendukungku! Aku ingin bernyanyi dan menari bersama semua orang! Saat Bloom dari Debut, ungkapkan 1 [Debut Holomen atau 1st Holomen] selain Buzz yang memiliki #Promise dari dekmu, lalu tambahkan ke tanganmu. Lalu kocok dekmu. 나나시 무메이 #EN #Promise #새 #그림 항상 응원해줘서 고마워! 모두와 노래하고 춤추고 싶어! Debut에서 Bloom했을 때, 자신의 덱에서 #Promise를 가진 Buzz 이외의 [Debut 홀로멤 또는 1st 홀로멤] 1장을 공개하고, 손패에 넣는다. 그리고 덱을 셔플한다. นานาชิ มุเมอิ #EN #Promise #นก #ศิลปะ ขอบคุณที่คอยเชียร์กันเสมอ! อยากร้องอยากเต้นกับทุกคน! เมื่อบลูมจาก Debut ให้เปิดเผย [Debut โฮโลเมนหรือ 1st โฮโลเมน] 1 ใบที่มี #Promise และไม่ใช่ Buzz จากเด็คของคุณ แล้วนำขึ้นมือ จากนั้นสับเด็ค Nanashi Mumei #EN #Promise #Bird #Art ¡Gracias por apoyarme siempre! ¡Quiero cantar y bailar con todos! Cuando haga Bloom desde Debut, revela 1 [Debut holomen o 1st holomen] que no sea Buzz y que tenga #Promise de tu mazo, y añádelo a tu mano. Luego baraja tu mazo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('52', 'hBP01-020', 'character', 'R', 'second', 'hBP01/hBP01-020_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-020_R.png', 190, NULL, 2, '["null","null"]', '高崎律', '七詩ムメイ', '{"arts":[{"cost_types":["white","null","null"],"damage":70,"is_plus":true,"special_targets":["purple"],"special_values":[50]}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["white"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"effect":"During this turn, your Center holomem and Collab holomem get +10 Arts for each of your Back holomem.","name":"All Together Now"}],"keyword":{"effect":"Reveal 1 holomem with #Promise from your deck and add it to your hand. Then shuffle your deck.","name":"The Promise of That Day"},"name":"Nanashi Mumei","tags":["#EN","#Promise","#Bird","#Art"]},"es":{"arts":[{"effect":"Durante este turno, por cada 1 de tus holomems de la Retaguardia, los Artes de tu holomem del Centro y de tu holomem de Colaboración +10.","name":"Todos juntos"}],"keyword":{"effect":"Revela 1 holomen con #Promise de tu mazo, añádelo a tu mano y luego baraja tu mazo.","name":"La promesa de aquel día"},"name":"Nanashi Mumei","tags":["#EN","#Promise","#Bird","#Art"]},"id":{"arts":[{"effect":"Selama giliran ini, untuk tiap 1 Back holomen milikmu, Arts Center holomen dan Kolab holomen milikmu +10.","name":"Semua Bersama-sama"}],"keyword":{"effect":"Ungkapkan 1 holomen yang memiliki #Promise dari Dek milikmu, lalu tambahkan ke tanganmu. Lalu, kocok Dek milikmu.","name":"Janji pada hari itu"},"name":"Nanashi Mumei","tags":["#EN","#Promise","#Burung","#Seni"]},"ja":{"arts":[{"effect":"このターンの間、自分のバックホロメン1人につき、自分のセンターホロメンとコラボホロメンのアーツ+10。","name":"みんな一緒に"}],"keyword":{"effect":"自分のデッキから、#Promiseを持つホロメン1枚を公開し、手札に加える。そしてデッキをシャッフルする。","name":"あの日の約束"},"name":"七詩ムメイ","tags":["#EN","#Promise","#トリ","#絵"]},"ko":{"arts":[{"effect":"이번 턴 동안, 자신의 백 홀로멘 1명당 자신의 센터 홀로멘과 콜라보 홀로멘의 아츠 +10.","name":"모두 함께"}],"keyword":{"effect":"자신의 덱에서, #Promise를 가진 홀로멘 1장을 공개하고 패에 넣는다. 그 후 덱을 셔플한다.","name":"그날의 약속"},"name":"나나시 무메이","tags":["#EN","#Promise","#새","#그림"]},"tc":{"arts":[{"effect":"在本回合期間，自己每有1位後台Holo成員，自己的中心Holo成員與合作Holo成員的藝術各+10。","name":"大家一起"}],"keyword":{"effect":"從自己的牌庫公開1張持有#Promise的holomen，加入手牌。然後將牌庫洗牌。","name":"那一天的約定"},"name":"七詩ムメイ","tags":["#EN","#Promise","#小鳥","#繪畫"]},"th":{"arts":[{"effect":"ในเทิร์นนี้ ศิลปะของโฮโลเมนกลางและโฮโลเมนคอลลาบของคุณ +10 ต่อแบ็กโฮโลเมน 1 คนของคุณ","name":"ทุกคนไปด้วยกัน"}],"keyword":{"effect":"เปิดเผยโฮโลเมน 1 ใบที่มี #Promise จากเด็คของคุณ แล้วนำขึ้นมือ จากนั้นสับเด็ค","name":"สัญญาในวันนั้น"},"name":"นานาชิ มุเมอิ","tags":["#EN","#Promise","#นก","#ศิลปะ"]}}}', '{}', 'ae3eac382b78a98cbacc820f7579b906075f6ac1de2a9d5e2a3b5be10fbcfed6', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
