INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (53, 'hBP01-021', 'hBP01-021 JP 0期生 歌 ときのそら #JP #0期生 #歌 みんな～こんそめ～ Tokino Sora #JP #0th Gen #Singing Hey everyone~ Konsome~ 時乃空 #JP #0期生 #歌唱 大家～空搜咩～ Tokino Sora #JP #Gen 0 #Menyanyi Semuanyaa～ konsome～ 토키노 소라 #JP #0기생 #노래 여러분~ 콘소메~ โตกิโนะ โซระ #JP #รุ่น 0 #เพลง ทุกคนน~ คงโซเมะ~ Tokino Sora #JP #0th Gen #Singing ¡Hola a todos~, consomé~!', '');
