INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (58, 'hBP01-025', 'hBP01-025 あるてら ID ID3期生 ベスティア・ゼータ #ID #ID3期生 温泉は飲まないでね！ 温泉でくつろぐ一日を Vestia Zeta #ID #ID 3rd Gen Please Don''t Drink the Hot Spring Water! A Relaxing Day at the Hot Springs Vestia Zeta #ID #ID3期生 溫泉不要喝喔！ 在溫泉悠閒度過的一天 Vestia Zeta #ID #ID Gen 3 Jangan diminum air onsennya ya! Sehari Santai di Onsen 베스티아 제타 #ID #ID 3기생 온천은 마시면 안 돼! 온천에서 느긋하게 보내는 하루를 เวสเทีย เซตา #ID #ID รุ่น 3 อย่าดื่มน้ำพุร้อนนะ! หนึ่งวันแห่งการผ่อนคลายในออนเซ็น Vestia Zeta #ID #ID 3rd Gen ¡No te bebas el onsen! Un día de relax en el onsen', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('59', 'hBP01-026', 'character', 'U', 'first', 'hBP01/hBP01-026_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-026_U.png', 110, NULL, 1, '["null"]', NULL, 'ベスティア・ゼータ', '{"arts":[{"cost_types":["null"],"damage":30}],"card_sets":["ブースターパック「ブルーミングレディアンス」","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["white"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"The Stage, Everyone—\"Mine\""}],"keyword":{"effect":"When this holomem Blooms from Debut, reveal 1 non-Buzz [Debut holomem or 1st holomem] with #ID 3rd Gen from your deck and add it to your hand. Then shuffle your deck.","name":"A New Destiny"},"name":"Vestia Zeta","tags":["#ID","#ID 3rd Gen"]},"es":{"arts":[{"name":"En el escenario, todo el mundo es «mío»"}],"keyword":{"effect":"Cuando hace Bloom desde Debut, revela 1 [Debut holomember o 1st holomember] que no sea Buzz y que tenga #ID 3rd Gen de tu mazo, y añádelo a tu mano. Después, baraja tu mazo.","name":"Un nuevo destino"},"name":"Vestia Zeta","tags":["#ID","#ID 3rd Gen"]},"id":{"arts":[{"name":"Panggung ini semuanya “milikku”"}],"keyword":{"effect":"Saat melakukan Bloom dari Debut, buka 1 kartu [Debut holomen atau 1st holomen] non-Buzz yang memiliki #ID Gen 3 dari dekmu, tambahkan ke tanganmu. Setelah itu, kocok dekmu.","name":"Takdir baru"},"name":"Vestia Zeta","tags":["#ID","#ID Gen 3"]},"ja":{"arts":[{"name":"ステージみんな「私のもの」"}],"keyword":{"effect":"DebutからBloomした時、自分のデッキから、#ID3期生を持つBuzz以外の[Debutホロメンか1stホロメン]1枚を公開し、手札に加える。そしてデッキをシャッフルする。","name":"新たな運命"},"name":"ベスティア・ゼータ","tags":["#ID","#ID3期生"]},"ko":{"arts":[{"name":"스테이지 모두 「내 것」"}],"keyword":{"effect":"Debut에서 Bloom했을 때, 자신의 덱에서 #ID 3기생를 가진 Buzz가 아닌 [Debut 홀로멘 또는 1st 홀로멘] 1장을 공개하고, 패에 넣는다. 그리고 덱을 셔플한다.","name":"새로운 운명"},"name":"베스티아 제타","tags":["#ID","#ID 3기생"]},"tc":{"arts":[{"name":"舞台和大家都是「我的東西」"}],"keyword":{"effect":"從Debut Bloom時，從自己的牌庫公開1張帶有#ID3期生、且不是Buzz的[Debut holomen或1st holomen]，加入手牌。然後將牌庫洗牌。","name":"新的命運"},"name":"Vestia Zeta","tags":["#ID","#ID3期生"]},"th":{"arts":[{"name":"บนเวที ทุกคนล้วนเป็น『ของฉัน』"}],"keyword":{"effect":"เมื่อ Bloom จาก Debut ให้อวด [Debutโฮโลเมน หรือ 1stโฮโลเมน] 1 ใบที่มี #ID รุ่น 3 และไม่ใช่ Buzz จากเด็คของคุณ แล้วนำเข้ามือ จากนั้นสับเด็ค","name":"โชคชะตาใหม่"},"name":"เวสเทีย เซตา","tags":["#ID","#ID รุ่น 3"]}}}', '{}', '7c15c25a23fa920c0f9e88fdccab7eb4ff46256d97bf0d7494a3dc834742c9b4', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
