INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (63, 'hBP01-029', 'hBP01-029 トロメラ EN Promise 歌 IRyS #EN #Promise #歌 清楚なネフィリムです！ IRyS #EN #Promise #Singing I’m a Refined Nephilim! IRyS #EN #Promise #歌唱 我是清純的 Nephilim！ IRyS #EN #Promise #Menyanyi Aku Nephilim yang anggun! IRyS #EN #Promise #노래 청초한 네피림입니다! IRyS #EN #Promise #เพลง ฉันคือเนฟิลิมผู้เรียบร้อยค่ะ! IRyS #EN #Promise #Singing ¡Soy una nefilim refinada!', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('64', 'hBP01-030', 'character', 'U', 'first', 'hBP01/hBP01-030_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-030_U.png', 110, NULL, 1, '["null"]', NULL, 'IRyS', '{"arts":[{"cost_types":["null"],"damage":40}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["white"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"I''ll sing my heart out, so watch me!"}],"keyword":{"effect":"During this turn, your [Center holomem and Collab holomem] with #Promise get +30 Arts.","name":"Let''s Wrap the Stage in Hope!"},"name":"IRyS","tags":["#EN","#Promise","#Singing"]},"es":{"arts":[{"name":"¡Voy a cantar con todas mis fuerzas, así que mírame!"}],"keyword":{"effect":"Durante este turno, las Arts de tus [holomen central y holomen de Colaboración] con #Promise obtienen +30.","name":"¡Envolvamos el escenario con esperanza!"},"name":"IRyS","tags":["#EN","#Promise","#Singing"]},"id":{"arts":[{"name":"Aku bakal nyanyi sepenuh hati, jadi lihat aku ya!"}],"keyword":{"effect":"Selama giliran ini, Arts [Center Holomen dan Collab Holomen] milikmu yang memiliki #Promise +30.","name":"Mari selimuti panggung dengan harapan!"},"name":"IRyS","tags":["#EN","#Promise","#Menyanyi"]},"ja":{"arts":[{"name":"一生懸命歌うから見ててね！"}],"keyword":{"effect":"このターンの間、自分の#Promiseを持つ[センターホロメンとコラボホロメン]のアーツ+30。","name":"ステージを希望で包もう！"},"name":"IRyS","tags":["#EN","#Promise","#歌"]},"ko":{"arts":[{"name":"열심히 노래할 테니까 봐줘!"}],"keyword":{"effect":"이번 턴 동안, 자신의 #Promise를 가진 [센터 홀로멘과 콜라보 홀로멘]의 아츠+30.","name":"스테이지를 희망으로 감싸자!"},"name":"IRyS","tags":["#EN","#Promise","#노래"]},"tc":{"arts":[{"name":"我會努力唱歌，請看著我喔！"}],"keyword":{"effect":"本回合內，自己持有#Promise的[中心holomen與合作holomen]的藝能+30。","name":"用希望包覆舞台吧！"},"name":"IRyS","tags":["#EN","#Promise","#歌唱"]},"th":{"arts":[{"name":"จะร้องสุดใจเลย คอยดูนะ!"}],"keyword":{"effect":"จนจบเทิร์นนี้ Arts ของ[เซ็นเตอร์โฮโลเมนและคอลแลบโฮโลเมน]ของคุณที่มี #Promise +30","name":"โอบเวทีนี้ด้วยความหวังกันเถอะ!"},"name":"IRyS","tags":["#EN","#Promise","#เพลง"]}}}', '{}', '6cf51036e4df393cb643811fb3d098891ad99f77fd7ba62b1676a403470264ac', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
