INSERT INTO card_tags (tag, card_id) VALUES ('歌', '64');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (64, 'hBP01-030', 'hBP01-030 EN Promise 歌 IRyS #EN #Promise #歌 一生懸命歌うから見ててね！ ステージを希望で包もう！ このターンの間、自分の#Promiseを持つ[センターホロメンとコラボホロメン]のアーツ+30。 IRyS #EN #Promise #Singing I''ll sing my heart out, so watch me! Let''s Wrap the Stage in Hope! During this turn, your [Center holomem and Collab holomem] with #Promise get +30 Arts. IRyS #EN #Promise #歌唱 我會努力唱歌，請看著我喔！ 用希望包覆舞台吧！ 本回合內，自己持有#Promise的[中心holomen與合作holomen]的藝能+30。 IRyS #EN #Promise #Menyanyi Aku bakal nyanyi sepenuh hati, jadi lihat aku ya! Mari selimuti panggung dengan harapan! Selama giliran ini, Arts [Center Holomen dan Collab Holomen] milikmu yang memiliki #Promise +30. IRyS #EN #Promise #노래 열심히 노래할 테니까 봐줘! 스테이지를 희망으로 감싸자! 이번 턴 동안, 자신의 #Promise를 가진 [센터 홀로멘과 콜라보 홀로멘]의 아츠+30. IRyS #EN #Promise #เพลง จะร้องสุดใจเลย คอยดูนะ! โอบเวทีนี้ด้วยความหวังกันเถอะ! จนจบเทิร์นนี้ Arts ของ[เซ็นเตอร์โฮโลเมนและคอลแลบโฮโลเมน]ของคุณที่มี #Promise +30 IRyS #EN #Promise #Singing ¡Voy a cantar con todas mis fuerzas, así que mírame! ¡Envolvamos el escenario con esperanza! Durante este turno, las Arts de tus [holomen central y holomen de Colaboración] con #Promise obtienen +30.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('65', 'hBP01-031', 'character', 'R', 'second', 'hBP01/hBP01-031_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-031_R.png', 200, NULL, 2, '["null","null"]', 'mizu', 'IRyS', '{"arts":[{"cost_types":["white","null","null"],"damage":50,"is_plus":true,"special_targets":["red"],"special_values":[50]}],"card_sets":["ブースターパック「ブルーミングレディアンス」","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["white"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"effect":"This Art gets +20 for each of your holomem with #Promise.","name":"The Power of Promise"}],"keyword":{"effect":"Look at your holoPower. Reveal 1 card from among it and add it to your hand. Then put the top card of your deck into your holoPower.","name":"Garden of Hope"},"name":"IRyS","tags":["#EN","#Promise","#Singing"]},"es":{"arts":[{"effect":"Por cada 1 de tus holomems con #Promise, este Arte +20.","name":"El poder de la promesa"}],"keyword":{"effect":"Mira tu Holo Power. De entre esas cartas, revela 1 y añádela a tu mano. Después, pon la carta superior de tu mazo en Holo Power.","name":"Jardín de la esperanza"},"name":"IRyS","tags":["#EN","#Promise","#Singing"]},"id":{"arts":[{"effect":"Untuk tiap 1 holomen milikmu yang memiliki #Promise, Arts ini +20.","name":"Kekuatan Janji"}],"keyword":{"effect":"Lihat Holo Power milikmu. Dari antaranya, buka 1 kartu dan tambahkan ke tanganmu. Setelah itu, jadikan 1 kartu teratas dekmu sebagai Holo Power.","name":"Taman harapan"},"name":"IRyS","tags":["#EN","#Promise","#Menyanyi"]},"ja":{"arts":[{"effect":"自分の#Promiseを持つホロメン1人につき、このアーツ+20。","name":"約束の力"}],"keyword":{"effect":"自分のホロパワーを見る。その中から1枚を公開し、手札に加える。そして自分のデッキの上から1枚をホロパワーにする。","name":"希望の庭園"},"name":"IRyS","tags":["#EN","#Promise","#歌"]},"ko":{"arts":[{"effect":"자신의 #Promise를 가진 홀로멘 1명당, 이 아츠 +20.","name":"약속의 힘"}],"keyword":{"effect":"자신의 홀로파워를 본다. 그 중에서 1장을 공개하고, 패에 넣는다. 그리고 자신의 덱 맨 위에서 1장을 홀로파워로 한다.","name":"희망의 정원"},"name":"IRyS","tags":["#EN","#Promise","#노래"]},"tc":{"arts":[{"effect":"自己每有1位持有#Promise的Holo成員，此藝術+20。","name":"約定的力量"}],"keyword":{"effect":"查看自己的Holopower。從中公開1張並加入手牌。然後將自己牌庫頂1張放入Holopower。","name":"希望的庭園"},"name":"IRyS","tags":["#EN","#Promise","#歌唱"]},"th":{"arts":[{"effect":"ศิลปะนี้ +20 ต่อโฮโลเมน 1 คนของคุณที่มี #Promise","name":"พลังแห่งคำสัญญา"}],"keyword":{"effect":"ดูโฮโลพาวเวอร์ของคุณ จากนั้นอวดการ์ด 1 ใบจากในนั้นแล้วนำเข้ามือ แล้วนำการ์ดใบบนสุดของเด็คคุณไปเป็นโฮโลพาวเวอร์","name":"สวนแห่งความหวัง"},"name":"IRyS","tags":["#EN","#Promise","#เพลง"]}}}', '{}', '64e44e3928d48656dbb0b0a837a88685f5b8efe9bd7bf835cece03fa0b15d225', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
