INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (66, 'hBP01-032', 'hBP01-032 JP 1期生 ハーフエルフ お酒 アキ・ローゼンタール #JP #1期生 #ハーフエルフ #お酒 アロ～ナ！ Aki Rosenthal #JP #1st Gen #Half-Elf #Alcohol Aro~na! 亞綺・羅森塔爾 #JP #1期生 #半精靈 #酒 阿囉～娜！ Aki Rosenthal #JP #Gen 1 #Setengah Elf #Alkohol Alo～na! 아키 로젠탈 #JP #1기생 #하프엘프 #술 아로~나! อากิ โรเซนธาล #JP #รุ่น 1 #ฮาล์ฟเยลฟ์ #แอลกอฮอล์ อาโล~น่า! Aki Rosenthal #JP #1st Gen #Half-Elf #Alcohol ¡Alo~na!', '');
