INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (67, 'hBP01-033', 'hBP01-033 安曇アキタケ JP 1期生 ハーフエルフ お酒 アキ・ローゼンタール #JP #1期生 #ハーフエルフ #お酒 アフターパーティー ヒーリングランウェイ サイコロを1回振れる:奇数の時、自分の緑ホロメン1人のHP20回復。 Aki Rosenthal #JP #1st Gen #Half-Elf #Alcohol After Party Healing Runway You may roll a die once: On an odd number, heal 20 HP from 1 of your green holomems. 亞綺・羅森塔爾 #JP #1期生 #半精靈 #酒 After Party 療癒伸展台 可以擲1次骰子：若為奇數，則自己1位綠色holomen回復20點HP。 Aki Rosenthal #JP #Gen 1 #Setengah Elf #Alkohol After Party Runway Penyembuhan Kamu boleh melempar dadu 1 kali: jika hasilnya ganjil, pulihkan 20 HP dari 1 holomen hijau milikmu. 아키 로젠탈 #JP #1기생 #하프엘프 #술 애프터 파티 힐링 런웨이 주사위를 1번 굴릴 수 있다: 홀수라면, 자신의 초록 홀로멘 1명의 HP를 20 회복한다. อากิ โรเซนธาล #JP #รุ่น 1 #ฮาล์ฟเยลฟ์ #แอลกอฮอล์ อาฟเตอร์ปาร์ตี้ Healing Runway คุณสามารถทอยลูกเต๋า 1 ครั้ง: ถ้าออกเลขคี่ ให้ฟื้นฟู HP 20 ให้โฮโลเมนสีเขียว 1 คนของคุณ Aki Rosenthal #JP #1st Gen #Half-Elf #Alcohol After Party Pasarela sanadora Puedes lanzar un dado una vez: si sale impar, cura 20 de HP a 1 de tus holomembers verdes.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('68', 'hBP01-034', 'character', 'C', 'first', 'hBP01/hBP01-034_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-034_C.png', 160, NULL, 1, '["null"]', '千種みのり', 'アキ・ローゼンタール', '{"arts":[{"cost_types":["green"],"damage":30},{"cost_types":["green","null"],"damage":50}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["green"],"translations":{"en":{"arts":[{"name":"My, my"},{"name":"Squishy Chat Time"}],"name":"Aki Rosenthal","tags":["#JP","#1st Gen","#Half-Elf","#Alcohol"]},"es":{"arts":[{"name":"Ay, ay"},{"name":"Charlita apachurrable"}],"name":"Aki Rosenthal","tags":["#JP","#1st Gen","#Half-Elf","#Alcohol"]},"id":{"arts":[{"name":"Ara ara"},{"name":"Ngobrol Mugi Mugi"}],"name":"Aki Rosenthal","tags":["#JP","#Gen 1","#Setengah Elf","#Alkohol"]},"ja":{"arts":[{"name":"あらあら"},{"name":"むぎゅむぎゅ雑談"}],"name":"アキ・ローゼンタール","tags":["#JP","#1期生","#ハーフエルフ","#お酒"]},"ko":{"arts":[{"name":"어머어머"},{"name":"꼬옥꼬옥 잡담"}],"name":"아키 로젠탈","tags":["#JP","#1기생","#하프엘프","#술"]},"tc":{"arts":[{"name":"哎呀呀"},{"name":"黏呼呼雜談"}],"name":"亞綺・羅森塔爾","tags":["#JP","#1期生","#半精靈","#酒"]},"th":{"arts":[{"name":"อุ๊ยตาย"},{"name":"เม้าท์มอยหนุบหนับ"}],"name":"อากิ โรเซนธาล","tags":["#JP","#รุ่น 1","#ฮาล์ฟเยลฟ์","#แอลกอฮอล์"]}}}', '{}', '6c1da4ceb05b503eeae713404d7a59c2b6f001026220c2bacc7f24055dfc8845', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
