INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (68, 'hBP01-034', 'hBP01-034 千種みのり JP 1期生 ハーフエルフ お酒 アキ・ローゼンタール #JP #1期生 #ハーフエルフ #お酒 あらあら むぎゅむぎゅ雑談 Aki Rosenthal #JP #1st Gen #Half-Elf #Alcohol My, my Squishy Chat Time 亞綺・羅森塔爾 #JP #1期生 #半精靈 #酒 哎呀呀 黏呼呼雜談 Aki Rosenthal #JP #Gen 1 #Setengah Elf #Alkohol Ara ara Ngobrol Mugi Mugi 아키 로젠탈 #JP #1기생 #하프엘프 #술 어머어머 꼬옥꼬옥 잡담 อากิ โรเซนธาล #JP #รุ่น 1 #ฮาล์ฟเยลฟ์ #แอลกอฮอล์ อุ๊ยตาย เม้าท์มอยหนุบหนับ Aki Rosenthal #JP #1st Gen #Half-Elf #Alcohol Ay, ay Charlita apachurrable', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('69', 'hBP01-035', 'character', 'C', 'first', 'hBP01/hBP01-035_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-035_C.png', 120, NULL, 1, '["null"]', '夏炉', 'アキ・ローゼンタール', '{"arts":[{"cost_types":["green"],"damage":40}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["green"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"When this holomem has a Tool attached, send the top card of your Cheer Deck to one of your holomem.","name":"AkiRose Fantasia"}],"keyword":{"effect":"You may attach 1 Tool card from your Archive to one of your holomems.","name":"Bremen Music Festival"},"name":"Aki Rosenthal","tags":["#JP","#1st Gen","#Half-Elf","#Alcohol"]},"es":{"arts":[{"effect":"Si este holomem tiene una Herramienta unida, envía la carta superior de tu Mazo de Cheer a uno de tus holomems.","name":"Fantasía de Akiroze"}],"keyword":{"effect":"Puedes unir 1 Herramienta de tu archivo a uno de tus holomen.","name":"Festival musical de Bremen"},"name":"Aki Rosenthal","tags":["#JP","#1st Gen","#Half-Elf","#Alcohol"]},"id":{"arts":[{"effect":"Saat holomen ini terpasang Tool, kirim 1 kartu teratas dari Cheer Deck milikmu kepada holomen milikmu.","name":"Fantasia Akiroze"}],"keyword":{"effect":"Kamu boleh memasang 1 Tool dari Arsip milikmu pada holomen milikmu.","name":"Festival Musik Bremen"},"name":"Aki Rosenthal","tags":["#JP","#Gen 1","#Setengah Elf","#Alkohol"]},"ja":{"arts":[{"effect":"このホロメンにツールが付いている時、自分のエールデッキの上から1枚を、自分のホロメンに送る。","name":"アキロゼ幻想曲"}],"keyword":{"effect":"自分のアーカイブのツール1枚を自分のホロメンに付けられる。","name":"ブレーメンの音楽祭"},"name":"アキ・ローゼンタール","tags":["#JP","#1期生","#ハーフエルフ","#お酒"]},"ko":{"arts":[{"effect":"이 홀로멘에 툴이 붙어 있을 때, 자신의 에일 덱 맨 위에서 1장을 자신의 홀로멘에게 보낸다.","name":"아키로제 환상곡"}],"keyword":{"effect":"자신의 아카이브의 툴 1장을 자신의 홀로멤에게 붙일 수 있다.","name":"브레멘 음악제"},"name":"아키 로젠탈","tags":["#JP","#1기생","#하프엘프","#술"]},"tc":{"arts":[{"effect":"當這位Holo成員附有工具時，將自己應援牌庫頂的1張卡附加到自己的Holo成員上。","name":"Akiroze幻想曲"}],"keyword":{"effect":"可以將自己存檔區的1張工具，附加給自己的Holomen。","name":"不來梅音樂祭"},"name":"亞綺・羅森塔爾","tags":["#JP","#1期生","#半精靈","#酒"]},"th":{"arts":[{"effect":"เมื่อโฮโลเมนนี้ติดเครื่องมืออยู่ ส่งการ์ดใบบนสุดจากเด็คพลังงานของคุณไปให้โฮโลเมนของคุณ","name":"Akirose Fantasia"}],"keyword":{"effect":"คุณสามารถติดเครื่องมือ 1 ใบจากอาร์ไคฟ์ของคุณให้โฮโลเมนของคุณ","name":"เทศกาลดนตรีแห่งเบรเมน"},"name":"อากิ โรเซนธาล","tags":["#JP","#รุ่น 1","#ฮาล์ฟเยลฟ์","#แอลกอฮอล์"]}}}', '{}', 'fe68a99509b467fda56ba98a5c6119cc89f3eac0adcf7557c1516ea19697c8f3', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
