INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (70, 'hBP01-036', 'hBP01-036 JP 1期生 ハーフエルフ お酒 アキ・ローゼンタール #JP #1期生 #ハーフエルフ #お酒 今日もがんばローゼ！ ロゼ隊のみんな応援しててね！ 自分のホロメン1人のHP20回復。 Aki Rosenthal #JP #1st Gen #Half-Elf #Alcohol Let''s Do Our Best-Rose Today Too! Everyone, cheer for Rose-tai, okay! Heal 20 HP from 1 of your holomems. 亞綺・羅森塔爾 #JP #1期生 #半精靈 #酒 今天也要加油薔薇！ 請大家為Rose-tai加油喔！ 自己的1位holomen回復HP20。 Aki Rosenthal #JP #Gen 1 #Setengah Elf #Alkohol Hari ini juga semangat, rose! Semuanya, dukung Tim Rose ya! Pulihkan 20 HP 1 holomen milikmu. 아키 로젠탈 #JP #1기생 #하프엘프 #술 오늘도 힘내로제! 로제대의 모두들 응원해줘! 자신의 홀로멘 1명의 HP를 20 회복한다. อากิ โรเซนธาล #JP #รุ่น 1 #ฮาล์ฟเยลฟ์ #แอลกอฮอล์ วันนี้ก็สู้ไปพร้อมโรเซ่! ทุกคนของ ทีมโรเซ่ ช่วยเชียร์กันด้วยนะ! ฟื้นฟู HP 20 ให้โฮโลเมนของคุณ 1 คน Aki Rosenthal #JP #1st Gen #Half-Elf #Alcohol ¡Hoy también, a darlo todo, Rose! ¡Todos, apoyen a Rose-tai, ¿sí?! Cura 20 HP a 1 de tus holomen.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('71', 'hBP01-037', 'character', 'R', 'second', 'hBP01/hBP01-037_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-037_R.png', 190, NULL, 2, '["null","null"]', 'りんけてん', 'アキ・ローゼンタール', '{"arts":[{"cost_types":["green","green","green"],"damage":70,"is_plus":true,"special_targets":["white"],"special_values":[50]}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["green"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"If a Tool is attached to this holomem, this Art gets +50.","name":"Secret Spare Key"}],"keyword":{"effect":"Send the top card of your Cheer Deck to one of your holomems. Then, if this holomem has a Tool attached to it, heal 40 HP from this holomem.","name":"Gothic Doll"},"name":"Aki Rosenthal","tags":["#JP","#1st Gen","#Half-Elf","#Alcohol"]},"es":{"arts":[{"effect":"Si este holomen tiene una Herramienta equipada, este Arte obtiene +50.","name":"La llave secreta"}],"keyword":{"effect":"Envía la carta superior de tu mazo de Cheer a uno de tus holomen. Después, si este holomen tiene una Herramienta unida, cura 40 HP a este holomen.","name":"Muñeca gótica"},"name":"Aki Rosenthal","tags":["#JP","#1st Gen","#Half-Elf","#Alcohol"]},"id":{"arts":[{"effect":"Saat holomen ini dipasangi Tool, Arts ini +50.","name":"Kunci Cadangan Rahasia"}],"keyword":{"effect":"Kirim 1 kartu teratas dari Deck Cheer milikmu ke holomen milikmu. Setelah itu, jika holomen ini dipasangi Tool, pulihkan 40 HP holomen ini.","name":"Boneka Gotik"},"name":"Aki Rosenthal","tags":["#JP","#Gen 1","#Setengah Elf","#Alkohol"]},"ja":{"arts":[{"effect":"このホロメンにツールが付いている時、このアーツ+50。","name":"秘密の合鍵"}],"keyword":{"effect":"自分のエールデッキの上から1枚を、自分のホロメンに送る。その後、このホロメンにツールが付いている時、このホロメンのHP40回復。","name":"ゴシックドール"},"name":"アキ・ローゼンタール","tags":["#JP","#1期生","#ハーフエルフ","#お酒"]},"ko":{"arts":[{"effect":"이 홀로멘에 툴이 붙어 있을 때, 이 아츠+50.","name":"비밀의 합열쇠"}],"keyword":{"effect":"자신의 엘 덱 위에서 1장을 자신의 홀로멤에게 보낸다. 그 후, 이 홀로멤에 툴이 붙어 있을 때, 이 홀로멤의 HP를 40 회복.","name":"고딕 돌"},"name":"아키 로젠탈","tags":["#JP","#1기생","#하프엘프","#술"]},"tc":{"arts":[{"effect":"當這位Holo成員附有工具時，此藝術+50。","name":"秘密的備用鑰匙"}],"keyword":{"effect":"將自己應援牌庫頂的1張卡送給自己的Holomen。之後，當這位Holomen附有工具時，這位Holomen回復HP40。","name":"哥德娃娃"},"name":"亞綺・羅森塔爾","tags":["#JP","#1期生","#半精靈","#酒"]},"th":{"arts":[{"effect":"เมื่อโฮโลเมนนี้ติดทูลอยู่ ศิลปะนี้ +50","name":"กุญแจสำรองลับ"}],"keyword":{"effect":"นำการ์ด 1 ใบจากบนสุดของเด็คเยลของคุณไปติดให้โฮโลเมนของคุณ จากนั้น ถ้าโฮโลเมนนี้ติดเครื่องมืออยู่ ฟื้นฟู HP 40 ให้โฮโลเมนนี้","name":"Gothic Doll"},"name":"อากิ โรเซนธาล","tags":["#JP","#รุ่น 1","#ฮาล์ฟเยลฟ์","#แอลกอฮอล์"]}}}', '{}', '3f3dadc56f4828ac8f622dc933b7cfc68a6a489484c880fdf69561f523da4d3b', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
