INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('80', 'hBP01-045', 'character', 'U', 'debut', 'hBP01/hBP01-045_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-045_U.png', 50, NULL, 1, '["null"]', '美和野らぐ', 'AZKi', '{"arts":[{"cost_types":["green"],"damage":20}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["green"],"keyword":{"type":"ギフト","type_code":"gift"},"translations":{"en":{"arts":[{"name":"With You in a Seaside Town"}],"keyword":{"effect":"While your Life is 3 or less, this holomem may Bloom into a 2nd 〈AZKi〉 from your hand, ignoring Bloom level.","name":"Overwrite"},"name":"AZKi","tags":["#JP","#0th Gen","#Singing"]},"es":{"arts":[{"name":"Contigo en la ciudad junto al mar"}],"keyword":{"effect":"Mientras tu Vida sea 3 o menos, este holomen puede hacer Bloom a un 2nd 〈AZKi〉 de tu mano ignorando el nivel de Bloom.","name":"Overwrite"},"name":"AZKi","tags":["#JP","#0th Gen","#Singing"]},"id":{"arts":[{"name":"Bersamamu di Kota Tepi Laut"}],"keyword":{"effect":"Selama Life-mu 3 atau kurang, holomen ini bisa Bloom ke 2nd 〈AZKi〉 dari tanganmu dengan mengabaikan level Bloom.","name":"Overwrite"},"name":"AZKi","tags":["#JP","#Gen 0","#Menyanyi"]},"ja":{"arts":[{"name":"海辺の街できみと"}],"keyword":{"effect":"自分のライフが3以下の間、このホロメンは、自分の手札の2nd〈AZKi〉に、Bloomレベルを無視してBloomできる。","name":"Overwrite"},"name":"AZKi","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"name":"바닷가 도시에서 너와"}],"keyword":{"effect":"자신의 라이프가 3 이하인 동안, 이 홀로멤은 자신의 패의 2nd 〈AZKi〉에 Bloom 레벨을 무시하고 Bloom할 수 있다.","name":"Overwrite"},"name":"AZKi","tags":["#JP","#0기생","#노래"]},"tc":{"arts":[{"name":"在海邊小鎮與你"}],"keyword":{"effect":"當自己的生命值為3以下時，此Holo成員可以無視Bloom等級，對自己手牌中的2nd〈AZKi〉進行Bloom。","name":"Overwrite"},"name":"AZKi","tags":["#JP","#0期生","#歌唱"]},"th":{"arts":[{"name":"กับเธอในเมืองริมทะเล"}],"keyword":{"effect":"ขณะที่ไลฟ์ของตนเองมี 3 หรือน้อยกว่า โฮโลเม็มนี้สามารถ Bloom ไปเป็น 2nd 〈AZKi〉 จากมือของตนเองได้โดยไม่สนเลเวล Bloom","name":"Overwrite"},"name":"AZKi","tags":["#JP","#รุ่น 0","#เพลง"]}}}', '{}', '911a86b9b2a7cf9888fc877a60ac14cb431384258397de0362559557f14a69c8', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
