INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (80, 'hBP01-045', 'hBP01-045 美和野らぐ JP 0期生 歌 AZKi #JP #0期生 #歌 海辺の街できみと Overwrite 自分のライフが3以下の間、このホロメンは、自分の手札の2nd〈AZKi〉に、Bloomレベルを無視してBloomできる。 AZKi #JP #0th Gen #Singing With You in a Seaside Town Overwrite While your Life is 3 or less, this holomem may Bloom into a 2nd 〈AZKi〉 from your hand, ignoring Bloom level. AZKi #JP #0期生 #歌唱 在海邊小鎮與你 Overwrite 當自己的生命值為3以下時，此Holo成員可以無視Bloom等級，對自己手牌中的2nd〈AZKi〉進行Bloom。 AZKi #JP #Gen 0 #Menyanyi Bersamamu di Kota Tepi Laut Overwrite Selama Life-mu 3 atau kurang, holomen ini bisa Bloom ke 2nd 〈AZKi〉 dari tanganmu dengan mengabaikan level Bloom. AZKi #JP #0기생 #노래 바닷가 도시에서 너와 Overwrite 자신의 라이프가 3 이하인 동안, 이 홀로멤은 자신의 패의 2nd 〈AZKi〉에 Bloom 레벨을 무시하고 Bloom할 수 있다. AZKi #JP #รุ่น 0 #เพลง กับเธอในเมืองริมทะเล Overwrite ขณะที่ไลฟ์ของตนเองมี 3 หรือน้อยกว่า โฮโลเม็มนี้สามารถ Bloom ไปเป็น 2nd 〈AZKi〉 จากมือของตนเองได้โดยไม่สนเลเวล Bloom AZKi #JP #0th Gen #Singing Contigo en la ciudad junto al mar Overwrite Mientras tu Vida sea 3 o menos, este holomen puede hacer Bloom a un 2nd 〈AZKi〉 de tu mano ignorando el nivel de Bloom.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('81', 'hBP01-046', 'character', 'C', 'first', 'hBP01/hBP01-046_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-046_C.png', 100, NULL, 1, '["null"]', NULL, 'AZKi', '{"arts":[{"cost_types":["null"],"damage":30}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["green"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"I Made It to Such a Wonderful World!"}],"keyword":{"effect":"Choose 1 to 3 Cheer on your Stage, and you may redistribute and reattach them among your holomems.","name":"Because Everyone in Pioneer Was There"},"name":"AZKi","tags":["#JP","#0th Gen","#Singing"]},"es":{"arts":[{"name":"¡He podido llegar a un mundo tan maravilloso!"}],"keyword":{"effect":"Elige de 1 a 3 Cheer de tu escenario y puedes redistribuirlos entre tus holomem cambiándolos de adjunto.","name":"Porque estaban todos los de Pioneer"},"name":"AZKi","tags":["#JP","#0th Gen","#Singing"]},"id":{"arts":[{"name":"Aku bisa datang ke dunia seindah ini!"}],"keyword":{"effect":"Pilih 1 sampai 3 Cheer di Stage milikmu, lalu kamu dapat membaginya dan memindahkannya ke holomem milikmu.","name":"Karena ada kalian semua dari Perintis"},"name":"AZKi","tags":["#JP","#Gen 0","#Menyanyi"]},"ja":{"arts":[{"name":"こんな素敵な世界に来れました！"}],"keyword":{"effect":"自分のステージのエール1～3枚を選び、自分のホロメンに割り振って付け替えられる。","name":"開拓者のみんながいたから"},"name":"AZKi","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"name":"이런 멋진 세상에 올 수 있었어요!"}],"keyword":{"effect":"자신의 스테이지의 에일 1~3장을 선택해 자신의 홀로멤에게 나누어 갈아붙일 수 있다.","name":"개척자의 모두가 있었으니까"},"name":"AZKi","tags":["#JP","#0기생","#노래"]},"tc":{"arts":[{"name":"能來到這麼美好的世界了！"}],"keyword":{"effect":"選擇自己舞台上的1～3張Cheers，可以分配後改裝到自己的Holo成員上。","name":"因為有開拓者的大家在"},"name":"AZKi","tags":["#JP","#0期生","#歌唱"]},"th":{"arts":[{"name":"ได้มาถึงโลกที่แสนวิเศษแบบนี้แล้ว!"}],"keyword":{"effect":"เลือกเยล 1 ถึง 3 ใบบนสเตจของคุณ แล้วคุณสามารถแจกจ่ายและย้ายไปติดกับโฮโลเมนของคุณใหม่ได้","name":"เพราะมีทุกคนของ ผู้บุกเบิก อยู่ด้วย"},"name":"AZKi","tags":["#JP","#รุ่น 0","#เพลง"]}}}', '{}', '7cec0f82a868ca18b671135f4832a2996f0ba1f4b33e6df050ec50f44924bccb', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
