INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (95, 'hBP01-058', 'hBP01-058 MyungYi JP 秘密結社holoX トリ お酒 鷹嶺ルイ #JP #秘密結社holoX #トリ #お酒 こんルイルイ おつルイルイ Takane Lui #JP #Secret Society holoX #Bird #Alcohol Konlui Lui Otsuluilui 鷹嶺露依 #JP #秘密結社holoX #小鳥 #酒 Kon Luilui OtsuLuilui Takane Lui #JP #Organisasi Rahasia holoX #Burung #Alkohol Konrui Rui Otsuruirui 타카네 루이 #JP #비밀결사 holoX #새 #술 콘루이루이 오츠루이루이 ทาคาเนะ รุย #JP #องค์กรลับ holoX #นก #แอลกอฮอล์ คงลุยลุย โอตสึลุยลุย Takane Lui #JP #Secret Society holoX #Bird #Alcohol ¡Konrurui! ¡Otsururui!', '');
