INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (99, 'hBP01-062', 'hBP01-062 EN Myth トリ 小鳥遊キアラ #EN #Myth #トリ キッケリキー！ 自分の手札1枚をアーカイブできる:このアーツ+20。 Takanashi Kiara #EN #Myth #Bird Cock-a-doodle-doo! You may archive 1 card from your hand: This Art gets +20. 小鳥遊琪亞拉 #EN #Myth #小鳥 咯咯啼！ 可將自己的1張手牌存檔：此藝術+20。 Takanashi Kiara #EN #Myth #Burung Kikeriki! Kamu boleh mengarsipkan 1 kartu dari tanganmu: Arts ini +20. 타카나시 키아라 #EN #Myth #새 키케리키ー! 자신의 손패 1장을 아카이브할 수 있다: 이 아츠+20. ทาคานาชิ คิอาระ #EN #Myth #นก คิกเคอริคี! คุณสามารถอาร์ไคฟ์การ์ดในมือของคุณ 1 ใบได้: ศิลปะนี้ +20 Takanashi Kiara #EN #Myth #Bird ¡Kikkeriki! Puedes archivar 1 carta de tu mano: este Arte obtiene +20.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('100', 'hBP01-063', 'character', 'U', 'debut', 'hBP01/hBP01-063_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-063_U.png', 60, NULL, 1, '["null"]', 'Akizone', '小鳥遊キアラ', '{"arts":[{"cost_types":["red"],"damage":20}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["red"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Fluffy Time"}],"keyword":{"effect":"If your Center holomem has #Bird, you may archive 1 card from your hand: Reveal 1 Mascot from your deck and add it to your hand. Then shuffle your deck.","name":"Kiwawa''s Magic"},"name":"Takanashi Kiara","tags":["#EN","#Myth","#Bird"]},"es":{"arts":[{"name":"Hora de achuches"}],"keyword":{"effect":"Cuando tu holomen central tenga #Bird, puedes archivar 1 carta de tu mano: revela 1 Mascot de tu mazo y añádelo a tu mano. Luego baraja tu mazo.","name":"La magia de Kiwawa"},"name":"Takanashi Kiara","tags":["#EN","#Myth","#Bird"]},"id":{"arts":[{"name":"Waktu Mofumofu"}],"keyword":{"effect":"Saat Center Holomen milikmu memiliki #Burung, kamu boleh mengarsipkan 1 kartu dari tanganmu: ungkapkan 1 Mascot dari dekmu, lalu tambahkan ke tanganmu. Lalu kocok dekmu.","name":"Sihir Kiwawa"},"name":"Takanashi Kiara","tags":["#EN","#Myth","#Burung"]},"ja":{"arts":[{"name":"もふもふタイム"}],"keyword":{"effect":"自分のセンターホロメンが#トリを持つ時、自分の手札1枚をアーカイブできる:自分のデッキから、マスコット1枚を公開し、手札に加える。そしてデッキをシャッフルする。","name":"きわわの魔法"},"name":"小鳥遊キアラ","tags":["#EN","#Myth","#トリ"]},"ko":{"arts":[{"name":"복슬복슬 타임"}],"keyword":{"effect":"자신의 센터 홀로멤이 #새를 가질 때, 자신의 손패 1장을 아카이브할 수 있다: 자신의 덱에서 마스코트 1장을 공개하고, 손패에 넣는다. 그리고 덱을 셔플한다.","name":"키와와의 마법"},"name":"타카나시 키아라","tags":["#EN","#Myth","#새"]},"tc":{"arts":[{"name":"毛茸茸時光"}],"keyword":{"effect":"當自己的中心Holomen持有#小鳥時，可以將自己1張手牌存入檔案區：從自己的牌庫中公開1張吉祥物，加入手牌。然後將牌庫洗牌。","name":"Kiwawa的魔法"},"name":"小鳥遊琪亞拉","tags":["#EN","#Myth","#小鳥"]},"th":{"arts":[{"name":"เวลาขนฟู"}],"keyword":{"effect":"เมื่อเซ็นเตอร์โฮโลเมนของคุณมี #นก คุณสามารถอาร์ไคฟ์การ์ดในมือของคุณ 1 ใบได้: เปิดเผยมาสคอต 1 ใบจากเด็คของคุณ แล้วนำขึ้นมือ จากนั้นสับเด็ค","name":"เวทมนตร์ของคิวาวะ"},"name":"ทาคานาชิ คิอาระ","tags":["#EN","#Myth","#นก"]}}}', '{}', '98ef120f48d9edabb56e8ab51e0b8ac9d8d44ddbe29e5990255f9f2c05065560', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
