INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (101, 'hBP01-064', 'hBP01-064 スコッティ EN Myth トリ 小鳥遊キアラ #EN #Myth #トリ auf Wiedersehen! Takanashi Kiara #EN #Myth #Bird auf Wiedersehen! 小鳥遊琪亞拉 #EN #Myth #小鳥 auf Wiedersehen! Takanashi Kiara #EN #Myth #Burung auf Wiedersehen! 타카나시 키아라 #EN #Myth #새 auf Wiedersehen! ทาคานาชิ คิอาระ #EN #Myth #นก auf Wiedersehen! Takanashi Kiara #EN #Myth #Bird ¡auf Wiedersehen!', '');
