INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (103, 'hBP01-066', 'hBP01-066 タスキブ EN Myth トリ 小鳥遊キアラ #EN #Myth #トリ 不死鳥の剣姫 跪きなさい。 このホロメンに重なっているホロメン1枚をアーカイブできる:相手のコラボホロメンに特殊ダメージ40を与える。 Takanashi Kiara #EN #Myth #Bird The Phoenix Sword Princess Kneel. You may archive 1 holomem overlapping this holomem: Deal 40 special damage to the opponent''s Collab holomem. 小鳥遊琪亞拉 #EN #Myth #小鳥 不死鳥的劍姬 跪下。 可以將重疊在這位Holo成員上的1張Holo成員放入存檔區：對對手的合作Holo成員造成特殊傷害40。 Takanashi Kiara #EN #Myth #Burung Putri Pedang Phoenix Abadi Berlututlah. Kamu boleh mengarsipkan 1 kartu holomen yang ditumpuk pada holomen ini: berikan 40 damage spesial kepada Kolab holomen lawan. 타카나시 키아라 #EN #Myth #새 불사조의 검희 무릎 꿇어라. 이 홀로멘에 겹쳐져 있는 홀로멘 1장을 아카이브할 수 있다: 상대의 콜라보 홀로멘에게 특수 대미지 40을 준다. ทาคานาชิ คิอาระ #EN #Myth #นก องค์หญิงดาบหงส์อมตะ คุกเข่าซะ สามารถส่งโฮโลเมน 1 ใบที่ซ้อนอยู่บนโฮโลเมนนี้เข้าอาร์ไคฟ์ได้: สร้างความเสียหายพิเศษ 40 ให้โฮโลเมนคอลลาบของฝ่ายตรงข้าม Takanashi Kiara #EN #Myth #Bird Princesa espadachina del fénix inmortal Arrodíllate. Puedes poner en el Archivo 1 carta de holomem superpuesta a este holomem: inflige 40 de daño especial al holomem de Colaboración del oponente.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('104', 'hBP01-067', 'character', 'RR', 'second', 'hBP01/hBP01-067_RR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-067_RR.png', 200, NULL, 2, '["null","null"]', 'タスキブ', '小鳥遊キアラ', '{"arts":[{"cost_types":["red","red"],"damage":70,"special_targets":["green"],"special_values":[50]},{"cost_types":["red","red","red"],"damage":80,"is_plus":true,"special_targets":["green"],"special_values":[50]}],"card_sets":["ブースターパック「ブルーミングレディアンス」","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["red"],"translations":{"en":{"arts":[{"name":"Flame-Colored Guidance"},{"effect":"This Art gets +10 for each holomem in your Archive. Then return 6 holomem cards from your Archive to the deck and shuffle it.","name":"Majestic Phoenix"}],"name":"Takanashi Kiara","tags":["#EN","#Myth","#Bird"]},"es":{"arts":[{"name":"Guía color llama"},{"effect":"Este Arte obtiene +10 por cada holomen en tu archivo. Después, devuelve 6 holomen de tu archivo al mazo y barájalo.","name":"Fénix Majestuoso"}],"name":"Takanashi Kiara","tags":["#EN","#Myth","#Bird"]},"id":{"arts":[{"name":"Tuntunan Warna Bara"},{"effect":"Arts ini +10 untuk setiap 1 holomen di Archive-mu. Lalu, kembalikan 6 kartu holomen dari Archive-mu ke deck dan kocok.","name":"Majestic Phoenix"}],"name":"Takanashi Kiara","tags":["#EN","#Myth","#Burung"]},"ja":{"arts":[{"name":"焔色の導き"},{"effect":"自分のアーカイブのホロメン1枚につき、このアーツ+10。そして自分のアーカイブのホロメン6枚をデッキに戻してシャッフルする。","name":"マジェスティック・フェニックス"}],"name":"小鳥遊キアラ","tags":["#EN","#Myth","#トリ"]},"ko":{"arts":[{"name":"불꽃빛 인도"},{"effect":"자신의 아카이브의 홀로멘 1장당, 이 아츠+10. 그리고 자신의 아카이브의 홀로멘 6장을 덱으로 되돌리고 섞는다.","name":"마제스틱 피닉스"}],"name":"타카나시 키아라","tags":["#EN","#Myth","#새"]},"tc":{"arts":[{"name":"焰色的引導"},{"effect":"自己的存檔區每有1張Holo成員卡，此藝術+10。然後將自己存檔區的6張Holo成員卡放回牌庫並洗牌。","name":"威嚴鳳凰"}],"name":"小鳥遊琪亞拉","tags":["#EN","#Myth","#小鳥"]},"th":{"arts":[{"name":"การชี้นำสีเปลวเพลิง"},{"effect":"ศิลปะนี้ +10 ต่อโฮโลเมน 1 ใบในอาร์ไคฟ์ของคุณ จากนั้นนำโฮโลเมน 6 ใบจากอาร์ไคฟ์ของคุณกลับเข้าเด็คแล้วสับ","name":"Majestic Phoenix"}],"name":"ทาคานาชิ คิอาระ","tags":["#EN","#Myth","#นก"]}}}', '{}', '3a43513c4d3953d39f2c259d5b1811edba748a0d6b75bc896127712ff98ad7a2', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
