INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('111', 'hBP01-072', 'character', 'C', 'debut', 'hBP01/hBP01-072_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-072_C.png', 80, NULL, 1, '["null"]', NULL, 'ハコス・ベールズ', '{"arts":[{"cost_types":["null"],"damage":20}],"card_sets":["ブースターパック「ブルーミングレディアンス」","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["red"],"translations":{"en":{"arts":[{"effect":"While Red Cheer is attached to this holomem, you may roll a die once: if the result is odd, deal 20 special damage to your opponent''s collab holomem.","name":"WAZZUP!!"}],"name":"Hakos Baelz","tags":["#EN","#Promise","#Animal Ears"]},"es":{"arts":[{"effect":"Si este holomen tiene Red Cheer unido, puedes lanzar 1 dado: si sale un número impar, inflige 20 de daño especial al holomen de Colaboración del oponente.","name":"WAZZUP!!"}],"name":"Hakos Baelz","tags":["#EN","#Promise","#Animal Ears"]},"id":{"arts":[{"effect":"Saat Yell Merah terpasang pada holomen ini, kamu boleh melempar dadu 1 kali: jika hasilnya ganjil, berikan 20 damage spesial kepada holomen Kolaborasi lawan.","name":"WAZZUP!!"}],"name":"Hakos Baelz","tags":["#EN","#Promise","#Telinga Hewan"]},"ja":{"arts":[{"effect":"このホロメンに赤エールが付いている時、サイコロを1回振れる:奇数の時、相手のコラボホロメンに特殊ダメージ20を与える。","name":"WAZZUP!!"}],"name":"ハコス・ベールズ","tags":["#EN","#Promise","#ケモミミ"]},"ko":{"arts":[{"effect":"이 홀로멘에 레드 옐가 붙어 있을 때, 주사위를 1번 굴릴 수 있다: 홀수라면, 상대의 콜라보 홀로멘에게 특수 대미지 20을 준다.","name":"WAZZUP!!"}],"name":"하코스 베일즈","tags":["#EN","#Promise","#수인귀"]},"tc":{"arts":[{"effect":"當這名holomen附有紅色應援時，可以擲1次骰子：若為奇數，則對對手的Collab holomen給予特殊傷害20。","name":"WAZZUP!!"}],"name":"哈克斯・貝爾茲","tags":["#EN","#Promise","#獸耳"]},"th":{"arts":[{"effect":"เมื่อโฮโลเมนนี้ติด เยลสีแดง อยู่ คุณสามารถทอยลูกเต๋า 1 ครั้งได้: ถ้าออกเลขคี่ สร้างดาเมจพิเศษ 20 ให้โฮโลเมนคอลแลบของคู่ต่อสู้","name":"ว่าไงงง!!"}],"name":"ฮาโกส เบลส์","tags":["#EN","#Promise","#หูสัตว์"]}}}', '{}', 'b5821a5f612e4cf54442666c7991a1a83d553d05bd3022a5118cdf6fc84bdac0', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
