INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('113', 'hBP01-074', 'character', 'U', 'first', 'hBP01/hBP01-074_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-074_U.png', 90, NULL, 1, '["null"]', NULL, 'ハコス・ベールズ', '{"arts":[{"cost_types":["null"],"damage":30}],"card_sets":["ブースターパック「ブルーミングレディアンス」","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["red"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"Let the Fun Begin!"}],"keyword":{"effect":"When this holomem Blooms from a Debut, you may return 1 [Debut holomem or 1st holomem] from your Archive to your hand: If the returned card has #EN, deal 20 special damage to your opponent''s Collab holomem.","name":"The Mouse Idol Finally Arrives!"},"name":"Hakos Baelz","tags":["#EN","#Promise","#Animal Ears"]},"es":{"arts":[{"name":"¡Empieza la diversión!"}],"keyword":{"effect":"Cuando Bloom desde Debut, puedes devolver a tu mano 1 [Debut holomen o 1st holomen] de tu archivo: si la carta devuelta tiene #EN, inflige 20 de daño especial al holomen de colaboración de tu oponente.","name":"¡Por fin entra en escena la idol ratoncita!"},"name":"Hakos Baelz","tags":["#EN","#Promise","#Animal Ears"]},"id":{"arts":[{"name":"Waktu serunya dimulai!"}],"keyword":{"effect":"Saat Bloom dari Debut, kamu boleh mengembalikan 1 kartu [Debut holomen atau 1st holomen] dari Arsip milikmu ke tangan: jika kartu yang dikembalikan memiliki #EN, berikan 20 Damage Khusus pada Collab holomen lawan.","name":"Idol tikus akhirnya tampil!"},"name":"Hakos Baelz","tags":["#EN","#Promise","#Telinga Hewan"]},"ja":{"arts":[{"name":"楽しい時間の始まりだ！"}],"keyword":{"effect":"DebutからBloomした時、自分のアーカイブの[Debutホロメンか1stホロメン]1枚を手札に戻せる:戻したカードが#ENを持つ時、相手のコラボホロメンに特殊ダメージ20を与える。","name":"ネズミアイドルがいよいよ登場！"},"name":"ハコス・ベールズ","tags":["#EN","#Promise","#ケモミミ"]},"ko":{"arts":[{"name":"즐거운 시간의 시작이다!"}],"keyword":{"effect":"Debut에서 Bloom했을 때, 자신의 아카이브의 [Debut 홀로멤 또는 1st 홀로멤] 1장을 패로 되돌릴 수 있다: 되돌린 카드가 #EN를 가지고 있다면, 상대의 콜라보 홀로멤에게 특수 대미지 20을 준다.","name":"쥐 아이돌이 드디어 등장!"},"name":"하코스 베일즈","tags":["#EN","#Promise","#수인귀"]},"tc":{"arts":[{"name":"歡樂時光開始了！"}],"keyword":{"effect":"從Debut Bloom時，可以將自己存檔區的[Debut Holomen或1st Holomen]1張返回手牌：若返回的卡片持有#EN，對手的合作Holomen受到特殊傷害20。","name":"鼠鼠偶像終於登場！"},"name":"哈克斯・貝爾茲","tags":["#EN","#Promise","#獸耳"]},"th":{"arts":[{"name":"ได้เวลาเริ่มต้นช่วงเวลาสนุกแล้ว!"}],"keyword":{"effect":"เมื่อ Bloom จาก Debut คุณสามารถนำ [Debutโฮโลเมน หรือ 1stโฮโลเมน] 1 ใบจากอาร์ไคฟ์ของคุณกลับขึ้นมือ: ถ้าการ์ดที่นำกลับมี #EN ให้สร้างความเสียหายพิเศษ 20 แก่โคแลบโฮโลเมนของคู่แข่ง","name":"ไอดอลหนูใกล้จะเปิดตัวแล้ว!"},"name":"ฮาโกส เบลส์","tags":["#EN","#Promise","#หูสัตว์"]}}}', '{}', '13c8b15abd72547a82183135c4de7c3bd31dec9aad8a0338b5686a593e04ad3b', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
