INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (118, 'hBP01-079', 'hBP01-079 JP 0期生 歌 星街すいせい #JP #0期生 #歌 すいちゃんはーー今日もかわいいーー！！ あっと驚かせるから見逃さないでね！ 相手のバックホロメン1人に特殊ダメージ20を与える（ダウンしても相手のライフは減らない）。 Hoshimachi Suisei #JP #0th Gen #Singing Suichan Is—Cute Today Too—!! I''m Gonna Amaze You, So Don''t Miss It! Deal 20 special damage to 1 of your opponent''s Back holomem (your opponent does not lose Life even if it is Downed). 星街彗星 #JP #0期生 #歌唱 彗醬今天也超可愛——！！ 我會讓你大吃一驚，可別看漏囉！ 對對手1名後場holomen造成特殊傷害20（即使倒下，對手的生命值也不會減少）。 Hoshimachi Suisei #JP #Gen 0 #Menyanyi Sui-chan ituーー hari ini juga imutーー!! Aku bakal bikin kalian kaget, jadi jangan sampai kelewatan! Berikan 20 kerusakan spesial kepada 1 Back holomen lawan (meskipun Down, Life lawan tidak berkurang). 호시마치 스이세이 #JP #0기생 #노래 스이쨩은ーー 오늘도 귀여워ーー!! 깜짝 놀라게 해줄 테니 놓치지 마! 상대의 백 홀로멘 1명에게 특수 데미지 20을 준다(다운되어도 상대의 라이프는 줄지 않는다). โฮชิมาชิ สุยเซย #JP #รุ่น 0 #เพลง ซุยจังน่ะーーวันนี้ก็น่ารักอีกแล้วーー!! จะทำให้ตกใจเลย ห้ามละสายตานะ! สร้างความเสียหายพิเศษ 20 ให้แก่แบ็กโฮโลเมน 1 คนของคู่ต่อสู้ (แม้จะถูกดาวน์ ไลฟ์ของคู่ต่อสู้ก็จะไม่ลดลง) Hoshimachi Suisei #JP #0th Gen #Singing ¡¡Suichan estáーー hoy también está lindísimaーー!! ¡Voy a sorprenderte, así que no te lo pierdas! Inflige 20 de daño especial a 1 holomen de la retaguardia de tu oponente (aunque sea Derribado, la Vida de tu oponente no disminuye).', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('119', 'hBP01-080', 'character', 'R', 'first', 'hBP01/hBP01-080_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-080_R.png', 110, NULL, 1, '["null"]', 'でいりー', '星街すいせい', '{"arts":[{"cost_types":["blue","blue"],"damage":70}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["blue"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Battle Maid"}],"keyword":{"effect":"You may roll a six-sided die once: If the result is odd, Down 1 of your opponent''s Back holomems whose HP is reduced by 40 or more (your opponent does not lose Life even if it is Downed).","name":"Memories of the Snowy Mountain"},"name":"Hoshimachi Suisei","tags":["#JP","#0th Gen","#Singing"]},"es":{"arts":[{"name":"La doncella combatiente"}],"keyword":{"effect":"Puedes lanzar 1 dado: si sale impar, derriba a 1 holomem de la retaguardia del oponente cuyo HP esté reducido en 40 o más (aunque sea derribado, la vida de tu oponente no disminuye).","name":"Recuerdos de la montaña nevada"},"name":"Hoshimachi Suisei","tags":["#JP","#0th Gen","#Singing"]},"id":{"arts":[{"name":"Sang Maid Petarung"}],"keyword":{"effect":"Kamu dapat melempar dadu 1 kali: Jika hasilnya ganjil, Knock Out 1 Back holomem lawan yang HP-nya sudah berkurang 40 atau lebih (meskipun Knock Out, Life lawan tidak berkurang).","name":"Kenangan gunung bersalju"},"name":"Hoshimachi Suisei","tags":["#JP","#Gen 0","#Menyanyi"]},"ja":{"arts":[{"name":"戦うメイドさん"}],"keyword":{"effect":"サイコロを1回振れる:奇数の時、相手のHPが40以上減っているバックホロメン1人をダウンさせる（ダウンしても相手のライフは減らない）。","name":"雪山の記憶"},"name":"星街すいせい","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"name":"싸우는 메이드"}],"keyword":{"effect":"주사위를 1번 굴릴 수 있다: 홀수라면, 상대의 HP가 40 이상 줄어든 백 홀로멤 1명을 다운시킨다(다운되어도 상대의 라이프는 줄지 않는다).","name":"설산의 기억"},"name":"호시마치 스이세이","tags":["#JP","#0기생","#노래"]},"tc":{"arts":[{"name":"戰鬥女僕"}],"keyword":{"effect":"可以擲1次骰子：若為奇數，則使對手1位HP已減少40以上的Back Holo成員倒下（即使倒下，對手的生命值也不會減少）。","name":"雪山的記憶"},"name":"星街彗星","tags":["#JP","#0期生","#歌唱"]},"th":{"arts":[{"name":"เมดนักสู้"}],"keyword":{"effect":"คุณสามารถทอยลูกเต๋า 1 ครั้ง: ถ้าออกเลขคี่ ทำให้แบ็กโฮโลเมนฝ่ายตรงข้าม 1 คนที่ HP ลดลงไปแล้ว 40 ขึ้นไป ดาวน์ (แม้จะดาวน์ ฝ่ายตรงข้ามก็จะไม่เสียไลฟ์)","name":"ความทรงจำแห่งภูเขาหิมะ"},"name":"โฮชิมาชิ สุยเซย","tags":["#JP","#รุ่น 0","#เพลง"]}}}', '{}', '2074570bcdcff636f28db9b0e78f8c2e8bdc310de4ac73e8436826793e742326', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
