INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (120, 'hBP01-081', 'hBP01-081 でいりー JP 0期生 歌 星街すいせい #JP #0期生 #歌 輝く彗星 このホロメンの青エール2枚をアーカイブできる:このホロメンに重なっているホロメン1枚につき、このアーツ+60（このアーツは相手のバックホロメンも対象にできる）。 空を駆ける光 自分のエールデッキの上から1枚を、自分の青ホロメンに送る。 Hoshimachi Suisei #JP #0th Gen #Singing Shining Comet You may archive 2 Blue Cheer from this holomem: this Arts gains +60 for each holomem stacked on this holomem (this Arts can also target your opponent''s back holomems). Light Racing Across the Sky Send the top card of your Cheer Deck to your Blue holomem. 星街彗星 #JP #0期生 #歌唱 閃耀的彗星 可以將這名holomen的2張藍色應援封存：這個藝術每有1張重疊在這名holomen上的holomen，便+60（這個藝術也可以以對手的Back holomen為對象）。 奔馳天際的光 將自己應援牌庫頂的1張送給自己的藍色Holo成員。 Hoshimachi Suisei #JP #Gen 0 #Menyanyi Komet Bersinar Kamu boleh mengarsipkan 2 kartu Yell Biru dari holomen ini: untuk tiap 1 holomen yang ditumpuk pada holomen ini, Arts ini +60 (Arts ini juga dapat menargetkan Back holomen lawan). Cahaya yang melesat di langit Kirim 1 kartu teratas dari Cheer Deck-mu ke holomen birumu. 호시마치 스이세이 #JP #0기생 #노래 빛나는 혜성 이 홀로멘의 블루 옐 2장을 아카이브할 수 있다: 이 홀로멘에 겹쳐져 있는 홀로멘 1장당, 이 아츠+60(이 아츠는 상대의 백 홀로멘도 대상으로 할 수 있다). 하늘을 달리는 빛 자신의 에일 덱 위에서 1장을 자신의 청 홀로멤에게 보낸다. โฮชิมาชิ สุยเซย #JP #รุ่น 0 #เพลง ดาวหางเปล่งประกาย คุณสามารถอาร์ไคฟ์ เยลสีน้ำเงิน 2 ใบของโฮโลเมนนี้ได้: อาร์ตนี้ +60 ต่อโฮโลเมน 1 ใบที่ซ้อนอยู่บนโฮโลเมนนี้ (อาร์ตนี้สามารถเลือกแบ็กโฮโลเมนของคู่ต่อสู้เป็นเป้าหมายได้ด้วย) แสงที่โผบินบนท้องฟ้า ส่งการ์ดใบบนสุด 1 ใบจากเยลเด็คของตนเองไปยังโฮโลเม็มสีน้ำเงินของตนเอง Hoshimachi Suisei #JP #0th Gen #Singing Cometa resplandeciente Puedes archivar 2 Blue Cheer de este holomen: esta Art +60 por cada 1 holomen superpuesto a este holomen (esta Art también puede elegir como objetivo a los holomen de la Retaguardia del oponente). La luz que surca el cielo Envía la carta superior de tu mazo de Cheer a uno de tus holomen azules.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('121', 'hBP01-081', 'character', 'UR', 'second', 'hBP01/hBP01-081_UR_02', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-081_UR_02.png', 210, NULL, 2, '["null","null"]', NULL, '星街すいせい', '{"arts":[{"cost_types":["blue","blue","blue","null"],"damage":60,"is_plus":true,"special_targets":["red"],"special_values":[50]}],"card_sets":["ブースターパック「ブルーミングレディアンス」","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["blue"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"effect":"You may archive 2 Blue Cheer from this holomem: this Arts gains +60 for each holomem stacked on this holomem (this Arts can also target your opponent''s back holomems).","name":"Shining Comet"}],"keyword":{"effect":"Send the top card of your Cheer Deck to your Blue holomem.","name":"Light Racing Across the Sky"},"name":"Hoshimachi Suisei","tags":["#JP","#0th Gen","#Singing"]},"es":{"arts":[{"effect":"Puedes archivar 2 Blue Cheer de este holomen: esta Art +60 por cada 1 holomen superpuesto a este holomen (esta Art también puede elegir como objetivo a los holomen de la Retaguardia del oponente).","name":"Cometa resplandeciente"}],"keyword":{"effect":"Envía la carta superior de tu mazo de Cheer a uno de tus holomen azules.","name":"La luz que surca el cielo"},"name":"Hoshimachi Suisei","tags":["#JP","#0th Gen","#Singing"]},"id":{"arts":[{"effect":"Kamu boleh mengarsipkan 2 kartu Yell Biru dari holomen ini: untuk tiap 1 holomen yang ditumpuk pada holomen ini, Arts ini +60 (Arts ini juga dapat menargetkan Back holomen lawan).","name":"Komet Bersinar"}],"keyword":{"effect":"Kirim 1 kartu teratas dari Cheer Deck-mu ke holomen birumu.","name":"Cahaya yang melesat di langit"},"name":"Hoshimachi Suisei","tags":["#JP","#Gen 0","#Menyanyi"]},"ja":{"arts":[{"effect":"このホロメンの青エール2枚をアーカイブできる:このホロメンに重なっているホロメン1枚につき、このアーツ+60（このアーツは相手のバックホロメンも対象にできる）。","name":"輝く彗星"}],"keyword":{"effect":"自分のエールデッキの上から1枚を、自分の青ホロメンに送る。","name":"空を駆ける光"},"name":"星街すいせい","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"effect":"이 홀로멘의 블루 옐 2장을 아카이브할 수 있다: 이 홀로멘에 겹쳐져 있는 홀로멘 1장당, 이 아츠+60(이 아츠는 상대의 백 홀로멘도 대상으로 할 수 있다).","name":"빛나는 혜성"}],"keyword":{"effect":"자신의 에일 덱 위에서 1장을 자신의 청 홀로멤에게 보낸다.","name":"하늘을 달리는 빛"},"name":"호시마치 스이세이","tags":["#JP","#0기생","#노래"]},"tc":{"arts":[{"effect":"可以將這名holomen的2張藍色應援封存：這個藝術每有1張重疊在這名holomen上的holomen，便+60（這個藝術也可以以對手的Back holomen為對象）。","name":"閃耀的彗星"}],"keyword":{"effect":"將自己應援牌庫頂的1張送給自己的藍色Holo成員。","name":"奔馳天際的光"},"name":"星街彗星","tags":["#JP","#0期生","#歌唱"]},"th":{"arts":[{"effect":"คุณสามารถอาร์ไคฟ์ เยลสีน้ำเงิน 2 ใบของโฮโลเมนนี้ได้: อาร์ตนี้ +60 ต่อโฮโลเมน 1 ใบที่ซ้อนอยู่บนโฮโลเมนนี้ (อาร์ตนี้สามารถเลือกแบ็กโฮโลเมนของคู่ต่อสู้เป็นเป้าหมายได้ด้วย)","name":"ดาวหางเปล่งประกาย"}],"keyword":{"effect":"ส่งการ์ดใบบนสุด 1 ใบจากเยลเด็คของตนเองไปยังโฮโลเม็มสีน้ำเงินของตนเอง","name":"แสงที่โผบินบนท้องฟ้า"},"name":"โฮชิมาชิ สุยเซย","tags":["#JP","#รุ่น 0","#เพลง"]}}}', '{}', '1a029e4c32818e3df26db3b4222289e41fc4181b79ddd58fd9fc10d984ae4bbb', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
