INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (122, 'hBP01-082', 'hBP01-082 ID ID3期生 こぼ・かなえる #ID #ID3期生 ぼこぼこぼこぼ Kobo Kanaeru #ID #ID 3rd Gen BoKoboKoboKobo こぼ・かなえる #ID #ID3期生 我KoboKoboKobo Kobo Kanaeru #ID #ID Gen 3 boKoboKoboKobo 코보 카나에루 #ID #ID 3기생 보코보코보코보 โคโบะ คานาเอรุ #ID #ID รุ่น 3 โบโคโบโคโบโคโบ Kobo Kanaeru #ID #ID 3rd Gen boKoboKoboKobo', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('123', 'hBP01-083', 'character', 'U', 'debut', 'hBP01/hBP01-083_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-083_U.png', 70, NULL, 1, '["null"]', 'ぽんかん⑧', 'こぼ・かなえる', '{"arts":[{"cost_types":["null"]}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["blue"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"It’s a Wave~!"}],"keyword":{"effect":"If your Center holomem has #ID, you may roll a die once: If the result is 3 or higher, send the top card of your Cheer Deck to one of your holomem.","name":"Take Kobo to the Sea!"},"name":"Kobo Kanaeru","tags":["#ID","#ID 3rd Gen"]},"es":{"arts":[{"name":"¡Es una olaaa!"}],"keyword":{"effect":"Cuando tu holomen central tenga #ID, puedes lanzar un dado 1 vez: si sale 3 o más, envía la carta superior de tu mazo de Cheer a 1 de tus holomen.","name":"¡Lleva a Kobo al mar!"},"name":"Kobo Kanaeru","tags":["#ID","#ID 3rd Gen"]},"id":{"arts":[{"name":"Itu ombak～!"}],"keyword":{"effect":"Saat Center holomen milikmu memiliki #ID, kamu boleh melempar dadu 1 kali: jika hasilnya 3 atau lebih, kirim 1 kartu teratas dari Dek Elmu milikmu ke holomen milikmu.","name":"Ajak Kobo ke laut!"},"name":"Kobo Kanaeru","tags":["#ID","#ID Gen 3"]},"ja":{"arts":[{"name":"波だ～！"}],"keyword":{"effect":"自分のセンターホロメンが#IDを持つ時、サイコロを1回振れる:3以上の時、自分のエールデッキの上から1枚を、自分のホロメンに送る。","name":"こぼを海に連れて！"},"name":"こぼ・かなえる","tags":["#ID","#ID3期生"]},"ko":{"arts":[{"name":"파도다~!"}],"keyword":{"effect":"자신의 센터 홀로멘이 #ID를 가지고 있을 때, 주사위를 1번 굴릴 수 있다: 3 이상이 나오면, 자신의 엘 덱 위에서부터 1장을 자신의 홀로멘에게 보낸다.","name":"코보를 바다에 데려가!"},"name":"코보 카나에루","tags":["#ID","#ID 3기생"]},"tc":{"arts":[{"name":"是海浪～！"}],"keyword":{"effect":"當自己的中位holomen持有#ID時，可以擲1次骰子：若為3以上，則將自己應援牌庫上方1張牌送到自己的holomen。","name":"帶Kobo去海邊！"},"name":"こぼ・かなえる","tags":["#ID","#ID3期生"]},"th":{"arts":[{"name":"คลื่นมาแล้ว~!"}],"keyword":{"effect":"เมื่อเซ็นเตอร์โฮโลเมนของคุณมี #ID คุณสามารถทอยลูกเต๋าได้ 1 ครั้ง: ถ้าออก 3 ขึ้นไป ส่งการ์ด 1 ใบบนสุดของเด็คเยลของคุณไปยังโฮโลเมนของคุณ","name":"พา โคโบ ไปทะเลที!"},"name":"โคโบะ คานาเอรุ","tags":["#ID","#ID รุ่น 3"]}}}', '{}', 'a3b7a3cc57b5b7aabef4f70ee53137eff9b25805dde7ba5fd6b6ff3848eb2876', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
