INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (124, 'hBP01-084', 'hBP01-084 ゆづあ ID ID3期生 こぼ・かなえる #ID #ID3期生 猫になる～ Kobo Kanaeru #ID #ID 3rd Gen Turning into a Cat~ こぼ・かなえる #ID #ID3期生 變成貓～ Kobo Kanaeru #ID #ID Gen 3 Jadi kucing～ 코보 카나에루 #ID #ID 3기생 고양이가 될래~ โคโบะ คานาเอรุ #ID #ID รุ่น 3 จะเป็นแมวแล้ว~ Kobo Kanaeru #ID #ID 3rd Gen Me vuelvo gato～', '');
