INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (125, 'hBP01-085', 'hBP01-085 Salmon88 ID ID3期生 こぼ・かなえる #ID #ID3期生 perayaan レインドロップス 相手のバックホロメン3人に特殊ダメージ10を与える（ダウンしても相手のライフは減らない）。 Kobo Kanaeru #ID #ID 3rd Gen perayaan Raindrops Deal 10 special damage to 3 of the opponent''s Back holomem (even if they are knocked out, the opponent does not lose Life). こぼ・かなえる #ID #ID3期生 perayaan Raindrops 對對手3位後台Holo成員造成特殊傷害10（即使被擊倒，對手的生命值也不會減少）。 Kobo Kanaeru #ID #ID Gen 3 perayaan Raindrops Berikan 10 damage spesial kepada 3 Back holomen lawan (meskipun Knock Out, Life lawan tidak berkurang). 코보 카나에루 #ID #ID 3기생 perayaan 레인드롭스 상대의 백 홀로멘 3명에게 특수 대미지 10을 준다(다운되어도 상대의 라이프는 줄지 않는다). โคโบะ คานาเอรุ #ID #ID รุ่น 3 การเฉลิมฉลอง เรนดรอปส์ สร้างความเสียหายพิเศษ 10 ให้แบ็กโฮโลเมนของฝ่ายตรงข้าม 3 คน (แม้ดาวน์ก็จะไม่ทำให้ไลฟ์ของฝ่ายตรงข้ามลดลง) Kobo Kanaeru #ID #ID 3rd Gen perayaan Gotas de lluvia Inflige 10 de daño especial a 3 holomems de la Retaguardia del oponente (aunque queden abatidos, la Vida del oponente no disminuye).', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('126', 'hBP01-086', 'character', 'U', 'first', 'hBP01/hBP01-086_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-086_U.png', 110, NULL, 1, '["null"]', NULL, 'こぼ・かなえる', '{"arts":[{"cost_types":["null"],"damage":40}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["blue"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"OnAeru"}],"keyword":{"effect":"You may archive 1 Cheer from your holomem with #ID: Deal 10 special damage to all of your opponent''s back holomem (even if they are Downed, your opponent does not lose Life).","name":"Virtual Marketing"},"name":"Kobo Kanaeru","tags":["#ID","#ID 3rd Gen"]},"es":{"arts":[{"name":"OnAeru"}],"keyword":{"effect":"Puedes archivar 1 Cheer de uno de tus holomen con #ID: inflige 10 de daño especial a todos los holomen de atrás de tu oponente (aunque queden derribados, tu oponente no pierde Vida).","name":"Marketing virtual"},"name":"Kobo Kanaeru","tags":["#ID","#ID 3rd Gen"]},"id":{"arts":[{"name":"OnAeru"}],"keyword":{"effect":"Kamu boleh archive 1 Cheer dari holomenmu yang memiliki #ID: berikan 10 damage spesial kepada semua Back holomen lawan (meskipun menjadi Down, Life lawan tidak berkurang).","name":"Pemasaran Virtual"},"name":"Kobo Kanaeru","tags":["#ID","#ID Gen 3"]},"ja":{"arts":[{"name":"OnAeru"}],"keyword":{"effect":"自分の#IDを持つホロメンのエール1枚をアーカイブできる:相手のバックホロメン全員に特殊ダメージ10を与える（ダウンしても相手のライフは減らない）。","name":"バーチャルマーケティング"},"name":"こぼ・かなえる","tags":["#ID","#ID3期生"]},"ko":{"arts":[{"name":"OnAeru"}],"keyword":{"effect":"자신의 #ID를 가진 홀로멤의 에일 1장을 아카이브할 수 있다: 상대의 백 홀로멤 전원에게 특수 대미지 10을 준다(다운되어도 상대의 라이프는 줄지 않는다).","name":"버추얼 마케팅"},"name":"코보 카나에루","tags":["#ID","#ID 3기생"]},"tc":{"arts":[{"name":"OnAeru"}],"keyword":{"effect":"可以將自己1名持有#ID的Holo成員的1張應援存入檔案區：對手所有後衛Holo成員受到特殊傷害10（即使倒下，對手的生命值也不會減少）。","name":"虛擬行銷"},"name":"こぼ・かなえる","tags":["#ID","#ID3期生"]},"th":{"arts":[{"name":"OnAeru"}],"keyword":{"effect":"สามารถอาร์ไคฟ์เยล 1 ใบของโฮโลเม็มของตนเองที่มี #ID: สร้างความเสียหายพิเศษ 10 ให้แบ็กโฮโลเม็มทั้งหมดของคู่ต่อสู้ (แม้จะดาวน์ก็ไม่ทำให้ไลฟ์ของคู่ต่อสู้ลดลง)","name":"การตลาดเสมือนจริง"},"name":"โคโบะ คานาเอรุ","tags":["#ID","#ID รุ่น 3"]}}}', '{}', '74b1643c853835db3e7b8ccd1612914ce27404400ddc0b15fcfda3d57a96423c', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
