INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (129, 'hBP01-089', 'hBP01-089 により ID ID1期生 歌 ムーナ・ホシノヴァ #ID #ID1期生 #歌 おつムーナ Moona Hoshinova #ID #ID 1st Gen #Singing OtsuMoona Moona Hoshinova #ID #ID1期生 #歌唱 OtsuMoona Moona Hoshinova #ID #ID Gen 1 #Menyanyi OtsuMoona 무나 호시노바 #ID #ID 1기생 #노래 오츠무나 มูนา โฮชิโนวา #ID #ID รุ่น 1 #เพลง โอตสึมูนา Moona Hoshinova #ID #ID 1st Gen #Singing OtsuMoona', '');
