INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (133, 'hBP01-092', 'hBP01-092 EN Promise オーロ・クロニー #EN #Promise クロにちは～ このホロメンのエール1枚を、自分の他の#Promiseを持つホロメンに付け替えられる。 Ouro Kronii #EN #Promise Kuronichiwa~ You may move 1 Cheer from this holomem to another of your holomems with #Promise. 歐羅・克羅妮 #EN #Promise 黑嚕你好～ 可以將這名holomen的1張能量改附給自己其他1名持有#Promise的holomen。 Ouro Kronii #EN #Promise Kuronichiwa～ Kamu boleh memindahkan 1 Ekoru dari holomen ini ke holomen lain milikmu yang memiliki #Promise. 오우로 크로니 #EN #Promise 쿠로니치와~ 이 홀로멘의 에일 1장을 자신의 다른 #Promise를 가진 홀로멘에게 갈아붙일 수 있다. โอโร่ โครนี #EN #Promise คุโระนิจิวะ~ คุณอาจย้ายเยล 1 ใบของโฮโลเมนนี้ไปติดให้โฮโลเมนอื่นของคุณที่มี #Promise Ouro Kronii #EN #Promise ¡Kuronichiwa~! Puedes cambiar 1 Cheer de este holomen a otro de tus holomen con #Promise.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('134', 'hBP01-093', 'character', 'C', 'first', 'hBP01/hBP01-093_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-093_C.png', 160, NULL, 1, '["null"]', 'ワダアルコ', 'オーロ・クロニー', '{"arts":[{"cost_types":["null"],"damage":40},{"cost_types":["blue","null"],"damage":60}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["blue"],"translations":{"en":{"arts":[{"name":"Kuroyasumi~"},{"name":"Kuro Nap Time"}],"name":"Ouro Kronii","tags":["#EN","#Promise"]},"es":{"arts":[{"name":"Descanso kuro~"},{"name":"Hora de descanso Kuro"}],"name":"Ouro Kronii","tags":["#EN","#Promise"]},"id":{"arts":[{"name":"Kuroyasumi～"},{"name":"Waktu Istirahat Kuro"}],"name":"Ouro Kronii","tags":["#EN","#Promise"]},"ja":{"arts":[{"name":"クロやすみ～"},{"name":"お休みクロタイム"}],"name":"オーロ・クロニー","tags":["#EN","#Promise"]},"ko":{"arts":[{"name":"쿠로야스미~"},{"name":"굿나잇 쿠로 타임"}],"name":"오우로 크로니","tags":["#EN","#Promise"]},"tc":{"arts":[{"name":"黑黑晚安～"},{"name":"晚安黑時光"}],"name":"歐羅・克羅妮","tags":["#EN","#Promise"]},"th":{"arts":[{"name":"คุโระยาสุมิ~"},{"name":"เวลาพักของคุโระ"}],"name":"โอโร่ โครนี","tags":["#EN","#Promise"]}}}', '{}', 'c2676f091fe8f433c979d97aef4937736a7433883b1db2ea343f4b73dec92957', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
