INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (134, 'hBP01-093', 'hBP01-093 ワダアルコ EN Promise オーロ・クロニー #EN #Promise クロやすみ～ お休みクロタイム Ouro Kronii #EN #Promise Kuroyasumi~ Kuro Nap Time 歐羅・克羅妮 #EN #Promise 黑黑晚安～ 晚安黑時光 Ouro Kronii #EN #Promise Kuroyasumi～ Waktu Istirahat Kuro 오우로 크로니 #EN #Promise 쿠로야스미~ 굿나잇 쿠로 타임 โอโร่ โครนี #EN #Promise คุโระยาสุมิ~ เวลาพักของคุโระ Ouro Kronii #EN #Promise Descanso kuro~ Hora de descanso Kuro', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('135', 'hBP01-094', 'character', 'U', 'first', 'hBP01/hBP01-094_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-094_U.png', 120, NULL, 1, '["null"]', NULL, 'オーロ・クロニー', '{"arts":[{"cost_types":["null"],"damage":40}],"card_sets":["ブースターパック「ブルーミングレディアンス」","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["blue"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"Let''s Make It a Fes to Remember!"}],"keyword":{"effect":"Reveal 1 Cheer from your Cheer Deck that is the same color as one of your holomem with #Promise, and send it to one of your holomem with #Promise. Then shuffle your Cheer Deck.","name":"Kuro-ni-hello!"},"name":"Ouro Kronii","tags":["#EN","#Promise"]},"es":{"arts":[{"name":"¡Hagamos de este fes algo inolvidable!"}],"keyword":{"effect":"Revela en tu mazo Cheer 1 Cheer del mismo color que 1 de tus holomen con #Promise, y envíalo a uno de tus holomen con #Promise. Luego baraja tu mazo Cheer.","name":"¡Hola-kuro!"},"name":"Ouro Kronii","tags":["#EN","#Promise"]},"id":{"arts":[{"name":"Ayo bikin fes yang tak terlupakan!"}],"keyword":{"effect":"Dari Cheer Deck milikmu, ungkapkan 1 Cheer dengan warna yang sama dengan 1 Holomen milikmu yang memiliki #Promise, lalu kirimkan ke Holomen milikmu yang memiliki #Promise. Lalu kocok Cheer Deck.","name":"Kuro-nichiwa!"},"name":"Ouro Kronii","tags":["#EN","#Promise"]},"ja":{"arts":[{"name":"忘れられないfesにしよう！"}],"keyword":{"effect":"自分のエールデッキから、自分の#Promiseを持つホロメン1人と同色のエール1枚を公開し、自分の#Promiseを持つホロメンに送る。そしてエールデッキをシャッフルする。","name":"クロにちは！"},"name":"オーロ・クロニー","tags":["#EN","#Promise"]},"ko":{"arts":[{"name":"잊지 못할 fes로 만들자!"}],"keyword":{"effect":"자신의 엘 덱에서 자신의 #Promise를 가진 홀로멤 1명과 같은 색의 엘 1장을 공개하고, 자신의 #Promise를 가진 홀로멤에게 보낸다. 그리고 엘 덱을 셔플한다.","name":"쿠로니치하!"},"name":"오우로 크로니","tags":["#EN","#Promise"]},"tc":{"arts":[{"name":"一起打造難忘的fes吧！"}],"keyword":{"effect":"從自己的應援牌庫中公開1張與自己1位持有#Promise的Holomen同色的應援，送給自己持有#Promise的Holomen。然後將應援牌庫洗牌。","name":"黑嚕你好！"},"name":"歐羅・克羅妮","tags":["#EN","#Promise"]},"th":{"arts":[{"name":"มาสร้างเฟสที่ไม่มีวันลืมกันเถอะ!"}],"keyword":{"effect":"เปิดเผยเยล 1 ใบจากเยลเด็คของคุณที่มีสีเดียวกับโฮโลเมน 1 คนของคุณที่มี #Promise แล้วส่งไปยังโฮโลเมนของคุณที่มี #Promise จากนั้นสับเยลเด็ค","name":"คุโระนิจิวะ!"},"name":"โอโร่ โครนี","tags":["#EN","#Promise"]}}}', '{}', 'a97f0d69de7c0c532fb657ad66aa2ed9b3f58ff2c3793cdef91f7fc347033b5d', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
