INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (138, 'hBP01-097', 'hBP01-097 mono JP 3期生 ハーフエルフ 不知火フレア #JP #3期生 #ハーフエルフ フレア～扉の向こう側へ～ それは「愛と絆の物語」 自分のセンターホロメンとお休みしていないバックホロメン1人を交代させる。 Shiranui Flare #JP #3rd Gen #Half-Elf Flare~ Beyond the Door~ That is "A Tale of Love and Bonds" Switch your Center holomem with 1 of your non-resting Back holomem. 不知火芙蕾雅 #JP #3期生 #半精靈 芙蕾雅～前往門的另一側～ 那就是「愛與羈絆的故事」 將自己的中位holomen與1名未在休息狀態的後場holomen互換。 Shiranui Flare #JP #Gen 3 #Setengah Elf Flare～ Menuju Sisi Lain Pintu～ Itu adalah "kisah cinta dan ikatan" Tukar Center holomen milikmu dengan 1 Back holomen milikmu yang tidak sedang Rest. 시라누이 플레어 #JP #3기생 #하프엘프 플레어~ 문 너머로~ 그것은 「사랑과 유대의 이야기」 자신의 센터 홀로멘과 쉬고 있지 않은 백 홀로멘 1명을 교체한다. ชิรานุย เฟลร์ #JP #รุ่น 3 #ฮาล์ฟเยลฟ์ เฟลร์ ~สู่ฝั่งตรงข้ามของประตู~ นั่นคือ "เรื่องราวแห่งความรักและสายใย" สลับเซ็นเตอร์โฮโลเมนของคุณกับแบ็กโฮโลเมน 1 คนของคุณที่ไม่ได้กำลังพักอยู่ Shiranui Flare #JP #3rd Gen #Half-Elf Flare ~al otro lado de la puerta~ Eso es «una historia de amor y lazos» Intercambia tu holomen central con 1 de tus holomen de la retaguardia que no esté en reposo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('139', 'hBP01-098', 'character', 'R', 'spot', 'hBP01/hBP01-098_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-098_R.png', 90, NULL, 1, '["null"]', 'mono', '白銀ノエル', '{"arts":[{"cost_types":["null","null"],"damage":20}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["null"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Noel ~Beyond the Door~"}],"keyword":{"effect":"You may send 1 Cheer from your Archive to your holomem.","name":"That is \"Me\""},"name":"Shirogane Noel","tags":["#JP","#3rd Gen","#Alcohol"]},"es":{"arts":[{"name":"Noel ~Al otro lado de la puerta~"}],"keyword":{"effect":"Puedes enviar 1 Cheer de tu Archivo a uno de tus holomen.","name":"Eso soy «yo»"},"name":"Shirogane Noel","tags":["#JP","#3rd Gen","#Alcohol"]},"id":{"arts":[{"name":"Noel～Ke balik pintu itu～"}],"keyword":{"effect":"Kamu boleh mengirim 1 Cheer dari Arsip milikmu ke holomen milikmu.","name":"Itu adalah \"aku\""},"name":"Shirogane Noel","tags":["#JP","#Gen 3","#Alkohol"]},"ja":{"arts":[{"name":"ノエル～扉の向こう側へ～"}],"keyword":{"effect":"自分のアーカイブのエール1枚を自分のホロメンに送れる。","name":"それは「俺」"},"name":"白銀ノエル","tags":["#JP","#3期生","#お酒"]},"ko":{"arts":[{"name":"노엘~문 너머로~"}],"keyword":{"effect":"자신의 아카이브의 에르 1장을 자신의 홀로멘에게 보낼 수 있다.","name":"그것은 「나」"},"name":"시로가네 노엘","tags":["#JP","#3기생","#술"]},"tc":{"arts":[{"name":"諾艾爾～前往門的另一側～"}],"keyword":{"effect":"可將自己歸檔區的1張應援送給自己的Holomen。","name":"那就是「我」"},"name":"白銀諾艾爾","tags":["#JP","#3期生","#酒"]},"th":{"arts":[{"name":"โนเอล ~สู่โลกอีกฟากของประตู~"}],"keyword":{"effect":"คุณสามารถส่งเชียร์ 1 ใบจากอาร์ไคฟ์ของคุณไปยังโฮโลเมนของคุณ","name":"นั่นคือ \"ฉัน\""},"name":"ชิโรกาเนะ โนเอล","tags":["#JP","#รุ่น 3","#แอลกอฮอล์"]}}}', '{}', '17b889c6aef3938bc979f2d7fa7f6d42464309cdbad794d2509344533d983829', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
