INSERT INTO card_tags (tag, card_id) VALUES ('お酒', '139');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (139, 'hBP01-098', 'hBP01-098 mono JP 3期生 お酒 白銀ノエル #JP #3期生 #お酒 ノエル～扉の向こう側へ～ それは「俺」 自分のアーカイブのエール1枚を自分のホロメンに送れる。 Shirogane Noel #JP #3rd Gen #Alcohol Noel ~Beyond the Door~ That is "Me" You may send 1 Cheer from your Archive to your holomem. 白銀諾艾爾 #JP #3期生 #酒 諾艾爾～前往門的另一側～ 那就是「我」 可將自己歸檔區的1張應援送給自己的Holomen。 Shirogane Noel #JP #Gen 3 #Alkohol Noel～Ke balik pintu itu～ Itu adalah "aku" Kamu boleh mengirim 1 Cheer dari Arsip milikmu ke holomen milikmu. 시로가네 노엘 #JP #3기생 #술 노엘~문 너머로~ 그것은 「나」 자신의 아카이브의 에르 1장을 자신의 홀로멘에게 보낼 수 있다. ชิโรกาเนะ โนเอล #JP #รุ่น 3 #แอลกอฮอล์ โนเอล ~สู่โลกอีกฟากของประตู~ นั่นคือ "ฉัน" คุณสามารถส่งเชียร์ 1 ใบจากอาร์ไคฟ์ของคุณไปยังโฮโลเมนของคุณ Shirogane Noel #JP #3rd Gen #Alcohol Noel ~Al otro lado de la puerta~ Eso soy «yo» Puedes enviar 1 Cheer de tu Archivo a uno de tus holomen.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('140', 'hBP01-099', 'character', 'R', 'spot', 'hBP01/hBP01-099_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-099_R.png', 70, NULL, 1, '["null"]', 'mono', '宝鐘マリン', '{"arts":[{"cost_types":["null"],"damage":10}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["null"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Marine ~Beyond the Door~"}],"keyword":{"effect":"You may roll a die once: If the result is odd, switch your opponent''s Center holomem with 1 of their Back holomem.","name":"That is \"Edinburgh Castle\""},"name":"Houshou Marine","tags":["#JP","#3rd Gen","#Art","#Ocean"]},"es":{"arts":[{"name":"Marine ~Al otro lado de la puerta~"}],"keyword":{"effect":"Puedes lanzar un dado 1 vez: si sale impar, haz que el holomen central de tu oponente y 1 de sus holomen de la retaguardia intercambien posiciones.","name":"Eso es «el Castillo de Edimburgo»"},"name":"Houshou Marine","tags":["#JP","#3rd Gen","#Art","#Ocean"]},"id":{"arts":[{"name":"Marine～Ke balik pintu itu～"}],"keyword":{"effect":"Kamu boleh melempar dadu 1 kali: jika hasilnya ganjil, tukarkan Center holomen lawan dengan 1 Back holomen lawan.","name":"Itu adalah \"Kastel Edinburgh\""},"name":"Houshou Marine","tags":["#JP","#Gen 3","#Seni","#Laut"]},"ja":{"arts":[{"name":"マリン～扉の向こう側へ～"}],"keyword":{"effect":"サイコロを1回振れる:奇数の時、相手のセンターホロメンとバックホロメン1人を交代させる。","name":"それは「エジンバラ城」"},"name":"宝鐘マリン","tags":["#JP","#3期生","#絵","#海"]},"ko":{"arts":[{"name":"마린~문 너머로~"}],"keyword":{"effect":"주사위를 1번 굴릴 수 있다:홀수이면, 상대의 센터 홀로멘과 백 홀로멘 1명을 교대시킨다.","name":"그것은 「에든버러 성」"},"name":"호쇼 마린","tags":["#JP","#3기생","#그림","#바다"]},"tc":{"arts":[{"name":"瑪琳～前往門的另一側～"}],"keyword":{"effect":"可擲1次骰子：若為奇數，則讓對手的中心Holomen與1名後台Holomen互換。","name":"那就是「愛丁堡城」"},"name":"寶鐘瑪琳","tags":["#JP","#3期生","#繪畫","#海洋"]},"th":{"arts":[{"name":"มาริน ~สู่โลกอีกฟากของประตู~"}],"keyword":{"effect":"คุณสามารถทอยลูกเต๋า 1 ครั้ง: ถ้าออกเลขคี่ ให้สลับเซ็นเตอร์โฮโลเมนของฝ่ายตรงข้ามกับแบ็กโฮโลเมนของฝ่ายตรงข้าม 1 คน","name":"นั่นคือ \"ปราสาทเอดินบะระ\""},"name":"โฮโช มารีน","tags":["#JP","#รุ่น 3","#ศิลปะ","#ทะเล"]}}}', '{}', 'c1c6f77f4376d15ed190c2aacb32afd2b5469ef4d1a4c5004af10412c223dd7d', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
