INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (140, 'hBP01-099', 'hBP01-099 mono JP 3期生 絵 海 宝鐘マリン #JP #3期生 #絵 #海 マリン～扉の向こう側へ～ それは「エジンバラ城」 サイコロを1回振れる:奇数の時、相手のセンターホロメンとバックホロメン1人を交代させる。 Houshou Marine #JP #3rd Gen #Art #Ocean Marine ~Beyond the Door~ That is "Edinburgh Castle" You may roll a die once: If the result is odd, switch your opponent''s Center holomem with 1 of their Back holomem. 寶鐘瑪琳 #JP #3期生 #繪畫 #海洋 瑪琳～前往門的另一側～ 那就是「愛丁堡城」 可擲1次骰子：若為奇數，則讓對手的中心Holomen與1名後台Holomen互換。 Houshou Marine #JP #Gen 3 #Seni #Laut Marine～Ke balik pintu itu～ Itu adalah "Kastel Edinburgh" Kamu boleh melempar dadu 1 kali: jika hasilnya ganjil, tukarkan Center holomen lawan dengan 1 Back holomen lawan. 호쇼 마린 #JP #3기생 #그림 #바다 마린~문 너머로~ 그것은 「에든버러 성」 주사위를 1번 굴릴 수 있다:홀수이면, 상대의 센터 홀로멘과 백 홀로멘 1명을 교대시킨다. โฮโช มารีน #JP #รุ่น 3 #ศิลปะ #ทะเล มาริน ~สู่โลกอีกฟากของประตู~ นั่นคือ "ปราสาทเอดินบะระ" คุณสามารถทอยลูกเต๋า 1 ครั้ง: ถ้าออกเลขคี่ ให้สลับเซ็นเตอร์โฮโลเมนของฝ่ายตรงข้ามกับแบ็กโฮโลเมนของฝ่ายตรงข้าม 1 คน Houshou Marine #JP #3rd Gen #Art #Ocean Marine ~Al otro lado de la puerta~ Eso es «el Castillo de Edimburgo» Puedes lanzar un dado 1 vez: si sale impar, haz que el holomen central de tu oponente y 1 de sus holomen de la retaguardia intercambien posiciones.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('141', 'hBP01-100', 'character', 'C', 'spot', 'hBP01/hBP01-100_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-100_C.png', 70, NULL, 1, '["null"]', NULL, '森カリオペ', '{"arts":[{"cost_types":["null"],"damage":30}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["null"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Soul Guidance"}],"keyword":{"effect":"You may return 1 to 3 Cheer from your Archive to your Cheer Deck. Then shuffle your Cheer Deck.","name":"Soul Harvest"},"name":"Mori Calliope","tags":["#EN","#Myth","#Singing"]},"es":{"arts":[{"name":"Guía del alma"}],"keyword":{"effect":"Puedes devolver de 1 a 3 Cheer de tu archivo al mazo de Cheer. Después, baraja el mazo de Cheer.","name":"Cosecha de almas"},"name":"Mori Calliope","tags":["#EN","#Myth","#Singing"]},"id":{"arts":[{"name":"Pemandu Jiwa"}],"keyword":{"effect":"Kamu boleh mengembalikan 1 hingga 3 Cheer dari Archive milikmu ke Cheer Deck. Lalu kocok Cheer Deck.","name":"Panen jiwa"},"name":"Mori Calliope","tags":["#EN","#Myth","#Menyanyi"]},"ja":{"arts":[{"name":"ソウルご案内"}],"keyword":{"effect":"自分のアーカイブのエール1～3枚をエールデッキに戻せる。そしてエールデッキをシャッフルする。","name":"ソウル収穫"},"name":"森カリオペ","tags":["#EN","#Myth","#歌"]},"ko":{"arts":[{"name":"소울 안내"}],"keyword":{"effect":"자신의 아카이브의 에일 1~3장을 에일 덱으로 되돌릴 수 있다. 그리고 에일 덱을 셔플한다.","name":"영혼 수확"},"name":"모리 칼리오페","tags":["#EN","#Myth","#노래"]},"tc":{"arts":[{"name":"靈魂嚮導"}],"keyword":{"effect":"可將自己存檔區的1～3張Cheers放回Cheers牌庫。然後將Cheers牌庫洗牌。","name":"靈魂收穫"},"name":"森美聲","tags":["#EN","#Myth","#歌唱"]},"th":{"arts":[{"name":"นำทางวิญญาณ"}],"keyword":{"effect":"คุณสามารถนำเยล 1~3 ใบจาก Archive ของคุณกลับเข้าเด็คเยลได้ จากนั้นสับเด็คเยล","name":"เก็บเกี่ยววิญญาณ"},"name":"โมริ คาลลิโอเป","tags":["#EN","#Myth","#เพลง"]}}}', '{}', 'a0862181b90f75e1df30452c3b3d074900e38c1e81d052b3648f17f8eeb335a2', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
