INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (141, 'hBP01-100', 'hBP01-100 EN Myth 歌 森カリオペ #EN #Myth #歌 ソウルご案内 ソウル収穫 自分のアーカイブのエール1～3枚をエールデッキに戻せる。そしてエールデッキをシャッフルする。 Mori Calliope #EN #Myth #Singing Soul Guidance Soul Harvest You may return 1 to 3 Cheer from your Archive to your Cheer Deck. Then shuffle your Cheer Deck. 森美聲 #EN #Myth #歌唱 靈魂嚮導 靈魂收穫 可將自己存檔區的1～3張Cheers放回Cheers牌庫。然後將Cheers牌庫洗牌。 Mori Calliope #EN #Myth #Menyanyi Pemandu Jiwa Panen jiwa Kamu boleh mengembalikan 1 hingga 3 Cheer dari Archive milikmu ke Cheer Deck. Lalu kocok Cheer Deck. 모리 칼리오페 #EN #Myth #노래 소울 안내 영혼 수확 자신의 아카이브의 에일 1~3장을 에일 덱으로 되돌릴 수 있다. 그리고 에일 덱을 셔플한다. โมริ คาลลิโอเป #EN #Myth #เพลง นำทางวิญญาณ เก็บเกี่ยววิญญาณ คุณสามารถนำเยล 1~3 ใบจาก Archive ของคุณกลับเข้าเด็คเยลได้ จากนั้นสับเด็คเยล Mori Calliope #EN #Myth #Singing Guía del alma Cosecha de almas Puedes devolver de 1 a 3 Cheer de tu archivo al mazo de Cheer. Después, baraja el mazo de Cheer.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('142', 'hBP01-101', 'character', 'C', 'spot', 'hBP01/hBP01-101_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-101_C.png', 80, NULL, 1, '["null"]', NULL, 'ワトソン・アメリア', '{"arts":[{"cost_types":["null","null"],"damage":20}],"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["null"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Something Elementary, Right?"}],"keyword":{"effect":"You may return 1 Item from your Archive to your hand.","name":"Clue Found"},"name":"Watson Amelia","tags":["#EN","#Myth"]},"es":{"arts":[{"name":"¿No es algo básico?"}],"keyword":{"effect":"Puedes devolver a tu mano 1 Item de tu Archivo.","name":"Pista descubierta"},"name":"Watson Amelia","tags":["#EN","#Myth"]},"id":{"arts":[{"name":"Hal dasar doang, kan?"}],"keyword":{"effect":"Kamu boleh mengembalikan 1 Item dari Arsip milikmu ke tanganmu.","name":"Petunjuk ditemukan"},"name":"Watson Amelia","tags":["#EN","#Myth"]},"ja":{"arts":[{"name":"初歩的なことなんでしょう？"}],"keyword":{"effect":"自分のアーカイブのアイテム1枚を手札に戻せる。","name":"手がかり発見"},"name":"ワトソン・アメリア","tags":["#EN","#Myth"]},"ko":{"arts":[{"name":"초보적인 거잖아?"}],"keyword":{"effect":"자신의 아카이브의 아이템 1장을 패로 되돌릴 수 있다.","name":"단서 발견"},"name":"왓슨 아멜리아","tags":["#EN","#Myth"]},"tc":{"arts":[{"name":"這不是很基礎的事嗎？"}],"keyword":{"effect":"可以將自己存檔區中的1張道具返回手牌。","name":"發現線索"},"name":"Watson Amelia","tags":["#EN","#Myth"]},"th":{"arts":[{"name":"มันเป็นเรื่องพื้นฐานไม่ใช่เหรอ?"}],"keyword":{"effect":"คุณสามารถนำไอเทม 1 ใบจากอาร์ไคฟ์ของคุณกลับขึ้นมือได้","name":"พบเบาะแสแล้ว"},"name":"วัตสัน อเมเลีย","tags":["#EN","#Myth"]}}}', '{}', '7df9be36d646efa97d1b4b3e20f045e4d1036d9fedf1ee1e984973e3cc2d97de', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
