INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('145', 'hBP01-104', 'supportItem', 'C', NULL, 'hBP01/hBP01-104_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-104_C.png', NULL, NULL, NULL, NULL, 'JinArt KABAKURA', 'ふつうのパソコン', '{"card_sets":["ブースターパック「ブルーミングレディアンス」","エクストラブースター サマー・ホログラム","スタートデッキ 赤 百鬼あやめ","スタートデッキ 紫 癒月ちょこ","スタートデッキ 白 轟はじめ","スタートデッキ 緑 風真いろは","スタートデッキ 黄 不知火フレア","スタートデッキ FLOW GLOW 推し 輪堂千速","スタートデッキ FLOW GLOW 推し 虎金妃笑虎","スタートデッキ 推し Advent","スタートデッキ 推し Justice","【使用可能カード】hGS 2026 大阪 セレクションロード"],"translations":{"en":{"ability_text":"Reveal 1 Debut holomem from your deck and put it onto the Stage. Then shuffle your deck.","name":"Regular PC"},"es":{"ability_text":"Revela 1 holomen Debut de tu mazo y ponlo en el Stage. Después, baraja el mazo.","name":"Regular PC"},"id":{"ability_text":"Ungkapkan 1 Debut Holomen dari deck Anda, lalu taruh ke Stage. Lalu shuffle deck.","name":"PC Biasa"},"ja":{"ability_text":"自分のデッキから、Debutホロメン1枚を公開し、ステージに出す。そしてデッキをシャッフルする。","name":"ふつうのパソコン"},"ko":{"ability_text":"자신의 덱에서 Debut 홀로멘 1장을 공개하고, 스테이지에 내보낸다. 그리고 덱을 셔플한다.","name":"평범한 PC"},"tc":{"ability_text":"從自己的牌庫公開1張Debut holomen，登場到舞台上。然後將牌庫洗牌。","name":"普通電腦"},"th":{"ability_text":"เปิดเผย Debut โฮโลเมน 1 ใบจากเด็คของคุณ แล้วนำออกสู่ Stage จากนั้นสับเด็ค","name":"พีซีธรรมดา"}}}', '{}', '5e2e48e79e490d569820dc57888ca140f51a54c96196eff17042e06fac288fba', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
