INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('169', 'hY02-001', 'supportCheer', 'C', NULL, 'COMMON/hY02-001_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/COMMON/hY02-001_C.png', NULL, NULL, NULL, NULL, 'はずき', '緑エール', '{"card_sets":["ブースターパック「ブルーミングレディアンス」","ブースターパック「クインテットスペクトラム」","ブースターパック「エリートスパーク」","スタートデッキ「ときのそら＆AZKi」","スタートデッキ 緑 風真いろは","スタートデッキ FLOW GLOW 推し 輪堂千速","ライブスタートデッキ 儒烏風亭らでん","スタートエールセット"],"color_codes":["green"],"translations":{"en":{"ability_text":"■ When a holomem leaves the Stage, Archive all Cheer attached to that holomem.\n■ When a holomem uses Baton Touch, Archive the specified number of Cheer attached to that holomem.","name":"Green Cheer"},"es":{"ability_text":"■Cuando un holomen deja el Stage, archiva todos los Cheer de ese holomen.\n■Cuando un holomen hace Baton Touch, archiva la cantidad de Cheer especificada de ese holomen.","name":"Green Cheer"},"id":{"ability_text":"■Saat holomen meninggalkan Stage, Archive semua Cheer pada holomen itu.\n■Saat holomen melakukan Baton Touch, Archive sejumlah Cheer yang ditentukan pada holomen itu.","name":"Yell Hijau"},"ja":{"ability_text":"■ホロメンがステージから離れる時、そのホロメンのエールすべてをアーカイブする。\r\n■ホロメンがバトンタッチする時、そのホロメンのエールを指定された枚数アーカイブする。","name":"緑エール"},"ko":{"ability_text":"■홀로멘이 스테이지를 떠날 때, 그 홀로멘의 에일 전부를 아카이브한다.\n■홀로멘이 Baton Touch할 때, 그 홀로멘의 에일을 지정된 장수만큼 아카이브한다.","name":"그린 옐"},"tc":{"ability_text":"■當holomen離開舞台時，將該holomen的所有應援存檔。\n■當holomen進行Baton Touch時，將該holomen指定數量的應援存檔。","name":"綠色應援"},"th":{"ability_text":"■เมื่อโฮโลเม็มออกจาก Stage ให้ Archive เยลทั้งหมดของโฮโลเม็มนั้น\n■เมื่อโฮโลเม็ม Baton Touch ให้ Archive เยลของโฮโลเม็มนั้นตามจำนวนที่กำหนด","name":"เยลสีเขียว"}}}', '{}', 'c1fc9f72041eba25ffccc590330f080a4c3f4650883ba0c9f50277880138a6f5', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
