INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('173', 'hYS01-002', 'oshiCharacter', 'OC', NULL, 'hY01/hYS01-002_OC', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hY01/hYS01-002_OC.png', NULL, 5, NULL, NULL, '松尾 省吾', '兎田ぺこら', '{"card_sets":["スタートエールセット"],"color_codes":["green"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Usada Pekora","oshi_skill":{"effect":"[Once per turn] Until end of turn, your Green Collab holomem gets Arts +20.","name":"GREEN BATON","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] Heal 20 HP from all of your green holomem.","name":"Let''s all do our best!","timing":"Once per game"}},"es":{"name":"Usada Pekora","oshi_skill":{"effect":"[Una vez por turno] Durante este turno, los Arts de tu holomen de colaboración verde +20.","name":"Bastón Verde","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Cura 20 PS a todos tus holomen verdes.","name":"¡Esforcémonos todos!","timing":"Una vez por partida"}},"id":{"name":"Usada Pekora","oshi_skill":{"effect":"[Sekali per giliran] Selama giliran ini, Arts Green Collaborator Holomen milikmu +20.","name":"Baton Hijau","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per permainan] Pulihkan 20 HP untuk semua holomen hijau milikmu.","name":"Ayo semua semangat!","timing":"Sekali per permainan"}},"ja":{"name":"兎田ぺこら","oshi_skill":{"effect":"[ターンに1回]このターンの間、自分の緑コラボホロメンのアーツ+20。","name":"グリーンバトン","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]自分の緑ホロメン全員のHP20回復。","name":"みんな頑張ろー！","timing":"ゲームに1回"}},"ko":{"name":"우사다 페코라","oshi_skill":{"effect":"[턴에 1번]이번 턴 동안, 자신의 녹색 콜라보 홀로멤의 아츠 +20.","name":"그린 배턴","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번]자신의 초록 홀로멘 전원의 HP를 20 회복한다.","name":"다들 힘내자~!","timing":"게임에 1번"}},"tc":{"name":"兔田佩克拉","oshi_skill":{"effect":"[每回合1次]這個回合中，自己的綠色Collab Holomen的Art+20。","name":"綠色接力棒","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場對戰1次]回復自己的所有綠色holomen各20點HP。","name":"大家一起加油吧！","timing":"每場對戰1次"}},"th":{"name":"อุซาดะ เปโคระ","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] ในเทิร์นนี้ อาร์ตของคอลแลบโฮโลเม็มเบอร์สีเขียวของคุณ +20","name":"กระบองสีเขียว","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] ฟื้นฟู HP 20 ให้โฮโลเมนสีเขียวของคุณทั้งหมด","name":"ทุกคนพยายามกันเถอะ!","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{}', 'f4d0c1a32e2da8d0d380fcb8f753e7e2364e1c6419d93d7ac84f0e2ad6d3b449', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
