INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (173, 'hYS01-002', 'hYS01-002 松尾 省吾 兎田ぺこら グリーンバトン [ターンに1回]このターンの間、自分の緑コラボホロメンのアーツ+20。 みんな頑張ろー！ [ゲームに1回]自分の緑ホロメン全員のHP20回復。 Usada Pekora GREEN BATON [Once per turn] Until end of turn, your Green Collab holomem gets Arts +20. Let''s all do our best! [Once per game] Heal 20 HP from all of your green holomem. 兔田佩克拉 綠色接力棒 [每回合1次]這個回合中，自己的綠色Collab Holomen的Art+20。 大家一起加油吧！ [每場對戰1次]回復自己的所有綠色holomen各20點HP。 Usada Pekora Baton Hijau [Sekali per giliran] Selama giliran ini, Arts Green Collaborator Holomen milikmu +20. Ayo semua semangat! [Sekali per permainan] Pulihkan 20 HP untuk semua holomen hijau milikmu. 우사다 페코라 그린 배턴 [턴에 1번]이번 턴 동안, 자신의 녹색 콜라보 홀로멤의 아츠 +20. 다들 힘내자~! [게임에 1번]자신의 초록 홀로멘 전원의 HP를 20 회복한다. อุซาดะ เปโคระ กระบองสีเขียว [ใช้ได้ 1 ครั้งต่อเทิร์น] ในเทิร์นนี้ อาร์ตของคอลแลบโฮโลเม็มเบอร์สีเขียวของคุณ +20 ทุกคนพยายามกันเถอะ! [ใช้ได้ 1 ครั้งต่อเกม] ฟื้นฟู HP 20 ให้โฮโลเมนสีเขียวของคุณทั้งหมด Usada Pekora Bastón Verde [Una vez por turno] Durante este turno, los Arts de tu holomen de colaboración verde +20. ¡Esforcémonos todos! [Una vez por partida] Cura 20 PS a todos tus holomen verdes.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('174', 'hYS01-003', 'oshiCharacter', 'OC', NULL, 'hY01/hYS01-003_OC', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hY01/hYS01-003_OC.png', NULL, 5, NULL, NULL, '松尾 省吾', '小鳥遊キアラ', '{"card_sets":["スタートエールセット"],"color_codes":["red"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Takanashi Kiara","oshi_skill":{"effect":"[Once per turn] During this turn, your red Collab holomem gets +20 Arts.","name":"RED BATON","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] Return 1 Red holomem from your Archive to your hand.","name":"Now then! One more time!","timing":"Once per game"}},"es":{"name":"Takanashi Kiara","oshi_skill":{"effect":"[Una vez por turno] Durante este turno, las artes de tu holomen de colaboración rojo obtienen +20.","name":"Bastón Rojo","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Devuelve a tu mano 1 holomen rojo de tu Archivo.","name":"¡Vamos! ¡Una vez más!","timing":"Una vez por partida"}},"id":{"name":"Takanashi Kiara","oshi_skill":{"effect":"[Sekali per giliran] Selama giliran ini, Arts holomen collab merah milikmu +20.","name":"Baton Merah","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per permainan] Kembalikan 1 Red Holomen dari Archive-mu ke tanganmu.","name":"Ayo! Sekali lagi!","timing":"Sekali per permainan"}},"ja":{"name":"小鳥遊キアラ","oshi_skill":{"effect":"[ターンに1回]このターンの間、自分の赤コラボホロメンのアーツ+20。","name":"レッドバトン","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]自分のアーカイブの赤ホロメン1枚を手札に戻す。","name":"さあ！もう一度！","timing":"ゲームに1回"}},"ko":{"name":"타카나시 키아라","oshi_skill":{"effect":"[턴에 1번]이번 턴 동안 자신의 빨간 콜라보 홀로멘의 아츠+20.","name":"레드 배턴","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번]자신의 아카이브의 적색 홀로멤 1장을 패로 되돌린다.","name":"자! 다시 한 번!","timing":"게임에 1번"}},"tc":{"name":"小鳥遊琪亞拉","oshi_skill":{"effect":"[每回合1次]在這個回合期間，自己的紅色合作holomen的藝術+20。","name":"紅色接力棒","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場對戰1次]將自己檔案區1張紅色Holomen返回手牌。","name":"來吧！再一次！","timing":"每場對戰1次"}},"th":{"name":"ทาคานาชิ คิอาระ","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] ในเทิร์นนี้ อาร์ตของโคลาโบโฮโลเมนสีแดงของคุณ +20","name":"กระบองสีแดง","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] นำโฮโลเม็มเบอร์สีแดง 1 ใบจากอาร์ไคฟ์ของคุณกลับขึ้นมือ","name":"เอาล่ะ! อีกครั้ง!","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{}', '2192dd46e3c97bbf8a141ed5517b70757cbc789f9bffbabc35b2a53fdfec6a8d', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
