INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (182, 'hBP01-076', 'hBP01-076 JP 0期生 歌 星街すいせい #JP #0期生 #歌 スターの原石 相手のバックホロメン1人に特殊ダメージ10を与える（ダウンしても相手のライフは減らない）。 Hoshimachi Suisei #JP #0th Gen #Singing A Star in the Rough Deal 10 special damage to 1 of the opponent''s Back holomem (even if it is downed, the opponent''s Life does not decrease). 星街彗星 #JP #0期生 #歌唱 明星原石 對對手1位後備Holo成員造成特殊傷害10（即使倒下，對手的生命值也不會減少）。 Hoshimachi Suisei #JP #Gen 0 #Menyanyi Batu Mentah Sang Bintang Berikan Special Damage 10 kepada 1 Back holomen lawan (meskipun menjadi Down, Life lawan tidak berkurang). 호시마치 스이세이 #JP #0기생 #노래 스타의 원석 상대의 백 홀로멤 1명에게 특수 대미지 10을 준다(다운되어도 상대의 라이프는 줄지 않는다). โฮชิมาชิ สุยเซย #JP #รุ่น 0 #เพลง อัญมณีดิบของดาวเด่น สร้างความเสียหายพิเศษ 10 ให้แก่แบ็คโฮโลเมนของฝ่ายตรงข้าม 1 คน (แม้จะดาวน์ก็จะไม่ทำให้ไลฟ์ของฝ่ายตรงข้ามลดลง) Hoshimachi Suisei #JP #0th Gen #Singing Una estrella en bruto Inflige 10 de daño especial a 1 holomen de la Retaguardia de tu oponente (aunque quede Fuera de Combate, la Vida de tu oponente no disminuye).', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('183', 'hBP01-092', 'character', 'P', 'debut', 'hPR/hBP01-092_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP01-092_P.png', 70, NULL, 1, '["null"]', NULL, 'オーロ・クロニー', '{"arts":[{"cost_types":["blue"],"damage":10}],"card_sets":["PRカード","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["blue"],"translations":{"en":{"arts":[{"effect":"You may move 1 Cheer from this holomem to another of your holomems with #Promise.","name":"Kuronichiwa~"}],"name":"Ouro Kronii","tags":["#EN","#Promise"]},"es":{"arts":[{"effect":"Puedes cambiar 1 Cheer de este holomen a otro de tus holomen con #Promise.","name":"¡Kuronichiwa~!"}],"name":"Ouro Kronii","tags":["#EN","#Promise"]},"id":{"arts":[{"effect":"Kamu boleh memindahkan 1 Ekoru dari holomen ini ke holomen lain milikmu yang memiliki #Promise.","name":"Kuronichiwa～"}],"name":"Ouro Kronii","tags":["#EN","#Promise"]},"ja":{"arts":[{"effect":"このホロメンのエール1枚を、自分の他の#Promiseを持つホロメンに付け替えられる。","name":"クロにちは～"}],"name":"オーロ・クロニー","tags":["#EN","#Promise"]},"ko":{"arts":[{"effect":"이 홀로멘의 에일 1장을 자신의 다른 #Promise를 가진 홀로멘에게 갈아붙일 수 있다.","name":"쿠로니치와~"}],"name":"오우로 크로니","tags":["#EN","#Promise"]},"tc":{"arts":[{"effect":"可以將這名holomen的1張能量改附給自己其他1名持有#Promise的holomen。","name":"黑嚕你好～"}],"name":"歐羅・克羅妮","tags":["#EN","#Promise"]},"th":{"arts":[{"effect":"คุณอาจย้ายเยล 1 ใบของโฮโลเมนนี้ไปติดให้โฮโลเมนอื่นของคุณที่มี #Promise","name":"คุโระนิจิวะ~"}],"name":"โอโร่ โครนี","tags":["#EN","#Promise"]}}}', '{}', 'ea77f307a27cd6c459e1727b64050666216f8ce8858faee0bce6db434f853f79', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
