INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (183, 'hBP01-092', 'hBP01-092 EN Promise オーロ・クロニー #EN #Promise クロにちは～ このホロメンのエール1枚を、自分の他の#Promiseを持つホロメンに付け替えられる。 Ouro Kronii #EN #Promise Kuronichiwa~ You may move 1 Cheer from this holomem to another of your holomems with #Promise. 歐羅・克羅妮 #EN #Promise 黑嚕你好～ 可以將這名holomen的1張能量改附給自己其他1名持有#Promise的holomen。 Ouro Kronii #EN #Promise Kuronichiwa～ Kamu boleh memindahkan 1 Ekoru dari holomen ini ke holomen lain milikmu yang memiliki #Promise. 오우로 크로니 #EN #Promise 쿠로니치와~ 이 홀로멘의 에일 1장을 자신의 다른 #Promise를 가진 홀로멘에게 갈아붙일 수 있다. โอโร่ โครนี #EN #Promise คุโระนิจิวะ~ คุณอาจย้ายเยล 1 ใบของโฮโลเมนนี้ไปติดให้โฮโลเมนอื่นของคุณที่มี #Promise Ouro Kronii #EN #Promise ¡Kuronichiwa~! Puedes cambiar 1 Cheer de este holomen a otro de tus holomen con #Promise.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('184', 'hBP01-104', 'supportItem', 'P', NULL, 'hPR/hBP01-104_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP01-104_P.png', NULL, NULL, NULL, NULL, 'JinArt KABAKURA', 'ふつうのパソコン', '{"card_sets":["PRカード","【使用可能カード】hGS 2026 大阪 セレクションロード"],"translations":{"en":{"ability_text":"Reveal 1 Debut holomem from your deck and put it onto the Stage. Then shuffle your deck.","name":"Regular PC"},"es":{"ability_text":"Revela 1 holomen Debut de tu mazo y ponlo en el Stage. Después, baraja el mazo.","name":"Regular PC"},"id":{"ability_text":"Ungkapkan 1 Debut Holomen dari deck Anda, lalu taruh ke Stage. Lalu shuffle deck.","name":"PC Biasa"},"ja":{"ability_text":"自分のデッキから、Debutホロメン1枚を公開し、ステージに出す。そしてデッキをシャッフルする。","name":"ふつうのパソコン"},"ko":{"ability_text":"자신의 덱에서 Debut 홀로멘 1장을 공개하고, 스테이지에 내보낸다. 그리고 덱을 셔플한다.","name":"평범한 PC"},"tc":{"ability_text":"從自己的牌庫公開1張Debut holomen，登場到舞台上。然後將牌庫洗牌。","name":"普通電腦"},"th":{"ability_text":"เปิดเผย Debut โฮโลเมน 1 ใบจากเด็คของคุณ แล้วนำออกสู่ Stage จากนั้นสับเด็ค","name":"พีซีธรรมดา"}}}', '{}', '37ce09838b5d0cfe3d394ca94e7e4429c846b3ebecdb020b05f4b57b41f13068', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
