INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (186, 'hSD01-004', 'hSD01-004 しゅがお JP 0期生 歌 ときのそら #JP #0期生 #歌 オンステージ！ レッツダンス！ このターンの間、自分のセンターホロメンのアーツ+20。 Tokino Sora #JP #0th Gen #Singing On Stage! Let''s Dance! During this turn, your Center holomem gets +20 Arts. 時乃空 #JP #0期生 #歌唱 On Stage！ Let''s Dance! 本回合內，自己的中心holomen的藝能+20。 Tokino Sora #JP #Gen 0 #Menyanyi On Stage! Ayo Menari! Selama giliran ini, Arts Center Holomen milikmu +20. 토키노 소라 #JP #0기생 #노래 온 스테이지! 렛츠 댄스! 이번 턴 동안, 자신의 센터 홀로멘의 아츠+20. โตกิโนะ โซระ #JP #รุ่น 0 #เพลง ออนสเตจ! มาเต้นกันเถอะ! จนจบเทิร์นนี้ Arts ของเซ็นเตอร์โฮโลเมนของคุณ +20 Tokino Sora #JP #0th Gen #Singing ¡En escena! ¡A bailar! Durante este turno, las Arts de tu holomen central obtienen +20.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('187', 'hSD01-009', 'character', 'P', 'debut', 'hPR/hSD01-009_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hSD01-009_P.png', 60, NULL, 1, '["null"]', '三九呂', 'AZKi', '{"arts":[{"cost_types":["null"],"damage":10}],"card_sets":["PRカード"],"color_codes":["green"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"And then, and then"}],"keyword":{"effect":"You may roll a die once: If the result is 4 or less, send the top card of your Cheer Deck to one of your Back holomems. If the result is 1, you may also move this holomem to the Back Position.","name":"An Expanding Map"},"name":"AZKi","tags":["#JP","#0th Gen","#Singing"]},"es":{"arts":[{"name":"Y luego y luego"}],"keyword":{"effect":"Puedes lanzar 1 dado: si sale 4 o menos, envía la carta superior de tu mazo de Cheer a 1 de tus holomen de atrás. Si sale 1, además, puedes mover este holomen a la posición de atrás.","name":"El mapa que se expande"},"name":"AZKi","tags":["#JP","#0th Gen","#Singing"]},"id":{"arts":[{"name":"Terus terus"}],"keyword":{"effect":"Kamu boleh melempar dadu 1 kali: jika hasilnya 4 atau kurang, kirim 1 kartu teratas dari Deck Cheer milikmu ke Back holomen milikmu. Jika hasilnya 1, sebagai tambahan, kamu boleh memindahkan holomen ini ke Posisi Belakang.","name":"Peta yang terbentang"},"name":"AZKi","tags":["#JP","#Gen 0","#Menyanyi"]},"ja":{"arts":[{"name":"ほいでほいで"}],"keyword":{"effect":"サイコロを1回振れる:４以下の時、自分のエールデッキの上から1枚を、自分のバックホロメンに送る。１の時、さらに、このホロメンをバックポジションに移動できる。","name":"広がる地図"},"name":"AZKi","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"name":"그러고 그러고"}],"keyword":{"effect":"주사위를 1번 굴릴 수 있다: 4 이하라면, 자신의 엘 덱 위에서 1장을 자신의 백 홀로멤에게 보낸다. 1이라면, 추가로 이 홀로멤을 백 포지션으로 이동시킬 수 있다.","name":"펼쳐지는 지도"},"name":"AZKi","tags":["#JP","#0기생","#노래"]},"tc":{"arts":[{"name":"然後然後"}],"keyword":{"effect":"可以擲1次骰子：若為4以下，將自己應援牌庫頂的1張卡，送給自己的後場Holomen。若為1，則可以再將這位Holomen移動到後場位置。","name":"展開的地圖"},"name":"AZKi","tags":["#JP","#0期生","#歌唱"]},"th":{"arts":[{"name":"แล้วก็แล้วก็"}],"keyword":{"effect":"คุณสามารถทอยลูกเต๋า 1 ครั้ง: ถ้าออก 4 หรือน้อยกว่า ให้นำการ์ด 1 ใบจากบนสุดของเด็คเยลของคุณไปติดให้แบ็กโฮโลเมนของคุณ ถ้าออก 1 เพิ่มเติม คุณสามารถย้ายโฮโลเมนนี้ไปที่ตำแหน่งแบ็กได้","name":"แผนที่ที่แผ่ขยาย"},"name":"AZKi","tags":["#JP","#รุ่น 0","#เพลง"]}}}', '{}', '7fe82c9277c3957451d935dee334184daa099dba0aee466b60b32ad9fdce298c', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
