INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('197', 'hPR-001', 'character', 'P', 'spot', 'hPR/hPR-001_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hPR-001_P.png', 50, NULL, 1, '["null"]', '信澤 収/もちぷよ', 'さくらみこ', '{"arts":[{"cost_types":["null"],"damage":10}],"card_sets":["PRカード"],"color_codes":["null"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"flower rhapsody"}],"keyword":{"effect":"You may roll a die once: If the result is 1, 3, or 5, reveal 1 [Red Cheer or Blue Cheer] from your Cheer Deck and send it to one of your Back holomem. Then shuffle your Cheer Deck.","name":"If I Could Become Someone''s New Bud"},"name":"Sakura Miko","tags":["#JP","#0th Gen","#Singing"]},"es":{"arts":[{"name":"flower rhapsody"}],"keyword":{"effect":"Puedes lanzar un dado 1 vez: si sale 1, 3 o 5, revela 1 carta [Red Cheer o Blue Cheer] de tu mazo de Cheer y ponla en tu holomen de la retaguardia. Luego baraja tu mazo de Cheer.","name":"Ojalá pueda ser el brote de alguien"},"name":"Sakura Miko","tags":["#JP","#0th Gen","#Singing"]},"id":{"arts":[{"name":"flower rhapsody"}],"keyword":{"effect":"Boleh melempar dadu 1 kali: jika hasilnya 1, 3, atau 5, ungkapkan 1 kartu [Yell Merah atau Yell Biru] dari Dek Elmu milikmu, lalu kirim ke Back holomen milikmu. Lalu, kocok Dek Elmu milikmu.","name":"Andai aku bisa menjadi awal tumbuhnya seseorang"},"name":"Sakura Miko","tags":["#JP","#Gen 0","#Menyanyi"]},"ja":{"arts":[{"name":"flower rhapsody"}],"keyword":{"effect":"サイコロを1回振れる:１か３か５の時、自分のエールデッキから、[赤エールか青エール]1枚を公開し、自分のバックホロメンに送る。そしてエールデッキをシャッフルする。","name":"誰かの芽吹きになれたら"},"name":"さくらみこ","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"name":"flower rhapsody"}],"keyword":{"effect":"주사위를 1번 굴릴 수 있다: 1, 3, 5가 나오면, 자신의 엘 덱에서 [레드 옐 또는 블루 옐] 1장을 공개하고 자신의 백 홀로멘에게 보낸다. 그 후 엘 덱을 셔플한다.","name":"누군가의 싹틈이 될 수 있다면"},"name":"사쿠라 미코","tags":["#JP","#0기생","#노래"]},"tc":{"arts":[{"name":"flower rhapsody"}],"keyword":{"effect":"可以擲1次骰子：若為1、3或5，則從自己的應援牌庫公開1張[紅色應援或藍色應援]，送到自己的後場holomen。然後將應援牌庫洗牌。","name":"若能成為某人的萌芽"},"name":"櫻巫女","tags":["#JP","#0期生","#歌唱"]},"th":{"arts":[{"name":"ราพโซดีแห่งดอกไม้"}],"keyword":{"effect":"ทอยลูกเต๋าได้ 1 ครั้ง: ถ้าออก 1, 3 หรือ 5 เปิดเผย [เยลสีแดง หรือ เยลสีน้ำเงิน] 1 ใบจากเด็คเยลของคุณ แล้วส่งไปยังแบ็กโฮโลเมนของคุณ จากนั้นสับเด็คเยล","name":"ถ้าฉันจะกลายเป็นต้นอ่อนของใครสักคนได้"},"name":"ซากุระ มิโกะ","tags":["#JP","#รุ่น 0","#เพลง"]}}}', '{}', 'b697efe3b69c9d9c0a08435bb694da41546b336f2d880b9ffe40992387798af1', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
