INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (198, 'hBP01-076', 'hBP01-076 水鈴 JP 0期生 歌 星街すいせい #JP #0期生 #歌 スターの原石 相手のバックホロメン1人に特殊ダメージ10を与える（ダウンしても相手のライフは減らない）。 Hoshimachi Suisei #JP #0th Gen #Singing A Star in the Rough Deal 10 special damage to 1 of the opponent''s Back holomem (even if it is downed, the opponent''s Life does not decrease). 星街彗星 #JP #0期生 #歌唱 明星原石 對對手1位後備Holo成員造成特殊傷害10（即使倒下，對手的生命值也不會減少）。 Hoshimachi Suisei #JP #Gen 0 #Menyanyi Batu Mentah Sang Bintang Berikan Special Damage 10 kepada 1 Back holomen lawan (meskipun menjadi Down, Life lawan tidak berkurang). 호시마치 스이세이 #JP #0기생 #노래 스타의 원석 상대의 백 홀로멤 1명에게 특수 대미지 10을 준다(다운되어도 상대의 라이프는 줄지 않는다). โฮชิมาชิ สุยเซย #JP #รุ่น 0 #เพลง อัญมณีดิบของดาวเด่น สร้างความเสียหายพิเศษ 10 ให้แก่แบ็คโฮโลเมนของฝ่ายตรงข้าม 1 คน (แม้จะดาวน์ก็จะไม่ทำให้ไลฟ์ของฝ่ายตรงข้ามลดลง) Hoshimachi Suisei #JP #0th Gen #Singing Una estrella en bruto Inflige 10 de daño especial a 1 holomen de la Retaguardia de tu oponente (aunque quede Fuera de Combate, la Vida de tu oponente no disminuye).', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('199', 'hBD24-001', 'oshiCharacter', 'P', NULL, 'hPR/hBD24-001_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBD24-001_P.png', NULL, 5, NULL, NULL, '飯田ぽち。', 'パヴォリア・レイネ', '{"card_sets":["PRカード"],"color_codes":["green"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Pavolia Reine","oshi_skill":{"effect":"[Once per turn] During this turn, 1 of your green holomem gets +20 Arts.","name":"GREEN ENHANCE","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] Reveal 1 green holomem from your deck and add it to your hand. Then shuffle your deck.","name":"Birthday Gift ~Green~","timing":"Once per game"}},"es":{"name":"Pavolia Reine","oshi_skill":{"effect":"[Una vez por turno] Durante este turno, las artes de 1 de tus holomen verdes obtienen +20.","name":"Mejora Verde","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Revela 1 holomen verde de tu mazo y ponlo en tu mano. Después, baraja el mazo.","name":"Regalo de cumpleaños ~Verde~","timing":"Una vez por partida"}},"id":{"name":"Pavolia Reine","oshi_skill":{"effect":"[Sekali per giliran] Selama giliran ini, Arts 1 holomen hijau milikmu +20.","name":"Peningkatan Hijau","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per game] Ungkapkan 1 holomem hijau dari deck-mu, lalu tambahkan ke tanganmu. Kemudian kocok deck-mu.","name":"Hadiah Ulang Tahun ～Hijau～","timing":"Sekali per permainan"}},"ja":{"name":"パヴォリア・レイネ","oshi_skill":{"effect":"[ターンに1回]このターンの間、自分の緑ホロメン1人のアーツ+20。","name":"グリーンエンハンス","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]自分のデッキから、緑ホロメン1枚を公開し、手札に加える。そしてデッキをシャッフルする。","name":"Birthday Gift ～Green～","timing":"ゲームに1回"}},"ko":{"name":"파볼리아 레이네","oshi_skill":{"effect":"[턴에 1번]이번 턴 동안 자신의 초록 홀로멘 1명의 아츠+20.","name":"그린 인핸스","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번] 자신의 덱에서 초록색 홀로멘 1장을 공개하여 패에 넣는다. 그리고 덱을 셔플한다.","name":"Birthday Gift ~Green~","timing":"게임에 1번"}},"tc":{"name":"Pavolia Reine","oshi_skill":{"effect":"[每回合1次]在這個回合期間，自己的1名綠色holomen的藝術+20。","name":"綠色強化","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場遊戲1次]從自己的牌組公開1張綠色Holo成員，加入手牌。然後將牌組洗牌。","name":"Birthday Gift ～Green～","timing":"每場對戰1次"}},"th":{"name":"ปาโวเลีย เรเน่","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] ในเทิร์นนี้ อาร์ตของโฮโลเมนสีเขียวของคุณ 1 คน +20","name":"เสริมพลังสีเขียว","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] เปิดเผยโฮโลเมนสีเขียว 1 ใบจากเด็คของคุณ แล้วเพิ่มขึ้นมือ จากนั้นสับเด็ค","name":"Birthday Gift ~Green~","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{}', '43866a70e50f836d15e6ab01100cfff2e9adc30409764610c3a3c8cd71d9a058', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
