INSERT INTO card_tags (tag, card_id) VALUES ('絵', '204');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (204, 'hBP01-019', 'hBP01-019 EN Promise トリ 絵 七詩ムメイ #EN #Promise #トリ #絵 いつも応援してくれてありがとう！ みんなと歌って踊りたい！ DebutからBloomした時、自分のデッキから、#Promiseを持つBuzz以外の[Debutホロメンか1stホロメン]1枚を公開し、手札に加える。そしてデッキをシャッフルする。 Nanashi Mumei #EN #Promise #Bird #Art Thank You for Always Supporting Me! I Want to Sing and Dance With Everyone! When Blooming from Debut, reveal 1 [Debut holomem or 1st holomem] other than Buzz with #Promise from your deck and add it to your hand. Then shuffle your deck. 七詩ムメイ #EN #Promise #小鳥 #繪畫 謝謝大家一直以來的支持！ 想和大家一起唱歌跳舞！ 從Debut Bloom時，從自己的牌庫中公開1張持有#Promise且不是Buzz的[Debut Holomen或1st Holomen]，加入手牌。然後將牌庫洗牌。 Nanashi Mumei #EN #Promise #Burung #Seni Terima kasih selalu mendukungku! Aku ingin bernyanyi dan menari bersama semua orang! Saat Bloom dari Debut, ungkapkan 1 [Debut Holomen atau 1st Holomen] selain Buzz yang memiliki #Promise dari dekmu, lalu tambahkan ke tanganmu. Lalu kocok dekmu. 나나시 무메이 #EN #Promise #새 #그림 항상 응원해줘서 고마워! 모두와 노래하고 춤추고 싶어! Debut에서 Bloom했을 때, 자신의 덱에서 #Promise를 가진 Buzz 이외의 [Debut 홀로멤 또는 1st 홀로멤] 1장을 공개하고, 손패에 넣는다. 그리고 덱을 셔플한다. นานาชิ มุเมอิ #EN #Promise #นก #ศิลปะ ขอบคุณที่คอยเชียร์กันเสมอ! อยากร้องอยากเต้นกับทุกคน! เมื่อบลูมจาก Debut ให้เปิดเผย [Debut โฮโลเมนหรือ 1st โฮโลเมน] 1 ใบที่มี #Promise และไม่ใช่ Buzz จากเด็คของคุณ แล้วนำขึ้นมือ จากนั้นสับเด็ค Nanashi Mumei #EN #Promise #Bird #Art ¡Gracias por apoyarme siempre! ¡Quiero cantar y bailar con todos! Cuando haga Bloom desde Debut, revela 1 [Debut holomen o 1st holomen] que no sea Buzz y que tenga #Promise de tu mazo, y añádelo a tu mano. Luego baraja tu mazo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('205', 'hBP01-022', 'character', 'P', 'first', 'hPR/hBP01-022_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP01-022_P.png', 110, NULL, 1, '["null"]', NULL, 'ときのそら', '{"arts":[{"cost_types":["null"],"damage":40}],"card_sets":["PRカード"],"color_codes":["white"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"Let’s Make This the Best Day Ever♪"}],"keyword":{"effect":"Draw 1 card from your deck.","name":"Are You Ready to Have Fun!?"},"name":"Tokino Sora","tags":["#JP","#0th Gen","#Singing"]},"es":{"arts":[{"name":"Hagamos de hoy el mejor día♪"}],"keyword":{"effect":"Roba 1 carta de tu mazo.","name":"¿¡Están listos para divertirse!?"},"name":"Tokino Sora","tags":["#JP","#0th Gen","#Singing"]},"id":{"arts":[{"name":"Mari jadikan hari ini yang terbaik♪"}],"keyword":{"effect":"Tarik 1 kartu dari dekmu.","name":"Sudah siap untuk bersenang-senang!?"},"name":"Tokino Sora","tags":["#JP","#Gen 0","#Menyanyi"]},"ja":{"arts":[{"name":"最高の一日にしようね♪"}],"keyword":{"effect":"自分のデッキを1枚引く。","name":"楽しむ準備はできてる！？"},"name":"ときのそら","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"name":"최고의 하루로 만들자♪"}],"keyword":{"effect":"자신의 덱을 1장 뽑는다.","name":"즐길 준비는 됐어!?"},"name":"토키노 소라","tags":["#JP","#0기생","#노래"]},"tc":{"arts":[{"name":"一起度過最棒的一天吧♪"}],"keyword":{"effect":"自己抽1張牌。","name":"做好享受的準備了嗎！？"},"name":"時乃空","tags":["#JP","#0期生","#歌唱"]},"th":{"arts":[{"name":"มาทำให้เป็นวันที่ดีที่สุดกันเถอะ♪"}],"keyword":{"effect":"จั่วการ์ดจากเด็คของคุณ 1 ใบ","name":"พร้อมจะสนุกกันหรือยัง!?"},"name":"โตกิโนะ โซระ","tags":["#JP","#รุ่น 0","#เพลง"]}}}', '{}', '4f949d54353fc89ec56294e806d56112dacbb8a3ae23eb7b97a6246876844f5a', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
