INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (205, 'hBP01-022', 'hBP01-022 JP 0期生 歌 ときのそら #JP #0期生 #歌 最高の一日にしようね♪ 楽しむ準備はできてる！？ 自分のデッキを1枚引く。 Tokino Sora #JP #0th Gen #Singing Let’s Make This the Best Day Ever♪ Are You Ready to Have Fun!? Draw 1 card from your deck. 時乃空 #JP #0期生 #歌唱 一起度過最棒的一天吧♪ 做好享受的準備了嗎！？ 自己抽1張牌。 Tokino Sora #JP #Gen 0 #Menyanyi Mari jadikan hari ini yang terbaik♪ Sudah siap untuk bersenang-senang!? Tarik 1 kartu dari dekmu. 토키노 소라 #JP #0기생 #노래 최고의 하루로 만들자♪ 즐길 준비는 됐어!? 자신의 덱을 1장 뽑는다. โตกิโนะ โซระ #JP #รุ่น 0 #เพลง มาทำให้เป็นวันที่ดีที่สุดกันเถอะ♪ พร้อมจะสนุกกันหรือยัง!? จั่วการ์ดจากเด็คของคุณ 1 ใบ Tokino Sora #JP #0th Gen #Singing Hagamos de hoy el mejor día♪ ¿¡Están listos para divertirse!? Roba 1 carta de tu mazo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('206', 'hBP01-026', 'character', 'P', 'first', 'hPR/hBP01-026_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP01-026_P.png', 110, NULL, 1, '["null"]', NULL, 'ベスティア・ゼータ', '{"arts":[{"cost_types":["null"],"damage":30}],"card_sets":["PRカード","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["white"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"The Stage, Everyone—\"Mine\""}],"keyword":{"effect":"When this holomem Blooms from Debut, reveal 1 non-Buzz [Debut holomem or 1st holomem] with #ID 3rd Gen from your deck and add it to your hand. Then shuffle your deck.","name":"A New Destiny"},"name":"Vestia Zeta","tags":["#ID","#ID 3rd Gen"]},"es":{"arts":[{"name":"En el escenario, todo el mundo es «mío»"}],"keyword":{"effect":"Cuando hace Bloom desde Debut, revela 1 [Debut holomember o 1st holomember] que no sea Buzz y que tenga #ID 3rd Gen de tu mazo, y añádelo a tu mano. Después, baraja tu mazo.","name":"Un nuevo destino"},"name":"Vestia Zeta","tags":["#ID","#ID 3rd Gen"]},"id":{"arts":[{"name":"Panggung ini semuanya “milikku”"}],"keyword":{"effect":"Saat melakukan Bloom dari Debut, buka 1 kartu [Debut holomen atau 1st holomen] non-Buzz yang memiliki #ID Gen 3 dari dekmu, tambahkan ke tanganmu. Setelah itu, kocok dekmu.","name":"Takdir baru"},"name":"Vestia Zeta","tags":["#ID","#ID Gen 3"]},"ja":{"arts":[{"name":"ステージみんな「私のもの」"}],"keyword":{"effect":"DebutからBloomした時、自分のデッキから、#ID3期生を持つBuzz以外の[Debutホロメンか1stホロメン]1枚を公開し、手札に加える。そしてデッキをシャッフルする。","name":"新たな運命"},"name":"ベスティア・ゼータ","tags":["#ID","#ID3期生"]},"ko":{"arts":[{"name":"스테이지 모두 「내 것」"}],"keyword":{"effect":"Debut에서 Bloom했을 때, 자신의 덱에서 #ID 3기생를 가진 Buzz가 아닌 [Debut 홀로멘 또는 1st 홀로멘] 1장을 공개하고, 패에 넣는다. 그리고 덱을 셔플한다.","name":"새로운 운명"},"name":"베스티아 제타","tags":["#ID","#ID 3기생"]},"tc":{"arts":[{"name":"舞台和大家都是「我的東西」"}],"keyword":{"effect":"從Debut Bloom時，從自己的牌庫公開1張帶有#ID3期生、且不是Buzz的[Debut holomen或1st holomen]，加入手牌。然後將牌庫洗牌。","name":"新的命運"},"name":"Vestia Zeta","tags":["#ID","#ID3期生"]},"th":{"arts":[{"name":"บนเวที ทุกคนล้วนเป็น『ของฉัน』"}],"keyword":{"effect":"เมื่อ Bloom จาก Debut ให้อวด [Debutโฮโลเมน หรือ 1stโฮโลเมน] 1 ใบที่มี #ID รุ่น 3 และไม่ใช่ Buzz จากเด็คของคุณ แล้วนำเข้ามือ จากนั้นสับเด็ค","name":"โชคชะตาใหม่"},"name":"เวสเทีย เซตา","tags":["#ID","#ID รุ่น 3"]}}}', '{}', '3a7fe614e541ef36128b7246a8761f93b9641ca08d8447df0990ac17f63b7f65', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
