INSERT INTO card_tags (tag, card_id) VALUES ('ID3期生', '206');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (206, 'hBP01-026', 'hBP01-026 ID ID3期生 ベスティア・ゼータ #ID #ID3期生 ステージみんな「私のもの」 新たな運命 DebutからBloomした時、自分のデッキから、#ID3期生を持つBuzz以外の[Debutホロメンか1stホロメン]1枚を公開し、手札に加える。そしてデッキをシャッフルする。 Vestia Zeta #ID #ID 3rd Gen The Stage, Everyone—"Mine" A New Destiny When this holomem Blooms from Debut, reveal 1 non-Buzz [Debut holomem or 1st holomem] with #ID 3rd Gen from your deck and add it to your hand. Then shuffle your deck. Vestia Zeta #ID #ID3期生 舞台和大家都是「我的東西」 新的命運 從Debut Bloom時，從自己的牌庫公開1張帶有#ID3期生、且不是Buzz的[Debut holomen或1st holomen]，加入手牌。然後將牌庫洗牌。 Vestia Zeta #ID #ID Gen 3 Panggung ini semuanya “milikku” Takdir baru Saat melakukan Bloom dari Debut, buka 1 kartu [Debut holomen atau 1st holomen] non-Buzz yang memiliki #ID Gen 3 dari dekmu, tambahkan ke tanganmu. Setelah itu, kocok dekmu. 베스티아 제타 #ID #ID 3기생 스테이지 모두 「내 것」 새로운 운명 Debut에서 Bloom했을 때, 자신의 덱에서 #ID 3기생를 가진 Buzz가 아닌 [Debut 홀로멘 또는 1st 홀로멘] 1장을 공개하고, 패에 넣는다. 그리고 덱을 셔플한다. เวสเทีย เซตา #ID #ID รุ่น 3 บนเวที ทุกคนล้วนเป็น『ของฉัน』 โชคชะตาใหม่ เมื่อ Bloom จาก Debut ให้อวด [Debutโฮโลเมน หรือ 1stโฮโลเมน] 1 ใบที่มี #ID รุ่น 3 และไม่ใช่ Buzz จากเด็คของคุณ แล้วนำเข้ามือ จากนั้นสับเด็ค Vestia Zeta #ID #ID 3rd Gen En el escenario, todo el mundo es «mío» Un nuevo destino Cuando hace Bloom desde Debut, revela 1 [Debut holomember o 1st holomember] que no sea Buzz y que tenga #ID 3rd Gen de tu mazo, y añádelo a tu mano. Después, baraja tu mazo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('207', 'hBP01-030', 'character', 'P', 'first', 'hPR/hBP01-030_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP01-030_P.png', 110, NULL, 1, '["null"]', NULL, 'IRyS', '{"arts":[{"cost_types":["null"],"damage":40}],"card_sets":["PRカード"],"color_codes":["white"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"I''ll sing my heart out, so watch me!"}],"keyword":{"effect":"During this turn, your [Center holomem and Collab holomem] with #Promise get +30 Arts.","name":"Let''s Wrap the Stage in Hope!"},"name":"IRyS","tags":["#EN","#Promise","#Singing"]},"es":{"arts":[{"name":"¡Voy a cantar con todas mis fuerzas, así que mírame!"}],"keyword":{"effect":"Durante este turno, las Arts de tus [holomen central y holomen de Colaboración] con #Promise obtienen +30.","name":"¡Envolvamos el escenario con esperanza!"},"name":"IRyS","tags":["#EN","#Promise","#Singing"]},"id":{"arts":[{"name":"Aku bakal nyanyi sepenuh hati, jadi lihat aku ya!"}],"keyword":{"effect":"Selama giliran ini, Arts [Center Holomen dan Collab Holomen] milikmu yang memiliki #Promise +30.","name":"Mari selimuti panggung dengan harapan!"},"name":"IRyS","tags":["#EN","#Promise","#Menyanyi"]},"ja":{"arts":[{"name":"一生懸命歌うから見ててね！"}],"keyword":{"effect":"このターンの間、自分の#Promiseを持つ[センターホロメンとコラボホロメン]のアーツ+30。","name":"ステージを希望で包もう！"},"name":"IRyS","tags":["#EN","#Promise","#歌"]},"ko":{"arts":[{"name":"열심히 노래할 테니까 봐줘!"}],"keyword":{"effect":"이번 턴 동안, 자신의 #Promise를 가진 [센터 홀로멘과 콜라보 홀로멘]의 아츠+30.","name":"스테이지를 희망으로 감싸자!"},"name":"IRyS","tags":["#EN","#Promise","#노래"]},"tc":{"arts":[{"name":"我會努力唱歌，請看著我喔！"}],"keyword":{"effect":"本回合內，自己持有#Promise的[中心holomen與合作holomen]的藝能+30。","name":"用希望包覆舞台吧！"},"name":"IRyS","tags":["#EN","#Promise","#歌唱"]},"th":{"arts":[{"name":"จะร้องสุดใจเลย คอยดูนะ!"}],"keyword":{"effect":"จนจบเทิร์นนี้ Arts ของ[เซ็นเตอร์โฮโลเมนและคอลแลบโฮโลเมน]ของคุณที่มี #Promise +30","name":"โอบเวทีนี้ด้วยความหวังกันเถอะ!"},"name":"IRyS","tags":["#EN","#Promise","#เพลง"]}}}', '{}', '8998d97114b8cb0d4276ea815c5c0ece064ab64a7ef42e2171a75e7e83dfe837', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
