INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (207, 'hBP01-030', 'hBP01-030 EN Promise 歌 IRyS #EN #Promise #歌 一生懸命歌うから見ててね！ ステージを希望で包もう！ このターンの間、自分の#Promiseを持つ[センターホロメンとコラボホロメン]のアーツ+30。 IRyS #EN #Promise #Singing I''ll sing my heart out, so watch me! Let''s Wrap the Stage in Hope! During this turn, your [Center holomem and Collab holomem] with #Promise get +30 Arts. IRyS #EN #Promise #歌唱 我會努力唱歌，請看著我喔！ 用希望包覆舞台吧！ 本回合內，自己持有#Promise的[中心holomen與合作holomen]的藝能+30。 IRyS #EN #Promise #Menyanyi Aku bakal nyanyi sepenuh hati, jadi lihat aku ya! Mari selimuti panggung dengan harapan! Selama giliran ini, Arts [Center Holomen dan Collab Holomen] milikmu yang memiliki #Promise +30. IRyS #EN #Promise #노래 열심히 노래할 테니까 봐줘! 스테이지를 희망으로 감싸자! 이번 턴 동안, 자신의 #Promise를 가진 [센터 홀로멘과 콜라보 홀로멘]의 아츠+30. IRyS #EN #Promise #เพลง จะร้องสุดใจเลย คอยดูนะ! โอบเวทีนี้ด้วยความหวังกันเถอะ! จนจบเทิร์นนี้ Arts ของ[เซ็นเตอร์โฮโลเมนและคอลแลบโฮโลเมน]ของคุณที่มี #Promise +30 IRyS #EN #Promise #Singing ¡Voy a cantar con todas mis fuerzas, así que mírame! ¡Envolvamos el escenario con esperanza! Durante este turno, las Arts de tus [holomen central y holomen de Colaboración] con #Promise obtienen +30.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('208', 'hBP01-036', 'character', 'P', 'first', 'hPR/hBP01-036_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP01-036_P.png', 100, NULL, 1, '["null"]', NULL, 'アキ・ローゼンタール', '{"arts":[{"cost_types":["null"],"damage":30}],"card_sets":["PRカード"],"color_codes":["green"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Let''s Do Our Best-Rose Today Too!"}],"keyword":{"effect":"Heal 20 HP from 1 of your holomems.","name":"Everyone, cheer for Rose-tai, okay!"},"name":"Aki Rosenthal","tags":["#JP","#1st Gen","#Half-Elf","#Alcohol"]},"es":{"arts":[{"name":"¡Hoy también, a darlo todo, Rose!"}],"keyword":{"effect":"Cura 20 HP a 1 de tus holomen.","name":"¡Todos, apoyen a Rose-tai, ¿sí?!"},"name":"Aki Rosenthal","tags":["#JP","#1st Gen","#Half-Elf","#Alcohol"]},"id":{"arts":[{"name":"Hari ini juga semangat, rose!"}],"keyword":{"effect":"Pulihkan 20 HP 1 holomen milikmu.","name":"Semuanya, dukung Tim Rose ya!"},"name":"Aki Rosenthal","tags":["#JP","#Gen 1","#Setengah Elf","#Alkohol"]},"ja":{"arts":[{"name":"今日もがんばローゼ！"}],"keyword":{"effect":"自分のホロメン1人のHP20回復。","name":"ロゼ隊のみんな応援しててね！"},"name":"アキ・ローゼンタール","tags":["#JP","#1期生","#ハーフエルフ","#お酒"]},"ko":{"arts":[{"name":"오늘도 힘내로제!"}],"keyword":{"effect":"자신의 홀로멘 1명의 HP를 20 회복한다.","name":"로제대의 모두들 응원해줘!"},"name":"아키 로젠탈","tags":["#JP","#1기생","#하프엘프","#술"]},"tc":{"arts":[{"name":"今天也要加油薔薇！"}],"keyword":{"effect":"自己的1位holomen回復HP20。","name":"請大家為Rose-tai加油喔！"},"name":"亞綺・羅森塔爾","tags":["#JP","#1期生","#半精靈","#酒"]},"th":{"arts":[{"name":"วันนี้ก็สู้ไปพร้อมโรเซ่!"}],"keyword":{"effect":"ฟื้นฟู HP 20 ให้โฮโลเมนของคุณ 1 คน","name":"ทุกคนของ ทีมโรเซ่ ช่วยเชียร์กันด้วยนะ!"},"name":"อากิ โรเซนธาล","tags":["#JP","#รุ่น 1","#ฮาล์ฟเยลฟ์","#แอลกอฮอล์"]}}}', '{}', 'b53149dba0b60e50a8e850ca050757bc8ffd3377bbcafa84a1ba362ac6704b21', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
