INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (208, 'hBP01-036', 'hBP01-036 JP 1期生 ハーフエルフ お酒 アキ・ローゼンタール #JP #1期生 #ハーフエルフ #お酒 今日もがんばローゼ！ ロゼ隊のみんな応援しててね！ 自分のホロメン1人のHP20回復。 Aki Rosenthal #JP #1st Gen #Half-Elf #Alcohol Let''s Do Our Best-Rose Today Too! Everyone, cheer for Rose-tai, okay! Heal 20 HP from 1 of your holomems. 亞綺・羅森塔爾 #JP #1期生 #半精靈 #酒 今天也要加油薔薇！ 請大家為Rose-tai加油喔！ 自己的1位holomen回復HP20。 Aki Rosenthal #JP #Gen 1 #Setengah Elf #Alkohol Hari ini juga semangat, rose! Semuanya, dukung Tim Rose ya! Pulihkan 20 HP 1 holomen milikmu. 아키 로젠탈 #JP #1기생 #하프엘프 #술 오늘도 힘내로제! 로제대의 모두들 응원해줘! 자신의 홀로멘 1명의 HP를 20 회복한다. อากิ โรเซนธาล #JP #รุ่น 1 #ฮาล์ฟเยลฟ์ #แอลกอฮอล์ วันนี้ก็สู้ไปพร้อมโรเซ่! ทุกคนของ ทีมโรเซ่ ช่วยเชียร์กันด้วยนะ! ฟื้นฟู HP 20 ให้โฮโลเมนของคุณ 1 คน Aki Rosenthal #JP #1st Gen #Half-Elf #Alcohol ¡Hoy también, a darlo todo, Rose! ¡Todos, apoyen a Rose-tai, ¿sí?! Cura 20 HP a 1 de tus holomen.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('209', 'hBP01-041', 'character', 'P', 'first', 'hPR/hBP01-041_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP01-041_P.png', 90, NULL, 1, '["null"]', NULL, '兎田ぺこら', '{"arts":[{"cost_types":["null"],"damage":30}],"card_sets":["PRカード","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["green"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"Don''t Miss It, Peko!"}],"keyword":{"effect":"Send the top card of your Cheer Deck to your Center holomem or Collab holomem.","name":"The Grown-Up Usada Pekora"},"name":"Usada Pekora","tags":["#JP","#3rd Gen","#Animal Ears"]},"es":{"arts":[{"name":"¡No te lo pierdas, peko!"}],"keyword":{"effect":"Envía la carta superior de tu mazo de Cheer a tu holomember central o a tu holomember de Colaboración.","name":"A Usada Pekora que ha crecido"},"name":"Usada Pekora","tags":["#JP","#3rd Gen","#Animal Ears"]},"id":{"arts":[{"name":"Jangan sampai kelewatan, peko ya!"}],"keyword":{"effect":"Kirim 1 kartu teratas dari Cheer Deck milikmu ke Center holomen atau Collab holomen milikmu.","name":"Usada Pekora yang telah tumbuh"},"name":"Usada Pekora","tags":["#JP","#Gen 3","#Telinga Hewan"]},"ja":{"arts":[{"name":"見逃しちゃだめぺこだよ！"}],"keyword":{"effect":"自分のエールデッキの上から1枚を、自分のセンターホロメンかコラボホロメンに送る。","name":"成長した兎田ぺこらを"},"name":"兎田ぺこら","tags":["#JP","#3期生","#ケモミミ"]},"ko":{"arts":[{"name":"놓치면 안 된다페코!"}],"keyword":{"effect":"자신의 엘 덱 맨 위에서 1장을 자신의 센터 홀로멘 또는 콜라보 홀로멘에게 보낸다.","name":"성장한 우사다 페코라를"},"name":"우사다 페코라","tags":["#JP","#3기생","#수인귀"]},"tc":{"arts":[{"name":"可別錯過了佩可喔！"}],"keyword":{"effect":"將自己應援牌庫頂1張附加給自己的Center holomen或Collaborator holomen。","name":"成長後的兔田佩克拉"},"name":"兔田佩克拉","tags":["#JP","#3期生","#獸耳"]},"th":{"arts":[{"name":"ห้ามพลาดเด็ดขาดเปโกะ!"}],"keyword":{"effect":"ส่งการ์ดใบบนสุดของเยลเด็คของคุณไปยังเซ็นเตอร์โฮโลเมนหรือโคลาโบโฮโลเมนของคุณ","name":"ตัว อุซาดะ เปโคระ ที่เติบโตขึ้น"},"name":"อุซาดะ เปโคระ","tags":["#JP","#รุ่น 3","#หูสัตว์"]}}}', '{}', 'ee334a1d889ad30deade91aa87261f1a0d5d1ce477c78619dac77a3204e92c9b', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
