INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (209, 'hBP01-041', 'hBP01-041 JP 3期生 ケモミミ 兎田ぺこら #JP #3期生 #ケモミミ 見逃しちゃだめぺこだよ！ 成長した兎田ぺこらを 自分のエールデッキの上から1枚を、自分のセンターホロメンかコラボホロメンに送る。 Usada Pekora #JP #3rd Gen #Animal Ears Don''t Miss It, Peko! The Grown-Up Usada Pekora Send the top card of your Cheer Deck to your Center holomem or Collab holomem. 兔田佩克拉 #JP #3期生 #獸耳 可別錯過了佩可喔！ 成長後的兔田佩克拉 將自己應援牌庫頂1張附加給自己的Center holomen或Collaborator holomen。 Usada Pekora #JP #Gen 3 #Telinga Hewan Jangan sampai kelewatan, peko ya! Usada Pekora yang telah tumbuh Kirim 1 kartu teratas dari Cheer Deck milikmu ke Center holomen atau Collab holomen milikmu. 우사다 페코라 #JP #3기생 #수인귀 놓치면 안 된다페코! 성장한 우사다 페코라를 자신의 엘 덱 맨 위에서 1장을 자신의 센터 홀로멘 또는 콜라보 홀로멘에게 보낸다. อุซาดะ เปโคระ #JP #รุ่น 3 #หูสัตว์ ห้ามพลาดเด็ดขาดเปโกะ! ตัว อุซาดะ เปโคระ ที่เติบโตขึ้น ส่งการ์ดใบบนสุดของเยลเด็คของคุณไปยังเซ็นเตอร์โฮโลเมนหรือโคลาโบโฮโลเมนของคุณ Usada Pekora #JP #3rd Gen #Animal Ears ¡No te lo pierdas, peko! A Usada Pekora que ha crecido Envía la carta superior de tu mazo de Cheer a tu holomember central o a tu holomember de Colaboración.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('210', 'hBP01-046', 'character', 'P', 'first', 'hPR/hBP01-046_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP01-046_P.png', 100, NULL, 1, '["null"]', NULL, 'AZKi', '{"arts":[{"cost_types":["null"],"damage":30}],"card_sets":["PRカード"],"color_codes":["green"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"I Made It to Such a Wonderful World!"}],"keyword":{"effect":"Choose 1 to 3 Cheer on your Stage, and you may redistribute and reattach them among your holomems.","name":"Because Everyone in Pioneer Was There"},"name":"AZKi","tags":["#JP","#0th Gen","#Singing"]},"es":{"arts":[{"name":"¡He podido llegar a un mundo tan maravilloso!"}],"keyword":{"effect":"Elige de 1 a 3 Cheer de tu escenario y puedes redistribuirlos entre tus holomem cambiándolos de adjunto.","name":"Porque estaban todos los de Pioneer"},"name":"AZKi","tags":["#JP","#0th Gen","#Singing"]},"id":{"arts":[{"name":"Aku bisa datang ke dunia seindah ini!"}],"keyword":{"effect":"Pilih 1 sampai 3 Cheer di Stage milikmu, lalu kamu dapat membaginya dan memindahkannya ke holomem milikmu.","name":"Karena ada kalian semua dari Perintis"},"name":"AZKi","tags":["#JP","#Gen 0","#Menyanyi"]},"ja":{"arts":[{"name":"こんな素敵な世界に来れました！"}],"keyword":{"effect":"自分のステージのエール1～3枚を選び、自分のホロメンに割り振って付け替えられる。","name":"開拓者のみんながいたから"},"name":"AZKi","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"name":"이런 멋진 세상에 올 수 있었어요!"}],"keyword":{"effect":"자신의 스테이지의 에일 1~3장을 선택해 자신의 홀로멤에게 나누어 갈아붙일 수 있다.","name":"개척자의 모두가 있었으니까"},"name":"AZKi","tags":["#JP","#0기생","#노래"]},"tc":{"arts":[{"name":"能來到這麼美好的世界了！"}],"keyword":{"effect":"選擇自己舞台上的1～3張Cheers，可以分配後改裝到自己的Holo成員上。","name":"因為有開拓者的大家在"},"name":"AZKi","tags":["#JP","#0期生","#歌唱"]},"th":{"arts":[{"name":"ได้มาถึงโลกที่แสนวิเศษแบบนี้แล้ว!"}],"keyword":{"effect":"เลือกเยล 1 ถึง 3 ใบบนสเตจของคุณ แล้วคุณสามารถแจกจ่ายและย้ายไปติดกับโฮโลเมนของคุณใหม่ได้","name":"เพราะมีทุกคนของ ผู้บุกเบิก อยู่ด้วย"},"name":"AZKi","tags":["#JP","#รุ่น 0","#เพลง"]}}}', '{}', '3640e80bcd770904c24b182d8c48d818de7a9537e117ba5ce1584d269d97a790', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
