INSERT INTO card_sets (set_name, card_id) VALUES ('PRカード', '211');
INSERT INTO card_sets (set_name, card_id) VALUES ('【使用可能カード】hGS 2026 大阪 セレクションロード', '211');
INSERT INTO card_tags (tag, card_id) VALUES ('JP', '211');
INSERT INTO card_tags (tag, card_id) VALUES ('秘密結社holoX', '211');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (211, 'hBP01-050', 'hBP01-050 JP 秘密結社holoX 風真いろは #JP #秘密結社holoX 元気を全力でお届けします！ 自分のエールデッキの上から1枚を、自分の〈風真いろは〉以外の#秘密結社holoXを持つホロメンに送る。 用心棒 [コラボポジション限定]相手のホロメンのアーツは、自分のコラボホロメンしか対象にできない（特殊ダメージは除く）。 Kazama Iroha #JP #Secret Society holoX Delivering Energy with All I''ve Got! Send the top card of your Cheer Deck to your holomem with #Secret Society holoX other than your 〈Kazama Iroha〉. Bodyguard [Collab Position only] Your opponent''s holomems'' Arts can only target your Collab holomem (excluding special damage). 風真伊呂波 #JP #秘密結社holoX 我會全力把元氣送給大家！ 將自己應援牌庫頂的1張牌送給自己持有#秘密結社holoX且不是〈風真伊呂波〉的Holomen。 保鑣 [僅限合作位置]對手holomen的藝能只能以自己的合作holomen為對象（特殊傷害除外）。 Kazama Iroha #JP #Organisasi Rahasia holoX Aku akan mengirimkan semangat sepenuh tenaga! Kirim 1 kartu teratas dari dek Cheer milikmu ke holomen milikmu yang memiliki #Organisasi Rahasia holoX selain 〈Kazama Iroha〉 milikmu. Pengawal [Khusus Posisi Collab] Arts holomen lawan hanya dapat menargetkan Collab Holomen milikmu (tidak termasuk Special Damage). 카자마 이로하 #JP #비밀결사 holoX 기운을 온 힘 다해 전해드립니다! 자신의 에일 덱 위에서부터 1장을 자신의 〈카자마 이로하〉 이외의 #비밀결사 holoX를 가진 홀로멘에게 보낸다. 호위무사 [콜라보 포지션 한정] 상대 홀로멘의 아츠는 자신의 콜라보 홀로멘만 대상으로 할 수 있다(특수 대미지는 제외). คาซามะ อิโรฮะ #JP #องค์กรลับ holoX จะส่งพลังสดใสให้เต็มกำลังเลยค่ะ! ส่งการ์ด 1 ใบจากบนสุดของเอิลเด็คของคุณไปยังโฮโลเมมของคุณที่มี #องค์กรลับ holoX ซึ่งไม่ใช่ 〈คาซามะ อิโรฮะ〉 บอดี้การ์ด [จำกัดเฉพาะตำแหน่งคอลแลบ] Arts ของโฮโลเมนคู่ต่อสู้สามารถเลือกเป้าหมายได้เฉพาะคอลแลบโฮโลเมนของคุณเท่านั้น (ยกเว้นแดเมจพิเศษ) Kazama Iroha #JP #Secret Society holoX ¡Les traigo energía con toda mi fuerza! Envía la carta de la parte superior de tu mazo de Cheer a un holomen con #Secret Society holoX que no sea tu 〈Kazama Iroha〉. Guardaespaldas [Solo posición de Colaboración] Las Arts de los holomen del oponente solo pueden elegir como objetivo a tu holomen de Colaboración (excepto el daño especial).', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('212', 'hBP01-054', 'character', 'P', 'first', 'hPR/hBP01-054_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP01-054_P.png', 120, NULL, 1, '["null"]', NULL, 'アイラニ・イオフィフティーン', '{"arts":[{"cost_types":["null"],"damage":30}],"card_sets":["PRカード","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["green"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"I''m looking forward to it!"}],"keyword":{"effect":"Send the top card of your Cheer Deck to your holomem with #ID other than your 〈Airani Iofifteen〉.","name":"A Sea Spreading with Green Light"},"name":"Airani Iofifteen","tags":["#ID","#ID 1st Gen","#Art"]},"es":{"arts":[{"name":"¡Tengo muchas ganas!"}],"keyword":{"effect":"Envía la carta superior de tu mazo Cheer a uno de tus holomen con #ID que no sea tu 〈Airani Iofifteen〉.","name":"El mar donde se expande la luz verde"},"name":"Airani Iofifteen","tags":["#ID","#ID 1st Gen","#Art"]},"id":{"arts":[{"name":"Aku nggak sabar menantikannya!"}],"keyword":{"effect":"Kirim 1 kartu teratas dari Cheer Deck milikmu ke Holomen milikmu yang memiliki #ID selain 〈Airani Iofifteen〉 milikmu.","name":"Lautan tempat cahaya hijau meluas"},"name":"Airani Iofifteen","tags":["#ID","#ID Gen 1","#Seni"]},"ja":{"arts":[{"name":"楽しみにしてるよ！"}],"keyword":{"effect":"自分のエールデッキの上から1枚を、自分の〈アイラニ・イオフィフティーン〉以外の#IDを持つホロメンに送る。","name":"緑の光が広がる海"},"name":"アイラニ・イオフィフティーン","tags":["#ID","#ID1期生","#絵"]},"ko":{"arts":[{"name":"기대하고 있을게!"}],"keyword":{"effect":"자신의 엘 덱 위에서부터 1장을 자신의 〈아이라니 이오피피틴〉 이외의 #ID를 가진 홀로멤에게 보낸다.","name":"초록빛이 퍼지는 바다"},"name":"아이라니 이오피피틴","tags":["#ID","#ID 1기생","#그림"]},"tc":{"arts":[{"name":"我很期待喔！"}],"keyword":{"effect":"將自己應援牌庫頂端1張卡送給自己1位持有#ID且不是〈艾拉妮・伊歐菲芙汀〉的Holomen。","name":"綠光蔓延的大海"},"name":"艾拉妮・伊歐菲芙汀","tags":["#ID","#ID1期生","#繪畫"]},"th":{"arts":[{"name":"ตั้งตารออยู่นะ!"}],"keyword":{"effect":"ส่งการ์ดบนสุดของเยลเด็คของคุณ 1 ใบไปยังโฮโลเมนของคุณที่มี #ID และไม่ใช่ 〈ไอราณี ไอโอฟิฟตีน〉","name":"ทะเลที่แสงสีเขียวแผ่ขยาย"},"name":"ไอราณี ไอโอฟิฟตีน","tags":["#ID","#ID รุ่น 1","#ศิลปะ"]}}}', '{}', 'd895638964dfb038bb68425a43842ec3082ddc96c4d2a997041d69cecef04ff0', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
