INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (212, 'hBP01-054', 'hBP01-054 ID ID1期生 絵 アイラニ・イオフィフティーン #ID #ID1期生 #絵 楽しみにしてるよ！ 緑の光が広がる海 自分のエールデッキの上から1枚を、自分の〈アイラニ・イオフィフティーン〉以外の#IDを持つホロメンに送る。 Airani Iofifteen #ID #ID 1st Gen #Art I''m looking forward to it! A Sea Spreading with Green Light Send the top card of your Cheer Deck to your holomem with #ID other than your 〈Airani Iofifteen〉. 艾拉妮・伊歐菲芙汀 #ID #ID1期生 #繪畫 我很期待喔！ 綠光蔓延的大海 將自己應援牌庫頂端1張卡送給自己1位持有#ID且不是〈艾拉妮・伊歐菲芙汀〉的Holomen。 Airani Iofifteen #ID #ID Gen 1 #Seni Aku nggak sabar menantikannya! Lautan tempat cahaya hijau meluas Kirim 1 kartu teratas dari Cheer Deck milikmu ke Holomen milikmu yang memiliki #ID selain 〈Airani Iofifteen〉 milikmu. 아이라니 이오피피틴 #ID #ID 1기생 #그림 기대하고 있을게! 초록빛이 퍼지는 바다 자신의 엘 덱 위에서부터 1장을 자신의 〈아이라니 이오피피틴〉 이외의 #ID를 가진 홀로멤에게 보낸다. ไอราณี ไอโอฟิฟตีน #ID #ID รุ่น 1 #ศิลปะ ตั้งตารออยู่นะ! ทะเลที่แสงสีเขียวแผ่ขยาย ส่งการ์ดบนสุดของเยลเด็คของคุณ 1 ใบไปยังโฮโลเมนของคุณที่มี #ID และไม่ใช่ 〈ไอราณี ไอโอฟิฟตีน〉 Airani Iofifteen #ID #ID 1st Gen #Art ¡Tengo muchas ganas! El mar donde se expande la luz verde Envía la carta superior de tu mazo Cheer a uno de tus holomen con #ID que no sea tu 〈Airani Iofifteen〉.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('213', 'hBP01-060', 'character', 'P', 'first', 'hPR/hBP01-060_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP01-060_P.png', 100, NULL, 1, '["null"]', NULL, '鷹嶺ルイ', '{"arts":[{"cost_types":["null"],"damage":40}],"card_sets":["PRカード","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["red"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"Keep Up, Okay?!"}],"keyword":{"effect":"When Blooming from Debut, you may archive 1 card from your hand: Draw 2 cards from your deck.","name":"It''s Really All Thanks to Everyone!!"},"name":"Takane Lui","tags":["#JP","#Secret Society holoX","#Bird","#Alcohol"]},"es":{"arts":[{"name":"¡Sígueme bien, eh!"}],"keyword":{"effect":"Cuando haga Bloom desde Debut, puedes archivar 1 carta de tu mano: roba 2 cartas de tu mazo.","name":"¡¡De verdad, es gracias a todos!!"},"name":"Takane Lui","tags":["#JP","#Secret Society holoX","#Bird","#Alcohol"]},"id":{"arts":[{"name":"Ikuti aku baik-baik ya!"}],"keyword":{"effect":"Saat Bloom dari Debut, kamu boleh archive 1 kartu dari tanganmu: ambil 2 kartu dari dekmu.","name":"Ini benar-benar berkat kalian semua!!"},"name":"Takane Lui","tags":["#JP","#Organisasi Rahasia holoX","#Burung","#Alkohol"]},"ja":{"arts":[{"name":"しっかりついてきてよね！"}],"keyword":{"effect":"DebutからBloomした時、自分の手札1枚をアーカイブできる:自分のデッキを2枚引く。","name":"本当にみんなのおかげ！！"},"name":"鷹嶺ルイ","tags":["#JP","#秘密結社holoX","#トリ","#お酒"]},"ko":{"arts":[{"name":"제대로 따라오라고!"}],"keyword":{"effect":"Debut에서 Bloom했을 때, 자신의 패 1장을 아카이브할 수 있다: 자신의 덱을 2장 뽑는다.","name":"정말 모두 덕분이야!!"},"name":"타카네 루이","tags":["#JP","#비밀결사 holoX","#새","#술"]},"tc":{"arts":[{"name":"要好好跟上我喔！"}],"keyword":{"effect":"從Debut進行Bloom時，可以將自己1張手牌存入檔案區：抽2張自己的牌庫。","name":"真的都是多虧了大家！！"},"name":"鷹嶺露依","tags":["#JP","#秘密結社holoX","#小鳥","#酒"]},"th":{"arts":[{"name":"ตามมาให้ดีล่ะ!"}],"keyword":{"effect":"เมื่อ Bloom จาก Debut สามารถอาร์ไคฟ์การ์ดในมือของตนเอง 1 ใบได้: จั่วการ์ดจากเด็คของตนเอง 2 ใบ","name":"ทั้งหมดนี้ต้องขอบคุณทุกคนจริงๆ!!"},"name":"ทาคาเนะ รุย","tags":["#JP","#องค์กรลับ holoX","#นก","#แอลกอฮอล์"]}}}', '{}', 'b72370df5e75705209755ce890edaad6227031649635481477530c0c3e3a3b50', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
