INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('223', 'hSD01-007', 'character', 'P', 'debut', 'hPR/hSD01-007_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hSD01-007_P.png', 50, NULL, 1, '["null"]', NULL, 'IRyS', '{"arts":[{"cost_types":["white"],"damage":20}],"card_sets":["PRカード"],"color_codes":["white"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Embodiment of Hope"}],"keyword":{"effect":"Look at your holoPower. Reveal 1 card from it and add it to your hand. Then put 1 card from your hand into your holoPower.","name":"HOPE"},"name":"IRyS","tags":["#EN","#Promise","#Singing"]},"es":{"arts":[{"name":"Encarnación de la esperanza"}],"keyword":{"effect":"Mira tu Holo Power. De entre esas cartas, revela 1 y añádela a tu mano. Después, pon 1 carta de tu mano en tu Holo Power.","name":"HOPE"},"name":"IRyS","tags":["#EN","#Promise","#Singing"]},"id":{"arts":[{"name":"Perwujudan Harapan"}],"keyword":{"effect":"Lihat Holo Power-mu. Dari antaranya, ungkapkan 1 kartu dan tambahkan ke tanganmu. Lalu, taruh 1 kartu dari tanganmu ke Holo Power.","name":"HARAPAN"},"name":"IRyS","tags":["#EN","#Promise","#Menyanyi"]},"ja":{"arts":[{"name":"希望の化身"}],"keyword":{"effect":"自分のホロパワーを見る。その中から1枚を公開し、手札に加える。そして自分の手札1枚をホロパワーにする。","name":"HOPE"},"name":"IRyS","tags":["#EN","#Promise","#歌"]},"ko":{"arts":[{"name":"희망의 화신"}],"keyword":{"effect":"자신의 홀로파워를 본다. 그중에서 1장을 공개하고, 패에 넣는다. 그리고 자신의 패 1장을 홀로파워로 한다.","name":"HOPE"},"name":"IRyS","tags":["#EN","#Promise","#노래"]},"tc":{"arts":[{"name":"希望的化身"}],"keyword":{"effect":"查看自己的Holo能量。從中公開1張，加入手牌。然後將自己1張手牌置為Holo能量。","name":"HOPE"},"name":"IRyS","tags":["#EN","#Promise","#歌唱"]},"th":{"arts":[{"name":"ร่างจุติแห่งความหวัง"}],"keyword":{"effect":"ดูโฮโลพาวเวอร์ของตนเอง เปิดเผยการ์ด 1 ใบจากในนั้นแล้วนำขึ้นมือ จากนั้นนำการ์ดในมือของตนเอง 1 ใบไปเป็นโฮโลพาวเวอร์","name":"HOPE"},"name":"IRyS","tags":["#EN","#Promise","#เพลง"]}}}', '{}', '712fbd4dca1a21e016faf42a3285306fcc8eaa3e8947906d604b95919acad63e', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
