INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (223, 'hSD01-007', 'hSD01-007 EN Promise 歌 IRyS #EN #Promise #歌 希望の化身 HOPE 自分のホロパワーを見る。その中から1枚を公開し、手札に加える。そして自分の手札1枚をホロパワーにする。 IRyS #EN #Promise #Singing Embodiment of Hope HOPE Look at your holoPower. Reveal 1 card from it and add it to your hand. Then put 1 card from your hand into your holoPower. IRyS #EN #Promise #歌唱 希望的化身 HOPE 查看自己的Holo能量。從中公開1張，加入手牌。然後將自己1張手牌置為Holo能量。 IRyS #EN #Promise #Menyanyi Perwujudan Harapan HARAPAN Lihat Holo Power-mu. Dari antaranya, ungkapkan 1 kartu dan tambahkan ke tanganmu. Lalu, taruh 1 kartu dari tanganmu ke Holo Power. IRyS #EN #Promise #노래 희망의 화신 HOPE 자신의 홀로파워를 본다. 그중에서 1장을 공개하고, 패에 넣는다. 그리고 자신의 패 1장을 홀로파워로 한다. IRyS #EN #Promise #เพลง ร่างจุติแห่งความหวัง HOPE ดูโฮโลพาวเวอร์ของตนเอง เปิดเผยการ์ด 1 ใบจากในนั้นแล้วนำขึ้นมือ จากนั้นนำการ์ดในมือของตนเอง 1 ใบไปเป็นโฮโลพาวเวอร์ IRyS #EN #Promise #Singing Encarnación de la esperanza HOPE Mira tu Holo Power. De entre esas cartas, revela 1 y añádela a tu mano. Después, pon 1 carta de tu mano en tu Holo Power.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('224', 'hSD01-012', 'character', 'P', 'debut', 'hPR/hSD01-012_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hSD01-012_P.png', 70, NULL, 1, '["null"]', NULL, 'アイラニ・イオフィフティーン', '{"arts":[{"cost_types":["green"],"damage":20}],"card_sets":["PRカード"],"color_codes":["green"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Drawing Is So Fun!"}],"keyword":{"effect":"You may send 1 [White Cheer or Green Cheer] from your Archive to your Center holomem.","name":"Let''s Draw Together!"},"name":"Airani Iofifteen","tags":["#ID","#ID 1st Gen","#Art"]},"es":{"arts":[{"name":"¡Dibujar es divertidísimo!"}],"keyword":{"effect":"Puedes enviar 1 [White Cheer o Green Cheer] de tu archivo a tu holomen del centro.","name":"¡Dibujemos juntas!"},"name":"Airani Iofifteen","tags":["#ID","#ID 1st Gen","#Art"]},"id":{"arts":[{"name":"Menggambar itu seru!"}],"keyword":{"effect":"Kamu boleh mengirim 1 kartu [Yell Putih atau Yell Hijau] dari Arsip milikmu ke Center holomen milikmu.","name":"Menggambar bareng!"},"name":"Airani Iofifteen","tags":["#ID","#ID Gen 1","#Seni"]},"ja":{"arts":[{"name":"お絵かきたのしー！"}],"keyword":{"effect":"自分のアーカイブの[白エールか緑エール]1枚を自分のセンターホロメンに送れる。","name":"一緒にお絵かき！"},"name":"アイラニ・イオフィフティーン","tags":["#ID","#ID1期生","#絵"]},"ko":{"arts":[{"name":"그림 그리기 재밌어!"}],"keyword":{"effect":"자신의 아카이브의 [화이트 옐 또는 그린 옐] 1장을 자신의 센터 홀로멤에게 보낼 수 있다.","name":"같이 그림 그리기!"},"name":"아이라니 이오피피틴","tags":["#ID","#ID 1기생","#그림"]},"tc":{"arts":[{"name":"畫畫好開心！"}],"keyword":{"effect":"可以將自己存檔區的1張[白色應援或綠色應援]送給自己的中心Holomen。","name":"一起畫畫！"},"name":"艾拉妮・伊歐菲芙汀","tags":["#ID","#ID1期生","#繪畫"]},"th":{"arts":[{"name":"วาดรูปสนุกจังเลย!"}],"keyword":{"effect":"คุณสามารถนำ [เยลสีขาว หรือ เยลสีเขียว] 1 ใบจากอาร์ไคฟ์ของคุณไปติดให้เซ็นเตอร์โฮโลเมนของคุณ","name":"มาวาดรูปด้วยกัน!"},"name":"ไอราณี ไอโอฟิฟตีน","tags":["#ID","#ID รุ่น 1","#ศิลปะ"]}}}', '{}', '745df8b82f21eeefbefb92392b0681fa1ab65749ef3482213be65660d68660ca', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
