INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (224, 'hSD01-012', 'hSD01-012 ID ID1期生 絵 アイラニ・イオフィフティーン #ID #ID1期生 #絵 お絵かきたのしー！ 一緒にお絵かき！ 自分のアーカイブの[白エールか緑エール]1枚を自分のセンターホロメンに送れる。 Airani Iofifteen #ID #ID 1st Gen #Art Drawing Is So Fun! Let''s Draw Together! You may send 1 [White Cheer or Green Cheer] from your Archive to your Center holomem. 艾拉妮・伊歐菲芙汀 #ID #ID1期生 #繪畫 畫畫好開心！ 一起畫畫！ 可以將自己存檔區的1張[白色應援或綠色應援]送給自己的中心Holomen。 Airani Iofifteen #ID #ID Gen 1 #Seni Menggambar itu seru! Menggambar bareng! Kamu boleh mengirim 1 kartu [Yell Putih atau Yell Hijau] dari Arsip milikmu ke Center holomen milikmu. 아이라니 이오피피틴 #ID #ID 1기생 #그림 그림 그리기 재밌어! 같이 그림 그리기! 자신의 아카이브의 [화이트 옐 또는 그린 옐] 1장을 자신의 센터 홀로멤에게 보낼 수 있다. ไอราณี ไอโอฟิฟตีน #ID #ID รุ่น 1 #ศิลปะ วาดรูปสนุกจังเลย! มาวาดรูปด้วยกัน! คุณสามารถนำ [เยลสีขาว หรือ เยลสีเขียว] 1 ใบจากอาร์ไคฟ์ของคุณไปติดให้เซ็นเตอร์โฮโลเมนของคุณ Airani Iofifteen #ID #ID 1st Gen #Art ¡Dibujar es divertidísimo! ¡Dibujemos juntas! Puedes enviar 1 [White Cheer o Green Cheer] de tu archivo a tu holomen del centro.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('225', 'hSD02-001', 'oshiCharacter', 'OC', NULL, 'hSD02/hSD02-001_OC', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD02/hSD02-001_OC.png', NULL, 5, NULL, NULL, '松尾 省吾', '百鬼あやめ', '{"card_sets":["スタートデッキ 赤 百鬼あやめ"],"color_codes":["red"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Nakiri Ayame","oshi_skill":{"effect":"[Once per turn] During this turn, your red Center holomem gets +20 Arts.","name":"RED MIC","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] Return 1 Red holomem from your Archive to your hand.","name":"Now then! One more time!","timing":"Once per game"}},"es":{"name":"Nakiri Ayame","oshi_skill":{"effect":"[Una vez por turno] Durante este turno, las artes de tu holomen central rojo obtienen +20.","name":"Micrófono Rojo","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Devuelve a tu mano 1 holomen rojo de tu Archivo.","name":"¡Vamos! ¡Una vez más!","timing":"Una vez por partida"}},"id":{"name":"Nakiri Ayame","oshi_skill":{"effect":"[Sekali per giliran] Selama giliran ini, Arts holomen center merah milikmu +20.","name":"Mik Merah","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per permainan] Kembalikan 1 Red Holomen dari Archive-mu ke tanganmu.","name":"Ayo! Sekali lagi!","timing":"Sekali per permainan"}},"ja":{"name":"百鬼あやめ","oshi_skill":{"effect":"[ターンに1回]このターンの間、自分の赤センターホロメンのアーツ+20。","name":"レッドマイク","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]自分のアーカイブの赤ホロメン1枚を手札に戻す。","name":"さあ！もう一度！","timing":"ゲームに1回"}},"ko":{"name":"나키리 아야메","oshi_skill":{"effect":"[턴에 1번]이번 턴 동안 자신의 빨간 센터 홀로멘의 아츠+20.","name":"레드 마이크","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번]자신의 아카이브의 적색 홀로멤 1장을 패로 되돌린다.","name":"자! 다시 한 번!","timing":"게임에 1번"}},"tc":{"name":"百鬼綾目","oshi_skill":{"effect":"[每回合1次]在這個回合期間，自己的紅色中心holomen的藝術+20。","name":"紅色麥克風","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場對戰1次]將自己檔案區1張紅色Holomen返回手牌。","name":"來吧！再一次！","timing":"每場對戰1次"}},"th":{"name":"นากิริ อายาเมะ","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] ในเทิร์นนี้ อาร์ตของเซ็นเตอร์โฮโลเมนสีแดงของคุณ +20","name":"ไมค์สีแดง","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] นำโฮโลเม็มเบอร์สีแดง 1 ใบจากอาร์ไคฟ์ของคุณกลับขึ้นมือ","name":"เอาล่ะ! อีกครั้ง!","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{}', '8575d2daf04958b97806eacc404c9216de76a4e1c33919410f189660b5f30587', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
