INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (226, 'hSD02-002', 'hSD02-002 JP 2期生 シューター 百鬼あやめ #JP #2期生 #シューター こんなきり～ Nakiri Ayame #JP #2nd Gen #Shooter Konnakiri~ 百鬼綾目 #JP #2期生 #射手 Konnakiri～ Nakiri Ayame #JP #Gen 2 #Penembak Konnakiri～ 나키리 아야메 #JP #2기생 #슈터 콘나키리~ นากิริ อายาเมะ #JP #รุ่น 2 #ชูตเตอร์ คนนาคิริ~ Nakiri Ayame #JP #2nd Gen #Shooter ¡Konnakiri~!', '');
