INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (232, 'hSD02-008', 'hSD02-008 和錆 JP 2期生 シューター 百鬼あやめ #JP #2期生 #シューター ファンシーバースデー プレゼント何かな？ 自分の手札1枚をアーカイブできる:相手のセンターホロメンかコラボホロメンに特殊ダメージ50を与える。 Nakiri Ayame #JP #2nd Gen #Shooter Fancy Birthday I Wonder What the Present Is? You may archive 1 card from your hand: Deal 50 special damage to the opponent''s Center holomem or Collab holomem. 百鬼綾目 #JP #2期生 #射手 夢幻生日 會是什麼禮物呢？ 可將自己手牌中的1張卡存入存檔區：對對手的中心Holo成員或合作Holo成員造成特殊傷害50。 Nakiri Ayame #JP #Gen 2 #Penembak Fancy Birthday Kira-kira hadiahnya apa ya? Kamu boleh Archive 1 kartu dari tanganmu: berikan Special Damage 50 kepada Center holomen lawan atau Collab holomen lawan. 나키리 아야메 #JP #2기생 #슈터 팬시 버스데이 선물 뭐려나? 자신의 패 1장을 아카이브할 수 있다: 상대의 센터 홀로멤 또는 콜라보 홀로멤에게 특수 대미지 50을 준다. นากิริ อายาเมะ #JP #รุ่น 2 #ชูตเตอร์ วันเกิดแฟนซี ของขวัญจะเป็นอะไรน้า? สามารถอาร์ไคฟ์การ์ดในมือของคุณ 1 ใบได้: สร้างความเสียหายพิเศษ 50 ให้แก่เซ็นเตอร์โฮโลเมนหรือคอลแลบโฮโลเมนของฝ่ายตรงข้าม Nakiri Ayame #JP #2nd Gen #Shooter Cumpleaños de fantasía ¿Qué será el regalo? Puedes archivar 1 carta de tu mano: inflige 50 de daño especial al holomen del Centro o al holomen de Colaboración de tu oponente.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('233', 'hSD02-009', 'character', 'RR', 'second', 'hSD02/hSD02-009_RR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD02/hSD02-009_RR.png', 180, NULL, 1, '["null"]', 'soriya', '百鬼あやめ', '{"arts":[{"cost_types":["red"],"damage":60,"special_targets":["yellow"],"special_values":[50]},{"cost_types":["red","red","null"],"damage":40,"special_targets":["yellow"],"special_values":[50]}],"card_sets":["スタートデッキ 赤 百鬼あやめ"],"color_codes":["red"],"translations":{"en":{"arts":[{"name":"The \"Aya\" in AyaFubuMi"},{"effect":"You may archive 1 to 3 cards from your hand: Deal 40 special damage to your opponent''s Center holomem for each card archived this way.","name":"’Tis I, Yo"}],"name":"Nakiri Ayame","tags":["#JP","#2nd Gen","#Shooter"]},"es":{"arts":[{"name":"La «Aya» de Ayafubumi"},{"effect":"Puedes archivar de 1 a 3 cartas de tu mano: inflige 40 de daño especial al holomen central de tu oponente por cada carta archivada de esta manera.","name":"Yo soy Yo"}],"name":"Nakiri Ayame","tags":["#JP","#2nd Gen","#Shooter"]},"id":{"arts":[{"name":"Bagian “Aya” dari Ayafubumi"},{"effect":"Kamu boleh mengarsipkan 1–3 kartu dari tanganmu: Berikan 40 damage spesial kepada Center holomen lawan untuk setiap 1 kartu yang diarsipkan.","name":"Aku loh, yo"}],"name":"Nakiri Ayame","tags":["#JP","#Gen 2","#Penembak"]},"ja":{"arts":[{"name":"あやふぶみの「あや」担当"},{"effect":"自分の手札1～3枚をアーカイブできる:相手のセンターホロメンに、アーカイブしたカード1枚につき、特殊ダメージ40を与える。","name":"余ーだ余"}],"name":"百鬼あやめ","tags":["#JP","#2期生","#シューター"]},"ko":{"arts":[{"name":"아야후부미의 「아야」 담당"},{"effect":"자신의 손패 1~3장을 아카이브할 수 있다: 상대의 센터 홀로멘에게, 아카이브한 카드 1장당 특수 대미지 40을 준다.","name":"요ー다 요"}],"name":"나키리 아야메","tags":["#JP","#2기생","#슈터"]},"tc":{"arts":[{"name":"Ayafubumi的「あや」擔當"},{"effect":"可將自己的手牌1～3張卡存檔：給予對手的中心Holo成員特殊傷害，每有1張已存檔的卡，便給予40。","name":"余來啦 余"}],"name":"百鬼綾目","tags":["#JP","#2期生","#射手"]},"th":{"arts":[{"name":"担当『อายะ』ของอายะฟุบุมิ"},{"effect":"คุณสามารถอาร์ไคฟ์การ์ดในมือของคุณ 1~3 ใบได้: สร้างความเสียหายพิเศษ 40 ให้แก่เซ็นเตอร์โฮโลเมนของฝ่ายตรงข้ามต่อการ์ด 1 ใบที่อาร์ไคฟ์","name":"ข้านี่แหละโยะ"}],"name":"นากิริ อายาเมะ","tags":["#JP","#รุ่น 2","#ชูตเตอร์"]}}}', '{}', '5c161037a822b75c16d35dbaae546a1567a7657390b9f9028696aee6b17808f5', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
