INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (234, 'hSD02-010', 'hSD02-010 JP 1期生 ゲーマーズ ケモミミ 絵 白上フブキ #JP #1期生 #ゲーマーズ #ケモミミ #絵 あやふぶみの「ふぶ」担当 帰ってきなさーい 自分のアーカイブのマスコット1枚を手札に戻せる。 Shirakami Fubuki #JP #1st Gen #Gamers #Animal Ears #Art Ayafubumi’s “Fubu” Come baaack~ You may return 1 Mascot from your Archive to your hand. 白上吹雪 #JP #1期生 #Gamers #獸耳 #繪畫 Ayafubumi 的「Fubu」擔當 快回來啦— 可以將自己Archive中1張吉祥物返回手牌。 Shirakami Fubuki #JP #Gen 1 #Gamers #Telinga Hewan #Seni Bagian “Fubu” dari Ayafubumi Pulanglah~ Kamu boleh mengembalikan 1 kartu Mascot dari Archive milikmu ke tanganmu. 시라카미 후부키 #JP #1기생 #게이머즈 #수인귀 #그림 아야후부미의 「후부」 담당 돌아오라구~ 자신의 아카이브에 있는 마스코트 1장을 패로 되돌릴 수 있다. ชิรากามิ ฟุบุกิ #JP #รุ่น 1 #เกมเมอร์ส #หูสัตว์ #ศิลปะ ผู้รับหน้าที่ “ฟุบ” แห่งอายะฟุบุมิ กลับมานี่เดี๋ยวนี้ คุณสามารถนำมาสคอต 1 ใบจาก Archive ของคุณกลับขึ้นมือได้ Shirakami Fubuki #JP #1st Gen #Gamers #Animal Ears #Art La "fubu" de Ayafubumi ¡Vuelveee! Puedes devolver a tu mano 1 Mascot de tu Archivo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('235', 'hSD02-011', 'character', 'U', 'spot', 'hSD02/hSD02-011_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD02/hSD02-011_U.png', 50, NULL, 1, '["null"]', NULL, '大神ミオ', '{"arts":[{"cost_types":["null"],"damage":10}],"card_sets":["スタートデッキ 赤 百鬼あやめ"],"color_codes":["null"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Ayafubumi’s “Mi”"}],"keyword":{"effect":"You may Archive 1 holomem from your hand: Send the top card of your Cheer Deck to your Debut holomem.","name":"Demon Beast Club"},"name":"Ookami Mio","tags":["#JP","#Gamers","#Animal Ears","#Cooking"]},"es":{"arts":[{"name":"La \"mi\" de Ayafubumi"}],"keyword":{"effect":"Puedes Archivar 1 holomen de tu mano: envía la carta superior de tu mazo de Cheers a uno de tus Debut holomen.","name":"Reunión oni-bestia"},"name":"Ookami Mio","tags":["#JP","#Gamers","#Animal Ears","#Cooking"]},"id":{"arts":[{"name":"Bagian “Mi” dari Ayafubumi"}],"keyword":{"effect":"Kamu boleh mengarsipkan 1 holomen dari tanganmu: kirim 1 kartu teratas dari Cheer Deck milikmu ke Debut holomen milikmu.","name":"Perkumpulan oni dan monster"},"name":"Ookami Mio","tags":["#JP","#Gamers","#Telinga Hewan","#Masakan"]},"ja":{"arts":[{"name":"あやふぶみの「み」担当"}],"keyword":{"effect":"自分の手札のホロメン1枚をアーカイブできる:自分のエールデッキの上から1枚を自分のDebutホロメンに送る。","name":"おにけもの会"},"name":"大神ミオ","tags":["#JP","#ゲーマーズ","#ケモミミ","#料理"]},"ko":{"arts":[{"name":"아야후부미의 「미」 담당"}],"keyword":{"effect":"자신의 패의 홀로멘 1장을 아카이브할 수 있다:자신의 에르 덱 위에서 1장을 자신의 Debut 홀로멘에게 보낸다.","name":"오니케모노회"},"name":"오오카미 미오","tags":["#JP","#게이머즈","#수인귀","#요리"]},"tc":{"arts":[{"name":"Ayafubumi 的「Mi」擔當"}],"keyword":{"effect":"可將自己手牌中的1張Holomen歸檔：將自己應援牌庫頂部1張牌送給自己的Debut Holomen。","name":"鬼怪會"},"name":"大神澪","tags":["#JP","#Gamers","#獸耳","#料理"]},"th":{"arts":[{"name":"ผู้รับหน้าที่ “มิ” แห่งอายะฟุบุมิ"}],"keyword":{"effect":"คุณสามารถอาร์ไคฟ์โฮโลเมน 1 ใบจากมือของคุณ: ส่งการ์ด 1 ใบบนสุดจากเชียร์เด็คของคุณไปยัง Debut โฮโลเมนของคุณ","name":"ชมรมอสูรกับสัตว์ประหลาด"},"name":"โอกามิ มิโอ","tags":["#JP","#เกมเมอร์ส","#หูสัตว์","#ทำอาหาร"]}}}', '{}', '3ab59242b738d31f87c433c0ec4f1efbc35b76f78acf1e419e8fba2a82732464', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
