INSERT INTO card_tags (tag, card_id) VALUES ('白上''sキャラクター', '238');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (238, 'hSD02-014', 'hSD02-014 はずき 白上''sキャラクター ぽよ余 #白上''sキャラクター このマスコットが付いているホロメンのHP+20。
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('239', 'hSD03-001', 'oshiCharacter', 'OC', NULL, 'hSD03/hSD03-001_OC', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD03/hSD03-001_OC.png', NULL, 5, NULL, NULL, '松尾 省吾', '猫又おかゆ', '{"card_sets":["スタートデッキ 青 猫又おかゆ"],"color_codes":["blue"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Nekomata Okayu","oshi_skill":{"effect":"[Once per turn] During this turn, your blue Center holomem gets +20 Arts.","name":"BLUE MIC","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] You may use this when a holomem on your Stage deals damage to your opponent''s Back holomem: deal 50 special damage to 1 of those opponent''s Back holomem.","name":"Backshot","timing":"Once per game"}},"es":{"name":"Nekomata Okayu","oshi_skill":{"effect":"[Una vez por turno] Durante este turno, las artes de tu holomen central azul obtienen +20.","name":"Micrófono Azul","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Puedes usar esto cuando uno de tus holomen del Escenario inflija daño a un holomen de retaguardia del oponente: inflige 50 de daño especial a 1 de esos holomen de retaguardia del oponente.","name":"Disparo por la espalda","timing":"Una vez por partida"}},"id":{"name":"Nekomata Okayu","oshi_skill":{"effect":"[Sekali per giliran] Selama giliran ini, Arts holomen center biru milikmu +20.","name":"Mik Biru","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per permainan] Dapat digunakan saat Holomen di Stage-mu memberikan damage kepada Back Holomen lawan: berikan 50 Special Damage kepada 1 Back Holomen lawan itu.","name":"Tembakan Belakang","timing":"Sekali per permainan"}},"ja":{"name":"猫又おかゆ","oshi_skill":{"effect":"[ターンに1回]このターンの間、自分の青センターホロメンのアーツ+20。","name":"ブルーマイク","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]自分のステージのホロメンが相手のバックホロメンにダメージを与えた時に使える:その相手のバックホロメン1人に特殊ダメージ50を与える。","name":"バックショット","timing":"ゲームに1回"}},"ko":{"name":"네코마타 오카유","oshi_skill":{"effect":"[턴에 1번]이번 턴 동안 자신의 파란 센터 홀로멘의 아츠+20.","name":"블루 마이크","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번]자신의 스테이지의 홀로멤이 상대의 백 홀로멤에게 대미지를 주었을 때 사용할 수 있다: 그 상대의 백 홀로멤 1명에게 특수 대미지 50을 준다.","name":"백샷","timing":"게임에 1번"}},"tc":{"name":"貓又小粥","oshi_skill":{"effect":"[每回合1次]在這個回合期間，自己的藍色中心holomen的藝術+20。","name":"藍色麥克風","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場對戰1次]可在自己舞台上的Holomen對對手的Back Holomen造成傷害時使用：對該對手1位Back Holomen給予特殊傷害50。","name":"背後一擊","timing":"每場對戰1次"}},"th":{"name":"เนโกะมาตะ โอกายุ","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] ในเทิร์นนี้ อาร์ตของเซ็นเตอร์โฮโลเมนสีน้ำเงินของคุณ +20","name":"ไมค์สีน้ำเงิน","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] ใช้ได้เมื่อโฮโลเม็มเบอร์บนสเตจของคุณสร้างแดเมจแก่แบ็กโฮโลเม็มเบอร์ของฝ่ายตรงข้าม: สร้างแดเมจพิเศษ 50 แก่แบ็กโฮโลเม็มเบอร์นั้น 1 คนของฝ่ายตรงข้าม","name":"Back Shot","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{}', 'bfbf3e373285edc7271b5bfca20aa47f4d9c600458f7cc9f8aeffd3ffccec898', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
INSERT INTO card_colors (color_code, card_id) VALUES ('blue', '239');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ 青 猫又おかゆ', '239');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (239, 'hSD03-001', 'hSD03-001 松尾 省吾 猫又おかゆ ブルーマイク [ターンに1回]このターンの間、自分の青センターホロメンのアーツ+20。 バックショット [ゲームに1回]自分のステージのホロメンが相手のバックホロメンにダメージを与えた時に使える:その相手のバックホロメン1人に特殊ダメージ50を与える。 Nekomata Okayu BLUE MIC [Once per turn] During this turn, your blue Center holomem gets +20 Arts. Backshot [Once per game] You may use this when a holomem on your Stage deals damage to your opponent''s Back holomem: deal 50 special damage to 1 of those opponent''s Back holomem. 貓又小粥 藍色麥克風 [每回合1次]在這個回合期間，自己的藍色中心holomen的藝術+20。 背後一擊 [每場對戰1次]可在自己舞台上的Holomen對對手的Back Holomen造成傷害時使用：對該對手1位Back Holomen給予特殊傷害50。 Nekomata Okayu Mik Biru [Sekali per giliran] Selama giliran ini, Arts holomen center biru milikmu +20. Tembakan Belakang [Sekali per permainan] Dapat digunakan saat Holomen di Stage-mu memberikan damage kepada Back Holomen lawan: berikan 50 Special Damage kepada 1 Back Holomen lawan itu. 네코마타 오카유 블루 마이크 [턴에 1번]이번 턴 동안 자신의 파란 센터 홀로멘의 아츠+20. 백샷 [게임에 1번]자신의 스테이지의 홀로멤이 상대의 백 홀로멤에게 대미지를 주었을 때 사용할 수 있다: 그 상대의 백 홀로멤 1명에게 특수 대미지 50을 준다. เนโกะมาตะ โอกายุ ไมค์สีน้ำเงิน [ใช้ได้ 1 ครั้งต่อเทิร์น] ในเทิร์นนี้ อาร์ตของเซ็นเตอร์โฮโลเมนสีน้ำเงินของคุณ +20 Back Shot [ใช้ได้ 1 ครั้งต่อเกม] ใช้ได้เมื่อโฮโลเม็มเบอร์บนสเตจของคุณสร้างแดเมจแก่แบ็กโฮโลเม็มเบอร์ของฝ่ายตรงข้าม: สร้างแดเมจพิเศษ 50 แก่แบ็กโฮโลเม็มเบอร์นั้น 1 คนของฝ่ายตรงข้าม Nekomata Okayu Micrófono Azul [Una vez por turno] Durante este turno, las artes de tu holomen central azul obtienen +20. Disparo por la espalda [Una vez por partida] Puedes usar esto cuando uno de tus holomen del Escenario inflija daño a un holomen de retaguardia del oponente: inflige 50 de daño especial a 1 de esos holomen de retaguardia del oponente.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('240', 'hSD03-002', 'character', 'C', 'debut', 'hSD03/hSD03-002_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD03/hSD03-002_C.png', 100, NULL, 1, '["null"]', NULL, '猫又おかゆ', '{"arts":[{"cost_types":["null"],"damage":30}],"card_sets":["スタートデッキ 青 猫又おかゆ","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["blue"],"translations":{"en":{"arts":[{"name":"Mogu Mogu~ Okayu~"}],"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Animal Ears"]},"es":{"arts":[{"name":"Mogu mogu～ Okayu～"}],"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Animal Ears"]},"id":{"arts":[{"name":"Mogu mogu～ Okayu～"}],"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Telinga Hewan"]},"ja":{"arts":[{"name":"もぐもぐ～おかゆ～"}],"name":"猫又おかゆ","tags":["#JP","#ゲーマーズ","#ケモミミ"]},"ko":{"arts":[{"name":"냠냠~ 오카유~"}],"name":"네코마타 오카유","tags":["#JP","#게이머즈","#수인귀"]},"tc":{"arts":[{"name":"嚼嚼～粥粥～"}],"name":"貓又小粥","tags":["#JP","#Gamers","#獸耳"]},"th":{"arts":[{"name":"ง่ำง่ำ~ โอคายู~"}],"name":"เนโกะมาตะ โอกายุ","tags":["#JP","#เกมเมอร์ส","#หูสัตว์"]}}}', '{}', 'a0d07818fe7aee16fc06646544331c85ffbdf62ee950df4f1c70b98de0d3d7ec', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
