INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (240, 'hSD03-002', 'hSD03-002 JP ゲーマーズ ケモミミ 猫又おかゆ #JP #ゲーマーズ #ケモミミ もぐもぐ～おかゆ～ Nekomata Okayu #JP #Gamers #Animal Ears Mogu Mogu~ Okayu~ 貓又小粥 #JP #Gamers #獸耳 嚼嚼～粥粥～ Nekomata Okayu #JP #Gamers #Telinga Hewan Mogu mogu～ Okayu～ 네코마타 오카유 #JP #게이머즈 #수인귀 냠냠~ 오카유~ เนโกะมาตะ โอกายุ #JP #เกมเมอร์ส #หูสัตว์ ง่ำง่ำ~ โอคายู~ Nekomata Okayu #JP #Gamers #Animal Ears Mogu mogu～ Okayu～', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('241', 'hSD03-003', 'character', 'C', 'debut', 'hSD03/hSD03-003_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD03/hSD03-003_C.png', 70, NULL, 1, '["null"]', '神岡ちろる', '猫又おかゆ', '{"arts":[{"cost_types":["blue"],"damage":10}],"card_sets":["スタートデッキ 青 猫又おかゆ"],"color_codes":["blue"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Please Let Me In Your Home"}],"keyword":{"effect":"If your Center holomem has #Gamers, deal 10 special damage to your opponent''s Center holomem and 1 of their Back holomem. However, even if they are Downed, your opponent does not lose Life.","name":"Pardon me for visiting your home...!"},"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Animal Ears"]},"es":{"arts":[{"name":"Por favor, déjame entrar a tu casa"}],"keyword":{"effect":"Si tu holomen central tiene #Gamers, inflige 10 de daño especial al holomen central de tu oponente y a 1 de sus holomen de la retaguardia. Sin embargo, aunque queden noqueados, la Vida de tu oponente no disminuye.","name":"¡Voy a molestar en tu casa...!"},"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Animal Ears"]},"id":{"arts":[{"name":"Tolong biarkan aku masuk rumahmu"}],"keyword":{"effect":"Saat Center holomen milikmu memiliki #Gamers, berikan 10 damage spesial kepada Center holomen lawan dan 1 Back holomen lawan. Namun, meskipun Down, Life lawan tidak berkurang.","name":"Permisi mampir ke rumahmu…!"},"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Telinga Hewan"]},"ja":{"arts":[{"name":"僕をお家に入れてください"}],"keyword":{"effect":"自分のセンターホロメンが#ゲーマーズを持つ時、相手のセンターホロメンとバックホロメン1人に特殊ダメージ10を与える。ただし、ダウンしても相手のライフは減らない。","name":"お家にお邪魔します…！"},"name":"猫又おかゆ","tags":["#JP","#ゲーマーズ","#ケモミミ"]},"ko":{"arts":[{"name":"저를 집에 들여보내 주세요"}],"keyword":{"effect":"자신의 센터 홀로멘이 #게이머즈을 가지고 있을 때, 상대의 센터 홀로멘과 백 홀로멘 1명에게 특수 대미지 10을 준다. 단, 다운되어도 상대의 라이프는 줄지 않는다.","name":"집에 실례할게요…!"},"name":"네코마타 오카유","tags":["#JP","#게이머즈","#수인귀"]},"tc":{"arts":[{"name":"請讓我進你家"}],"keyword":{"effect":"當自己的中心Holomen持有#Gamers時，對對手的中心Holomen與1名後台Holomen造成特殊傷害10。但即使因此倒下，對手的生命值也不會減少。","name":"打擾你家了…！"},"name":"貓又小粥","tags":["#JP","#Gamers","#獸耳"]},"th":{"arts":[{"name":"ขอให้ผมเข้าบ้านทีเถอะ"}],"keyword":{"effect":"เมื่อเซ็นเตอร์โฮโลเมนของคุณมี #เกมเมอร์ส สร้างความเสียหายพิเศษ 10 ให้แก่เซ็นเตอร์โฮโลเมนของฝ่ายตรงข้ามและแบ็กโฮโลเมนของฝ่ายตรงข้าม 1 คน แต่ถึงถูกดาวน์ก็จะไม่ทำให้ไลฟ์ของฝ่ายตรงข้ามลดลง","name":"ขอรบกวนที่บ้านหน่อยนะ...!"},"name":"เนโกะมาตะ โอกายุ","tags":["#JP","#เกมเมอร์ส","#หูสัตว์"]}}}', '{}', 'c47d2eefb0446f79d54b000ebe47e3baf168126fa3c727675b6e37af5b543ac6', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
