INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (244, 'hSD03-006', 'hSD03-006 相音光 JP ゲーマーズ ケモミミ 歌 猫又おかゆ #JP #ゲーマーズ #ケモミミ #歌 猫かぶり しゃー このホロメンの青エール1枚をアーカイブできる:相手のセンターホロメンとバックホロメン1人に特殊ダメージ10を与える。 Nekomata Okayu #JP #Gamers #Animal Ears #Singing Playing Cat Shaa You may archive 1 of this holomem''s Blue Cheer: Deal 10 special damage to the opponent''s Center holomem and 1 of their Back holomem. 貓又小粥 #JP #Gamers #獸耳 #歌唱 裝乖貓 嚇 可將此Holo成員的1張藍色應援存入存檔區：對對手的中心Holo成員與1位後備Holo成員造成特殊傷害10。 Nekomata Okayu #JP #Gamers #Telinga Hewan #Menyanyi Sok Imut Syaa Kamu boleh Archive 1 Yell Biru dari holomen ini: berikan Special Damage 10 kepada Center holomen lawan dan 1 Back holomen lawan. 네코마타 오카유 #JP #게이머즈 #수인귀 #노래 내숭 샤ー 이 홀로멤의 블루 옐 1장을 아카이브할 수 있다: 상대의 센터 홀로멤과 백 홀로멤 1명에게 특수 대미지 10을 준다. เนโกะมาตะ โอกายุ #JP #เกมเมอร์ส #หูสัตว์ #เพลง เสแสร้งใสซื่อ ช่า สามารถอาร์ไคฟ์ เยลสีน้ำเงิน 1 ใบของโฮโลเมนนี้ได้: สร้างความเสียหายพิเศษ 10 ให้แก่เซ็นเตอร์โฮโลเมนของฝ่ายตรงข้ามและแบ็คโฮโลเมน 1 คน Nekomata Okayu #JP #Gamers #Animal Ears #Singing Hacerse la buena Shaa Puedes archivar 1 Blue Cheer de este holomen: inflige 10 de daño especial al holomen del Centro de tu oponente y a 1 holomen de la Retaguardia.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('245', 'hSD03-007', 'character', 'U', 'first', 'hSD03/hSD03-007_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD03/hSD03-007_U.png', 110, NULL, 1, '["null"]', NULL, '猫又おかゆ', '{"arts":[{"cost_types":["null"],"damage":20}],"card_sets":["スタートデッキ 青 猫又おかゆ","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["blue"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"I’ll Give It My All and Deliver My Own Kind of Song!"}],"keyword":{"effect":"You may send 1 Cheer from your archive to one of your holomem with #Gamers.","name":"Hey, make sure to laugh a whole lot again, okay!"},"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Animal Ears"]},"es":{"arts":[{"name":"¡Les entregaré mi canción, con todo y a mi manera!"}],"keyword":{"effect":"Puedes enviar 1 Cheer de tu archivo a uno de tus holomen con #Gamers.","name":"¡Y vuelve a sonreír muchísimo, ¿vale?!"},"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Animal Ears"]},"id":{"arts":[{"name":"Akan kusampaikan lagu versiku sepenuh hati!"}],"keyword":{"effect":"Kamu boleh mengirim 1 Cheer dari Arsipmu ke Holomen milikmu yang memiliki #Gamers.","name":"Tolong tertawa banyak lagi ya!"},"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Telinga Hewan"]},"ja":{"arts":[{"name":"全力で僕なりの歌、お届けします！"}],"keyword":{"effect":"自分のアーカイブのエール1枚を自分の#ゲーマーズを持つホロメンに送れる。","name":"また、たくさん笑ってよね！"},"name":"猫又おかゆ","tags":["#JP","#ゲーマーズ","#ケモミミ"]},"ko":{"arts":[{"name":"전력으로, 나다운 노래 전해드릴게요!"}],"keyword":{"effect":"자신의 아카이브의 엘 1장을 자신의 #게이머즈를 가진 홀로멤에게 보낼 수 있다.","name":"또, 많이 웃어줘!"},"name":"네코마타 오카유","tags":["#JP","#게이머즈","#수인귀"]},"tc":{"arts":[{"name":"我會全力送上屬於我的歌聲！"}],"keyword":{"effect":"可以將自己檔案區中的1張應援送給自己持有#Gamers的Holomen。","name":"還要再多笑一點喔！"},"name":"貓又小粥","tags":["#JP","#Gamers","#獸耳"]},"th":{"arts":[{"name":"จะขอมอบบทเพลงในแบบของผมอย่างเต็มกำลัง!"}],"keyword":{"effect":"คุณสามารถส่งเยล 1 ใบจากอาร์ไคฟ์ของคุณไปยังโฮโลเมนของคุณที่มี #เกมเมอร์ส ได้","name":"แล้วก็ช่วยหัวเราะกันเยอะๆ อีกนะ!"},"name":"เนโกะมาตะ โอกายุ","tags":["#JP","#เกมเมอร์ส","#หูสัตว์"]}}}', '{}', '2f4fb9874dd30411b798e257d7d7551d935830e75faeaf5168bf99c38b774cfe', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
