INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (245, 'hSD03-007', 'hSD03-007 JP ゲーマーズ ケモミミ 猫又おかゆ #JP #ゲーマーズ #ケモミミ 全力で僕なりの歌、お届けします！ また、たくさん笑ってよね！ 自分のアーカイブのエール1枚を自分の#ゲーマーズを持つホロメンに送れる。 Nekomata Okayu #JP #Gamers #Animal Ears I’ll Give It My All and Deliver My Own Kind of Song! Hey, make sure to laugh a whole lot again, okay! You may send 1 Cheer from your archive to one of your holomem with #Gamers. 貓又小粥 #JP #Gamers #獸耳 我會全力送上屬於我的歌聲！ 還要再多笑一點喔！ 可以將自己檔案區中的1張應援送給自己持有#Gamers的Holomen。 Nekomata Okayu #JP #Gamers #Telinga Hewan Akan kusampaikan lagu versiku sepenuh hati! Tolong tertawa banyak lagi ya! Kamu boleh mengirim 1 Cheer dari Arsipmu ke Holomen milikmu yang memiliki #Gamers. 네코마타 오카유 #JP #게이머즈 #수인귀 전력으로, 나다운 노래 전해드릴게요! 또, 많이 웃어줘! 자신의 아카이브의 엘 1장을 자신의 #게이머즈를 가진 홀로멤에게 보낼 수 있다. เนโกะมาตะ โอกายุ #JP #เกมเมอร์ส #หูสัตว์ จะขอมอบบทเพลงในแบบของผมอย่างเต็มกำลัง! แล้วก็ช่วยหัวเราะกันเยอะๆ อีกนะ! คุณสามารถส่งเยล 1 ใบจากอาร์ไคฟ์ของคุณไปยังโฮโลเมนของคุณที่มี #เกมเมอร์ส ได้ Nekomata Okayu #JP #Gamers #Animal Ears ¡Les entregaré mi canción, con todo y a mi manera! ¡Y vuelve a sonreír muchísimo, ¿vale?! Puedes enviar 1 Cheer de tu archivo a uno de tus holomen con #Gamers.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('246', 'hSD03-008', 'buzzCharacter', 'R', 'first', 'hSD03/hSD03-008_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD03/hSD03-008_R.png', 240, NULL, 2, '["null","null"]', 'ぴ助', '猫又おかゆ', '{"arts":[{"cost_types":["blue","null"],"damage":60}],"card_sets":["スタートデッキ 青 猫又おかゆ"],"color_codes":["blue"],"keyword":{"type":"ギフト","type_code":"gift"},"translations":{"en":{"arts":[{"name":"The Greatest Nekomata Okayu~"}],"keyword":{"effect":"[Center Position only] All [〈Takane Lui〉, 〈Ookami Mio〉, 〈Shirakami Fubuki〉, 〈Laplus Darknesss〉, and 〈Inugami Korone〉] on your Stage get Arts +20.","name":"Thief Construction Representative Director CEO"},"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Animal Ears"]},"es":{"arts":[{"name":"El más grandioso Nekomata Okayu～"}],"keyword":{"effect":"[Solo posición central] Los Arts de todos [〈Takane Lui〉 y 〈Ookami Mio〉 y 〈Shirakami Fubuki〉 y 〈Laplus Darknesss〉 y 〈Inugami Korone〉] en tu escenario obtienen +20.","name":"Thief Construction representante director general CEO"},"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Animal Ears"]},"id":{"arts":[{"name":"Nekomata Okayu paling hebat～"}],"keyword":{"effect":"[Hanya Posisi Center] Arts semua [〈Takane Lui〉, 〈Ookami Mio〉, 〈Shirakami Fubuki〉, 〈Laplus Darknesss〉, dan 〈Inugami Korone〉] di Stage milikmu +20.","name":"Konstruksi Pencuri Direktur Perwakilan CEO"},"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Telinga Hewan"]},"ja":{"arts":[{"name":"いちばんえらい猫又おかゆ～"}],"keyword":{"effect":"[センターポジション限定]自分のステージの[〈鷹嶺ルイ〉と〈大神ミオ〉と〈白上フブキ〉と〈ラプラス・ダークネス〉と〈戌神ころね〉]全員のアーツ+20。","name":"泥棒建設代表取締役 CEO"},"name":"猫又おかゆ","tags":["#JP","#ゲーマーズ","#ケモミミ"]},"ko":{"arts":[{"name":"가장 위대한 네코마타 오카유~"}],"keyword":{"effect":"[센터 포지션 한정] 자신의 스테이지의 [〈타카네 루이〉와 〈오오카미 미오〉와 〈시라카미 후부키〉와 〈라플라스 다크니스〉와 〈이누가미 코로네〉] 전원의 아츠+20.","name":"도둑 건설 대표이사 CEO"},"name":"네코마타 오카유","tags":["#JP","#게이머즈","#수인귀"]},"tc":{"arts":[{"name":"最了不起的貓又小粥～"}],"keyword":{"effect":"[僅限中心位置]自己舞台上的[〈鷹嶺露依〉與〈大神澪〉與〈白上吹雪〉與〈Laplus Darknesss〉與〈戌神沁音〉]全員的藝術+20。","name":"泥棒建設代表董事 CEO"},"name":"貓又小粥","tags":["#JP","#Gamers","#獸耳"]},"th":{"arts":[{"name":"เนโกะมาตะ โอกายุ ที่เก่งที่สุดเลย~"}],"keyword":{"effect":"[เฉพาะตำแหน่งเซ็นเตอร์] อาร์ตของ [〈ทาคาเนะ รุย〉 และ 〈โอกามิ มิโอ〉 และ 〈ชิรากามิ ฟุบุกิ〉 และ 〈ลาปลัส ดาร์กเนส〉 และ 〈อินุกามิ โคโรเนะ〉] ทั้งหมดบนสเตจของคุณ +20","name":"CEO ตัวแทนกรรมการของ โจรก่อสร้าง"},"name":"เนโกะมาตะ โอกายุ","tags":["#JP","#เกมเมอร์ส","#หูสัตว์"]}}}', '{}', 'b32f5235f32e52f29ca09cafe5f28c1eb3f57dc03c9ea3fa018bf508470859f8', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
