INSERT INTO card_tags (tag, card_id) VALUES ('ケモミミ', '248');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (248, 'hSD03-010', 'hSD03-010 JP ゲーマーズ ケモミミ 戌神ころね #JP #ゲーマーズ #ケモミミ おらよ～ 泥棒建設インターン 自分のセンターホロメンが〈猫又おかゆ〉の時、自分のデッキから、[マスコットかファン]1枚を公開し、手札に加える。そしてデッキをシャッフルする。 Inugami Korone #JP #Gamers #Animal Ears There ya go~ Thief Construction Intern If your Center holomem is 〈Nekomata Okayu〉, reveal 1 [Mascot or Fan] from your deck and add it to your hand. Then shuffle your deck. 戌神沁音 #JP #Gamers #獸耳 拿去啦～ 泥棒建設實習生 當自己的中衛Holo成員為〈貓又小粥〉時，從自己的牌庫公開1張[吉祥物或粉絲]，加入手牌。然後將牌庫洗牌。 Inugami Korone #JP #Gamers #Telinga Hewan Nih ya～ Magang Konstruksi Pencuri Saat Center holomenmu adalah 〈Nekomata Okayu〉, ungkapkan 1 kartu [Mascot atau Fan] dari dekmu, tambahkan ke tanganmu. Lalu, kocok deknya. 이누가미 코로네 #JP #게이머즈 #수인귀 자~ 간다~ 도둑 건설 인턴 자신의 센터 홀로멤이 〈네코마타 오카유〉일 때, 자신의 덱에서 [마스코트 또는 팬] 1장을 공개하고, 패에 넣는다. 그리고 덱을 셔플한다. อินุกามิ โคโรเนะ #JP #เกมเมอร์ส #หูสัตว์ เอ้า รับไป~ เด็กฝึกของ โจรก่อสร้าง เมื่อเซ็นเตอร์โฮโลเม็มของตนเองคือ 〈เนโกะมาตะ โอกายุ〉 ให้เปิดเผย [มาสคอตหรือแฟน] 1 ใบจากเด็คของตนเอง แล้วนำขึ้นมือ จากนั้นสับเด็ค Inugami Korone #JP #Gamers #Animal Ears ¡Toma ya～! Practicante de Thief Construction Si tu holomen central es 〈Nekomata Okayu〉, revela 1 carta [Mascot o Fan] de tu mazo y añádela a tu mano. Después, baraja tu mazo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('249', 'hSD03-011', 'character', 'U', 'spot', 'hSD03/hSD03-011_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD03/hSD03-011_U.png', 60, NULL, 1, '["null"]', NULL, 'ラプラス・ダークネス', '{"arts":[{"cost_types":["null"],"damage":10},{"cost_types":["null","null"],"damage":20}],"card_sets":["スタートデッキ 青 猫又おかゆ"],"color_codes":["null"],"translations":{"en":{"arts":[{"name":"Minister of Agriculture Thief Construction"},{"effect":"If you have 2 or fewer cards in hand, draw from your Deck until you have 3 cards in hand.","name":"I''ll Make You Eat It, No Matter What"}],"name":"Laplus Darknesss","tags":["#JP","#Secret Society holoX","#Shooter"]},"es":{"arts":[{"name":"Ministra de Agricultura Thief Construction"},{"effect":"Si tienes 2 o menos cartas en la mano, roba cartas de tu Mazo hasta tener 3 cartas en la mano.","name":"Te haré probarlo, cueste lo que cueste"}],"name":"Laplus Darknesss","tags":["#JP","#Secret Society holoX","#Shooter"]},"id":{"arts":[{"name":"Menteri Pertanian Konstruksi Pencuri"},{"effect":"Saat kartu di tanganmu 2 atau kurang, tarik kartu dari Deck milikmu sampai tanganmu menjadi 3 kartu.","name":"Aku pasti bakal bikin kamu makan ini"}],"name":"Laplus Darknesss","tags":["#JP","#Organisasi Rahasia holoX","#Penembak"]},"ja":{"arts":[{"name":"泥棒建設農業大臣"},{"effect":"自分の手札が2枚以下の時、手札が3枚になるまで、自分のデッキを引く。","name":"絶対、食わせてみせるわ"}],"name":"ラプラス・ダークネス","tags":["#JP","#秘密結社holoX","#シューター"]},"ko":{"arts":[{"name":"도둑 건설 농업대신"},{"effect":"자신의 패가 2장 이하일 때, 패가 3장이 될 때까지 자신의 덱을 뽑는다.","name":"반드시 먹여주겠어"}],"name":"라플라스 다크니스","tags":["#JP","#비밀결사 holoX","#슈터"]},"tc":{"arts":[{"name":"泥棒建設農業大臣"},{"effect":"當自己的手牌為2張以下時，抽牌直到手牌變成3張為止。","name":"我絕對會讓你吃下去"}],"name":"Laplus Darknesss","tags":["#JP","#秘密結社holoX","#射手"]},"th":{"arts":[{"name":"รัฐมนตรีเกษตร โจรก่อสร้าง"},{"effect":"เมื่อการ์ดบนมือของคุณมี 2 ใบหรือน้อยกว่า จั่วการ์ดจากเด็คของคุณจนการ์ดบนมือมี 3 ใบ","name":"ฉันจะทำให้นายกินให้ได้แน่"}],"name":"ลาปลัส ดาร์กเนส","tags":["#JP","#องค์กรลับ holoX","#ชูตเตอร์"]}}}', '{}', '7059eb5831a9920db06ddac075bf0ec64a3f32f136ef14a65ca9c172008cf07c', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
INSERT INTO card_colors (color_code, card_id) VALUES ('null', '249');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ 青 猫又おかゆ', '249');
INSERT INTO card_tags (tag, card_id) VALUES ('JP', '249');
INSERT INTO card_tags (tag, card_id) VALUES ('秘密結社holoX', '249');
INSERT INTO card_tags (tag, card_id) VALUES ('シューター', '249');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (249, 'hSD03-011', 'hSD03-011 JP 秘密結社holoX シューター ラプラス・ダークネス #JP #秘密結社holoX #シューター 泥棒建設農業大臣 絶対、食わせてみせるわ 自分の手札が2枚以下の時、手札が3枚になるまで、自分のデッキを引く。 Laplus Darknesss #JP #Secret Society holoX #Shooter Minister of Agriculture Thief Construction I''ll Make You Eat It, No Matter What If you have 2 or fewer cards in hand, draw from your Deck until you have 3 cards in hand. Laplus Darknesss #JP #秘密結社holoX #射手 泥棒建設農業大臣 我絕對會讓你吃下去 當自己的手牌為2張以下時，抽牌直到手牌變成3張為止。 Laplus Darknesss #JP #Organisasi Rahasia holoX #Penembak Menteri Pertanian Konstruksi Pencuri Aku pasti bakal bikin kamu makan ini Saat kartu di tanganmu 2 atau kurang, tarik kartu dari Deck milikmu sampai tanganmu menjadi 3 kartu. 라플라스 다크니스 #JP #비밀결사 holoX #슈터 도둑 건설 농업대신 반드시 먹여주겠어 자신의 패가 2장 이하일 때, 패가 3장이 될 때까지 자신의 덱을 뽑는다. ลาปลัส ดาร์กเนส #JP #องค์กรลับ holoX #ชูตเตอร์ รัฐมนตรีเกษตร โจรก่อสร้าง ฉันจะทำให้นายกินให้ได้แน่ เมื่อการ์ดบนมือของคุณมี 2 ใบหรือน้อยกว่า จั่วการ์ดจากเด็คของคุณจนการ์ดบนมือมี 3 ใบ Laplus Darknesss #JP #Secret Society holoX #Shooter Ministra de Agricultura Thief Construction Te haré probarlo, cueste lo que cueste Si tienes 2 o menos cartas en la mano, roba cartas de tu Mazo hasta tener 3 cartas en la mano.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('250', 'hSD03-012', 'supportEventLimited', 'U', NULL, 'hSD03/hSD03-012_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD03/hSD03-012_U.png', NULL, NULL, NULL, NULL, 'ぴ助', '泥棒建設', '{"card_sets":["スタートデッキ 青 猫又おかゆ"],"translations":{"en":{"ability_text":"You can use this card only if you have 6 or fewer cards in your hand, not counting this card.\n\nLook at the top 4 cards of your deck. Reveal any number of 〈Nekomata Okayu〉, 〈Takane Lui〉, 〈Ookami Mio〉, 〈Shirakami Fubuki〉, 〈Laplus Darknesss〉, and 〈Inugami Korone〉 from among them, and add the revealed holomem to your hand. Then return the remaining cards to the bottom of your deck in any order.\n\nLIMITED: You may use only 1 card per turn.","name":"Thief Construction"},"es":{"ability_text":"No puedes usar esta carta a menos que tu mano, sin contar esta carta, tenga 6 cartas o menos.\n\nMira las 4 cartas superiores de tu Deck. De entre ellas, revela cualquier cantidad de 〈Nekomata Okayu〉, 〈Takane Lui〉, 〈Ookami Mio〉, 〈Shirakami Fubuki〉, 〈Laplus Darknesss〉 y 〈Inugami Korone〉, y añade a tu mano los holomen revelados. Luego, devuelve el resto de las cartas al fondo del Deck en el orden que quieras.\n\nLIMITED: Solo puedes usar 1 carta por turno.","name":"Thief Construction"},"id":{"ability_text":"Kartu ini hanya bisa digunakan jika kartu di tanganmu, tidak termasuk kartu ini, berjumlah 6 atau kurang.\n\nLihat 4 kartu teratas Deck milikmu. Dari antaranya, ungkapkan sebanyak yang kamu mau 〈Nekomata Okayu〉, 〈Takane Lui〉, 〈Ookami Mio〉, 〈Shirakami Fubuki〉, 〈Laplus Darknesss〉, dan 〈Inugami Korone〉, lalu tambahkan Holomen yang diungkapkan ke tanganmu. Kemudian, kembalikan sisa kartunya ke bawah Deck dengan urutan sesukamu.\n\nLIMITED: Hanya bisa digunakan 1 kartu per giliran.","name":"Konstruksi Pencuri"},"ja":{"ability_text":"このカードは、自分の手札がこのカードを含まずに6枚以下でなければ使えない。\n\r\n自分のデッキの上から4枚を見る。その中から、〈猫又おかゆ〉と〈鷹嶺ルイ〉と〈大神ミオ〉と〈白上フブキ〉と〈ラプラス・ダークネス〉と〈戌神ころね〉を好きな枚数公開し、公開したホロメンを手札に加える。そして残ったカードを好きな順でデッキの下に戻す。\n\r\nLIMITED:ターンに1枚しか使えない。","name":"泥棒建設"},"ko":{"ability_text":"이 카드는, 자신의 패가 이 카드를 포함하지 않고 6장 이하여야만 사용할 수 있다.\n\n자신의 덱 위에서 4장을 본다. 그 중에서, 〈네코마타 오카유〉와 〈타카네 루이〉와 〈오오카미 미오〉와 〈시라카미 후부키〉와 〈라플라스 다크니스〉와 〈이누가미 코로네〉를 원하는 수만큼 공개하고, 공개한 홀로멘을 패에 넣는다. 그리고 남은 카드를 원하는 순서로 덱 아래로 되돌린다.\n\nLIMITED: 턴에 1장만 사용할 수 있다.","name":"도둑 건설"},"tc":{"ability_text":"這張卡只有在不計入這張卡的情況下，自己的手牌為6張以下時才能使用。\n\n查看自己牌庫頂4張。從中可公開任意張〈貓又小粥〉、〈鷹嶺露依〉、〈大神澪〉、〈白上吹雪〉、〈Laplus Darknesss〉與〈戌神沁音〉，將公開的Holomen加入手牌。然後將剩下的卡以任意順序放回牌庫底。\n\nLIMITED:每回合只能使用1張。","name":"泥棒建設"},"th":{"ability_text":"ใช้การ์ดนี้ได้ก็ต่อเมื่อในมือของคุณมีการ์ด 6 ใบหรือน้อยกว่า โดยไม่นับการ์ดนี้\n\nดูการ์ด 4 ใบบนสุดของเด็คคุณ จากนั้นเปิดเผยโฮโลเมนที่เป็น 〈เนโกะมาตะ โอกายุ〉 〈ทาคาเนะ รุย〉 〈โอกามิ มิโอ〉 〈ชิรากามิ ฟุบุกิ〉 〈ลาปลัส ดาร์กเนส〉 และ 〈อินุกามิ โคโรเนะ〉 จากในนั้นได้ตามจำนวนที่ต้องการ แล้วนำโฮโลเมนที่เปิดเผยขึ้นมือ จากนั้นนำการ์ดที่เหลือกลับไปไว้ใต้เด็คตามลำดับใดก็ได้\n\nLIMITED: ใช้ได้เพียง 1 ใบต่อเทิร์น","name":"โจรก่อสร้าง"}}}', '{}', '8b192f0f66b2f1930b60d54aadcaa3af842c5d7dde91920fc01fb1bfbeb44886', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ 青 猫又おかゆ', '250');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (250, 'hSD03-012', 'hSD03-012 ぴ助 泥棒建設 このカードは、自分の手札がこのカードを含まずに6枚以下でなければ使えない。
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('251', 'hSD03-013', 'supportMascot', 'C', NULL, 'hSD03/hSD03-013_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD03/hSD03-013_C.png', NULL, NULL, NULL, NULL, 'JinArt こばやかわやまと', 'おかにゃん', '{"card_sets":["スタートデッキ 青 猫又おかゆ"],"translations":{"en":{"ability_text":"The holomem this Mascot is attached to takes -10 damage while in the Center Position or Collab Position.\n\n◆ Additional ability if attached to 〈Nekomata Okayu〉\nWhen an ability of the holomem this Mascot is attached to would Archive Cheer, you may Archive this Mascot instead of 1 Blue Cheer to be Archived.\n\nYou may attach only 1 Mascot to each of your holomem.","name":"Okanyan"},"es":{"ability_text":"El daño que recibe en la Center Position o en la Collab Position el holomen al que está unida esta Mascot -10.\n\n◆ Si está unida a 〈Nekomata Okayu〉, añade la habilidad siguiente\nCuando archives Cheer por una habilidad del holomen al que está unida esta Mascot, puedes archivar esta Mascot en lugar de archivar 1 Blue Cheer.\n\nSolo puedes unir 1 Mascot a cada uno de tus holomen.","name":"Okanyan"},"id":{"ability_text":"Damage yang diterima Holomen yang dipasangi Mascot ini saat berada di Center Position atau Collab Position -10.\n\n◆Jika dipasang pada 〈Nekomata Okayu〉, tambahkan kemampuan\nSaat meng-Archive Cheer dengan kemampuan Holomen yang dipasangi Mascot ini, sebagai pengganti 1 kartu Yell Biru yang harus di-Archive, kamu bisa meng-Archive Mascot ini.\n\nSetiap Holomen milikmu hanya bisa dipasangi 1 Mascot.","name":"Okanyan"},"ja":{"ability_text":"このマスコットが付いているホロメンがセンターポジションかコラボポジションで受けるダメージ-10。\n\r\n◆〈猫又おかゆ〉に付いていたら能力追加\r\nこのマスコットが付いてるホロメンの能力でエールをアーカイブする時、アーカイブする青エール1枚のかわりに、このマスコットをアーカイブできる。\n\r\nマスコットは、自分のホロメン1人につき1枚だけ付けられる。","name":"おかにゃん"},"ko":{"ability_text":"이 마스코트가 붙어 있는 홀로멘이 센터 포지션 또는 콜라보 포지션에서 받는 데미지-10.\n\n◆〈네코마타 오카유〉에 붙어 있으면 능력 추가\n이 마스코트가 붙어 있는 홀로멘의 능력으로 에일을 아카이브할 때, 아카이브할 블루 옐 1장 대신 이 마스코트를 아카이브할 수 있다.\n\n마스코트는, 자신의 홀로멘 1명당 1장만 붙일 수 있다.","name":"오카냥"},"tc":{"ability_text":"這個吉祥物所附著的Holomen在中心位置或Collab位置受到的傷害-10。\n\n◆如果附在〈貓又小粥〉上，追加能力\n當因這個吉祥物所附著的Holomen的能力而要Archive Cheers時，可以Archive這個吉祥物來代替Archive 1張藍色應援。\n\n吉祥物每位自己的Holomen只能附1張。","name":"おかにゃん"},"th":{"ability_text":"แดเมจที่โฮโลเมนที่ติดมาสคอตนี้อยู่ได้รับในตำแหน่งเซ็นเตอร์หรือตำแหน่ง Collab -10\n\n◆ถ้าติดอยู่กับ〈เนโกะมาตะ โอกายุ〉 จะได้รับความสามารถเพิ่ม\nเมื่อ Archive Cheer ด้วยความสามารถของโฮโลเมนที่ติดมาสคอตนี้อยู่ คุณอาจ Archive มาสคอตนี้แทน เยลสีน้ำเงิน 1 ใบที่จะต้อง Archive\n\nMascot ติดได้เพียง 1 ใบต่อโฮโลเมนของคุณ 1 คนเท่านั้น","name":"โอกะญัง"}}}', '{}', 'd613137f9c62d1930f8d76f2948c68620fe90b4bd0787e47528c63c06e9e3135', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ 青 猫又おかゆ', '251');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (251, 'hSD03-013', 'hSD03-013 JinArt こばやかわやまと おかにゃん このマスコットが付いているホロメンがセンターポジションかコラボポジションで受けるダメージ-10。
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('252', 'hSD03-014', 'supportFan', 'C', NULL, 'hSD03/hSD03-014_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD03/hSD03-014_C.png', NULL, NULL, NULL, NULL, 'JinArt こばやかわやまと', 'おにぎりゃー', '{"card_sets":["スタートデッキ 青 猫又おかゆ"],"translations":{"en":{"ability_text":"The holomem this Fan is attached to gets HP +10.\n\nThis Fan can be attached only to your 〈Nekomata Okayu〉, and you may attach any number of them to each holomem.","name":"Onigiryaa"},"es":{"ability_text":"El HP del holomen al que está unido este Fan +10.\n\nEste Fan solo puede unirse a tus 〈Nekomata Okayu〉, y puedes unir cualquier número a cada uno.","name":"Onigiryaa"},"id":{"ability_text":"HP Holomen yang dipasangi Fan ini +10.\n\nFan ini hanya bisa dipasang pada 〈Nekomata Okayu〉 milikmu, dan bisa dipasang berapa pun banyaknya pada tiap 1 orang.","name":"Onigiryaa"},"ja":{"ability_text":"このファンが付いているホロメンのHP+10。\n\r\nこのファンは、自分の〈猫又おかゆ〉だけに付けられ、1人につき何枚でも付けられる。","name":"おにぎりゃー"},"ko":{"ability_text":"이 팬이 붙어 있는 홀로멘의 HP+10.\n\n이 팬은, 자신의 〈네코마타 오카유〉에게만 붙일 수 있으며, 1명당 몇 장이든 붙일 수 있다.","name":"오니기랴"},"tc":{"ability_text":"這個粉絲所附著的Holomen的HP+10。\n\n這個粉絲只能附在自己的〈貓又小粥〉上，且每位可附任意張數。","name":"飯糰民"},"th":{"ability_text":"HP ของโฮโลเมนที่ติดแฟนนี้อยู่ +10\n\nแฟนนี้ติดได้เฉพาะกับ〈เนโกะมาตะ โอกายุ〉ของคุณเท่านั้น และติดได้กี่ใบก็ได้ต่อ 1 คน","name":"โอนิกิร่า"}}}', '{}', '0e6db4ba57ad1c510af71130ceeb04b8d3f278bc070e0e1dd8f28f1fc0be4259', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
