INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('253', 'hSD04-001', 'oshiCharacter', 'OC', NULL, 'hSD04/hSD04-001_OC', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD04/hSD04-001_OC.png', NULL, 5, NULL, NULL, '松尾 省吾', '癒月ちょこ', '{"card_sets":["スタートデッキ 紫 癒月ちょこ"],"color_codes":["purple"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Yuzuki Choco","oshi_skill":{"effect":"[Once per turn] During this turn, your purple Center holomem gets Arts +20.","name":"PURPLE MIC","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] Draw 2 cards from your deck, then archive 1 card from your hand.","name":"CARD CHANGE","timing":"Once per game"}},"es":{"name":"Yuzuki Choco","oshi_skill":{"effect":"[Una vez por turno] Durante este turno, las Arts de tu Centro holomen morado +20.","name":"Micrófono Morado","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Después de robar 2 cartas de tu mazo, archiva 1 carta de tu mano.","name":"Cambio de carta","timing":"Una vez por partida"}},"id":{"name":"Yuzuki Choco","oshi_skill":{"effect":"[Sekali per giliran] Selama giliran ini, Arts dari Center holomem ungu milikmu +20.","name":"Mik Ungu","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per game] Setelah kamu menarik 2 kartu dari deck-mu, arsipkan 1 kartu dari tanganmu.","name":"Ganti Kartu","timing":"Sekali per permainan"}},"ja":{"name":"癒月ちょこ","oshi_skill":{"effect":"[ターンに1回]このターンの間、自分の紫センターホロメンのアーツ+20。","name":"パープルマイク","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]自分のデッキを2枚引いた後、手札1枚をアーカイブする。","name":"カードチェンジ","timing":"ゲームに1回"}},"ko":{"name":"유즈키 초코","oshi_skill":{"effect":"[턴에 1번] 이 턴 동안, 자신의 보라색 센터 홀로멘의 아츠 +20.","name":"퍼플 마이크","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번] 자신의 덱을 2장 뽑은 뒤, 패 1장을 아카이브한다.","name":"카드 체인지","timing":"게임에 1번"}},"tc":{"name":"癒月巧可","oshi_skill":{"effect":"[每回合1次]在這個回合中，自己的紫色中心Holo成員的藝術+20。","name":"紫色麥克風","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場遊戲1次]抽自己的牌組2張後，將1張手牌存入歸檔。","name":"卡牌變換","timing":"每場對戰1次"}},"th":{"name":"ยุซุกิ โชโคะ","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] ในระหว่างเทิร์นนี้ อาร์ตของเซ็นเตอร์โฮโลเมนสีม่วงของคุณ +20","name":"ไมค์สีม่วง","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] จั่วการ์ดจากเด็คของคุณ 2 ใบ แล้วเก็บการ์ดในมือ 1 ใบเข้าอาร์ไคฟ์","name":"เปลี่ยนการ์ด","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{}', 'b6be082a13ff7b8f11e09af585ee4ef01726afa51ce45b45a9d3d1a35b76d478', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
