INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (254, 'hSD04-002', 'hSD04-002 JP 2期生 料理 癒月ちょこ #JP #2期生 #料理 魔界の保健医 Yuzuki Choco #JP #2nd Gen #Cooking School Nurse of the Demon Realm 癒月巧可 #JP #2期生 #料理 魔界的保健醫 Yuzuki Choco #JP #Gen 2 #Masakan Dokter UKS Dunia Iblis 유즈키 초코 #JP #2기생 #요리 마계의 보건의 ยุซุกิ โชโคะ #JP #รุ่น 2 #ทำอาหาร คุณหมอห้องพยาบาลแห่งโลกปีศาจ Yuzuki Choco #JP #2nd Gen #Cooking Enfermera escolar del inframundo', '');
