INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (255, 'hSD04-003', 'hSD04-003 さとうぽて JP 2期生 料理 癒月ちょこ #JP #2期生 #料理 マイキュ～トスチュ～デ～ンツ グッイブニ～ング 自分の推しホロメンの色が紫の時、自分のデッキを1枚引く。 Yuzuki Choco #JP #2nd Gen #Cooking My Cuuute Stuuudents Good Eveni~ng If your oshi holomem is purple, draw 1 card. 癒月巧可 #JP #2期生 #料理 我的可～愛學～生們 Goooood Evening～ 當自己的推Holomen的顏色為紫色時，自己抽1張牌。 Yuzuki Choco #JP #Gen 2 #Masakan Murid-muridkuuu yang lucuuu Good Ibu~ning Jika warna oshiholomen milikmu adalah ungu, tarik 1 kartu dari Deck milikmu. 유즈키 초코 #JP #2기생 #요리 마이 큐~트 스튜~던츠 굿 이브니~잉 자신의 오시 홀로멤의 색이 보라일 때, 자신의 덱을 1장 뽑는다. ยุซุกิ โชโคะ #JP #รุ่น 2 #ทำอาหาร นักเรี๊ยน~น่ารักของฉัน กู๊ดอีฟนี~ง ถ้าสีของโอชิโฮโลเมนของคุณเป็นสีม่วง ให้จั่วการ์ด 1 ใบจากเด็คของคุณ Yuzuki Choco #JP #2nd Gen #Cooking Mis estuuudiaaantes adorables ¡Guu ibuniiing! Si el color de tu oshi holomen es morado, roba 1 carta de tu mazo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('256', 'hSD04-004', 'character', 'U', 'debut', 'hSD04/hSD04-004_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD04/hSD04-004_U.png', 60, NULL, 1, '["null"]', 'とぴあ', '癒月ちょこ', '{"arts":[{"cost_types":["purple"],"damage":20}],"card_sets":["スタートデッキ 紫 癒月ちょこ"],"color_codes":["purple"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Eat Up Lots♡"}],"keyword":{"effect":"You may archive 1 card from your hand: Reveal 1 Event with #Food from your deck and add it to your hand. Then shuffle your deck.","name":"Hellishly Heaped Meal"},"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"es":{"arts":[{"name":"Come un montón, ¿sí?♡"}],"keyword":{"effect":"Puedes archivar 1 carta de tu mano: revela 1 Evento de tu mazo que tenga #Food y añádelo a tu mano. Luego baraja tu mazo.","name":"Arroz infernal bien servido"},"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"id":{"arts":[{"name":"Makan yang banyak ya♡"}],"keyword":{"effect":"Kamu boleh mengarsipkan 1 kartu dari tanganmu: ungkapkan 1 Event yang memiliki #Makanan dari dekmu, lalu tambahkan ke tanganmu. Lalu kocok dekmu.","name":"Nasi porsi neraka"},"name":"Yuzuki Choco","tags":["#JP","#Gen 2","#Masakan"]},"ja":{"arts":[{"name":"いっぱい食べてね♡"}],"keyword":{"effect":"自分の手札1枚をアーカイブできる:自分のデッキから、#食べ物を持つイベント1枚を公開し、手札に加える。そしてデッキをシャッフルする。","name":"地獄盛りごはん"},"name":"癒月ちょこ","tags":["#JP","#2期生","#料理"]},"ko":{"arts":[{"name":"많이 먹어줘♡"}],"keyword":{"effect":"자신의 손패 1장을 아카이브할 수 있다: 자신의 덱에서 #음식를 가진 이벤트 1장을 공개하고, 손패에 넣는다. 그리고 덱을 셔플한다.","name":"지옥 푸짐 덮밥"},"name":"유즈키 초코","tags":["#JP","#2기생","#요리"]},"tc":{"arts":[{"name":"要多吃一點喔♡"}],"keyword":{"effect":"可以將自己1張手牌存入檔案區：從自己的牌庫中公開1張持有#食物的活動卡，加入手牌。然後將牌庫洗牌。","name":"地獄豪華蓋飯"},"name":"癒月巧可","tags":["#JP","#2期生","#料理"]},"th":{"arts":[{"name":"กินเยอะๆ นะ♡"}],"keyword":{"effect":"คุณสามารถอาร์ไคฟ์การ์ดในมือของคุณ 1 ใบได้: เปิดเผยอีเวนต์ 1 ใบจากเด็คของคุณที่มี #อาหาร แล้วนำขึ้นมือ จากนั้นสับเด็ค","name":"ข้าวจัดเต็มนรก"},"name":"ยุซุกิ โชโคะ","tags":["#JP","#รุ่น 2","#ทำอาหาร"]}}}', '{}', 'b5cbf2424e57e792b789a223efd7f7848af18443571837cee3ef1d645bc66e15', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
