INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (257, 'hSD04-005', 'hSD04-005 桝石きのと JP 2期生 料理 癒月ちょこ #JP #2期生 #料理 おつかれいと…… あ～む（ﾁｭｯ） Yuzuki Choco #JP #2nd Gen #Cooking Otsukareito... Say Ahh~ (chu) 癒月巧可 #JP #2期生 #料理 辛苦雷特…… 啊～嗯（啾） Yuzuki Choco #JP #Gen 2 #Masakan Otsukareito…… Aaam（chu） 유즈키 초코 #JP #2기생 #요리 오츠카레이트…… 아~앙(쪽) ยุซุกิ โชโคะ #JP #รุ่น 2 #ทำอาหาร โอตสึคาเรโตะ…… อ้าม~（จุ๊บ） Yuzuki Choco #JP #2nd Gen #Cooking Otsukareito…… Aaaam~ (chu)', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('258', 'hSD04-006', 'character', 'C', 'first', 'hSD04/hSD04-006_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD04/hSD04-006_C.png', 130, NULL, NULL, NULL, 'Nardack', '癒月ちょこ', '{"arts":[{"cost_types":["purple","null"],"damage":30}],"card_sets":["スタートデッキ 紫 癒月ちょこ"],"color_codes":["purple"],"translations":{"en":{"arts":[{"effect":"When this Art deals damage to an opponent''s holomem, heal 10 HP from this holomem for each 10 damage dealt.","name":"Forbidden Kiss"}],"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"es":{"arts":[{"effect":"Cuando este Arte haga daño a un holomen del oponente, cura 10 HP a este holomen por cada 10 de daño infligido.","name":"Beso prohibido"}],"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"id":{"arts":[{"effect":"Saat Arts ini memberi damage kepada holomen lawan, pulihkan HP holomen ini 10 untuk setiap 10 damage yang diberikan.","name":"Ciuman Terlarang"}],"name":"Yuzuki Choco","tags":["#JP","#Gen 2","#Masakan"]},"ja":{"arts":[{"effect":"このアーツで相手のホロメンにダメージを与えた時、与えたダメージ10につき、このホロメンのHP10回復。","name":"禁断のキッス"}],"name":"癒月ちょこ","tags":["#JP","#2期生","#料理"]},"ko":{"arts":[{"effect":"이 아츠로 상대의 홀로멘에게 대미지를 주었을 때, 준 대미지 10마다 이 홀로멘의 HP를 10 회복한다.","name":"금단의 키스"}],"name":"유즈키 초코","tags":["#JP","#2기생","#요리"]},"tc":{"arts":[{"effect":"當此藝術對對手的Holo成員造成傷害時，每造成10點傷害，這位Holo成員回復HP10。","name":"禁忌之吻"}],"name":"癒月巧可","tags":["#JP","#2期生","#料理"]},"th":{"arts":[{"effect":"เมื่อศิลปะนี้สร้างความเสียหายแก่โฮโลเมนของฝ่ายตรงข้าม ฟื้นฟู HP ของโฮโลเมนนี้ 10 ต่อความเสียหาย 10 ที่สร้าง","name":"จูบต้องห้าม"}],"name":"ยุซุกิ โชโคะ","tags":["#JP","#รุ่น 2","#ทำอาหาร"]}}}', '{}', '2ce1ff06d87a6cb4799563b3e73cd503ac483c1a39c7af4c9f9bf9201db88913', '44136fa355b3678a1146ad16f7e8649e94fb4f