INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (258, 'hSD04-006', 'hSD04-006 Nardack JP 2期生 料理 癒月ちょこ #JP #2期生 #料理 禁断のキッス このアーツで相手のホロメンにダメージを与えた時、与えたダメージ10につき、このホロメンのHP10回復。 Yuzuki Choco #JP #2nd Gen #Cooking Forbidden Kiss When this Art deals damage to an opponent''s holomem, heal 10 HP from this holomem for each 10 damage dealt. 癒月巧可 #JP #2期生 #料理 禁忌之吻 當此藝術對對手的Holo成員造成傷害時，每造成10點傷害，這位Holo成員回復HP10。 Yuzuki Choco #JP #Gen 2 #Masakan Ciuman Terlarang Saat Arts ini memberi damage kepada holomen lawan, pulihkan HP holomen ini 10 untuk setiap 10 damage yang diberikan. 유즈키 초코 #JP #2기생 #요리 금단의 키스 이 아츠로 상대의 홀로멘에게 대미지를 주었을 때, 준 대미지 10마다 이 홀로멘의 HP를 10 회복한다. ยุซุกิ โชโคะ #JP #รุ่น 2 #ทำอาหาร จูบต้องห้าม เมื่อศิลปะนี้สร้างความเสียหายแก่โฮโลเมนของฝ่ายตรงข้าม ฟื้นฟู HP ของโฮโลเมนนี้ 10 ต่อความเสียหาย 10 ที่สร้าง Yuzuki Choco #JP #2nd Gen #Cooking Beso prohibido Cuando este Arte haga daño a un holomen del oponente, cura 10 HP a este holomen por cada 10 de daño infligido.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('259', 'hSD04-007', 'character', 'U', 'first', 'hSD04/hSD04-007_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD04/hSD04-007_U.png', 110, NULL, 1, '["null"]', NULL, '癒月ちょこ', '{"arts":[{"cost_types":["null","null"],"damage":30}],"card_sets":["スタートデッキ 紫 癒月ちょこ","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["purple"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"Heal 20 HP from 1 of your back holomems.","name":"Love You! Mwah♡"}],"keyword":{"effect":"You may return 1 non-LIMITED Event from your Archive to your hand.","name":"Plop!"},"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"es":{"arts":[{"effect":"Cura 20 HP a 1 de tus holomen de la Retaguardia.","name":"¡Te adoro! Chu♡"}],"keyword":{"effect":"Puedes devolver a tu mano 1 Evento que no sea LIMITED de tu Archivo.","name":"¡Chokkooon!"},"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"id":{"arts":[{"effect":"Pulihkan 20 HP dari 1 Back holomen milikmu.","name":"Suka banget! Muah♡"}],"keyword":{"effect":"Kamu boleh mengembalikan 1 Event non-LIMITED dari Archive milikmu ke tanganmu.","name":"Jreng!"},"name":"Yuzuki Choco","tags":["#JP","#Gen 2","#Masakan"]},"ja":{"arts":[{"effect":"自分のバックホロメン1人のHP20回復。","name":"大好き！ちゅっ♡"}],"keyword":{"effect":"自分のアーカイブのLIMITED以外のイベント1枚を手札に戻せる。","name":"ちょっこーん！"},"name":"癒月ちょこ","tags":["#JP","#2期生","#料理"]},"ko":{"arts":[{"effect":"자신의 백 홀로멘 1명의 HP 20 회복.","name":"정말 좋아! 쪽♡"}],"keyword":{"effect":"자신의 아카이브에 있는 LIMITED가 아닌 이벤트 1장을 패로 되돌릴 수 있다.","name":"쪼꼬온!"},"name":"유즈키 초코","tags":["#JP","#2기생","#요리"]},"tc":{"arts":[{"effect":"回復自己1名Back holomen的HP 20。","name":"最喜歡你了！啾♡"}],"keyword":{"effect":"可以將自己Archive中1張LIMITED以外的事件返回手牌。","name":"蹲一下！"},"name":"癒月巧可","tags":["#JP","#2期生","#料理"]},"th":{"arts":[{"effect":"ฟื้นฟู HP 20 ให้แบ็กโฮโลเมนของคุณ 1 คน","name":"รักที่สุดเลย! จุ๊บ♡"}],"keyword":{"effect":"คุณสามารถนำอีเวนต์ 1 ใบที่ไม่ใช่ LIMITED จาก Archive ของคุณกลับขึ้นมือได้","name":"จุ๊มปุ๊ก!"},"name":"ยุซุกิ โชโคะ","tags":["#JP","#รุ่น 2","#ทำอาหาร"]}}}', '{}', 'cf5b9ae21c4ac61f7b0093af381b28d5cdf0d50218ad4f02943f7d3f4da6e2fe', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
