INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (260, 'hSD04-008', 'hSD04-008 いちかわはる JP 2期生 料理 癒月ちょこ #JP #2期生 #料理 がんばってつくったよ 召し上がれ 自分のアーカイブの#食べ物を持つイベント1枚を手札に戻せる:このアーツ+20。 Yuzuki Choco #JP #2nd Gen #Cooking I Worked Hard on This Dig In You may return 1 Event with #Food from your Archive to your hand: this Art gets +20. 癒月巧可 #JP #2期生 #料理 我很努力做出來的喔 請享用 可以將自己存檔區的1張持有#食物的活動返回手牌：此藝術+20。 Yuzuki Choco #JP #Gen 2 #Masakan Aku bikin ini dengan sungguh-sungguh Silakan dinikmati Kamu boleh mengembalikan 1 Event yang memiliki #Makanan dari Archive milikmu ke tanganmu: Arts ini +20. 유즈키 초코 #JP #2기생 #요리 열심히 만들었어 드세요 자신의 아카이브의 #음식를 가진 이벤트 1장을 패로 되돌릴 수 있다: 이 아츠 +20. ยุซุกิ โชโคะ #JP #รุ่น 2 #ทำอาหาร ตั้งใจทำสุดๆ เลยนะ เชิญทานเลย คุณสามารถนำอีเวนต์ 1 ใบที่มี #อาหาร จากอาร์ไคฟ์ของคุณกลับขึ้นมือได้: ศิลปะนี้ +20 Yuzuki Choco #JP #2nd Gen #Cooking Lo hice con mucho esfuerzo Buen provecho Puedes devolver a tu mano 1 Evento con #Food de tu Archivo: este Arte +20.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('261', 'hSD04-009', 'character', 'RR', 'second', 'hSD04/hSD04-009_RR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD04/hSD04-009_RR.png', 190, NULL, 1, '["null"]', 'saihate', '癒月ちょこ', '{"arts":[{"cost_types":["purple","null"],"damage":50,"special_targets":["green"],"special_values":[50]},{"cost_types":["purple","purple","null"],"damage":60,"is_plus":true,"special_targets":["green"],"special_values":[50]}],"card_sets":["スタートデッキ 紫 癒月ちょこ"],"color_codes":["purple"],"translations":{"en":{"arts":[{"name":"33... 22... 11..."},{"effect":"This Arts gains +40 for each Event you used this turn.","name":"Aku-tto"}],"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"es":{"arts":[{"name":"33… 22… 11…"},{"effect":"Esta Art +40 por cada 1 Evento que hayas usado este turno.","name":"Akutto"}],"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"id":{"arts":[{"name":"33… 22… 11…"},{"effect":"Untuk tiap 1 Event yang telah kamu gunakan pada giliran ini, Arts ini +40.","name":"Akutto"}],"name":"Yuzuki Choco","tags":["#JP","#Gen 2","#Masakan"]},"ja":{"arts":[{"name":"33… 22… 11…"},{"effect":"このターンに自分が使っていたイベント1枚につき、このアーツ+40。","name":"あくとっ"}],"name":"癒月ちょこ","tags":["#JP","#2期生","#料理"]},"ko":{"arts":[{"name":"33… 22… 11…"},{"effect":"이번 턴에 자신이 사용한 이벤트 1장당, 이 아츠+40.","name":"아쿠톳"}],"name":"유즈키 초코","tags":["#JP","#2기생","#요리"]},"tc":{"arts":[{"name":"33… 22… 11…"},{"effect":"這個回合自己每使用過1張活動卡，這個藝術便+40。","name":"Acutto"}],"name":"癒月巧可","tags":["#JP","#2期生","#料理"]},"th":{"arts":[{"name":"33… 22… 11…"},{"effect":"อาร์ตนี้ +40 ต่ออีเวนต์ 1 ใบที่คุณได้ใช้ในเทิร์นนี้","name":"อาคุตต์"}],"name":"ยุซุกิ โชโคะ","tags":["#JP","#รุ่น 2","#ทำอาหาร"]}}}', '{}', 'b41a79bc40c6d14923d8f524b13ab38a618361106ca8a631a3b7cb0afb6d47bf', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
