INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (261, 'hSD04-009', 'hSD04-009 saihate JP 2期生 料理 癒月ちょこ #JP #2期生 #料理 33… 22… 11… あくとっ このターンに自分が使っていたイベント1枚につき、このアーツ+40。 Yuzuki Choco #JP #2nd Gen #Cooking 33... 22... 11... Aku-tto This Arts gains +40 for each Event you used this turn. 癒月巧可 #JP #2期生 #料理 33… 22… 11… Acutto 這個回合自己每使用過1張活動卡，這個藝術便+40。 Yuzuki Choco #JP #Gen 2 #Masakan 33… 22… 11… Akutto Untuk tiap 1 Event yang telah kamu gunakan pada giliran ini, Arts ini +40. 유즈키 초코 #JP #2기생 #요리 33… 22… 11… 아쿠톳 이번 턴에 자신이 사용한 이벤트 1장당, 이 아츠+40. ยุซุกิ โชโคะ #JP #รุ่น 2 #ทำอาหาร 33… 22… 11… อาคุตต์ อาร์ตนี้ +40 ต่ออีเวนต์ 1 ใบที่คุณได้ใช้ในเทิร์นนี้ Yuzuki Choco #JP #2nd Gen #Cooking 33… 22… 11… Akutto Esta Art +40 por cada 1 Evento que hayas usado este turno.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('262', 'hSD04-010', 'character', 'U', 'spot', 'hSD04/hSD04-010_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD04/hSD04-010_U.png', 60, NULL, 1, '["null"]', NULL, '大空スバル', '{"arts":[{"cost_types":["null","null"],"damage":20}],"card_sets":["スタートデッキ 紫 癒月ちょこ"],"color_codes":["null"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Hell Lottery—You’re Drawing One!"}],"keyword":{"effect":"If your Center holomem is 〈Yuzuki Choco〉, you may send 1 Cheer card from your Archive to one of your holomems.","name":"Chiyokooooo!!"},"name":"Oozora Subaru","tags":["#JP","#2nd Gen"]},"es":{"arts":[{"name":"¡Te haré sacar el sorteo infernal!"}],"keyword":{"effect":"Si tu holomen del centro es 〈Yuzuki Choco〉, puedes enviar 1 Cheer de tu archivo a uno de tus holomen.","name":"¡¡Chiyokoooo!!"},"name":"Oozora Subaru","tags":["#JP","#2nd Gen"]},"id":{"arts":[{"name":"Undian Neraka, bakal kusuruh kamu tarik!"}],"keyword":{"effect":"Saat Center holomen milikmu adalah 〈Yuzuki Choco〉, kamu boleh mengirim 1 Cheer dari Arsip milikmu ke holomen milikmu.","name":"Chiyokooo!!"},"name":"Oozora Subaru","tags":["#JP","#Gen 2"]},"ja":{"arts":[{"name":"地獄くじ引き、引かせるぞっ"}],"keyword":{"effect":"自分のセンターホロメンが〈癒月ちょこ〉の時、自分のアーカイブのエール1枚を自分のホロメンに送れる。","name":"ちよこーーッ！！"},"name":"大空スバル","tags":["#JP","#2期生"]},"ko":{"arts":[{"name":"지옥 제비뽑기, 뽑게 해주지"}],"keyword":{"effect":"자신의 센터 홀로멤이 〈유즈키 초코〉일 때, 자신의 아카이브의 엘 1장을 자신의 홀로멤에게 보낼 수 있다.","name":"치요코ーー!!"},"name":"오오조라 스바루","tags":["#JP","#2기생"]},"tc":{"arts":[{"name":"地獄抽籤，給我抽下去！"}],"keyword":{"effect":"當自己的中心Holomen為〈癒月巧可〉時，可以將自己存檔區的1張應援送給自己的Holomen。","name":"Chiyoko——！！"},"name":"大空昴","tags":["#JP","#2期生"]},"th":{"arts":[{"name":"ลอตเตอรี่จากนรก ฉันจะให้เธอจับเอง!"}],"keyword":{"effect":"เมื่อเซ็นเตอร์โฮโลเมนของคุณคือ 〈ยุซุกิ โชโคะ〉 คุณสามารถนำเยล 1 ใบจากอาร์ไคฟ์ของคุณไปติดให้โฮโลเมนของคุณ","name":"ชิโยโกะーーッ!!"},"name":"โอโซระ สุบารุ","tags":["#JP","#รุ่น 2"]}}}', '{}', '13aeafb69e683a0468c640b8268590f87d31d528bc7eb7836bd3ab2a80d7d1c6', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
