INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (275, 'hBP02-008', 'hBP02-008 JP 1期生 ゲーマーズ ケモミミ 絵 白上フブキ #JP #1期生 #ゲーマーズ #ケモミミ #絵 こんこんきーつね！ Shirakami Fubuki #JP #1st Gen #Gamers #Animal Ears #Art Konkonki-tsune! 白上吹雪 #JP #1期生 #Gamers #獸耳 #繪畫 konkon狐～！ Shirakami Fubuki #JP #Gen 1 #Gamers #Telinga Hewan #Seni Konkon kitsune! 시라카미 후부키 #JP #1기생 #게이머즈 #수인귀 #그림 콩콩 키츠네! ชิรากามิ ฟุบุกิ #JP #รุ่น 1 #เกมเมอร์ส #หูสัตว์ #ศิลปะ คงคงคิ้ตสึเนะ! Shirakami Fubuki #JP #1st Gen #Gamers #Animal Ears #Art ¡Konkonkitsune!', '');
