INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (278, 'hBP02-011', 'hBP02-011 JP 1期生 ゲーマーズ ケモミミ 絵 白上フブキ #JP #1期生 #ゲーマーズ #ケモミミ #絵 ダメですよっ！ 白上から目をそらしちゃ 自分のデッキから、#白上''sキャラクターを持つカード1枚を公開し、手札に加える。そしてデッキをシャッフルする。 Shirakami Fubuki #JP #1st Gen #Gamers #Animal Ears #Art You Mustn’t! Don''t Look Away from Shirakami Reveal 1 card with #Shirakami''s Character from your deck and add it to your hand. Then shuffle your deck. 白上吹雪 #JP #1期生 #Gamers #獸耳 #繪畫 不可以喔！ 可別把視線從白上身上移開 從自己的牌庫中公開1張持有#白上的角色的卡，加入手牌。然後將牌庫洗牌。 Shirakami Fubuki #JP #Gen 1 #Gamers #Telinga Hewan #Seni Nggak boleh! Jangan alihkan pandangan dari Shirakami Dari dekmu, ungkapkan 1 kartu yang memiliki #Karakter Shirakami, lalu tambahkan ke tanganmu. Lalu kocok dekmu. 시라카미 후부키 #JP #1기생 #게이머즈 #수인귀 #그림 안 된다구요! 시라카미에게서 눈을 돌리면 자신의 덱에서 #시라카미의 캐릭터를 가진 카드 1장을 공개하고, 손패에 넣는다. 그리고 덱을 셔플한다. ชิรากามิ ฟุบุกิ #JP #รุ่น 1 #เกมเมอร์ส #หูสัตว์ #ศิลปะ ไม่ได้นะ! อย่าหลบสายตาจาก ชิรากามิ ล่ะ เปิดเผยการ์ด 1 ใบที่มี #ตัวละครของชิรากามิ จากเด็คของคุณ แล้วนำขึ้นมือ จากนั้นสับเด็ค Shirakami Fubuki #JP #1st Gen #Gamers #Animal Ears #Art ¡Eso no se hace! No apartes la mirada de Shirakami Revela 1 carta de tu mazo que tenga #Shirakami''s Character y añádela a tu mano. Luego baraja tu mazo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('279', 'hBP02-012', 'character', 'R', 'first', 'hBP02/hBP02-012_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-012_R.png', 100, NULL, 1, '["null"]', 'CNO', '白上フブキ', '{"arts":[{"cost_types":["white","null"],"damage":50,"is_plus":true}],"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["white"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"Until end of turn, your [Center holomem and Collab holomem] with your Mascot attached get +20 Arts.","name":"Please Lend Me Your Strength"}],"keyword":{"effect":"You may reattach 1 Mascot on your Stage to your holomem.","name":"I''ll Move It a Little"},"name":"Shirakami Fubuki","tags":["#JP","#1st Gen","#Gamers","#Animal Ears","#Art"]},"es":{"arts":[{"effect":"Durante este turno, los Artes de tu [holomen del Centro y holomen de Colaboración] que tengan un Mascot unido +20.","name":"Préstame tu fuerza, ¿sí?"}],"keyword":{"effect":"Puedes cambiar 1 Mascot de tu escenario a uno de tus holomen.","name":"Voy a moverlo un poquito"},"name":"Shirakami Fubuki","tags":["#JP","#1st Gen","#Gamers","#Animal Ears","#Art"]},"id":{"arts":[{"effect":"Selama giliran ini, Arts dari [holomen Center dan holomen Collab] milikmu yang terpasang Mascot +20.","name":"Tolong pinjamkan kekuatanmu, ya"}],"keyword":{"effect":"Kamu boleh memindahkan 1 Mascot di Stage-mu ke holomenmu.","name":"Aku geser sedikit ya"},"name":"Shirakami Fubuki","tags":["#JP","#Gen 1","#Gamers","#Telinga Hewan","#Seni"]},"ja":{"arts":[{"effect":"このターンの間、自分のマスコットが付いている[センターホロメンとコラボホロメン]のアーツ+20。","name":"力をかしてくださいね"}],"keyword":{"effect":"自分のステージのマスコット1枚を、自分のホロメンに付け替えられる。","name":"ちょっと動かしますね"},"name":"白上フブキ","tags":["#JP","#1期生","#ゲーマーズ","#ケモミミ","#絵"]},"ko":{"arts":[{"effect":"이번 턴 동안, 자신의 마스코트가 붙어 있는 [센터 홀로멘과 콜라보 홀로멘]의 아츠 +20.","name":"힘을 빌려주세요"}],"keyword":{"effect":"자신의 스테이지의 마스코트 1장을 자신의 홀로멤에게 다시 붙일 수 있다.","name":"잠깐 움직여 볼게요"},"name":"시라카미 후부키","tags":["#JP","#1기생","#게이머즈","#수인귀","#그림"]},"tc":{"arts":[{"effect":"本回合期間，自己附有吉祥物的[中心Holomen與合作Holomen]的藝術+20。","name":"請借給我力量吧"}],"keyword":{"effect":"可以將自己舞台上的1張吉祥物改附到自己的Holo成員上。","name":"我稍微動一下喔"},"name":"白上吹雪","tags":["#JP","#1期生","#Gamers","#獸耳","#繪畫"]},"th":{"arts":[{"effect":"ตลอดเทิร์นนี้ ศิลปะของ [โฮโลเมมตำแหน่งเซ็นเตอร์และโฮโลเมมตำแหน่งคอลแลบ] ที่ติดมาสคอตของคุณอยู่ +20","name":"ช่วยยืมพลังให้ฉันหน่อยนะ"}],"keyword":{"effect":"สามารถย้ายมาสคอต 1 ใบบนสเตจของตนเองไปติดกับโฮโลเม็มของตนเองได้","name":"ขอขยับหน่อยนะคะ"},"name":"ชิรากามิ ฟุบุกิ","tags":["#JP","#รุ่น 1","#เกมเมอร์ส","#หูสัตว์","#ศิลปะ"]}}}', '{}', '6555ba0581a899b254dad25806f73f9e2790443f5ea622cbea9a4611faa7af3f', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
