INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('288', 'hBP02-021', 'character', 'U', 'first', 'hBP02/hBP02-021_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-021_U.png', 120, NULL, 1, '["null"]', NULL, 'パヴォリア・レイネ', '{"arts":[{"cost_types":["null"],"damage":20}],"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["green"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"You may send 1 Cheer from your Archive to one of your holomem.","name":"So keep watching, okay? I love you!"}],"keyword":{"effect":"Heal 10 HP from 1 of your holomems for each color of Cheer on your Stage.","name":"I''ll sing and dance with all my heart."},"name":"Pavolia Reine","tags":["#ID","#ID 2nd Gen","#Bird","#Art"]},"es":{"arts":[{"effect":"Puedes enviar 1 Cheer de tu Archivo a uno de tus holomen.","name":"¡Así que mírame! ¡Te quiero!"}],"keyword":{"effect":"Cura 10 HP a 1 de tus holomen por cada color de Cheer en tu escenario.","name":"Cantaré y bailaré con todo mi corazón."},"name":"Pavolia Reine","tags":["#ID","#ID 2nd Gen","#Bird","#Art"]},"id":{"arts":[{"effect":"Kamu boleh kirim 1 El dari Archive kamu ke holomen milikmu.","name":"Jadi, lihat aku ya! Aku sayang kalian!"}],"keyword":{"effect":"Untuk setiap 1 warna Cheer di Stage milikmu, pulihkan 10 HP dari 1 holomen milikmu.","name":"Aku akan bernyanyi dan menari sepenuh hati."},"name":"Pavolia Reine","tags":["#ID","#ID Gen 2","#Burung","#Seni"]},"ja":{"arts":[{"effect":"自分のアーカイブのエール1枚を自分のホロメンに送れる。","name":"だから見ててね！大好き！"}],"keyword":{"effect":"自分のステージのエール1色につき、自分のホロメン1人のHP10回復。","name":"心を込めて歌って、踊ります。"},"name":"パヴォリア・レイネ","tags":["#ID","#ID2期生","#トリ","#絵"]},"ko":{"arts":[{"effect":"자신의 아카이브의 에일 1장을 자신의 홀로멤에게 보낼 수 있다.","name":"그러니까 지켜봐 줘! 정말 좋아해!"}],"keyword":{"effect":"자신의 스테이지의 엘 1색마다, 자신의 홀로멤 1명의 HP를 10 회복.","name":"마음을 담아 노래하고, 춤춥니다."},"name":"파볼리아 레이네","tags":["#ID","#ID 2기생","#새","#그림"]},"tc":{"arts":[{"effect":"可將自己存檔區中的1張應援送給自己的Holo成員。","name":"所以要看著我喔！最喜歡你了！"}],"keyword":{"effect":"自己舞台上每有1種顏色的應援，自己的1位Holomen回復HP10。","name":"我會全心全意地歌唱、跳舞。"},"name":"Pavolia Reine","tags":["#ID","#ID2期生","#小鳥","#繪畫"]},"th":{"arts":[{"effect":"คุณสามารถส่งเยล 1 ใบจากอาร์ไคฟ์ของคุณไปยังโฮโลเมนของคุณได้","name":"เพราะงั้นคอยดูนะ! รักที่สุดเลย!"}],"keyword":{"effect":"ฟื้นฟู HP 10 ให้โฮโลเมนของคุณ 1 คน ต่อเยลแต่ละสีบนสเตจของคุณ","name":"จะร้องและเต้นด้วยหัวใจทั้งหมดของฉัน"},"name":"ปาโวเลีย เรเน่","tags":["#ID","#ID รุ่น 2","#นก","#ศิลปะ"]}}}', '{}', '590dd2cf66b2c226e2bed2468503630576a64e5d9987f9cb00b086c4b4cb86b8', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
