INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (290, 'hBP02-023', 'hBP02-023 pbj ID ID2期生 トリ 絵 パヴォリア・レイネ #ID #ID2期生 #トリ #絵 孔雀の舞 自分のステージのエール1色につき、このアーツ+20。 Kanjeng 自分のエールデッキから、エール1枚を公開し、自分のホロメンに送る。そしてエールデッキをシャッフルする。 Pavolia Reine #ID #ID 2nd Gen #Bird #Art Peacock Dance This Art gets +20 for each color of Cheer on your Stage. Kanjeng Reveal 1 Cheer from your Cheer Deck and send it to one of your holomems. Then shuffle your Cheer Deck. Pavolia Reine #ID #ID2期生 #小鳥 #繪畫 孔雀之舞 自己舞台上的應援每有1種顏色，此藝術+20。 Kanjeng 從自己的應援牌庫公開1張應援，附加給自己的holomen。然後將應援牌庫洗牌。 Pavolia Reine #ID #ID Gen 2 #Burung #Seni Tarian Merak Untuk tiap 1 warna Cheer di Stage milikmu, Arts ini +20. Kanjeng Buka 1 kartu Cheer dari Cheer Deck milikmu, lalu kirimkan ke salah satu holomen milikmu. Setelah itu, kocok Cheer Deck-mu. 파볼리아 레이네 #ID #ID 2기생 #새 #그림 공작의 춤 자신의 스테이지의 에일 1색당, 이 아츠 +20. Kanjeng 자신의 엘 덱에서 엘 1장을 공개하고, 자신의 홀로멘에게 보낸다. 그리고 엘 덱을 셔플한다. ปาโวเลีย เรเน่ #ID #ID รุ่น 2 #นก #ศิลปะ ระบำนกยูง ศิลปะนี้ +20 ต่อพลังงาน 1 สีบนสเตจของคุณ Kanjeng อวดเยล 1 ใบจากเยลเด็คของคุณ แล้วส่งไปยังโฮโลเมนของคุณ จากนั้นสับเยลเด็ค Pavolia Reine #ID #ID 2nd Gen #Bird #Art Danza del pavo real Por cada 1 color de Cheer en tu Escenario, este Arte +20. Kanjeng Revela 1 Cheer de tu mazo de Cheer y envíaselo a uno de tus holomembers. Después, baraja tu mazo de Cheer.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('291', 'hBP02-024', 'character', 'C', 'debut', 'hBP02/hBP02-024_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-024_C.png', 90, NULL, 2, '["null","null"]', NULL, '大神ミオ', '{"arts":[{"cost_types":["null"],"damage":10}],"card_sets":["ブースターパック「クインテットスペクトラム」","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["green"],"translations":{"en":{"arts":[{"effect":"You may move 1 Cheer on your Stage to a holomem with #JP.","name":"Me, me, it''s me~ It''s Ookami Mio~"}],"name":"Ookami Mio","tags":["#JP","#Gamers","#Animal Ears","#Cooking"]},"es":{"arts":[{"effect":"Puedes volver a unir 1 Cheer de tu Escenario a un holomen con #JP que controles.","name":"Uchi uchi, soy yo~ soy Ookami Mio~"}],"name":"Ookami Mio","tags":["#JP","#Gamers","#Animal Ears","#Cooking"]},"id":{"arts":[{"effect":"Kamu boleh pindahkan 1 El di Stage kamu agar terpasang pada holomen milikmu yang memiliki #JP.","name":"Uchi uchi, ini aku～ Ookami Mio lho～"}],"name":"Ookami Mio","tags":["#JP","#Gamers","#Telinga Hewan","#Masakan"]},"ja":{"arts":[{"effect":"自分のステージのエール1枚を、自分の#JPを持つホロメンに付け替えられる。","name":"うちうち、うちだよ～大神ミオだよ～"}],"name":"大神ミオ","tags":["#JP","#ゲーマーズ","#ケモミミ","#料理"]},"ko":{"arts":[{"effect":"자신의 스테이지의 에일 1장을 자신의 #JP를 가진 홀로멤에게 다시 붙일 수 있다.","name":"우리우리, 나야~ 오오카미 미오야~"}],"name":"오오카미 미오","tags":["#JP","#게이머즈","#수인귀","#요리"]},"tc":{"arts":[{"effect":"可將自己舞台上的1張應援，改附給自己持有#JP的Holo成員。","name":"我我我，是我喔～大神澪喔～"}],"name":"大神澪","tags":["#JP","#Gamers","#獸耳","#料理"]},"th":{"arts":[{"effect":"คุณสามารถสลับเยล 1 ใบบนสเตจของคุณไปติดกับโฮโลเมนที่มี #JP ของคุณได้","name":"อุจิอุจิ ฉันเองน้า~ โอกามิ มิโอ ไง~"}],"name":"โอกามิ มิโอ","tags":["#JP","#เกมเมอร์ส","#หูสัตว์","#ทำอาหาร"]}}}', '{}', '10ab874a4185f018942254d9108c3c58deb68e037e5f41ddd6a390cefbdfed31', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
