INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (297, 'hBP02-030', 'hBP02-030 あかさあい JP 3期生 絵 海 宝鐘マリン #JP #3期生 #絵 #海 船長、何されちゃうのかな？ もう、どスケベ♥ Houshou Marine #JP #3rd Gen #Art #Ocean Captain, what are they gonna do to you? Good Grief, You Perv♥ 寶鐘瑪琳 #JP #3期生 #繪畫 #海洋 船長，會對我做什麼呢？ 真是的，超色♥ Houshou Marine #JP #Gen 3 #Seni #Laut Kapten, bakal diapain ya? Ih, mesum banget♥ 호쇼 마린 #JP #3기생 #그림 #바다 선장, 뭘 당하게 되는 걸까? 정말, 음탕해♥ โฮโช มารีน #JP #รุ่น 3 #ศิลปะ #ทะเล กัปตัน จะโดนทำอะไรน้า? โอ๊ย ลามกสุดๆ ♥ Houshou Marine #JP #3rd Gen #Art #Ocean Capitana, ¿qué te van a hacer? Ay, qué pervertidilla♥', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('298', 'hBP02-031', 'character', 'U', 'first', 'hBP02/hBP02-031_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-031_U.png', 130, NULL, 1, '["null"]', NULL, '宝鐘マリン', '{"arts":[{"cost_types":["null"],"damage":30}],"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["red"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"Let''s Set Sail Together! (Wholesomely)"}],"keyword":{"effect":"Deal 20 special damage to your opponent''s Collab holomem.","name":"Your Voices Support the Captain!"},"name":"Houshou Marine","tags":["#JP","#3rd Gen","#Art","#Ocean"]},"es":{"arts":[{"name":"¡Zarpemos juntas! (sano)"}],"keyword":{"effect":"Inflige 20 de daño especial al holomen de colaboración de tu oponente.","name":"¡Las voces de ustedes sostienen a la Capitana!"},"name":"Houshou Marine","tags":["#JP","#3rd Gen","#Art","#Ocean"]},"id":{"arts":[{"name":"Ayo berlayar bersama! (sehat)"}],"keyword":{"effect":"Berikan 20 Damage Khusus pada Collab holomen lawan.","name":"Suara kalian adalah penopang Kapten!"},"name":"Houshou Marine","tags":["#JP","#Gen 3","#Seni","#Laut"]},"ja":{"arts":[{"name":"いっしょに出航しましょう！（健全）"}],"keyword":{"effect":"相手のコラボホロメンに特殊ダメージ20を与える。","name":"キミたちの声が船長の支えです！"},"name":"宝鐘マリン","tags":["#JP","#3期生","#絵","#海"]},"ko":{"arts":[{"name":"같이 출항해요! (건전)"}],"keyword":{"effect":"상대의 콜라보 홀로멤에게 특수 대미지 20을 준다.","name":"너희들의 목소리가 선장의 버팀목입니다!"},"name":"호쇼 마린","tags":["#JP","#3기생","#그림","#바다"]},"tc":{"arts":[{"name":"一起啟航吧！（健全）"}],"keyword":{"effect":"對手的合作Holomen受到特殊傷害20。","name":"你們的聲音就是船長的支柱！"},"name":"寶鐘瑪琳","tags":["#JP","#3期生","#繪畫","#海洋"]},"th":{"arts":[{"name":"ออกเรือไปด้วยกันเถอะ!（ใสสะอาด）"}],"keyword":{"effect":"สร้างความเสียหายพิเศษ 20 แก่โคแลบโฮโลเมนของคู่แข่ง","name":"เสียงของพวกเธอคือกำลังใจของกัปตัน!"},"name":"โฮโช มารีน","tags":["#JP","#รุ่น 3","#ศิลปะ","#ทะเล"]}}}', '{}', '7a603d4ef2099115efd27b84fcc9b93fc7c3fdd25fab918bebb3ea76be615234', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
