INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (302, 'hBP02-035', 'hBP02-035 JP 秘密結社holoX 海 沙花叉クロヱ #JP #秘密結社holoX #海 ばっくばっくばく～ん Sakamata Chloe #JP #Secret Society holoX #Ocean Chomp chomp CHOMP~ 沙花叉克蘿耶 #JP #秘密結社holoX #海洋 大口大口啊嗚～ Sakamata Chloe #JP #Organisasi Rahasia holoX #Laut Bakku bakku baku～n 사카마타 클로에 #JP #비밀결사 holoX #바다 왁왁와구~응 ซากามาตะ โคลเอ #JP #องค์กรลับ holoX #ทะเล บั๊กบั๊กบากุ~น Sakamata Chloe #JP #Secret Society holoX #Ocean Back back bakuun～', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('303', 'hBP02-036', 'character', 'U', 'debut', 'hBP02/hBP02-036_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-036_U.png', 60, NULL, 1, '["null"]', 'TAiGA', '沙花叉クロヱ', '{"arts":[{"cost_types":["null"],"damage":20}],"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["blue"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"That Throwaway Reality!"}],"keyword":{"effect":"Look at the top 3 cards of your deck. Reveal 1 2nd holomem with #SecretSocietyholoX from among them and add it to your hand. Then return the remaining cards to the bottom of your deck in any order.","name":"Interning at the Cleaners"},"name":"Sakamata Chloe","tags":["#JP","#Secret Society holoX","#Ocean"]},"es":{"arts":[{"name":"¡Una realidad para escupir y tirar!"}],"keyword":{"effect":"Mira las 3 cartas superiores de tu mazo. Revela 1 2nd holomen con #秘密結社holox de entre ellas y añádelo a tu mano. Luego devuelve las cartas restantes al fondo de tu mazo en el orden que prefieras.","name":"Prácticas en la agencia de limpieza"},"name":"Sakamata Chloe","tags":["#JP","#Secret Society holoX","#Ocean"]},"id":{"arts":[{"name":"Hancurkan kenyataan yang ingin dimuntahkan lalu dibuang itu!"}],"keyword":{"effect":"Lihat 3 kartu teratas dekmu. Ungkapkan 1 2nd Holomen yang memiliki #秘密結社holox dari antaranya, lalu tambahkan ke tanganmu. Lalu kembalikan sisa kartu ke bagian bawah dek dalam urutan sesuka hati.","name":"Magang di jasa kebersihan"},"name":"Sakamata Chloe","tags":["#JP","#Organisasi Rahasia holoX","#Laut"]},"ja":{"arts":[{"name":"吐いて捨てるような現実を！"}],"keyword":{"effect":"自分のデッキの上から3枚を見る。その中から、#秘密結社holoxを持つ2ndホロメン1枚を公開し、手札に加える。そして残ったカードを好きな順でデッキの下に戻す。","name":"掃除屋でインターン"},"name":"沙花叉クロヱ","tags":["#JP","#秘密結社holoX","#海"]},"ko":{"arts":[{"name":"토해내듯 내던질 현실을!"}],"keyword":{"effect":"자신의 덱 위에서부터 3장을 본다. 그중에서 #비밀결사holoX를 가진 2nd 홀로멤 1장을 공개하고, 손패에 넣는다. 그리고 남은 카드를 원하는 순서로 덱 아래로 되돌린다.","name":"청소부 인턴"},"name":"사카마타 클로에","tags":["#JP","#비밀결사 holoX","#바다"]},"tc":{"arts":[{"name":"將這種爛到想吐的現實給！"}],"keyword":{"effect":"查看自己牌庫頂端3張牌。從中公開1張持有#秘密結社holox的2nd Holomen，加入手牌。然後將剩餘的牌依喜歡的順序放回牌庫底。","name":"在清潔公司實習"},"name":"沙花叉克蘿耶","tags":["#JP","#秘密結社holoX","#海洋"]},"th":{"arts":[{"name":"ความจริงที่น่าอ้วกจนอยากคายทิ้ง!"}],"keyword":{"effect":"ดูการ์ด 3 ใบจากบนสุดของเด็คของคุณ จากนั้นเปิดเผย 2nd โฮโลเมน 1 ใบที่มี #秘密結社holox จากในนั้นแล้วนำขึ้นมือ แล้วนำการ์ดที่เหลือกลับไปไว้ใต้เด็คตามลำดับที่ต้องการ","name":"ฝึกงานกับบริษัทรับทำความสะอาด"},"name":"ซากามาตะ โคลเอ","tags":["#JP","#องค์กรลับ holoX","#ทะเล"]}}}', '{}', '15a563d7b3c9db873ee1755312c1b08a19916b0d3c5ef91e7dfe9ff6cbfda4a6', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
