INSERT INTO card_tags (tag, card_id) VALUES ('2期生', '313');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (313, 'hBP02-046', 'hBP02-046 TSCR JP 2期生 紫咲シオン #JP #2期生 チェンジ・ザ・エール サイコロを1回振れる:5以上の時、相手のステージのエール1枚を、相手のホロメンに付け替える。 入れ替えの魔法 自分の手札1枚をアーカイブできる:自分のアーカイブの#魔法を持つカード1枚を手札に戻す。 Murasaki Shion #JP #2nd Gen Change the Yell You may roll a die once: if it is 5 or higher, move 1 Cheer on the opponent''s Stage to a different one of the opponent''s holomem. Switching Magic You may archive 1 card from your hand: Return 1 card with #Magic from your Archive to your hand. 紫咲詩音 #JP #2期生 Change the Yell 可以擲1次骰子：若為5以上，將對手舞台上的1張應援改附給對手的Holomen。 替換的魔法 可以將自己手牌1張放置到Archive：將自己Archive中1張帶有#魔法的卡返回手牌。 Murasaki Shion #JP #Gen 2 Change the Ale Kamu boleh melempar dadu 1 kali: jika hasilnya 5 atau lebih, pindahkan 1 Cheer di Stage lawan ke holomen lawan. Sihir pertukaran Kamu boleh mengarsipkan 1 kartu dari tanganmu: kembalikan 1 kartu yang memiliki #Sihir dari Archive milikmu ke tanganmu. 무라사키 시온 #JP #2기생 체인지 더 에일 주사위를 1회 굴릴 수 있다: 5 이상이라면, 상대 스테이지의 에일 1장을 상대의 홀로멘에게 갈아붙인다. 바꿔치기의 마법 자신의 패 1장을 아카이브할 수 있다: 자신의 아카이브에 있는 #마법를 가진 카드 1장을 패로 되돌린다. มุราซากิ ชิออง #JP #รุ่น 2 เชนจ์ ดิ เยล คุณสามารถทอยลูกเต๋า 1 ครั้งได้: ถ้าออก 5 ขึ้นไป ย้ายเอิล 1 ใบจากสเตจของฝ่ายตรงข้ามไปติดกับโฮโลเมมของฝ่ายตรงข้าม เวทมนตร์สลับตัว คุณสามารถเก็บการ์ดในมือของคุณ 1 ใบเข้า Archive ได้: นำการ์ด 1 ใบที่มี #เวทมนตร์ จาก Archive ของคุณกลับขึ้นมือ Murasaki Shion #JP #2nd Gen Change the Yell Puedes lanzar 1 dado: si sale 5 o más, cambia de lugar 1 Cheer del Escenario de tu oponente para unirlo a uno de sus holomen. Magia de intercambio Puedes archivar 1 carta de tu mano: devuelve a tu mano 1 carta con #Magic de tu Archivo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('314', 'hBP02-047', 'character', 'RR', 'second', 'hBP02/hBP02-047_RR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-047_RR.png', 200, NULL, 2, '["null","null"]', '夕城', '紫咲シオン', '{"arts":[{"cost_types":["purple","purple","null"],"damage":80,"special_targets":["green"],"special_values":[50]}],"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["purple"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"Deal 20 special damage to the opponent''s Center holomem and Collab holomem for each Cheer on the opponent''s Center holomem.","name":"Violet Magic"}],"keyword":{"effect":"You may roll one die: If the result is 4 or higher, reattach 1 Cheer on your opponent''s Stage to one of your opponent''s holomem.","name":"Mischief Magic"},"name":"Murasaki Shion","tags":["#JP","#2nd Gen"]},"es":{"arts":[{"effect":"Inflige al holomen del Centro y al holomen de Colaboración de tu oponente 20 de daño especial por cada Cheer del holomen del Centro de tu oponente.","name":"Magia violeta"}],"keyword":{"effect":"Puedes lanzar un dado 1 vez: si sale 4 o más, cambia 1 Cheer del escenario de tu oponente a otro de sus holomen.","name":"Magia traviesa"},"name":"Murasaki Shion","tags":["#JP","#2nd Gen"]},"id":{"arts":[{"effect":"Berikan Special Damage 20 kepada Center holomen lawan dan Collab holomen lawan, untuk setiap 1 El pada Center holomen lawan.","name":"Sihir Violet"}],"keyword":{"effect":"Kamu boleh melempar dadu 1 kali: jika hasilnya 4 atau lebih, pindahkan 1 kartu Cheer di Stage lawan ke holomen lawan.","name":"Sihir keusilan"},"name":"Murasaki Shion","tags":["#JP","#Gen 2"]},"ja":{"arts":[{"effect":"相手のセンターホロメンとコラボホロメンに、相手のセンターホロメンのエール1枚につき、特殊ダメージ20を与える。","name":"ヴァイオレットマジック"}],"keyword":{"effect":"サイコロを1回振れる:4以上の時、相手のステージのエール1枚を、相手のホロメンに付け替える。","name":"いたずらの魔法"},"name":"紫咲シオン","tags":["#JP","#2期生"]},"ko":{"arts":[{"effect":"상대의 센터 홀로멤과 콜라보 홀로멤에게, 상대의 센터 홀로멤의 에일 1장당 특수 대미지 20을 준다.","name":"바이올렛 매직"}],"keyword":{"effect":"주사위를 1번 굴릴 수 있다: 4 이상이 나오면, 상대 스테이지의 에일 1장을 상대의 홀로멤에게 다시 붙인다.","name":"장난의 마법"},"name":"무라사키 시온","tags":["#JP","#2기생"]},"tc":{"arts":[{"effect":"對手的中心Holo成員與合作Holo成員，依對手的中心Holo成員每有1張應援，各造成特殊傷害20。","name":"紫羅蘭魔法"}],"keyword":{"effect":"可以擲1次骰子：若為4以上，將對手舞台上的1張應援改附到對手的Holo成員上。","name":"惡作劇的魔法"},"name":"紫咲詩音","tags":["#JP","#2期生"]},"th":{"arts":[{"effect":"สร้างความเสียหายพิเศษ 20 ให้แก่เซ็นเตอร์โฮโลเมนและคอลแลบโฮโลเมนของฝ่ายตรงข้าม ต่อเยล 1 ใบของเซ็นเตอร์โฮโลเมนของฝ่ายตรงข้าม","name":"เวทมนตร์สีไวโอเล็ต"}],"keyword":{"effect":"สามารถทอยลูกเต๋า 1 ครั้ง: หากออก 4 ขึ้นไป ให้ย้ายเยล 1 ใบบนสเตจของคู่ต่อสู้ไปติดกับโฮโลเม็มของคู่ต่อสู้","name":"เวทมนตร์แห่งการแกล้ง"},"name":"มุราซากิ ชิออง","tags":["#JP","#รุ่น 2"]}}}', '{}', '95f18bd668b7b7fea305675d4da11db40af1fada66113522645f4019f009e17d', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
