INSERT INTO card_tags (tag, card_id) VALUES ('歌', '326');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (326, 'hBP02-059', 'hBP02-059 たむ EN Myth 歌 森カリオペ #EN #Myth #歌 Featuring Myth 自分のアーカイブに#Mythを持つホロメンが、4枚以上ある時、このアーツ+40。8枚以上ある時、さらに、このアーツ+40。 Soul Voice 自分のデッキから、カード1枚を公開し、アーカイブする。そしてデッキをシャッフルする。 Mori Calliope #EN #Myth #Singing Featuring Myth If there are 4 or more holomem with #Myth in your Archive, this Art gets +40. If there are 8 or more, additionally, this Art gets +40. Soul Voice Reveal 1 card from your deck and archive it. Then shuffle your deck. 森美聲 #EN #Myth #歌唱 Featuring Myth 當自己的存檔區有4張以上持有#Myth的Holo成員時，此藝術+40。有8張以上時，再額外使此藝術+40。 Soul Voice 從自己的牌庫公開1張卡牌，並將其存檔。然後將牌庫洗牌。 Mori Calliope #EN #Myth #Menyanyi Featuring Myth Saat ada 4 kartu atau lebih holomen yang memiliki #Myth di Arsip milikmu, Arts ini +40. Saat ada 8 kartu atau lebih, tambahan lagi Arts ini +40. Soul Voice Ungkapkan 1 kartu dari dekmu, lalu arsipkan kartu itu. Setelah itu, kocok dekmu. 모리 칼리오페 #EN #Myth #노래 Featuring Myth 자신의 아카이브에 #Myth를 가진 홀로멘이 4장 이상 있을 때, 이 아츠 +40. 8장 이상 있을 때, 추가로 이 아츠 +40. Soul Voice 자신의 덱에서 카드 1장을 공개하고 아카이브한다. 그리고 덱을 셔플한다. โมริ คาลลิโอเป #EN #Myth #เพลง Featuring Myth ถ้าในอาร์ไคฟ์ของคุณมีโฮโลเมนที่มี #Myth ตั้งแต่ 4 ใบขึ้นไป ศิลปะนี้ +40 ถ้ามีตั้งแต่ 8 ใบขึ้นไป เพิ่มอีก ศิลปะนี้ +40 Soul Voice เปิดเผยการ์ด 1 ใบจากเด็คของคุณ แล้วเก็บเข้าอาร์ไคฟ์ จากนั้นสับเด็ค Mori Calliope #EN #Myth #Singing Featuring Myth Si hay 4 o más holomems con #Myth en tu Archivo, este Arte +40. Si hay 8 o más, además, este Arte +40. Soul Voice Revela 1 carta de tu mazo, archívala y luego baraja tu mazo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('327', 'hBP02-060', 'buzzCharacter', 'R', 'first', 'hBP02/hBP02-060_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-060_R.png', 240, NULL, 1, '["null"]', '江田藤', '癒月ちょこ', '{"arts":[{"cost_types":["purple","null","null"],"damage":80}],"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["purple"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"Charm You Just Can’t Hide"}],"keyword":{"effect":"You may heal 50 HP from 1 of your Back holomems: Deal 10 special damage to your opponent''s Center holomem for each 10 damage healed.","name":"A Seductive Gaze"},"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"es":{"arts":[{"name":"Un encanto imposible de ocultar"}],"keyword":{"effect":"Puedes curar 50 HP a 1 de tus holomem de la retaguardia: inflige 10 de daño especial al holomem central de tu oponente por cada 10 de daño curado.","name":"Mirada seductora"},"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"id":{"arts":[{"name":"Pesona yang Tak Bisa Disembunyikan"}],"keyword":{"effect":"Kamu dapat memulihkan 50 HP dari 1 Back holomem milikmu: Berikan 10 Damage Khusus kepada Center holomem lawan untuk setiap 10 damage yang dipulihkan.","name":"Tatapan menggoda"},"name":"Yuzuki Choco","tags":["#JP","#Gen 2","#Masakan"]},"ja":{"arts":[{"name":"隠しきれない魅力"}],"keyword":{"effect":"自分のバックホロメン1人のHP50回復できる:相手のセンターホロメンに、回復したダメージ10につき、特殊ダメージ10を与える。","name":"誘惑の視線"},"name":"癒月ちょこ","tags":["#JP","#2期生","#料理"]},"ko":{"arts":[{"name":"감출 수 없는 매력"}],"keyword":{"effect":"자신의 백 홀로멤 1명의 HP를 50 회복할 수 있다: 상대의 센터 홀로멤에게 회복한 대미지 10당 특수 대미지 10을 준다.","name":"유혹의 시선"},"name":"유즈키 초코","tags":["#JP","#2기생","#요리"]},"tc":{"arts":[{"name":"藏不住的魅力"}],"keyword":{"effect":"可以使自己1位Back Holo成員回復HP50：對對手的Center Holo成員，每回復10點傷害，就造成特殊傷害10。","name":"誘惑的視線"},"name":"癒月巧可","tags":["#JP","#2期生","#料理"]},"th":{"arts":[{"name":"เสน่ห์ที่ปิดไม่มิด"}],"keyword":{"effect":"คุณสามารถฟื้นฟู HP 50 ให้แบ็กโฮโลเมนของคุณ 1 คน: สร้างดาเมจพิเศษ 10 แก่เซ็นเตอร์โฮโลเมนของฝ่ายตรงข้ามต่อดาเมจที่ฟื้นฟูทุก 10","name":"สายตาเย้ายวน"},"name":"ยุซุกิ โชโคะ","tags":["#JP","#รุ่น 2","#ทำอาหาร"]}}}', '{}', '415b430bc9ca68df5897590b3fd31d07abfb17cde702d517d3a78b981ab4902a', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
