INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (330, 'hBP02-063', 'hBP02-063 EN Myth 絵 海 一伊那尓栖 #EN #Myth #絵 #海 楽しんでいこう！！！ みんな「WAH」の準備はいいかー！ 自分の#Mythを持つホロメン1人のHP20回復。 Ninomae Ina''nis #EN #Myth #Art #Ocean Let’s Have Fun!!! Everyone, are you ready to "WAH"?! Heal 20 HP from 1 of your holomems with #Myth. 一伊那尓栖 #EN #Myth #繪畫 #海洋 盡情享受吧！！！ 大家都準備好喊「WAH」了嗎—！ 使自己1位持有#Myth的Holo成員回復HP20。 Ninomae Ina''nis #EN #Myth #Seni #Laut Ayo bersenang-senang!!! Semuanya—siap bilang "WAH"?! Pulihkan 20 HP dari 1 holomem milikmu yang memiliki #Myth. 니노마에 이나니스 #EN #Myth #그림 #바다 재밌게 가보자!!! 모두 「WAH」 할 준비 됐나~! 자신의 #Myth를 가진 홀로멤 1명의 HP 20 회복. นิโนมาเอะ อินาอนิส #EN #Myth #ศิลปะ #ทะเล มาสนุกกันให้เต็มที่!!! ทุกคนพร้อมจะร้อง "WAH" กันหรือยังー! ฟื้นฟู HP 20 ให้โฮโลเมน 1 คนของคุณที่มี #Myth Ninomae Ina''nis #EN #Myth #Art #Ocean ¡¡¡Vamos a divertirnos!!! ¡Todos, ¿están listos para el «WAH»?! Cura 20 HP a 1 de tus holomem con #Myth.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('331', 'hBP02-064', 'buzzCharacter', 'RR', 'first', 'hBP02/hBP02-064_RR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-064_RR.png', 250, NULL, 2, '["null","null"]', '虎んと', '一伊那尓栖', '{"arts":[{"cost_types":["purple","null"],"damage":60,"is_plus":true}],"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["purple"],"translations":{"en":{"arts":[{"effect":"If there are 5 or more holomem with #Myth in your Archive, you may move 1 Cheer from this holomem to another of your holomem. If there are 10 or more instead, this Art gets an additional +50.","name":"Archaic Smile"}],"name":"Ninomae Ina''nis","tags":["#EN","#Myth","#Art","#Ocean"]},"es":{"arts":[{"effect":"Si hay 5 o más holomen con #Myth en tu Archivo, puedes volver a unir 1 Cheer de este holomen a otro de tus holomen. Si hay 10 o más, además, este Arte +50.","name":"Sonrisa arcaica"}],"name":"Ninomae Ina''nis","tags":["#EN","#Myth","#Art","#Ocean"]},"id":{"arts":[{"effect":"Saat ada 5 kartu atau lebih holomen dengan #Myth di Archive kamu, kamu boleh pindahkan 1 El dari holomen ini agar terpasang pada holomen milikmu yang lain. Saat ada 10 kartu atau lebih, selain itu, Arts ini +50.","name":"Senyum Arkais"}],"name":"Ninomae Ina''nis","tags":["#EN","#Myth","#Seni","#Laut"]},"ja":{"arts":[{"effect":"自分のアーカイブに#Mythを持つホロメンが、5枚以上ある時、このホロメンのエール1枚を、自分の他のホロメンに付け替えられる。10枚以上ある時、さらに、このアーツ+50。","name":"アルカイックスマイル"}],"name":"一伊那尓栖","tags":["#EN","#Myth","#絵","#海"]},"ko":{"arts":[{"effect":"자신의 아카이브에 #Myth를 가진 홀로멤이 5장 이상 있을 때, 이 홀로멤의 에일 1장을 자신의 다른 홀로멤에게 다시 붙일 수 있다. 10장 이상 있을 때, 추가로 이 아츠 +50.","name":"아카익 스마일"}],"name":"니노마에 이나니스","tags":["#EN","#Myth","#그림","#바다"]},"tc":{"arts":[{"effect":"當自己的存檔區中有5張以上持有#Myth的Holo成員時，可將此Holo成員的1張應援改附給自己的其他Holo成員。當有10張以上時，則再使此藝術+50。","name":"古典微笑"}],"name":"一伊那尓栖","tags":["#EN","#Myth","#繪畫","#海洋"]},"th":{"arts":[{"effect":"เมื่อในอาร์ไคฟ์ของคุณมีโฮโลเมนที่มี #Myth ตั้งแต่ 5 ใบขึ้นไป คุณสามารถสลับเยล 1 ใบของโฮโลเมนนี้ไปติดกับโฮโลเมนอื่นของคุณได้ เมื่อมีตั้งแต่ 10 ใบขึ้นไป นอกจากนี้ อาร์ตนี้ +50","name":"รอยยิ้มโบราณ"}],"name":"นิโนมาเอะ อินาอนิส","tags":["#EN","#Myth","#ศิลปะ","#ทะเล"]}}}', '{}', '26fa19275f058f797d9ebaa0fd3a22dc63d14ceff1423059061b33cc71d6da03', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
