INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('372', 'hBP02-002', 'oshiCharacter', 'OUR', NULL, 'hBP02/hBP02-002_OUR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-002_OUR.png', NULL, 5, NULL, NULL, 'すなれ', 'パヴォリア・レイネ', '{"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["green"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Pavolia Reine","oshi_skill":{"effect":"[Once per turn] By Archiving 1 Green Cheer of your holomem, reveal 1 Cheer from your Cheer Deck and send it to your holomem. Then shuffle your Cheer Deck.","name":"HALU","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] Until end of turn, all holomem with #ID 2nd Gen on your Stage get Arts +20 for each Cheer color that holomem has.","name":"A Feast of Vivid Colors","timing":"Once per game"}},"es":{"name":"Pavolia Reine","oshi_skill":{"effect":"[Una vez por turno] Al archivar 1 carta Green Cheer de uno de tus holomen, revela 1 Cheer de tu mazo Cheer y envíalo a uno de tus holomen. Luego baraja el mazo Cheer.","name":"HALU","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Durante este turno, todos los holomen de tu Escenario con #ID 2nd Gen obtienen Arts +20 por cada color de Cheer de ese holomen.","name":"Banquete multicolor","timing":"Una vez por partida"}},"id":{"name":"Pavolia Reine","oshi_skill":{"effect":"[Sekali per giliran] Dengan mengarsipkan 1 Yell Hijau dari holomen milikmu, ungkapkan 1 Cheer dari cheer deck milikmu, lalu kirimkan ke holomen milikmu. Kemudian kocok cheer deck milikmu.","name":"HALU","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per permainan] Selama giliran ini, semua Holomen di Stage milikmu yang memiliki #ID Gen 2 mendapatkan Arts +20 untuk setiap 1 warna Cheer pada Holomen tersebut.","name":"Perjamuan Warna-Warni","timing":"Sekali per permainan"}},"ja":{"name":"パヴォリア・レイネ","oshi_skill":{"effect":"[ターンに1回]自分のホロメンの緑エール1枚をアーカイブすることで、自分のエールデッキから、エール1枚を公開し、自分のホロメンに送る。そしてエールデッキをシャッフルする。","name":"HALU","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]このターンの間、自分のステージの#ID2期生を持つホロメン全員は、そのホロメンのエール1色につき、アーツ+20。","name":"極彩色の宴","timing":"ゲームに1回"}},"ko":{"name":"파볼리아 레이네","oshi_skill":{"effect":"[턴에 1번]자신의 홀로멘의 그린 옐 1장을 아카이브함으로써 자신의 에일 덱에서 에일 1장을 공개하고 자신의 홀로멘에게 보낸다. 그리고 에일 덱을 셔플한다.","name":"HALU","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번]이번 턴 동안, 자신의 스테이지의 #ID 2기생을 가진 홀로멤 전원은 그 홀로멤의 에일 1색당 아츠 +20.","name":"극채색의 연회","timing":"게임에 1번"}},"tc":{"name":"Pavolia Reine","oshi_skill":{"effect":"[每回合1次]可以將自己holomen的1張綠色應援存入存檔區，從自己的應援牌庫公開1張應援，送給自己的holomen。然後將應援牌庫洗牌。","name":"HALU","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場對戰1次]這個回合中，自己舞台上所有持有#ID2期生的Holomen，每有1種該Holomen身上的能量顏色，Art+20。","name":"極彩之宴","timing":"每場對戰1次"}},"th":{"name":"ปาโวเลีย เรเน่","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] โดยอาร์ไคฟ์ เยลสีเขียว 1 ใบของโฮโลเมนของคุณ ให้เปิดเผยเยล 1 ใบจากเด็คเยลของคุณ แล้วส่งไปยังโฮโลเมนของคุณ จากนั้นสับเด็คเยล","name":"HALU","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] ในเทิร์นนี้ โฮโลเม็มเบอร์ทั้งหมดบนสเตจของคุณที่มี #ID รุ่น 2 จะได้รับอาร์ต +20 ต่อเอเลิร์ 1 สีของโฮโลเม็มเบอร์ใบนั้น","name":"งานเลี้ยงหลากสีสัน","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{}', 'cff49b7818a6cebee1a20f1a631e4297ae46a0baabc3615f8e73219138b158b3', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
INSERT INTO card_colors (color_code, card_id) VALUES ('green', '372');
INSERT INTO card_sets (set_name, card_id) VALUES ('ブースターパック「クインテットスペクトラム」', '372');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (372, 'hBP02-002', 'hBP02-002 すなれ パヴォリア・レイネ HALU [ターンに1回]自分のホロメンの緑エール1枚をアーカイブすることで、自分のエールデッキから、エール1枚を公開し、自分のホロメンに送る。そしてエールデッキをシャッフルする。 極彩色の宴 [ゲームに1回]このターンの間、自分のステージの#ID2期生を持つホロメン全員は、そのホロメンのエール1色につき、アーツ+20。 Pavolia Reine HALU [Once per turn] By Archiving 1 Green Cheer of your holomem, reveal 1 Cheer from your Cheer Deck and send it to your holomem. Then shuffle your Cheer Deck. A Feast of Vivid Colors [Once per game] Until end of turn, all holomem with #ID 2nd Gen on your Stage get Arts +20 for each Cheer color that holomem has. Pavolia Reine HALU [每回合1次]可以將自己holomen的1張綠色應援存入存檔區，從自己的應援牌庫公開1張應援，送給自己的holomen。然後將應援牌庫洗牌。 極彩之宴 [每場對戰1次]這個回合中，自己舞台上所有持有#ID2期生的Holomen，每有1種該Holomen身上的能量顏色，Art+20。 Pavolia Reine HALU [Sekali per giliran] Dengan mengarsipkan 1 Yell Hijau dari holomen milikmu, ungkapkan 1 Cheer dari cheer deck milikmu, lalu kirimkan ke holomen milikmu. Kemudian kocok cheer deck milikmu. Perjamuan Warna-Warni [Sekali per permainan] Selama giliran ini, semua Holomen di Stage milikmu yang memiliki #ID Gen 2 mendapatkan Arts +20 untuk setiap 1 warna Cheer pada Holomen tersebut. 파볼리아 레이네 HALU [턴에 1번]자신의 홀로멘의 그린 옐 1장을 아카이브함으로써 자신의 에일 덱에서 에일 1장을 공개하고 자신의 홀로멘에게 보낸다. 그리고 에일 덱을 셔플한다. 극채색의 연회 [게임에 1번]이번 턴 동안, 자신의 스테이지의 #ID 2기생을 가진 홀로멤 전원은 그 홀로멤의 에일 1색당 아츠 +20. ปาโวเลีย เรเน่ HALU [ใช้ได้ 1 ครั้งต่อเทิร์น] โดยอาร์ไคฟ์ เยลสีเขียว 1 ใบของโฮโลเมนของคุณ ให้เปิดเผยเยล 1 ใบจากเด็คเยลของคุณ แล้วส่งไปยังโฮโลเมนของคุณ จากนั้นสับเด็คเยล งานเลี้ยงหลากสีสัน [ใช้ได้ 1 ครั้งต่อเกม] ในเทิร์นนี้ โฮโลเม็มเบอร์ทั้งหมดบนสเตจของคุณที่มี #ID รุ่น 2 จะได้รับอาร์ต +20 ต่อเอเลิร์ 1 สีของโฮโลเม็มเบอร์ใบนั้น Pavolia Reine HALU [Una vez por turno] Al archivar 1 carta Green Cheer de uno de tus holomen, revela 1 Cheer de tu mazo Cheer y envíalo a uno de tus holomen. Luego baraja el mazo Cheer. Banquete multicolor [Una vez por partida] Durante este turno, todos los holomen de tu Escenario con #ID 2nd Gen obtienen Arts +20 por cada color de Cheer de ese holomen.', '');
