INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (382, 'hBP02-012', 'hBP02-012 CNO JP 1期生 ゲーマーズ ケモミミ 絵 白上フブキ #JP #1期生 #ゲーマーズ #ケモミミ #絵 力をかしてくださいね このターンの間、自分のマスコットが付いている[センターホロメンとコラボホロメン]のアーツ+20。 ちょっと動かしますね 自分のステージのマスコット1枚を、自分のホロメンに付け替えられる。 Shirakami Fubuki #JP #1st Gen #Gamers #Animal Ears #Art Please Lend Me Your Strength Until end of turn, your [Center holomem and Collab holomem] with your Mascot attached get +20 Arts. I''ll Move It a Little You may reattach 1 Mascot on your Stage to your holomem. 白上吹雪 #JP #1期生 #Gamers #獸耳 #繪畫 請借給我力量吧 本回合期間，自己附有吉祥物的[中心Holomen與合作Holomen]的藝術+20。 我稍微動一下喔 可以將自己舞台上的1張吉祥物改附到自己的Holo成員上。 Shirakami Fubuki #JP #Gen 1 #Gamers #Telinga Hewan #Seni Tolong pinjamkan kekuatanmu, ya Selama giliran ini, Arts dari [holomen Center dan holomen Collab] milikmu yang terpasang Mascot +20. Aku geser sedikit ya Kamu boleh memindahkan 1 Mascot di Stage-mu ke holomenmu. 시라카미 후부키 #JP #1기생 #게이머즈 #수인귀 #그림 힘을 빌려주세요 이번 턴 동안, 자신의 마스코트가 붙어 있는 [센터 홀로멘과 콜라보 홀로멘]의 아츠 +20. 잠깐 움직여 볼게요 자신의 스테이지의 마스코트 1장을 자신의 홀로멤에게 다시 붙일 수 있다. ชิรากามิ ฟุบุกิ #JP #รุ่น 1 #เกมเมอร์ส #หูสัตว์ #ศิลปะ ช่วยยืมพลังให้ฉันหน่อยนะ ตลอดเทิร์นนี้ ศิลปะของ [โฮโลเมมตำแหน่งเซ็นเตอร์และโฮโลเมมตำแหน่งคอลแลบ] ที่ติดมาสคอตของคุณอยู่ +20 ขอขยับหน่อยนะคะ สามารถย้ายมาสคอต 1 ใบบนสเตจของตนเองไปติดกับโฮโลเม็มของตนเองได้ Shirakami Fubuki #JP #1st Gen #Gamers #Animal Ears #Art Préstame tu fuerza, ¿sí? Durante este turno, los Artes de tu [holomen del Centro y holomen de Colaboración] que tengan un Mascot unido +20. Voy a moverlo un poquito Puedes cambiar 1 Mascot de tu escenario a uno de tus holomen.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('383', 'hBP02-013', 'character', 'SR', 'second', 'hBP02/hBP02-013_SR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-013_SR.png', 180, NULL, 2, '["null","null"]', 'むっちりしいたけ', '白上フブキ', '{"arts":[{"cost_types":["white","white","null"],"damage":80,"is_plus":true,"special_targets":["purple"],"special_values":[50]}],"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["white"],"keyword":{"type":"ギフト","type_code":"gift"},"translations":{"en":{"arts":[{"effect":"This Arts gains +20 for each Mascot on your Stage.","name":"Feast of the Mascots"}],"keyword":{"effect":"This holomem can have up to 2 Mascots with different card names attached.","name":"Together with Everyone!"},"name":"Shirakami Fubuki","tags":["#JP","#1st Gen","#Gamers","#Animal Ears","#Art"]},"es":{"arts":[{"effect":"Esta Art +20 por cada 1 Mascota en tu Escenario.","name":"Banquete de mascotas"}],"keyword":{"effect":"A este holomen se le pueden adjuntar hasta 2 Mascot con nombres de carta distintos.","name":"¡Junto a todos!"},"name":"Shirakami Fubuki","tags":["#JP","#1st Gen","#Gamers","#Animal Ears","#Art"]},"id":{"arts":[{"effect":"Untuk tiap 1 Mascot di Stage milikmu, Arts ini +20.","name":"Perjamuan Para Maskot"}],"keyword":{"effect":"Holomen ini dapat dipasangi hingga 2 Mascot dengan nama kartu yang berbeda.","name":"Bersama semua orang!"},"name":"Shirakami Fubuki","tags":["#JP","#Gen 1","#Gamers","#Telinga Hewan","#Seni"]},"ja":{"arts":[{"effect":"自分のステージのマスコット1枚につき、このアーツ+20。","name":"マスコットたちの饗宴"}],"keyword":{"effect":"このホロメンは、異なるカード名のマスコットを2枚まで付けられる。","name":"みんなと一緒！"},"name":"白上フブキ","tags":["#JP","#1期生","#ゲーマーズ","#ケモミミ","#絵"]},"ko":{"arts":[{"effect":"자신의 스테이지의 마스코트 1장당, 이 아츠+20.","name":"마스코트들의 향연"}],"keyword":{"effect":"이 홀로멘