INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (391, 'hBP02-021', 'hBP02-021 ID ID2期生 トリ 絵 パヴォリア・レイネ #ID #ID2期生 #トリ #絵 だから見ててね！大好き！ 自分のアーカイブのエール1枚を自分のホロメンに送れる。 心を込めて歌って、踊ります。 自分のステージのエール1色につき、自分のホロメン1人のHP10回復。 Pavolia Reine #ID #ID 2nd Gen #Bird #Art So keep watching, okay? I love you! You may send 1 Cheer from your Archive to one of your holomem. I''ll sing and dance with all my heart. Heal 10 HP from 1 of your holomems for each color of Cheer on your Stage. Pavolia Reine #ID #ID2期生 #小鳥 #繪畫 所以要看著我喔！最喜歡你了！ 可將自己存檔區中的1張應援送給自己的Holo成員。 我會全心全意地歌唱、跳舞。 自己舞台上每有1種顏色的應援，自己的1位Holomen回復HP10。 Pavolia Reine #ID #ID Gen 2 #Burung #Seni Jadi, lihat aku ya! Aku sayang kalian! Kamu boleh kirim 1 El dari Archive kamu ke holomen milikmu. Aku akan bernyanyi dan menari sepenuh hati. Untuk setiap 1 warna Cheer di Stage milikmu, pulihkan 10 HP dari 1 holomen milikmu. 파볼리아 레이네 #ID #ID 2기생 #새 #그림 그러니까 지켜봐 줘! 정말 좋아해! 자신의 아카이브의 에일 1장을 자신의 홀로멤에게 보낼 수 있다. 마음을 담아 노래하고, 춤춥니다. 자신의 스테이지의 엘 1색마다, 자신의 홀로멤 1명의 HP를 10 회복. ปาโวเลีย เรเน่ #ID #ID รุ่น 2 #นก #ศิลปะ เพราะงั้นคอยดูนะ! รักที่สุดเลย! คุณสามารถส่งเยล 1 ใบจากอาร์ไคฟ์ของคุณไปยังโฮโลเมนของคุณได้ จะร้องและเต้นด้วยหัวใจทั้งหมดของฉัน ฟื้นฟู HP 10 ให้โฮโลเมนของคุณ 1 คน ต่อเยลแต่ละสีบนสเตจของคุณ Pavolia Reine #ID #ID 2nd Gen #Bird #Art ¡Así que mírame! ¡Te quiero! Puedes enviar 1 Cheer de tu Archivo a uno de tus holomen. Cantaré y bailaré con todo mi corazón. Cura 10 HP a 1 de tus holomen por cada color de Cheer en tu escenario.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('392', 'hBP02-022', 'character', 'SR', 'first', 'hBP02/hBP02-022_SR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-022_SR.png', 130, NULL, 1, '["null"]', '久賀フーナ', 'パヴォリア・レイネ', '{"arts":[{"cost_types":["green","null"],"damage":40,"is_plus":true}],"card_sets":["ブースターパック「クインテットスペクトラム」","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["green"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"If there are 2 or more colors of Cheers on your Stage, this Arts gains +20.","name":"Spicy Night"}],"keyword":{"effect":"Reveal 1 〈Tatang〉 from your deck and add it to your hand. Then shuffle your deck.","name":"What AreYou Waiting For?"},"name":"Pavolia Reine","tags":["#ID","#ID 2nd Gen","#Bird","#Art"]},"es":{"arts":[{"effect":"Si hay 2 o más colores de Cheers en tu Escenario, esta Art +20.","name":"Spicy Night"}],"keyword":{"effect":"Revela 1 carta 〈Tatang〉 de tu mazo y añádela a tu mano. Luego baraja tu mazo.","name":"What AreYou Waiting For?"},"name":"Pavolia Reine","tags":["#ID","#ID 2nd Gen","#Bird","#Art"]},"id":{"arts":[{"effect":"Saat ada 2 warna Ekoru atau lebih di Stage milikmu, Arts ini +20.","name":"Spicy Night"}],"keyword":{"effect":"Ungkapkan 1 kartu 〈Tatang〉 dari dekmu, lalu tambahkan ke tanganmu. Lalu kocok dekmu.","name":"What AreYou Waiting For?"},"name":"Pavolia Reine","tags":["#ID","#ID Gen 2","#Burung","#Seni"]},"ja":{"arts":[{"effect":"自分のステージにエールが2色以上ある時、このアーツ+20。","name":"Spicy Night"}],"keyword":{"effect":"自分のデッキから、〈Tatang〉1枚を公開し、手札に加える。そしてデッキをシャッフルする。","name":"What AreYou Waiting For?"},"name":"パヴォリア・レイネ","tags":["#ID","#ID2期生","#トリ","#絵"]},"ko":{"arts":[{"effect":"자신의 스테이지에 에일이 2색 이상 있을 때, 이 아츠+20.","name":"Spicy Night"}],"keyword":{"effect":"자신의 덱에서 〈Tatang〉 1장을 공개하고, 손패에 넣는다. 그리고 덱을 셔플한다.","name":"What AreYou Waiting For?"},"name":"파볼리아 레이네","tags":["#ID","#ID 2기생","#새","#그림"]},"tc":{"arts":[{"effect":"當自己舞台上有2種顏色以上的能量時，這個藝術+20。","name":"Spicy Night"}],"keyword":{"effect":"從自己的牌庫中公開1張〈Tatang〉，加入手牌。然後將牌庫洗牌。","name":"What AreYou Waiting For?"},"name":"Pavolia Reine","tags":["#ID","#ID2期生","#小鳥","#繪畫"]},"th":{"arts":[{"effect":"เมื่อบนสเตจของคุณมีเยลตั้งแต่ 2 สีขึ้นไป อาร์ตนี้ +20","name":"Spicy Night"}],"keyword":{"effect":"เปิดเผย 〈Tatang〉 1 ใบจากเด็คของคุณ แล้วนำขึ้นมือ จากนั้นสับเด็ค","name":"What AreYou Waiting For?"},"name":"ปาโวเลีย เรเน่","tags":["#ID","#ID รุ่น 2","#นก","#ศิลปะ"]}}}', '{}', '70ff7ac79092ec5d840ad7fa2d6e61586064b9d033e6057b35791d79ede8eed9', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
