INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (400, 'hBP02-031', 'hBP02-031 JP 3期生 絵 海 宝鐘マリン #JP #3期生 #絵 #海 いっしょに出航しましょう！（健全） キミたちの声が船長の支えです！ 相手のコラボホロメンに特殊ダメージ20を与える。 Houshou Marine #JP #3rd Gen #Art #Ocean Let''s Set Sail Together! (Wholesomely) Your Voices Support the Captain! Deal 20 special damage to your opponent''s Collab holomem. 寶鐘瑪琳 #JP #3期生 #繪畫 #海洋 一起啟航吧！（健全） 你們的聲音就是船長的支柱！ 對手的合作Holomen受到特殊傷害20。 Houshou Marine #JP #Gen 3 #Seni #Laut Ayo berlayar bersama! (sehat) Suara kalian adalah penopang Kapten! Berikan 20 Damage Khusus pada Collab holomen lawan. 호쇼 마린 #JP #3기생 #그림 #바다 같이 출항해요! (건전) 너희들의 목소리가 선장의 버팀목입니다! 상대의 콜라보 홀로멤에게 특수 대미지 20을 준다. โฮโช มารีน #JP #รุ่น 3 #ศิลปะ #ทะเล ออกเรือไปด้วยกันเถอะ!（ใสสะอาด） เสียงของพวกเธอคือกำลังใจของกัปตัน! สร้างความเสียหายพิเศษ 20 แก่โคแลบโฮโลเมนของคู่แข่ง Houshou Marine #JP #3rd Gen #Art #Ocean ¡Zarpemos juntas! (sano) ¡Las voces de ustedes sostienen a la Capitana! Inflige 20 de daño especial al holomen de colaboración de tu oponente.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('401', 'hBP02-032', 'character', 'SR', 'first', 'hBP02/hBP02-032_SR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-032_SR.png', 130, NULL, 1, '["null"]', 'あかさあい', '宝鐘マリン', '{"arts":[{"cost_types":["null","null"],"damage":50}],"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["red"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"Yousoro"}],"keyword":{"effect":"Reveal 1 〈Houshou Marine〉 from your deck and add it to your hand. Then shuffle your deck. Your Bloom Effect \"Houshou''s Pirate Crew\" can only be used once per turn.","name":"Houshou''s Pirate Crew"},"name":"Houshou Marine","tags":["#JP","#3rd Gen","#Art","#Ocean"]},"es":{"arts":[{"name":"¡Yosoro!"}],"keyword":{"effect":"Revela 1 〈Houshou Marine〉 de tu mazo y añádelo a tu mano. Después, baraja el mazo. Tu Bloom Effect «La tripulación pirata de Houshou» solo puede usarse una vez por turno.","name":"La tripulación pirata de Houshou"},"name":"Houshou Marine","tags":["#JP","#3rd Gen","#Art","#Ocean"]},"id":{"arts":[{"name":"Yousoro"}],"keyword":{"effect":"Dari Dek milikmu, ungkapkan 1 kartu 〈Houshou Marine〉, tambahkan ke tanganmu. Lalu, kocok Dek. Bloom Effect milikmu \"Kelompok Bajak Laut Houshou\" hanya bisa digunakan sekali per giliran.","name":"Kru bajak laut Houshou"},"name":"Houshou Marine","tags":["#JP","#Gen 3","#Seni","#Laut"]},"ja":{"arts":[{"name":"ヨーソロー"}],"keyword":{"effect":"自分のデッキから、〈宝鐘マリン〉1枚を公開し、手札に加える。そしてデッキをシャッフルする。自分のブルームエフェクト「宝鐘の海賊団」はターンに1回しか使えない。","name":"宝鐘の海賊団"},"name":"宝鐘マリン","tags":["#JP","#3期生","#絵","#海"]},"ko":{"arts":[{"name":"요-소로"}],"keyword":{"effect":"자신의 덱에서, 〈호쇼 마린〉 1장을 공개하고 패에 넣는다. 그리고 덱을 셔플한다. 자신의 블룸 이펙트 「호쇼의 해적단」은 턴에 1번만 사용할 수 있다.","name":"호쇼의 해적단"},"name":"호쇼 마린","tags":["#JP","#3기생","#그림","#바다"]},"tc":{"arts":[{"name":"YOSORO"}],"keyword":{"effect":"從自己的牌庫公開1張〈寶鐘瑪琳〉，加入手牌。然後洗牌庫。自己的綻放效果「寶鐘的海賊團」每回合只能使用1次。","name":"寶鐘的海賊團"},"name":"寶鐘瑪琳","tags":["#JP","#3期生","#繪畫","#海洋"]},"th":{"arts":[{"name":"โยโซโร่"}],"keyword":{"effect":"เปิดเผย 〈โฮโช มารีน〉 1 ใบจากเด็คของคุณ นำขึ้นมือ แล้วสับเด็ค Bloom Effect \"กลุ่มโจรสลัดของ โฮโช\" ของคุณ ใช้ได้เพียงเทิร์นละ 1 ครั้ง","name":"กลุ่มโจรสลัดของ โฮโช"},"name":"โฮโช มารีน","tags":["#JP","#รุ่น 3","#ศิลปะ","#ทะเล"]}}}', '{}', '4876eb97c2664b897b8af709c0e956b4df94c26b846652ac5286f19532041db3', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
