INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (407, 'hBP02-037', 'hBP02-037 パセリ JP 秘密結社holoX 海 沙花叉クロヱ #JP #秘密結社holoX #海 ふたりじめビーチ Sakamata Chloe #JP #Secret Society holoX #Ocean Private Beach for Two 沙花叉克蘿耶 #JP #秘密結社holoX #海洋 兩人獨享海灘 Sakamata Chloe #JP #Organisasi Rahasia holoX #Laut Pantai Berdua Saja 사카마타 클로에 #JP #비밀결사 holoX #바다 둘이서만 비치 ซากามาตะ โคลเอ #JP #องค์กรลับ holoX #ทะเล ชายหาดสองต่อสอง Sakamata Chloe #JP #Secret Society holoX #Ocean Playa para dos', '');
