INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (414, 'hBP02-044', 'hBP02-044 Tam-U JP 2期生 ケモミミ 紫咲シオン #JP #2期生 #ケモミミ 照れくさ やだ、もー Murasaki Shion #JP #2nd Gen #Animal Ears How Embarrassing Oh, stop it~ 紫咲詩音 #JP #2期生 #獸耳 真害羞 討厭啦，真是的 Murasaki Shion #JP #Gen 2 #Telinga Hewan Malu ah Aduh, ih 무라사키 시온 #JP #2기생 #수인귀 쑥스럽네 아, 정말 มุราซากิ ชิออง #JP #รุ่น 2 #หูสัตว์ เขินจัง โอ๊ย เอ้า~ Murasaki Shion #JP #2nd Gen #Animal Ears Qué vergüencita Ay, ya basta', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('415', 'hBP02-045', 'character', 'S', 'first', 'hBP02/hBP02-045_S', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-045_S.png', 130, NULL, 1, '["null"]', NULL, '紫咲シオン', '{"arts":[{"cost_types":["null"],"damage":40}],"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["purple"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"I’m Super Happy!!"}],"keyword":{"effect":"Look at the top 3 cards of your deck. Reveal 1 [Blue holomem or Purple holomem] from among them and add it to your hand. Then return the remaining cards to the bottom of your deck in any order.","name":"An All-Group Live After So Long!!"},"name":"Murasaki Shion","tags":["#JP","#2nd Gen"]},"es":{"arts":[{"name":"¡¡Estoy feliz al máximo!!"}],"keyword":{"effect":"Mira las 3 cartas superiores de tu mazo. De entre ellas, revela 1 [holomen azul o holomen morado] y añádelo a tu mano. Después, devuelve las cartas restantes al fondo del mazo en el orden que quieras.","name":"¡¡¡Un concierto grupal después de tanto tiempo!!!"},"name":"Murasaki Shion","tags":["#JP","#2nd Gen"]},"id":{"arts":[{"name":"Bahagia banget!!"}],"keyword":{"effect":"Lihat 3 kartu teratas dari dekmu. Dari antaranya, ungkapkan 1 kartu [Blue holomen atau Purple holomen], tambahkan ke tanganmu. Lalu, kembalikan sisa kartunya ke bagian bawah dek dengan urutan sesukamu.","name":"Live bareng satu grup lagi setelah sekian lama!!"},"name":"Murasaki Shion","tags":["#JP","#Gen 2"]},"ja":{"arts":[{"name":"最高にハッピーです！！"}],"keyword":{"effect":"自分のデッキの上から3枚を見る。その中から、[青ホロメンか紫ホロメン]1枚を公開し、手札に加える。そして残ったカードを好きな順でデッキの下に戻す。","name":"久しぶりの全体ライブーっ！！"},"name":"紫咲シオン","tags":["#JP","#2期生"]},"ko":{"arts":[{"name":"최고로 해피해요!!"}],"keyword":{"effect":"자신의 덱 위에서 3장을 본다. 그중에서 [청 홀로멤 또는 자 홀로멤] 1장을 공개하고, 패에 넣는다. 그리고 남은 카드를 원하는 순서로 덱 맨 아래로 되돌린다.","name":"오랜만의 전체 라이브다아앗!!"},"name":"무라사키 시온","tags":["#JP","#2기생"]},"tc":{"arts":[{"name":"超級幸福快樂！！"}],"keyword":{"effect":"查看自己牌庫頂的3張。從中公開1張[藍色Holo成員或紫色Holo成員]，加入手牌。然後將其餘的卡依照自己喜歡的順序放回牌庫底。","name":"久違的全體演唱會——！！"},"name":"紫咲詩音","tags":["#JP","#2期生"]},"th":{"arts":[{"name":"มีความสุขสุดๆ ไปเลย!!"}],"keyword":{"effect":"ดูการ์ด 3 ใบบนสุดของเด็คตนเอง จากนั้นเปิดเผย [โฮโลเม็มสีน้ำเงินหรือโฮโลเม็มสีม่วง] 1 ใบจากในนั้นแล้วนำขึ้นมือ แล้วนำการ์ดที่เหลือกลับไปไว้ใต้เด็คตามลำดับที่ต้องการ","name":"ไลฟ์รวมวงครั้งแรกในรอบนานนนน!!"},"name":"มุราซากิ ชิออง","tags":["#JP","#รุ่น 2"]}}}', '{}', '6f9b32645e8c3f03b9f776f756eced770a56a3b2cea17d70267b4c8bdbbfe1c2', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
