INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (420, 'hBP02-050', 'hBP02-050 おむたつ ID ID2期生 語学 クレイジー・オリー #ID #ID2期生 #語学 君を大好きな後輩 きゃ～！先輩ごめ～ん！ Kureiji Ollie #ID #ID 2nd Gen #Languages The Underclassman Who Adores You Kyaa~! Sorry, Senpai~! Kureiji Ollie #ID #ID2期生 #語言 最喜歡你的後輩 呀～！前輩對不起啦～！ Kureiji Ollie #ID #ID Gen 2 #Bahasa Junior yang sayang banget sama kamu Kyaa～! Maaf, senpai～n! 크레이지 올리 #ID #ID 2기생 #언어 널 정말 좋아하는 후배 꺄~! 선배 미안~! เครซี่ โอลลี่ #ID #ID รุ่น 2 #ภาษา รุ่นน้องที่ชอบเธอมาก กรี๊ด~! ขอโทษนะคะรุ่นพี่~! Kureiji Ollie #ID #ID 2nd Gen #Languages La kouhai que te adora ¡Aaah! ¡Perdón, senpai!', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('421', 'hBP02-051', 'character', 'S', 'first', 'hBP02/hBP02-051_S', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-051_S.png', 130, NULL, 1, '["null"]', NULL, 'クレイジー・オリー', '{"arts":[{"cost_types":["null"],"damage":20}],"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["purple"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"I''m Gonna Scream My Head Off for My Oshi!!"}],"keyword":{"effect":"You may Bloom 1 of your Debut holomems with #ID 2nd Gen using a holomem in your Archive. Your Bloom Effect \"Genkaika!!\" can only be used once per turn.","name":"Losing It!!"},"name":"Kureiji Ollie","tags":["#ID","#ID 2nd Gen","#Languages"]},"es":{"arts":[{"name":"¡¡Voy a gritar sin parar viendo a mi oshi!!"}],"keyword":{"effect":"Puedes hacer Bloom de 1 de tus holomem Debut con #ID 2nd Gen usando un holomem de tu archivo. Tu Efecto Bloom «限界化！！» solo puede usarse una vez por turno.","name":"¡¡Al límite!!"},"name":"Kureiji Ollie","tags":["#ID","#ID 2nd Gen","#Languages"]},"id":{"arts":[{"name":"Lihat oshi lalu teriak sepuasnya!!"}],"keyword":{"effect":"Kamu dapat melakukan Bloom pada 1 Debut holomem milikmu yang memiliki #ID Gen 2 dengan menggunakan holomem dari Archive milikmu. Bloom Effect milikmu \"限界化！！\" hanya dapat digunakan sekali per giliran.","name":"Melewati batas!!"},"name":"Kureiji Ollie","tags":["#ID","#ID Gen 2","#Bahasa"]},"ja":{"arts":[{"name":"推しを見て叫びまくるぞ！！"}],"keyword":{"effect":"自分の#ID2期生を持つDebutホロメン1人を、自分のアーカイブのホロメンを使ってBloomできる。自分のブルームエフェクト「限界化！！」はターンに1回しか使えない。","name":"限界化！！"},"name":"クレイジー・オリー","tags":["#ID","#ID2期生","#語学"]},"ko":{"arts":[{"name":"최애를 보고 실컷 외칠 거야!!"}],"keyword":{"effect":"자신의 #ID 2기생를 가진 Debut 홀로멤 1명을 자신의 아카이브의 홀로멤을 사용해 Bloom할 수 있다. 자신의 블룸 이펙트 「한계화!!」는 턴에 1번밖에 사용할 수 없다.","name":"한계화!!"},"name":"크레이지 올리","tags":["#ID","#ID 2기생","#언어"]},"tc":{"arts":[{"name":"看到推就要放聲尖叫！！"}],"keyword":{"effect":"可以使用自己存檔區的Holo成員，讓自己1位持有#ID2期生的Debut Holo成員進行Bloom。自己的Bloom Effect「極限化！！」一回合只能使用1次。","name":"極限化！！"},"name":"Kureiji Ollie","tags":["#ID","#ID2期生","#語言"]},"th":{"arts":[{"name":"จะกรี๊ดให้สุดเสียงเมื่อเห็นโอชิเลย!!"}],"keyword":{"effect":"คุณสามารถบลูม Debut โฮโลเมน 1 คนของคุณที่มี #ID รุ่น 2 โดยใช้โฮโลเมนจากอาร์ไคฟ์ของคุณ บลูมเอฟเฟกต์「สุดขีดไปเลย!!」ของคุณใช้ได้เพียงเทิร์นละครั้ง","name":"สุดขีดไปเลย!!"},"name":"เครซี่ โอลลี่","tags":["#ID","#ID รุ่น 2","#ภาษา"]}}}', '{}', '9925744c1d7e2c71a7960f0485c44ae7b9b3f503e1620d273f4ed1c6804016ad', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
