INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (421, 'hBP02-051', 'hBP02-051 ID ID2期生 語学 クレイジー・オリー #ID #ID2期生 #語学 推しを見て叫びまくるぞ！！ 限界化！！ 自分の#ID2期生を持つDebutホロメン1人を、自分のアーカイブのホロメンを使ってBloomできる。自分のブルームエフェクト「限界化！！」はターンに1回しか使えない。 Kureiji Ollie #ID #ID 2nd Gen #Languages I''m Gonna Scream My Head Off for My Oshi!! Losing It!! You may Bloom 1 of your Debut holomems with #ID 2nd Gen using a holomem in your Archive. Your Bloom Effect "Genkaika!!" can only be used once per turn. Kureiji Ollie #ID #ID2期生 #語言 看到推就要放聲尖叫！！ 極限化！！ 可以使用自己存檔區的Holo成員，讓自己1位持有#ID2期生的Debut Holo成員進行Bloom。自己的Bloom Effect「極限化！！」一回合只能使用1次。 Kureiji Ollie #ID #ID Gen 2 #Bahasa Lihat oshi lalu teriak sepuasnya!! Melewati batas!! Kamu dapat melakukan Bloom pada 1 Debut holomem milikmu yang memiliki #ID Gen 2 dengan menggunakan holomem dari Archive milikmu. Bloom Effect milikmu "限界化！！" hanya dapat digunakan sekali per giliran. 크레이지 올리 #ID #ID 2기생 #언어 최애를 보고 실컷 외칠 거야!! 한계화!! 자신의 #ID 2기생를 가진 Debut 홀로멤 1명을 자신의 아카이브의 홀로멤을 사용해 Bloom할 수 있다. 자신의 블룸 이펙트 「한계화!!」는 턴에 1번밖에 사용할 수 없다. เครซี่ โอลลี่ #ID #ID รุ่น 2 #ภาษา จะกรี๊ดให้สุดเสียงเมื่อเห็นโอชิเลย!! สุดขีดไปเลย!! คุณสามารถบลูม Debut โฮโลเมน 1 คนของคุณที่มี #ID รุ่น 2 โดยใช้โฮโลเมนจากอาร์ไคฟ์ของคุณ บลูมเอฟเฟกต์「สุดขีดไปเลย!!」ของคุณใช้ได้เพียงเทิร์นละครั้ง Kureiji Ollie #ID #ID 2nd Gen #Languages ¡¡Voy a gritar sin parar viendo a mi oshi!! ¡¡Al límite!! Puedes hacer Bloom de 1 de tus holomem Debut con #ID 2nd Gen usando un holomem de tu archivo. Tu Efecto Bloom «限界化！！» solo puede usarse una vez por turno.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('422', 'hBP02-052', 'character', 'SR', 'first', 'hBP02/hBP02-052_SR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-052_SR.png', 120, NULL, 1, '["null"]', 'LAM', 'クレイジー・オリー', '{"arts":[{"cost_types":["null","null"],"damage":40,"is_plus":true}],"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["purple"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"If this holomem has Cheer other than purple attached, this Art gets +20.","name":"In the Name of Justice, I"}],"keyword":{"effect":"Draw 1 card from your deck.","name":"Straight on to the Truth"},"name":"Kureiji Ollie","tags":["#ID","#ID 2nd Gen","#Languages"]},"es":{"arts":[{"effect":"Si este holomem tiene unido un Cheer que no sea morado, este Arte +20.","name":"En nombre de la justicia, yo"}],"keyword":{"effect":"Roba 1 carta de tu mazo.","name":"Avanzar por el camino de la verdad"},"name":"Kureiji Ollie","tags":["#ID","#ID 2nd Gen","#Languages"]},"id":{"arts":[{"effect":"Saat holomen ini terpasang Cheer selain ungu, Arts ini +20.","name":"Atas nama keadilan, aku"}],"keyword":{"effect":"Tarik 1 kartu dari dekmu.","name":"Menempuh jalan kebenaran"},"name":"Kureiji Ollie","tags":["#ID","#ID Gen 2","#Bahasa"]},"ja":{"arts":[{"effect":"このホロメンに紫以外のエールが付いている時、このアーツ+20。","name":"正義の名の下に、儂は"}],"keyword":{"effect":"自分のデッキを1枚引く。","name":"真実一路"},"name":"クレイジー・オリー","tags":["#ID","#ID2期生","#語学"]},"ko":{"arts":[{"effect":"이 홀로멘에 보라색 이외의 에일이 붙어 있을 때, 이 아츠 +20.","name":"정의의 이름 아래, 나는"}],"keyword":{"effect":"자신의 덱을 1장 뽑는다.","name":"진실일로"},"name":"크레이지 올리","tags":["#ID","#ID 2기생","#언어"]},"tc":{"arts":[{"effect":"當這位Holo成員附有紫色以外的應援時，此藝術+20。","name":"在正義之名下，老身要"}],"keyword":{"effect":"自己抽1張牌。","name":"勇往直前"},"name":"Kureiji Ollie","tags":["#ID","#ID2期生","#語言"]},"th":{"arts":[{"effect":"เมื่อโฮโลเมนนี้ติดพลังงานที่ไม่ใช่สีม่วงอยู่ ศิลปะนี้ +20","name":"ภายใต้ชื่อแห่งความยุติธรรม ข้าคือ"}],"keyword":{"effect":"จั่วการ์ดจากเด็คของคุณ 1 ใบ","name":"มุ่งสู่ความจริง"},"name":"เครซี่ โอลลี่","tags":["#ID","#ID รุ่น 2","#ภาษา"]}}}', '{}', '521dd7c571f37516664438338405427b47ebe70c2819ab8b6f842f830dcd7628', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
