INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('431', 'hBP02-060', 'buzzCharacter', 'SR', 'first', 'hBP02/hBP02-060_SR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-060_SR.png', 240, NULL, 1, '["null"]', '江田藤', '癒月ちょこ', '{"arts":[{"cost_types":["purple","null","null"],"damage":80}],"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["purple"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"Charm You Just Can’t Hide"}],"keyword":{"effect":"You may heal 50 HP from 1 of your Back holomems: Deal 10 special damage to your opponent''s Center holomem for each 10 damage healed.","name":"A Seductive Gaze"},"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"es":{"arts":[{"name":"Un encanto imposible de ocultar"}],"keyword":{"effect":"Puedes curar 50 HP a 1 de tus holomem de la retaguardia: inflige 10 de daño especial al holomem central de tu oponente por cada 10 de daño curado.","name":"Mirada seductora"},"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"id":{"arts":[{"name":"Pesona yang Tak Bisa Disembunyikan"}],"keyword":{"effect":"Kamu dapat memulihkan 50 HP dari 1 Back holomem milikmu: Berikan 10 Damage Khusus kepada Center holomem lawan untuk setiap 10 damage yang dipulihkan.","name":"Tatapan menggoda"},"name":"Yuzuki Choco","tags":["#JP","#Gen 2","#Masakan"]},"ja":{"arts":[{"name":"隠しきれない魅力"}],"keyword":{"effect":"自分のバックホロメン1人のHP50回復できる:相手のセンターホロメンに、回復したダメージ10につき、特殊ダメージ10を与える。","name":"誘惑の視線"},"name":"癒月ちょこ","tags":["#JP","#2期生","#料理"]},"ko":{"arts":[{"name":"감출 수 없는 매력"}],"keyword":{"effect":"자신의 백 홀로멤 1명의 HP를 50 회복할 수 있다: 상대의 센터 홀로멤에게 회복한 대미지 10당 특수 대미지 10을 준다.","name":"유혹의 시선"},"name":"유즈키 초코","tags":["#JP","#2기생","#요리"]},"tc":{"arts":[{"name":"藏不住的魅力"}],"keyword":{"effect":"可以使自己1位Back Holo成員回復HP50：對對手的Center Holo成員，每回復10點傷害，就造成特殊傷害10。","name":"誘惑的視線"},"name":"癒月巧可","tags":["#JP","#2期生","#料理"]},"th":{"arts":[{"name":"เสน่ห์ที่ปิดไม่มิด"}],"keyword":{"effect":"คุณสามารถฟื้นฟู HP 50 ให้แบ็กโฮโลเมนของคุณ 1 คน: สร้างดาเมจพิเศษ 10 แก่เซ็นเตอร์โฮโลเมนของฝ่ายตรงข้ามต่อดาเมจที่ฟื้นฟูทุก 10","name":"สายตาเย้ายวน"},"name":"ยุซุกิ โชโคะ","tags":["#JP","#รุ่น 2","#ทำอาหาร"]}}}', '{}', '223ab7ef00de592d0080fc3e4c830668b2c636860ec7da0e89a442fbcf734320', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
