INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (436, 'hBP02-066', 'hBP02-066 つなかわ EN Advent 歌 トリ ネリッサ・レイヴンクロフト #EN #Advent #歌 #トリ 良い響きですね アイドルソングというものは Nerissa Ravencroft #EN #Advent #Singing #Bird What a Lovely Ring As for Idol Songs... Nerissa Ravencroft #EN #Advent #歌唱 #小鳥 真是動聽呢 所謂偶像歌曲 Nerissa Ravencroft #EN #Advent #Menyanyi #Burung Indah sekali bunyinya Yang namanya lagu idol itu 네리사 레이븐크로프트 #EN #Advent #노래 #새 좋은 울림이네요 아이돌 송이라는 것은 เนริสซา เรเวนครอฟต์ #EN #Advent #เพลง #นก เป็นเสียงที่ไพเราะดีนะ สิ่งที่เรียกว่าเพลงไอดอลนั้น Nerissa Ravencroft #EN #Advent #Singing #Bird Qué buen sonido Eso que llaman canción idol', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('437', 'hBP02-067', 'character', 'S', 'first', 'hBP02/hBP02-067_S', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hBP02-067_S.png', 120, NULL, 1, '["null"]', 'EB十', 'ネリッサ・レイヴンクロフト', '{"arts":[{"cost_types":["null"],"damage":20}],"card_sets":["ブースターパック「クインテットスペクトラム」","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["purple"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"Tea Over Coffee"}],"keyword":{"effect":"Look at the top 3 cards of your deck. Reveal 1 holomem with #Singing from among them and add it to your hand. Then put the remaining cards on the bottom of your deck in any order.","name":"Tea Party with Nerissa"},"name":"Nerissa Ravencroft","tags":["#EN","#Advent","#Singing","#Bird"]},"es":{"arts":[{"name":"Prefiero té antes que café"}],"keyword":{"effect":"Mira las 3 cartas de la parte superior de tu mazo. De entre ellas, revela 1 holomen con #Singing y añádelo a tu mano. Luego devuelve las cartas restantes al fondo del mazo en el orden que quieras.","name":"Té con Nerissa"},"name":"Nerissa Ravencroft","tags":["#EN","#Advent","#Singing","#Bird"]},"id":{"arts":[{"name":"Daripada kopi, pilih teh"}],"keyword":{"effect":"Lihat 3 kartu teratas dari Dek milikmu. Dari antaranya, ungkapkan 1 holomen yang memiliki #Menyanyi, lalu tambahkan ke tanganmu. Lalu, kembalikan kartu sisanya ke bawah Dek dalam urutan sesukamu.","name":"Pesta teh dengan Nerissa"},"name":"Nerissa Ravencroft","tags":["#EN","#Advent","#Menyanyi","#Burung"]},"ja":{"arts":[{"name":"コーヒーよりも紅茶です"}],"keyword":{"effect":"自分のデッキの上から3枚を見る。その中から、#歌を持つホロメン1枚を公開し、手札に加える。そして残ったカードを好きな順でデッキの下に戻す。","name":"ネリッサとお茶会"},"name":"ネリッサ・レイヴンクロフト","tags":["#EN","#Advent","#歌","#トリ"]},"ko":{"arts":[{"name":"커피보다 홍차예요"}],"keyword":{"effect":"자신의 덱 위에서부터 3장을 본다. 그중에서 #노래를 가진 홀로멘 1장을 공개하고 패에 넣는다. 그리고 남은 카드를 원하는 순서로 덱 아래로 되돌린다.","name":"네리사와 다과회"},"name":"네리사 레이븐크로프트","tags":["#EN","#Advent","#노래","#새"]},"tc":{"arts":[{"name":"比起咖啡更愛紅茶"}],"keyword":{"effect":"查看自己牌庫上方3張牌。從中公開1張持有#歌唱的holomen，加入手牌。然後將剩餘的牌以任意順序放回牌庫底。","name":"和Nerissa的茶會"},"name":"Nerissa Ravencroft","tags":["#EN","#Advent","#歌唱","#小鳥"]},"th":{"arts":[{"name":"ชอบชามากกว่ากาแฟ"}],"keyword":{"effect":"ดูการ์ด 3 ใบบนสุดของเด็คคุณ จากนั้นเปิดเผยโฮโลเมน 1 ใบที่มี #เพลง จากในนั้น แล้วนำขึ้นมือ หลังจากนั้นนำการ์ดที่เหลือกลับไปไว้ใต้เด็คตามลำดับที่ต้องการ","name":"งานน้ำชากับ เนริสสา"},"name":"เนริสซา เรเวนครอฟต์","tags":["#EN","#Advent","#เพลง","#นก"]}}}', '{}', 'f5b4e897edc48c506123d4f72b3101dcbb4e10065d4e12cc4caabf7030d5ef2f', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
