INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('482', 'hBP02-009', 'character', 'P', 'debut', 'hPR/hBP02-009_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP02-009_P.png', 80, NULL, 1, '["null"]', 'yadapot', '白上フブキ', '{"arts":[{"cost_types":["white"],"damage":20}],"card_sets":["PRカード"],"color_codes":["white"],"keyword":{"type":"ギフト","type_code":"gift"},"translations":{"en":{"arts":[{"name":"Otsukon deshita~"}],"keyword":{"effect":"[Collab Position Only] All of your holomems with your Mascot attached get +10 Arts.","name":"Ohakonkitsune!"},"name":"Shirakami Fubuki","tags":["#JP","#1st Gen","#Gamers","#Animal Ears","#Art"]},"es":{"arts":[{"name":"¡Otsukooon deshita~!"}],"keyword":{"effect":"[Solo Posición de Colaboración] Las Arts de todos tus holomem con tu Mascota adjunta obtienen +10.","name":"¡Ohakonkitsune!"},"name":"Shirakami Fubuki","tags":["#JP","#1st Gen","#Gamers","#Animal Ears","#Art"]},"id":{"arts":[{"name":"Otsukon deshitaa"}],"keyword":{"effect":"[Hanya Posisi Collab] Arts semua holomem milikmu yang terpasang Maskot +10.","name":"Ohakonkiitsune!"},"name":"Shirakami Fubuki","tags":["#JP","#Gen 1","#Gamers","#Telinga Hewan","#Seni"]},"ja":{"arts":[{"name":"おつこーんでしたー"}],"keyword":{"effect":"[コラボポジション限定]自分のマスコットが付いているホロメン全員のアーツ+10。","name":"おはこんきーつね！"},"name":"白上フブキ","tags":["#JP","#1期生","#ゲーマーズ","#ケモミミ","#絵"]},"ko":{"arts":[{"name":"오츠콘이었습니다ー"}],"keyword":{"effect":"[콜라보 포지션 한정] 자신의 마스코트가 붙어 있는 홀로멤 전원의 아츠+10.","name":"오하콘키츠네!"},"name":"시라카미 후부키","tags":["#JP","#1기생","#게이머즈","#수인귀","#그림"]},"tc":{"arts":[{"name":"Otsukon 了－"}],"keyword":{"effect":"[Collab位置限定]自己所有附有吉祥物的Holo成員，其藝術+10。","name":"早安konki狐狸！"},"name":"白上吹雪","tags":["#JP","#1期生","#Gamers","#獸耳","#繪畫"]},"th":{"arts":[{"name":"โอตสึคงงงง"}],"keyword":{"effect":"[เฉพาะตำแหน่งคอลแลบ] อาร์ตของโฮโลเมนทุกคนของคุณที่มีมาสคอตติดอยู่ +10","name":"โอฮะคงคิตสึเนะ!"},"name":"ชิรากามิ ฟุบุกิ","tags":["#JP","#รุ่น 1","#เกมเมอร์ส","#หูสัตว์","#ศิลปะ"]}}}', '{}', '76296cec51e6fbc5db25ed83ea330c22315237264f5a7352ae09a2b923c94dd4', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
