INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (483, 'hBP02-008', 'hBP02-008 LAL!ROLE JP 1期生 ゲーマーズ ケモミミ 絵 白上フブキ #JP #1期生 #ゲーマーズ #ケモミミ #絵 こんこんきーつね！ Shirakami Fubuki #JP #1st Gen #Gamers #Animal Ears #Art Konkonki-tsune! 白上吹雪 #JP #1期生 #Gamers #獸耳 #繪畫 konkon狐～！ Shirakami Fubuki #JP #Gen 1 #Gamers #Telinga Hewan #Seni Konkon kitsune! 시라카미 후부키 #JP #1기생 #게이머즈 #수인귀 #그림 콩콩 키츠네! ชิรากามิ ฟุบุกิ #JP #รุ่น 1 #เกมเมอร์ส #หูสัตว์ #ศิลปะ คงคงคิ้ตสึเนะ! Shirakami Fubuki #JP #1st Gen #Gamers #Animal Ears #Art ¡Konkonkitsune!', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('484', 'hBP01-004', 'oshiCharacter', 'P', NULL, 'hPR/hBP01-004_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP01-004_P.png', NULL, 6, NULL, NULL, 'チェリ子', '兎田ぺこら', '{"card_sets":["PRカード"],"color_codes":["green"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Usada Pekora","oshi_skill":{"effect":"[Once per turn] On your opponent''s turn, you may use this when your holomem is Downed: redistribute all Green Cheer from 1 of your Downed holomem among your other holomem and reattach them.","name":"Hey, Rabbits~","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] During this turn, treat all your die rolls as 6.","name":"Lucky Rabbit","timing":"Once per game"}},"es":{"name":"Usada Pekora","oshi_skill":{"effect":"[Una vez por turno] Puedes usar esto durante el turno de tu oponente, cuando uno de tus holomen quede K.O.: reasigna todos los Green Cheer de 1 de tus holomen que quedó K.O. entre tus otros holomen y únelos a ellos.","name":"Conejitos salvajes~","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Durante este turno, todos los resultados de tus dados se tratan como 6.","name":"Conejo de la suerte","timing":"Una vez por partida"}},"id":{"name":"Usada Pekora","oshi_skill":{"effect":"[Sekali per giliran] Dapat digunakan saat Holomen milikmu Knock Out pada giliran lawan: bagi dan pindahkan semua Yell Hijau dari 1 Holomen milikmu yang Knock Out itu ke Holomen lain milikmu.","name":"Para Kelinci Liar～","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per game] Selama giliran ini, semua hasil lemparan dadumu dianggap sebagai 6.","name":"Kelinci Keberuntungan","timing":"Sekali per permainan"}},"ja":{"name":"兎田ぺこら","oshi_skill":{"effect":"[ターンに1回]相手のターンで、自分のホロメンがダウンした時に使える:自分のダウンしたホロメン1人の緑エールすべてを、自分の他のホロメンに割り振って付け替える。","name":"野兎たち～","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]このターンの間、自分のサイコロの目の数すべてを6として扱う。","name":"幸運兎","timing":"ゲームに1回"}},"ko":{"name":"우사다 페코라","oshi_skill":{"effect":"[턴에 1번]상대의 턴에, 자신의 홀로멤이 다운되었을 때 사용할 수 있다: 자신의 다운된 홀로멤 1명의 그린 옐 전부를 자신의 다른 홀로멤에게 나누어 갈아붙인다.","name":"들토끼들아~","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번] 이 턴 동안, 자신의 주사위 눈의 수를 모두 6으로 취급한다.","name":"행운의 토끼","timing":"게임에 1번"}},"tc":{"name":"兔田佩克拉","oshi_skill":{"effect":"[每回合1次]可在對手回合中，自己的Holomen倒下時使用：將自己1位倒下Holomen上的所有綠色應援，分配並改附給自己的其他Holomen。","name":"野兔們～","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場遊戲1次]在這個回合中，將自己所有骰子的點數視為6。","name":"幸運兔","timing":"每場對戰1次"}},"th":{"name":"อุซาดะ เปโคระ","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] ใช้ได้เมื่อโฮโลเม็มเบอร์ของคุณดาวน์ในเทิร์นของฝ่ายตรงข้าม: แบ่ง เยลสีเขียว ทั้งหมดของโฮโลเม็มเบอร์ที่ดาวน์ 1 คนของคุณ แล้วย้ายไปติดกับโฮโลเม็มเบอร์อื่นของคุณ","name":"พวกกระต่ายป่า~","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] ในระหว่างเทิร์นนี้ แต้มบนลูกเต๋าทั้งหมดของคุณให้นับเป็น 6","name":"กระต่ายนำโชค","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{}', '44b1fbcfe8dd6091adbd6be56f6593466fe106421bcba04456229f3e9b4a0e22', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
INSERT INTO card_colors (color_code, card_id) VALUES ('green', '484');
INSERT INTO card_sets (set_name, card_id) VALUES ('PRカード', '484');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (484, 'hBP01-004', 'hBP01-004 チェリ子 兎田ぺこら 野兎たち～ [ターンに1回]相手のターンで、自分のホロメンがダウンした時に使える:自分のダウンしたホロメン1人の緑エールすべてを、自分の他のホロメンに割り振って付け替える。 幸運兎 [ゲームに1回]このターンの間、自分のサイコロの目の数すべてを6として扱う。 Usada Pekora Hey, Rabbits~ [Once per turn] On your opponent''s turn, you may use this when your holomem is Downed: redistribute all Green Cheer from 1 of your Downed holomem among your other holomem and reattach them. Lucky Rabbit [Once per game] During this turn, treat all your die rolls as 6. 兔田佩克拉 野兔們～ [每回合1次]可在對手回合中，自己的Holomen倒下時使用：將自己1位倒下Holomen上的所有綠色應援，分配並改附給自己的其他Holomen。 幸運兔 [每場遊戲1次]在這個回合中，將自己所有骰子的點數視為6。 Usada Pekora Para Kelinci Liar～ [Sekali per giliran] Dapat digunakan saat Holomen milikmu Knock Out pada giliran lawan: bagi dan pindahkan semua Yell Hijau dari 1 Holomen milikmu yang Knock Out itu ke Holomen lain milikmu. Kelinci Keberuntungan [Sekali per game] Selama giliran ini, semua hasil lemparan dadumu dianggap sebagai 6. 우사다 페코라 들토끼들아~ [턴에 1번]상대의 턴에, 자신의 홀로멤이 다운되었을 때 사용할 수 있다: 자신의 다운된 홀로멤 1명의 그린 옐 전부를 자신의 다른 홀로멤에게 나누어 갈아붙인다. 행운의 토끼 [게임에 1번] 이 턴 동안, 자신의 주사위 눈의 수를 모두 6으로 취급한다. อุซาดะ เปโคระ พวกกระต่ายป่า~ [ใช้ได้ 1 ครั้งต่อเทิร์น] ใช้ได้เมื่อโฮโลเม็มเบอร์ของคุณดาวน์ในเทิร์นของฝ่ายตรงข้าม: แบ่ง เยลสีเขียว ทั้งหมดของโฮโลเม็มเบอร์ที่ดาวน์ 1 คนของคุณ แล้วย้ายไปติดกับโฮโลเม็มเบอร์อื่นของคุณ กระต่ายนำโชค [ใช้ได้ 1 ครั้งต่อเกม] ในระหว่างเทิร์นนี้ แต้มบนลูกเต๋าทั้งหมดของคุณให้นับเป็น 6 Usada Pekora Conejitos salvajes~ [Una vez por turno] Puedes usar esto durante el turno de tu oponente, cuando uno de tus holomen quede K.O.: reasigna todos los Green Cheer de 1 de tus holomen que quedó K.O. entre tus otros holomen y únelos a ellos. Conejo de la suerte [Una vez por partida] Durante este turno, todos los resultados de tus dados se tratan como 6.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('485', 'hBP02-047', 'character', 'P', 'second', 'hPR/hBP02-047_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP02-047_P.png', 200, NULL, 2, '["null","null"]', 'チェリ子', '紫咲シオン', '{"arts":[{"cost_types":["purple","purple","null"],"damage":80,"special_targets":["green"],"special_values":[50]}],"card_sets":["PRカード"],"color_codes":["purple"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"Deal 20 special damage to the opponent''s Center holomem and Collab holomem for each Cheer on the opponent''s Center holomem.","name":"Violet Magic"}],"keyword":{"effect":"You may roll one die: If the result is 4 or higher, reattach 1 Cheer on your opponent''s Stage to one of your opponent''s holomem.","name":"Mischief Magic"},"name":"Murasaki Shion","tags":["#JP","#2nd Gen"]},"es":{"arts":[{"effect":"Inflige al holomen del Centro y al holomen de Colaboración de tu oponente 20 de daño especial por cada Cheer del holomen del Centro de tu oponente.","name":"Magia violeta"}],"keyword":{"effect":"Puedes lanzar un dado 1 vez: si sale 4 o más, cambia 1 Cheer del escenario de tu oponente a otro de sus holomen.","name":"Magia traviesa"},"name":"Murasaki Shion","tags":["#JP","#2nd Gen"]},"id":{"arts":[{"effect":"Berikan Special Damage 20 kepada Center holomen lawan dan Collab holomen lawan, untuk setiap 1 El pada Center holomen lawan.","name":"Sihir Violet"}],"keyword":{"effect":"Kamu boleh melempar dadu 1 kali: jika hasilnya 4 atau lebih, pindahkan 1 kartu Cheer di Stage lawan ke holomen lawan.","name":"Sihir keusilan"},"name":"Murasaki Shion","tags":["#JP","#Gen 2"]},"ja":{"arts":[{"effect":"相手のセンターホロメンとコラボホロメンに、相手のセンターホロメンのエール1枚につき、特殊ダメージ20を与える。","name":"ヴァイオレットマジック"}],"keyword":{"effect":"サイコロを1回振れる:4以上の時、相手のステージのエール1枚を、相手のホロメンに付け替える。","name":"いたずらの魔法"},"name":"紫咲シオン","tags":["#JP","#2期生"]},"ko":{"arts":[{"effect":"상대의 센터 홀로멤과 콜라보 홀로멤에게, 상대의 센터 홀로멤의 에일 1장당 특수 대미지 20을 준다.","name":"바이올렛 매직"}],"keyword":{"effect":"주사위를 1번 굴릴 수 있다: 4 이상이 나오면, 상대 스테이지의 에일 1장을 상대의 홀로멤에게 다시 붙인다.","name":"장난의 마법"},"name":"무라사키 시온","tags":["#JP","#2기생"]},"tc":{"arts":[{"effect":"對手的中心Holo成員與合作Holo成員，依對手的中心Holo成員每有1張應援，各造成特殊傷害20。","name":"紫羅蘭魔法"}],"keyword":{"effect":"可以擲1次骰子：若為4以上，將對手舞台上的1張應援改附到對手的Holo成員上。","name":"惡作劇的魔法"},"name":"紫咲詩音","tags":["#JP","#2期生"]},"th":{"arts":[{"effect":"สร้างความเสียหายพิเศษ 20 ให้แก่เซ็นเตอร์โฮโลเมนและคอลแลบโฮโลเมนของฝ่ายตรงข้าม ต่อเยล 1 ใบของเซ็นเตอร์โฮโลเมนของฝ่ายตรงข้าม","name":"เวทมนตร์สีไวโอเล็ต"}],"keyword":{"effect":"สามารถทอยลูกเต๋า 1 ครั้ง: หากออก 4 ขึ้นไป ให้ย้ายเยล 1 ใบบนสเตจของคู่ต่อสู้ไปติดกับโฮโลเม็มของคู่ต่อสู้","name":"เวทมนตร์แห่งการแกล้ง"},"name":"มุราซากิ ชิออง","tags":["#JP","#รุ่น 2"]}}}', '{}', '570b6868ddef591f5310bb05e3497630bbd5911f15cc75900a1d69d2dfb3788a', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
