INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (486, 'hBP01-077', 'hBP01-077 ひなつ JP 0期生 歌 星街すいせい #JP #0期生 #歌 新しい衣装 煌きのワードローブ 自分の推しホロメンが〈星街すいせい〉の時、このホロメンの青エール1枚をアーカイブできる:自分のデッキを2枚引く。 Hoshimachi Suisei #JP #0th Gen #Singing A New Outfit A Sparkling Wardrobe If your oshi holomem is 〈Hoshimachi Suisei〉, you may archive 1 Blue Cheer of this holomem: Draw 2 cards from your deck. 星街彗星 #JP #0期生 #歌唱 新服裝 閃耀的衣櫥 當自己的推holomen是〈星街彗星〉時，可以將這名holomen的1張藍色應援存檔：自己抽2張牌。 Hoshimachi Suisei #JP #Gen 0 #Menyanyi Kostum Baru Lemari pakaian yang berkilau Saat Oshi holomen milikmu adalah 〈Hoshimachi Suisei〉, kamu boleh mengarsipkan 1 Yell Biru milik holomen ini: tarik 2 kartu dari Dekkmu. 호시마치 스이세이 #JP #0기생 #노래 새로운 의상 반짝임의 워드로브 자신의 오시 홀로멘이 〈호시마치 스이세이〉일 때, 이 홀로멘의 블루 옐 1장을 아카이브할 수 있다: 자신의 덱을 2장 뽑는다. โฮชิมาชิ สุยเซย #JP #รุ่น 0 #เพลง ชุดใหม่ ตู้เสื้อผ้าแห่งประกายเจิดจ้า เมื่อโอชิโฮโลเมนของคุณเป็น〈โฮชิมาชิ สุยเซย〉 คุณสามารถอาร์ไคฟ์ เยลสีน้ำเงิน 1 ใบของโฮโลเมนนี้ได้: จั่วการ์ดจากเด็คของคุณ 2 ใบ Hoshimachi Suisei #JP #0th Gen #Singing Un nuevo atuendo Vestidor resplandeciente Cuando tu oshi holomen sea 〈Hoshimachi Suisei〉, puedes archivar 1 Blue Cheer de este holomen: roba 2 cartas de tu mazo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('487', 'hBP01-020', 'character', 'P', 'second', 'hPR/hBP01-020_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP01-020_P.png', 190, NULL, 2, '["null","null"]', '高崎律', '七詩ムメイ', '{"arts":[{"cost_types":["white","null","null"],"damage":70,"is_plus":true,"special_targets":["purple"],"special_values":[50]}],"card_sets":["PRカード"],"color_codes":["white"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"effect":"During this turn, your Center holomem and Collab holomem get +10 Arts for each of your Back holomem.","name":"All Together Now"}],"keyword":{"effect":"Reveal 1 holomem with #Promise from your deck and add it to your hand. Then shuffle your deck.","name":"The Promise of That Day"},"name":"Nanashi Mumei","tags":["#EN","#Promise","#Bird","#Art"]},"es":{"arts":[{"effect":"Durante este turno, por cada 1 de tus holomems de la Retaguardia, los Artes de tu holomem del Centro y de tu holomem de Colaboración +10.","name":"Todos juntos"}],"keyword":{"effect":"Revela 1 holomen con #Promise de tu mazo, añádelo a tu mano y luego baraja tu mazo.","name":"La promesa de aquel día"},"name":"Nanashi Mumei","tags":["#EN","#Promise","#Bird","#Art"]},"id":{"arts":[{"effect":"Selama giliran ini, untuk tiap 1 Back holomen milikmu, Arts Center holomen dan Kolab holomen milikmu +10.","name":"Semua Bersama-sama"}],"keyword":{"effect":"Ungkapkan 1 holomen yang memiliki #Promise dari Dek milikmu, lalu tambahkan ke tanganmu. Lalu, kocok Dek milikmu.","name":"Janji pada hari itu"},"name":"Nanashi Mumei","tags":["#EN","#Promise","#Burung","#Seni"]},"ja":{"arts":[{"effect":"このターンの間、自分のバックホロメン1人につき、自分のセンターホロメンとコラボホロメンのアーツ+10。","name":"みんな一緒に"}],"keyword":{"effect":"自分のデッキから、#Promiseを持つホロメン1枚を公開し、手札に加える。そしてデッキをシャッフルする。","name":"あの日の約束"},"name":"七詩ムメイ","tags":["#EN","#Promise","#トリ","#絵"]},"ko":{"arts":[{"effect":"이번 턴 동안, 자신의 백 홀로멘 1명당 자신의 센터 홀로멘과 콜라보 홀로멘의 아츠 +10.","name":"모두 함께"}],"keyword":{"effect":"자신의 덱에서, #Promise를 가진 홀로멘 1장을 공개하고 패에 넣는다. 그 후 덱을 셔플한다.","name":"그날의 약속"},"name":"나나시 무메이","tags":["#EN","#Promise","#새","#그림"]},"tc":{"arts":[{"effect":"在本回合期間，自己每有1位後台Holo成員，自己的中心Holo成員與合作Holo成員的藝術各+10。","name":"大家一起"}],"keyword":{"effect":"從自己的牌庫公開1張持有#Promise的holomen，加入手牌。然後將牌庫洗牌。","name":"那一天的約定"},"name":"七詩ムメイ","tags":["#EN","#Promise","#小鳥","#繪畫"]},"th":{"arts":[{"effect":"ในเทิร์นนี้ ศิลปะของโฮโลเมนกลางและโฮโลเมนคอลลาบของคุณ +10 ต่อแบ็กโฮโลเมน 1 คนของคุณ","name":"ทุกคนไปด้วยกัน"}],"keyword":{"effect":"เปิดเผยโฮโลเมน 1 ใบที่มี #Promise จากเด็คของคุณ แล้วนำขึ้นมือ จากนั้นสับเด็ค","name":"สัญญาในวันนั้น"},"name":"นานาชิ มุเมอิ","tags":["#EN","#Promise","#นก","#ศิลปะ"]}}}', '{}', 'd65424520b9f4e3a32a2fd68a1a0e5a6ac70cecb9d8c1690e22e1dfe1bd5ae31', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
