INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (488, 'hBP01-031', 'hBP01-031 mizu EN Promise 歌 IRyS #EN #Promise #歌 約束の力 自分の#Promiseを持つホロメン1人につき、このアーツ+20。 希望の庭園 自分のホロパワーを見る。その中から1枚を公開し、手札に加える。そして自分のデッキの上から1枚をホロパワーにする。 IRyS #EN #Promise #Singing The Power of Promise This Art gets +20 for each of your holomem with #Promise. Garden of Hope Look at your holoPower. Reveal 1 card from among it and add it to your hand. Then put the top card of your deck into your holoPower. IRyS #EN #Promise #歌唱 約定的力量 自己每有1位持有#Promise的Holo成員，此藝術+20。 希望的庭園 查看自己的Holopower。從中公開1張並加入手牌。然後將自己牌庫頂1張放入Holopower。 IRyS #EN #Promise #Menyanyi Kekuatan Janji Untuk tiap 1 holomen milikmu yang memiliki #Promise, Arts ini +20. Taman harapan Lihat Holo Power milikmu. Dari antaranya, buka 1 kartu dan tambahkan ke tanganmu. Setelah itu, jadikan 1 kartu teratas dekmu sebagai Holo Power. IRyS #EN #Promise #노래 약속의 힘 자신의 #Promise를 가진 홀로멘 1명당, 이 아츠 +20. 희망의 정원 자신의 홀로파워를 본다. 그 중에서 1장을 공개하고, 패에 넣는다. 그리고 자신의 덱 맨 위에서 1장을 홀로파워로 한다. IRyS #EN #Promise #เพลง พลังแห่งคำสัญญา ศิลปะนี้ +20 ต่อโฮโลเมน 1 คนของคุณที่มี #Promise สวนแห่งความหวัง ดูโฮโลพาวเวอร์ของคุณ จากนั้นอวดการ์ด 1 ใบจากในนั้นแล้วนำเข้ามือ แล้วนำการ์ดใบบนสุดของเด็คคุณไปเป็นโฮโลพาวเวอร์ IRyS #EN #Promise #Singing El poder de la promesa Por cada 1 de tus holomems con #Promise, este Arte +20. Jardín de la esperanza Mira tu Holo Power. De entre esas cartas, revela 1 y añádela a tu mano. Después, pon la carta superior de tu mazo en Holo Power.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('489', 'hBP01-037', 'character', 'P', 'second', 'hPR/hBP01-037_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP01-037_P.png', 190, NULL, 2, '["null","null"]', 'りんけてん', 'アキ・ローゼンタール', '{"arts":[{"cost_types":["green","green","green"],"damage":70,"is_plus":true,"special_targets":["white"],"special_values":[50]}],"card_sets":["PRカード"],"color_codes":["green"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"If a Tool is attached to this holomem, this Art gets +50.","name":"Secret Spare Key"}],"keyword":{"effect":"Send the top card of your Cheer Deck to one of your holomems. Then, if this holomem has a Tool attached to it, heal 40 HP from this holomem.","name":"Gothic Doll"},"name":"Aki Rosenthal","tags":["#JP","#1st Gen","#Half-Elf","#Alcohol"]},"es":{"arts":[{"effect":"Si este holomen tiene una Herramienta equipada, este Arte obtiene +50.","name":"La llave secreta"}],"keyword":{"effect":"Envía la carta superior de tu mazo de Cheer a uno de tus holomen. Después, si este holomen tiene una Herramienta unida, cura 40 HP a este holomen.","name":"Muñeca gótica"},"name":"Aki Rosenthal","tags":["#JP","#1st Gen","#Half-Elf","#Alcohol"]},"id":{"arts":[{"effect":"Saat holomen ini dipasangi Tool, Arts ini +50.","name":"Kunci Cadangan Rahasia"}],"keyword":{"effect":"Kirim 1 kartu teratas dari Deck Cheer milikmu ke holomen milikmu. Setelah itu, jika holomen ini dipasangi Tool, pulihkan 40 HP holomen ini.","name":"Boneka Gotik"},"name":"Aki Rosenthal","tags":["#JP","#Gen 1","#Setengah Elf","#Alkohol"]},"ja":{"arts":[{"effect":"このホロメンにツールが付いている時、このアーツ+50。","name":"秘密の合鍵"}],"keyword":{"effect":"自分のエールデッキの上から1枚を、自分のホロメンに送る。その後、このホロメンにツールが付いている時、このホロメンのHP40回復。","name":"ゴシックドール"},"name":"アキ・ローゼンタール","tags":["#JP","#1期生","#ハーフエルフ","#お酒"]},"ko":{"arts":[{"effect":"이 홀로멘에 툴이 붙어 있을 때, 이 아츠+50.","name":"비밀의 합열쇠"}],"keyword":{"effect":"자신의 엘 덱 위에서 1장을 자신의 홀로멤에게 보낸다. 그 후, 이 홀로멤에 툴이 붙어 있을 때, 이 홀로멤의 HP를 40 회복.","name":"고딕 돌"},"name":"아키 로젠탈","tags":["#JP","#1기생","#하프엘프","#술"]},"tc":{"arts":[{"effect":"當這位Holo成員附有工具時，此藝術+50。","name":"秘密的備用鑰匙"}],"keyword":{"effect":"將自己應援牌庫頂的1張卡送給自己的Holomen。之後，當這位Holomen附有工具時，這位Holomen回復HP40。","name":"哥德娃娃"},"name":"亞綺・羅森塔爾","tags":["#JP","#1期生","#半精靈","#酒"]},"th":{"arts":[{"effect":"เมื่อโฮโลเมนนี้ติดทูลอยู่ ศิลปะนี้ +50","name":"กุญแจสำรองลับ"}],"keyword":{"effect":"นำการ์ด 1 ใบจากบนสุดของเด็คเยลของคุณไปติดให้โฮโลเมนของคุณ จากนั้น ถ้าโฮโลเมนนี้ติดเครื่องมืออยู่ ฟื้นฟู HP 40 ให้โฮโลเมนนี้","name":"Gothic Doll"},"name":"อากิ โรเซนธาล","tags":["#JP","#รุ่น 1","#ฮาล์ฟเยลฟ์","#แอลกอฮอล์"]}}}', '{}', '21328a9b2c2e861db0631cb0d06645a9e913255acc30d84ce1177265d8d4978d', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
