INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (495, 'hSD01-006', 'hSD01-006 I☆LA JP 0期生 歌 ときのそら #JP #0期生 #歌 ドリームライブ SorAZ シンパシー 自分のステージにホロメンの〈AZKi〉がいる時、このアーツ+50。 Tokino Sora #JP #0th Gen #Singing Dream Live SorAZ Sympathy If there is a holomem 〈AZKi〉 on your Stage, this Art gets +50. 時乃空 #JP #0期生 #歌唱 夢幻演唱會 SorAZ Sympathy 當自己的舞台上有Holomen的〈AZKi〉時，此藝術+50。 Tokino Sora #JP #Gen 0 #Menyanyi Dream Live SorAZ Sympathy Jika ada 〈AZKi〉 holomen di Stage milikmu, Arts ini +50. 토키노 소라 #JP #0기생 #노래 드림 라이브 SorAZ 심퍼시 자신의 스테이지에 홀로멘의 〈AZKi〉가 있을 때, 이 아츠 +50. โตกิโนะ โซระ #JP #รุ่น 0 #เพลง ดรีมไลฟ์ SorAZ ซิมพาธี ขณะที่บนสเตจของคุณมี 〈AZKi〉 ของโฮโลเมมอยู่ ศิลปะนี้ +50 Tokino Sora #JP #0th Gen #Singing Dream Live Simpatía SorAZ Si hay un 〈AZKi〉 de holomen en tu Escenario, este Arte +50.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('496', 'hSD01-011', 'character', 'P', 'second', 'hPR/hSD01-011_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hSD01-011_P.png', 190, NULL, 2, '["null","null"]', 'I☆LA', 'AZKi', '{"arts":[{"cost_types":["green"],"damage":60,"special_targets":["blue"],"special_values":[50]},{"cost_types":["green","green","null"],"damage":100,"is_plus":true,"special_targets":["blue"],"special_values":[50]}],"card_sets":["PRカード"],"color_codes":["green"],"translations":{"en":{"arts":[{"effect":"When you have a holomem with 〈Tokino Sora〉 on your Stage, send the top card of your Cheer Deck to one of your holomem.","name":"SorAZ Gravity"},{"effect":"You may roll a die once: if the result is odd, this Arts gains +50. If the result is 1, additionally, this Arts gains +50.","name":"Destiny Song"}],"name":"AZKi","tags":["#JP","#0th Gen","#Singing"]},"es":{"arts":[{"effect":"Si hay un 〈Tokino Sora〉 de holomem en tu Escenario, envía la carta superior de tu Mazo de Cheer a uno de tus holomems.","name":"Gravedad SorAZ"},{"effect":"Puedes lanzar 1 dado: si sale un número impar, esta Art +50. Si sale 1, además, esta Art +50.","name":"Canción del destino"}],"name":"AZKi","tags":["#JP","#0th Gen","#Singing"]},"id":{"arts":[{"effect":"Saat ada 〈Tokino Sora〉 holomen di Stage milikmu, kirim 1 kartu teratas dari Cheer Deck milikmu kepada holomen milikmu.","name":"SorAZ Gravity"},{"effect":"Kamu boleh melempar dadu 1 kali: jika hasilnya ganjil, Arts ini +50. Jika hasilnya 1, tambahan lagi, Arts ini +50.","name":"Destiny Song"}],"name":"AZKi","tags":["#JP","#Gen 0","#Menyanyi"]},"ja":{"arts":[{"effect":"自分のステージにホロメンの〈ときのそら〉がいる時、自分のエールデッキの上から1枚を、自分のホロメンに送る。","name":"SorAZ グラビティ"},{"effect":"サイコロを1回振れる:奇数の時、このアーツ+50。１の時、さらに、このアーツ+50。","name":"デスティニーソング"}],"name":"AZKi","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"effect":"자신의 스테이지에 홀로멘의 〈토키노 소라〉가 있을 때, 자신의 에일 덱 맨 위에서 1장을 자신의 홀로멘에게 보낸다.","name":"SorAZ 그래비티"},{"effect":"주사위를 1번 굴릴 수 있다: 홀수라면, 이 아츠+50. 1이라면, 추가로 이 아츠+50.","name":"데스티니 송"}],"name":"AZKi","tags":["#JP","#0기생","#노래"]},"tc":{"arts":[{"effect":"當自己的舞台上有Holo成員的〈時乃空〉時，將自己應援牌庫頂的1張卡附加到自己的Holo成員上。","name":"SorAZ Gravity"},{"effect":"可以擲1次骰子：為奇數時，這個藝術+50。若為1，則再使這個藝術+50。","name":"Destiny Song"}],"name":"AZKi","tags":["#JP","#0期生","#歌唱"]},"th":{"arts":[{"effect":"เมื่อบนสเตจของคุณมี〈โตกิโนะ โซระ〉ของโฮโลเมนอยู่ ส่งการ์ดใบบนสุดจากเด็คพลังงานของคุณไปให้โฮโลเมนของคุณ","name":"SorAZ แรงโน้มถ่วง"},{"effect":"คุณสามารถทอยลูกเต๋า 1 ครั้งได้: ถ้าออกเลขคี่ อาร์ตนี้ +50 ถ้าออก 1 เพิ่มอีก อาร์ตนี้ +50","name":"เพลงแห่งโชคชะตา"}],"name":"AZKi","tags":["#JP","#รุ่น 0","#เพลง"]}}}', '{}', 'e45c263b60358794f0b2e59a08a660da50f4831058c2a33e678067c0a084d3d9', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
