INSERT INTO card_tags (tag, card_id) VALUES ('シューター', '497');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (497, 'hSD02-007', 'hSD02-007 JP 2期生 シューター 百鬼あやめ #JP #2期生 #シューター 輝いた余を見逃さないでね～～！！ どーっちどっち♪ DebutからBloomした時、自分のデッキの上から2枚を見る。その中から、1枚を公開し、手札に加える。そして残ったカードをアーカイブする。 Nakiri Ayame #JP #2nd Gen #Shooter Don’t Miss Me Shining~~!! Which One, Which One♪ When this holomem Blooms from Debut, look at the top 2 cards of your deck. Reveal 1 of them and add it to your hand. Then archive the remaining card. 百鬼綾目 #JP #2期生 #射手 別錯過閃閃發亮的余喔～～！！ 是哪邊是哪邊♪ 從Debut Bloom時，查看自己牌庫頂2張。從中公開1張並加入手牌。然後將剩餘的卡片放置到Archive。 Nakiri Ayame #JP #Gen 2 #Penembak Jangan sampai melewatkan aku yang bersinar～～!! Yang mana, yang mana♪ Saat melakukan Bloom dari Debut, lihat 2 kartu teratas dekmu. Dari antaranya, buka 1 kartu dan tambahkan ke tanganmu. Lalu, arsipkan kartu sisanya. 나키리 아야메 #JP #2기생 #슈터 빛나는 나를 놓치지 말라고～～!! 어~느 쪽 어느 쪽♪ Debut에서 Bloom했을 때, 자신의 덱 맨 위에서 2장을 본다. 그 중에서 1장을 공개하고, 패에 넣는다. 그리고 남은 카드를 아카이브한다. นากิริ อายาเมะ #JP #รุ่น 2 #ชูตเตอร์ อย่าพลาดฉันในยามเปล่งประกายล่ะ～～!! อันไหนเอ่ย อันไหนเอ่ย♪ เมื่อ Bloom จาก Debut ให้ดูการ์ด 2 ใบบนสุดของเด็คของคุณ จากนั้นอวด 1 ใบจากในนั้นแล้วนำเข้ามือ แล้วนำการ์ดที่เหลือเข้า Archive Nakiri Ayame #JP #2nd Gen #Shooter ¡¡No dejes pasar a este yo brillante～～!! ¿Cuál será, cuál será? ♪ Cuando hace Bloom desde Debut, mira las 2 cartas superiores de tu mazo. De entre ellas, revela 1 y añádela a tu mano. Después, archiva la carta restante.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('498', 'hSD03-007', 'character', 'P', 'first', 'hPR/hSD03-007_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hSD03-007_P.png', 110, NULL, 1, '["null"]', NULL, '猫又おかゆ', '{"arts":[{"cost_types":["null"],"damage":20}],"card_sets":["PRカード","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["blue"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"I’ll Give It My All and Deliver My Own Kind of Song!"}],"keyword":{"effect":"You may send 1 Cheer from your archive to one of your holomem with #Gamers.","name":"Hey, make sure to laugh a whole lot again, okay!"},"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Animal Ears"]},"es":{"arts":[{"name":"¡Les entregaré mi canción, con todo y a mi manera!"}],"keyword":{"effect":"Puedes enviar 1 Cheer de tu archivo a uno de tus holomen con #Gamers.","name":"¡Y vuelve a sonreír muchísimo, ¿vale?!"},"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Animal Ears"]},"id":{"arts":[{"name":"Akan kusampaikan lagu versiku sepenuh hati!"}],"keyword":{"effect":"Kamu boleh mengirim 1 Cheer dari Arsipmu ke Holomen milikmu yang memiliki #Gamers.","name":"Tolong tertawa banyak lagi ya!"},"name":"Nekomata Okayu","tags":["#JP","#Gamers","#Telinga Hewan"]},"ja":{"arts":[{"name":"全力で僕なりの歌、お届けします！"}],"keyword":{"effect":"自分のアーカイブのエール1枚を自分の#ゲーマーズを持つホロメンに送れる。","name":"また、たくさん笑ってよね！"},"name":"猫又おかゆ","tags":["#JP","#ゲーマーズ","#ケモミミ"]},"ko":{"arts":[{"name":"전력으로, 나다운 노래 전해드릴게요!"}],"keyword":{"effect":"자신의 아카이브의 엘 1장을 자신의 #게이머즈를 가진 홀로멤에게 보낼 수 있다.","name":"또, 많이 웃어줘!"},"name":"네코마타 오카유","tags":["#JP","#게이머즈","#수인귀"]},"tc":{"arts":[{"name":"我會全力送上屬於我的歌聲！"}],"keyword":{"effect":"可以將自己檔案區中的1張應援送給自己持有#Gamers的Holomen。","name":"還要再多笑一點喔！"},"name":"貓又小粥","tags":["#JP","#Gamers","#獸耳"]},"th":{"arts":[{"name":"จะขอมอบบทเพลงในแบบของผมอย่างเต็มกำลัง!"}],"keyword":{"effect":"คุณสามารถส่งเยล 1 ใบจากอาร์ไคฟ์ของคุณไปยังโฮโลเมนของคุณที่มี #เกมเมอร์ส ได้","name":"แล้วก็ช่วยหัวเราะกันเยอะๆ อีกนะ!"},"name":"เนโกะมาตะ โอกายุ","tags":["#JP","#เกมเมอร์ส","#หูสัตว์"]}}}', '{}', 'f7fc03d4075e2945e143412734d10668bd3dbdd7e53a99a92745e382d1675a03', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
