INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (498, 'hSD03-007', 'hSD03-007 JP ゲーマーズ ケモミミ 猫又おかゆ #JP #ゲーマーズ #ケモミミ 全力で僕なりの歌、お届けします！ また、たくさん笑ってよね！ 自分のアーカイブのエール1枚を自分の#ゲーマーズを持つホロメンに送れる。 Nekomata Okayu #JP #Gamers #Animal Ears I’ll Give It My All and Deliver My Own Kind of Song! Hey, make sure to laugh a whole lot again, okay! You may send 1 Cheer from your archive to one of your holomem with #Gamers. 貓又小粥 #JP #Gamers #獸耳 我會全力送上屬於我的歌聲！ 還要再多笑一點喔！ 可以將自己檔案區中的1張應援送給自己持有#Gamers的Holomen。 Nekomata Okayu #JP #Gamers #Telinga Hewan Akan kusampaikan lagu versiku sepenuh hati! Tolong tertawa banyak lagi ya! Kamu boleh mengirim 1 Cheer dari Arsipmu ke Holomen milikmu yang memiliki #Gamers. 네코마타 오카유 #JP #게이머즈 #수인귀 전력으로, 나다운 노래 전해드릴게요! 또, 많이 웃어줘! 자신의 아카이브의 엘 1장을 자신의 #게이머즈를 가진 홀로멤에게 보낼 수 있다. เนโกะมาตะ โอกายุ #JP #เกมเมอร์ส #หูสัตว์ จะขอมอบบทเพลงในแบบของผมอย่างเต็มกำลัง! แล้วก็ช่วยหัวเราะกันเยอะๆ อีกนะ! คุณสามารถส่งเยล 1 ใบจากอาร์ไคฟ์ของคุณไปยังโฮโลเมนของคุณที่มี #เกมเมอร์ส ได้ Nekomata Okayu #JP #Gamers #Animal Ears ¡Les entregaré mi canción, con todo y a mi manera! ¡Y vuelve a sonreír muchísimo, ¿vale?! Puedes enviar 1 Cheer de tu archivo a uno de tus holomen con #Gamers.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('499', 'hSD04-007', 'character', 'P', 'first', 'hPR/hSD04-007_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hSD04-007_P.png', 110, NULL, 1, '["null"]', NULL, '癒月ちょこ', '{"arts":[{"cost_types":["null","null"],"damage":30}],"card_sets":["PRカード","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["purple"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"Heal 20 HP from 1 of your back holomems.","name":"Love You! Mwah♡"}],"keyword":{"effect":"You may return 1 non-LIMITED Event from your Archive to your hand.","name":"Plop!"},"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"es":{"arts":[{"effect":"Cura 20 HP a 1 de tus holomen de la Retaguardia.","name":"¡Te adoro! Chu♡"}],"keyword":{"effect":"Puedes devolver a tu mano 1 Evento que no sea LIMITED de tu Archivo.","name":"¡Chokkooon!"},"name":"Yuzuki Choco","tags":["#JP","#2nd Gen","#Cooking"]},"id":{"arts":[{"effect":"Pulihkan 20 HP dari 1 Back holomen milikmu.","name":"Suka banget! Muah♡"}],"keyword":{"effect":"Kamu boleh mengembalikan 1 Event non-LIMITED dari Archive milikmu ke tanganmu.","name":"Jreng!"},"name":"Yuzuki Choco","tags":["#JP","#Gen 2","#Masakan"]},"ja":{"arts":[{"effect":"自分のバックホロメン1人のHP20回復。","name":"大好き！ちゅっ♡"}],"keyword":{"effect":"自分のアーカイブのLIMITED以外のイベント1枚を手札に戻せる。","name":"ちょっこーん！"},"name":"癒月ちょこ","tags":["#JP","#2期生","#料理"]},"ko":{"arts":[{"effect":"자신의 백 홀로멘 1명의 HP 20 회복.","name":"정말 좋아! 쪽♡"}],"keyword":{"effect":"자신의 아카이브에 있는 LIMITED가 아닌 이벤트 1장을 패로 되돌릴 수 있다.","name":"쪼꼬온!"},"name":"유즈키 초코","tags":["#JP","#2기생","#요리"]},"tc":{"arts":[{"effect":"回復自己1名Back holomen的HP 20。","name":"最喜歡你了！啾♡"}],"keyword":{"effect":"可以將自己Archive中1張LIMITED以外的事件返回手牌。","name":"蹲一下！"},"name":"癒月巧可","tags":["#JP","#2期生","#料理"]},"th":{"arts":[{"effect":"ฟื้นฟู HP 20 ให้แบ็กโฮโลเมนของคุณ 1 คน","name":"รักที่สุดเลย! จุ๊บ♡"}],"keyword":{"effect":"คุณสามารถนำอีเวนต์ 1 ใบที่ไม่ใช่ LIMITED จาก Archive ของคุณกลับขึ้นมือได้","name":"จุ๊มปุ๊ก!"},"name":"ยุซุกิ โชโคะ","tags":["#JP","#รุ่น 2","#ทำอาหาร"]}}}', '{}', '6556daa9741ec61222e7ea39a310584cd717ac15e1271c68af9cd9d892a96db8', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
