INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (500, 'hBP02-008', 'hBP02-008 JP 1期生 ゲーマーズ ケモミミ 絵 白上フブキ #JP #1期生 #ゲーマーズ #ケモミミ #絵 こんこんきーつね！ Shirakami Fubuki #JP #1st Gen #Gamers #Animal Ears #Art Konkonki-tsune! 白上吹雪 #JP #1期生 #Gamers #獸耳 #繪畫 konkon狐～！ Shirakami Fubuki #JP #Gen 1 #Gamers #Telinga Hewan #Seni Konkon kitsune! 시라카미 후부키 #JP #1기생 #게이머즈 #수인귀 #그림 콩콩 키츠네! ชิรากามิ ฟุบุกิ #JP #รุ่น 1 #เกมเมอร์ส #หูสัตว์ #ศิลปะ คงคงคิ้ตสึเนะ! Shirakami Fubuki #JP #1st Gen #Gamers #Animal Ears #Art ¡Konkonkitsune!', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('501', 'hBP02-024', 'character', 'P', 'debut', 'hPR/hBP02-024_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP02-024_P.png', 90, NULL, 2, '["null","null"]', NULL, '大神ミオ', '{"arts":[{"cost_types":["null"],"damage":10}],"card_sets":["PRカード","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["green"],"translations":{"en":{"arts":[{"effect":"You may move 1 Cheer on your Stage to a holomem with #JP.","name":"Me, me, it''s me~ It''s Ookami Mio~"}],"name":"Ookami Mio","tags":["#JP","#Gamers","#Animal Ears","#Cooking"]},"es":{"arts":[{"effect":"Puedes volver a unir 1 Cheer de tu Escenario a un holomen con #JP que controles.","name":"Uchi uchi, soy yo~ soy Ookami Mio~"}],"name":"Ookami Mio","tags":["#JP","#Gamers","#Animal Ears","#Cooking"]},"id":{"arts":[{"effect":"Kamu boleh pindahkan 1 El di Stage kamu agar terpasang pada holomen milikmu yang memiliki #JP.","name":"Uchi uchi, ini aku～ Ookami Mio lho～"}],"name":"Ookami Mio","tags":["#JP","#Gamers","#Telinga Hewan","#Masakan"]},"ja":{"arts":[{"effect":"自分のステージのエール1枚を、自分の#JPを持つホロメンに付け替えられる。","name":"うちうち、うちだよ～大神ミオだよ～"}],"name":"大神ミオ","tags":["#JP","#ゲーマーズ","#ケモミミ","#料理"]},"ko":{"arts":[{"effect":"자신의 스테이지의 에일 1장을 자신의 #JP를 가진 홀로멤에게 다시 붙일 수 있다.","name":"우리우리, 나야~ 오오카미 미오야~"}],"name":"오오카미 미오","tags":["#JP","#게이머즈","#수인귀","#요리"]},"tc":{"arts":[{"effect":"可將自己舞台上的1張應援，改附給自己持有#JP的Holo成員。","name":"我我我，是我喔～大神澪喔～"}],"name":"大神澪","tags":["#JP","#Gamers","#獸耳","#料理"]},"th":{"arts":[{"effect":"คุณสามารถสลับเยล 1 ใบบนสเตจของคุณไปติดกับโฮโลเมนที่มี #JP ของคุณได้","name":"อุจิอุจิ ฉันเองน้า~ โอกามิ มิโอ ไง~"}],"name":"โอกามิ มิโอ","tags":["#JP","#เกมเมอร์ส","#หูสัตว์","#ทำอาหาร"]}}}', '{}', '30674055b15f9cb4db12c637501eb941075fd03372d7e335b995cd3b72a46371', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
