INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (501, 'hBP02-024', 'hBP02-024 JP ゲーマーズ ケモミミ 料理 大神ミオ #JP #ゲーマーズ #ケモミミ #料理 うちうち、うちだよ～大神ミオだよ～ 自分のステージのエール1枚を、自分の#JPを持つホロメンに付け替えられる。 Ookami Mio #JP #Gamers #Animal Ears #Cooking Me, me, it''s me~ It''s Ookami Mio~ You may move 1 Cheer on your Stage to a holomem with #JP. 大神澪 #JP #Gamers #獸耳 #料理 我我我，是我喔～大神澪喔～ 可將自己舞台上的1張應援，改附給自己持有#JP的Holo成員。 Ookami Mio #JP #Gamers #Telinga Hewan #Masakan Uchi uchi, ini aku～ Ookami Mio lho～ Kamu boleh pindahkan 1 El di Stage kamu agar terpasang pada holomen milikmu yang memiliki #JP. 오오카미 미오 #JP #게이머즈 #수인귀 #요리 우리우리, 나야~ 오오카미 미오야~ 자신의 스테이지의 에일 1장을 자신의 #JP를 가진 홀로멤에게 다시 붙일 수 있다. โอกามิ มิโอ #JP #เกมเมอร์ส #หูสัตว์ #ทำอาหาร อุจิอุจิ ฉันเองน้า~ โอกามิ มิโอ ไง~ คุณสามารถสลับเยล 1 ใบบนสเตจของคุณไปติดกับโฮโลเมนที่มี #JP ของคุณได้ Ookami Mio #JP #Gamers #Animal Ears #Cooking Uchi uchi, soy yo~ soy Ookami Mio~ Puedes volver a unir 1 Cheer de tu Escenario a un holomen con #JP que controles.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('502', 'hBP02-028', 'character', 'P', 'debut', 'hPR/hBP02-028_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP02-028_P.png', 100, NULL, 1, '["null"]', NULL, '宝鐘マリン', '{"arts":[{"cost_types":["null"],"damage":30}],"card_sets":["PRカード","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["red"],"translations":{"en":{"arts":[{"name":"I’m Houshou Marine, Captain of the Houshou Pirate Crew!"}],"name":"Houshou Marine","tags":["#JP","#3rd Gen","#Art","#Ocean"]},"es":{"arts":[{"name":"¡Soy Houshou Marine, capitana de la tripulación pirata Houshou!"}],"name":"Houshou Marine","tags":["#JP","#3rd Gen","#Art","#Ocean"]},"id":{"arts":[{"name":"Aku Houshou Marine, kapten bajak laut Houshou!"}],"name":"Houshou Marine","tags":["#JP","#Gen 3","#Seni","#Laut"]},"ja":{"arts":[{"name":"宝鐘海賊団船長の宝鐘マリンですぅー！"}],"name":"宝鐘マリン","tags":["#JP","#3期生","#絵","#海"]},"ko":{"arts":[{"name":"호쇼 해적단 선장 호쇼 마린입니다아ー!"}],"name":"호쇼 마린","tags":["#JP","#3기생","#그림","#바다"]},"tc":{"arts":[{"name":"我是寶鐘海賊團船長的寶鐘瑪琳唷—！"}],"name":"寶鐘瑪琳","tags":["#JP","#3期生","#繪畫","#海洋"]},"th":{"arts":[{"name":"ฉัน โฮโช มารีน กัปตันกองโจรสลัด โฮโช ค่าา!"}],"name":"โฮโช มารีน","tags":["#JP","#รุ่น 3","#ศิลปะ","#ทะเล"]}}}', '{}', '710d25e92c2ef3c2e760f031395c39fa01bf7597d7f3ecf7655a98a8c08e204c', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
