INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (503, 'hBP02-048', 'hBP02-048 ID ID2期生 語学 クレイジー・オリー #ID #ID2期生 #語学 ゾンばんは！ Kureiji Ollie #ID #ID 2nd Gen #Languages Zombanwa! Kureiji Ollie #ID #ID2期生 #語言 殭晚安！ Kureiji Ollie #ID #ID Gen 2 #Bahasa Zonbanwa! 크레이지 올리 #ID #ID 2기생 #언어 좀방하! เครซี่ โอลลี่ #ID #ID รุ่น 2 #ภาษา ซนบังวะ! Kureiji Ollie #ID #ID 2nd Gen #Languages ¡Zonbanwa!', '');
