INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (507, 'hBP02-029', 'hBP02-029 しゅがお JP 3期生 絵 海 お酒 宝鐘マリン #JP #3期生 #絵 #海 #お酒 マリン“船長”だろぉぉん！？ マリンと宅飲み 相手のコラボホロメンに特殊ダメージ20を与える。 Houshou Marine #JP #3rd Gen #Art #Ocean #Alcohol I''m Captain Marine, aren''t I!? Drinking at Home with Marine Deal 20 special damage to your opponent''s Collab holomem. 寶鐘瑪琳 #JP #3期生 #繪畫 #海洋 #酒 我是瑪琳「船長」吧喔喔喔喔！？ 和Marine在家小酌 對手的合作Holomen受到特殊傷害20。 Houshou Marine #JP #Gen 3 #Seni #Laut #Alkohol Aku ini Kapten Marin, ya kaaaan!? Minum di rumah bareng Marine Berikan 20 Damage Khusus pada Collab holomen lawan. 호쇼 마린 #JP #3기생 #그림 #바다 #술 마린 “선장”이잖아아앙!? 마린과 집술 상대의 콜라보 홀로멤에게 특수 대미지 20을 준다. โฮโช มารีน #JP #รุ่น 3 #ศิลปะ #ทะเล #แอลกอฮอล์ มารินคือ“กัปตัน”ไงล่าาาา!? ดื่มที่บ้านกับมาริน สร้างความเสียหายพิเศษ 20 แก่โคแลบโฮโลเมนของคู่แข่ง Houshou Marine #JP #3rd Gen #Art #Ocean #Alcohol ¡¿Soy la “Capitana” Marine, nooooo!? Tragos en casa con Marine Inflige 20 de daño especial al holomen de colaboración de tu oponente.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('508', 'hBP02-043', 'character', 'P', 'debut', 'hPR/hBP02-043_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP02-043_P.png', 50, NULL, 1, '["null"]', 'しゅがお', '紫咲シオン', '{"arts":[{"cost_types":["purple"],"damage":30}],"card_sets":["PRカード"],"color_codes":["purple"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Let’s Go Together"}],"keyword":{"effect":"You may roll a die once: If the result is 4 or higher, reveal 1 card with #Magic from your deck and add it to your hand. Then shuffle your deck.","name":"I''ll Show You Magic"},"name":"Murasaki Shion","tags":["#JP","#2nd Gen"]},"es":{"arts":[{"name":"Vamos juntos"}],"keyword":{"effect":"Puedes lanzar un dado 1 vez: si sale 4 o más, revela 1 carta con #Magic de tu mazo, añádela a tu mano y luego baraja tu mazo.","name":"Te enseñaré magia"},"name":"Murasaki Shion","tags":["#JP","#2nd Gen"]},"id":{"arts":[{"name":"Ayo Pergi Bersama"}],"keyword":{"effect":"Boleh melempar dadu 1 kali: jika hasilnya 4 atau lebih, ungkapkan 1 kartu yang memiliki #Sihir dari Dek milikmu, lalu tambahkan ke tanganmu. Lalu, kocok Dek milikmu.","name":"Akan kutunjukkan sihir"},"name":"Murasaki Shion","tags":["#JP","#Gen 2"]},"ja":{"arts":[{"name":"一緒に行こう"}],"keyword":{"effect":"サイコロを1回振れる:4以上の時、自分のデッキから、#魔法を持つカード1枚を公開し、手札に加える。そしてデッキをシャッフルする。","name":"魔法見せてあげる"},"name":"紫咲シオン","tags":["#JP","#2期生"]},"ko":{"arts":[{"name":"함께 가자"}],"keyword":{"effect":"주사위를 1번 굴릴 수 있다: 4 이상이 나오면, 자신의 덱에서 #마법를 가진 카드 1장을 공개하고 패에 넣는다. 그 후 덱을 셔플한다.","name":"마법 보여줄게"},"name":"무라사키 시온","tags":["#JP","#2기생"]},"tc":{"arts":[{"name":"一起走吧"}],"keyword":{"effect":"可以擲1次骰子：若為4以上，則從自己的牌庫公開1張持有#魔法的卡牌，加入手牌。然後將牌庫洗牌。","name":"讓你見識魔法"},"name":"紫咲詩音","tags":["#JP","#2期生"]},"th":{"arts":[{"name":"ไปด้วยกันเถอะ"}],"keyword":{"effect":"ทอยลูกเต๋าได้ 1 ครั้ง: ถ้าออก 4 ขึ้นไป เปิดเผยการ์ด 1 ใบที่มี #เวทมนตร์ จากเด็คของคุณ แล้วนำขึ้นมือ จากนั้นสับเด็ค","name":"จะให้ดูเวทมนตร์"},"name":"มุราซากิ ชิออง","tags":["#JP","#รุ่น 2"]}}}', '{}', '508e50d49fafc2536208b976c4e89bbdb88754fc6bdf4b1a515091b131a89174', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
