INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (511, 'hBP02-014', 'hBP02-014 JP 3期生 お酒 白銀ノエル #JP #3期生 #お酒 こんまっする～！ Shirogane Noel #JP #3rd Gen #Alcohol Konmuscle~! 白銀諾艾爾 #JP #3期生 #酒 空肌肉啦～！ Shirogane Noel #JP #Gen 3 #Alkohol Konmassuru～! 시로가네 노엘 #JP #3기생 #술 콘맛슬~! ชิโรกาเนะ โนเอล #JP #รุ่น 3 #แอลกอฮอล์ คงมัสเซิล~! Shirogane Noel #JP #3rd Gen #Alcohol ¡Konmasscle~!', '');
