INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (518, 'hSD05-002', 'hSD05-002 DEV_IS ReGLOSS ベイビー 轟はじめ #DEV_IS #ReGLOSS #ベイビー ぶんぶんぶーん！ Todoroki Hajime #DEV_IS #ReGLOSS #Baby Vroom vroom vrooom! 轟初芽 #DEV_IS #ReGLOSS #嬰兒 嗡嗡嗡～！ Todoroki Hajime #DEV_IS #ReGLOSS #Bayi Bunbunbuuun! 토도로키 하지메 #DEV_IS #ReGLOSS #베이비 붕붕부웅! โทโดโรกิ ฮาจิเมะ #DEV_IS #ReGLOSS #เบบี้ บึ๊นบึ๊นบู๊น! Todoroki Hajime #DEV_IS #ReGLOSS #Baby ¡Bun bun buuun!', '');
