INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (520, 'hSD05-004', 'hSD05-004 Watersnake DEV_IS ReGLOSS ベイビー 轟はじめ #DEV_IS #ReGLOSS #ベイビー ReGLOSSの番長 Todoroki Hajime #DEV_IS #ReGLOSS #Baby The Boss of ReGLOSS 轟初芽 #DEV_IS #ReGLOSS #嬰兒 ReGLOSS的番長 Todoroki Hajime #DEV_IS #ReGLOSS #Bayi Bos ReGLOSS 토도로키 하지메 #DEV_IS #ReGLOSS #베이비 ReGLOSS의 반장 โทโดโรกิ ฮาจิเมะ #DEV_IS #ReGLOSS #เบบี้ หัวหน้าแก๊งของ ReGLOSS Todoroki Hajime #DEV_IS #ReGLOSS #Baby La jefa de ReGLOSS', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('521', 'hSD05-005', 'character', 'C', 'first', 'hSD05/hSD05-005_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD05/hSD05-005_C.png', 140, NULL, 1, '["null"]', '詰め木', '轟はじめ', '{"arts":[{"cost_types":["white"],"damage":40},{"cost_types":["null","null"],"damage":60}],"card_sets":["スタートデッキ 白 轟はじめ"],"color_codes":["white"],"translations":{"en":{"arts":[{"name":"Yoroshiku!"},{"name":"Whee!"}],"name":"Todoroki Hajime","tags":["#DEV_IS","#ReGLOSS","#Baby"]},"es":{"arts":[{"name":"¡Yoroshiku!"},{"name":"¡Wiiii!"}],"name":"Todoroki Hajime","tags":["#DEV_IS","#ReGLOSS","#Baby"]},"id":{"arts":[{"name":"Yoroshiku!"},{"name":"Wii!"}],"name":"Todoroki Hajime","tags":["#DEV_IS","#ReGLOSS","#Bayi"]},"ja":{"arts":[{"name":"夜路紫駆！"},{"name":"うぃー！"}],"name":"轟はじめ","tags":["#DEV_IS","#ReGLOSS","#ベイビー"]},"ko":{"arts":[{"name":"요로시쿠!"},{"name":"위ー!"}],"name":"토도로키 하지메","tags":["#DEV_IS","#ReGLOSS","#베이비"]},"tc":{"arts":[{"name":"夜路死苦！"},{"name":"嗚咿－！"}],"name":"轟初芽","tags":["#DEV_IS","#ReGLOSS","#嬰兒"]},"th":{"arts":[{"name":"โยะโระชิคุ!"},{"name":"วี~!"}],"name":"โทโดโรกิ ฮาจิเมะ","tags":["#DEV_IS","#ReGLOSS","#เบบี้"]}}}', '{}', 'e307c1f54910e47e605d0f2ec18a1a22569552afd5087b2742c27999caf31de2', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
