INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (521, 'hSD05-005', 'hSD05-005 詰め木 DEV_IS ReGLOSS ベイビー 轟はじめ #DEV_IS #ReGLOSS #ベイビー 夜路紫駆！ うぃー！ Todoroki Hajime #DEV_IS #ReGLOSS #Baby Yoroshiku! Whee! 轟初芽 #DEV_IS #ReGLOSS #嬰兒 夜路死苦！ 嗚咿－！ Todoroki Hajime #DEV_IS #ReGLOSS #Bayi Yoroshiku! Wii! 토도로키 하지메 #DEV_IS #ReGLOSS #베이비 요로시쿠! 위ー! โทโดโรกิ ฮาจิเมะ #DEV_IS #ReGLOSS #เบบี้ โยะโระชิคุ! วี~! Todoroki Hajime #DEV_IS #ReGLOSS #Baby ¡Yoroshiku! ¡Wiiii!', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('522', 'hSD05-006', 'character', 'C', 'first', 'hSD05/hSD05-006_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD05/hSD05-006_C.png', 100, NULL, 1, '["null"]', 'HASU', '轟はじめ', '{"arts":[{"cost_types":["null"],"damage":30},{"cost_types":["white","null"],"damage":50,"is_plus":true}],"card_sets":["スタートデッキ 白 轟はじめ"],"color_codes":["white"],"translations":{"en":{"arts":[{"name":"Light on Her Feet, Todoroki Hajime"},{"effect":"If you have 3 or more holomem with #ReGLOSS and different card names on your Stage, this Art gets +20.","name":"Arigatoryaasu"}],"name":"Todoroki Hajime","tags":["#DEV_IS","#ReGLOSS","#Baby"]},"es":{"arts":[{"name":"Paso ligero, Todoroki Hajime"},{"effect":"Si hay 3 o más holomen con #ReGLOSS con nombres de carta diferentes en tu Escenario, este Arte +20.","name":"Arigatryas~"}],"name":"Todoroki Hajime","tags":["#DEV_IS","#ReGLOSS","#Baby"]},"id":{"arts":[{"name":"Langkah Ringan, Todoroki Hajime"},{"effect":"Jika ada 3 holomen atau lebih di Stage milikmu yang memiliki #ReGLOSS dengan nama kartu berbeda, Arts ini +20.","name":"Arigatoryaasu"}],"name":"Todoroki Hajime","tags":["#DEV_IS","#ReGLOSS","#Bayi"]},"ja":{"arts":[{"name":"足取り軽め、轟はじめ"},{"effect":"自分のステージに異なるカード名の#ReGLOSSを持つホロメンが3人以上いる時、このアーツ+20。","name":"ありあとりゃあすっ"}],"name":"轟はじめ","tags":["#DEV_IS","#ReGLOSS","#ベイビー"]},"ko":{"arts":[{"name":"가벼운 발걸음, 토도로키 하지메"},{"effect":"자신의 스테이지에 카드명이 서로 다른 #ReGLOSS를 가진 홀로멘이 3명 이상 있을 때, 이 아츠 +20.","name":"아리아토랴앗스"}],"name":"토도로키 하지메","tags":["#DEV_IS","#ReGLOSS","#베이비"]},"tc":{"arts":[{"name":"步伐輕快，轟初芽"},{"effect":"當自己的舞台上有3位以上持有#ReGLOSS且卡名各不相同的Holomen時，此藝術+20。","name":"謝謝啦啊啊"}],"name":"轟初芽","tags":["#DEV_IS","#ReGLOSS","#嬰兒"]},"th":{"arts":[{"name":"ก้าวเบาสบาย โทโดโรกิ ฮาจิเมะ"},{"effect":"ขณะที่บนสเตจของคุณมีโฮโลเมมที่มี #ReGLOSS ซึ่งมีชื่อการ์ดต่างกัน 3 คนขึ้นไป ศิลปะนี้ +20","name":"อาริอะโตะริอาสุสึ"}],"name":"โทโดโรกิ ฮาจิเมะ","tags":["#DEV_IS","#ReGLOSS","#เบบี้"]}}}', '{}', '208af5f8cbfcc4b97a5fa4f61fe34cc777d8ccdf8e67318480b9c57801796b6f', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
