INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (523, 'hSD05-007', 'hSD05-007 DEV_IS ReGLOSS ベイビー 轟はじめ #DEV_IS #ReGLOSS #ベイビー 度胸、愛嬌、最強 宇宙一の番長を目指すなんでも屋 自分のデッキを1枚引く。 Todoroki Hajime #DEV_IS #ReGLOSS #Baby Courage, Charm, Invincible A Jack-of-All-Trades Aiming to Be the Number One Boss in the Universe Draw 1 card from your deck. 轟初芽 #DEV_IS #ReGLOSS #嬰兒 膽識、討喜、最強 以成為宇宙第一番長為目標的萬事屋 自己抽1張牌。 Todoroki Hajime #DEV_IS #ReGLOSS #Bayi Berani, Menawan, Terkuat Tukang serbabisa yang membidik jadi bos nomor satu di alam semesta Tarik 1 kartu dari dekmu. 토도로키 하지메 #DEV_IS #ReGLOSS #베이비 배짱, 애교, 최강 우주 제일의 짱을 목표로 하는 해결사 자신의 덱을 1장 뽑는다. โทโดโรกิ ฮาจิเมะ #DEV_IS #ReGLOSS #เบบี้ ใจถึง น่ารัก แกร่งสุด ร้านสารพัดรับจ้างผู้มุ่งสู่การเป็นหัวโจกอันดับหนึ่งแห่งจักรวาล จั่วการ์ดจากเด็คของคุณ 1 ใบ Todoroki Hajime #DEV_IS #ReGLOSS #Baby Valentía, encanto, invencible La chica para todo que aspira a ser la jefa número uno del universo Roba 1 carta de tu mazo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('524', 'hSD05-008', 'buzzCharacter', 'R', 'first', 'hSD05/hSD05-008_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD05/hSD05-008_R.png', 230, NULL, 2, '["null","null"]', 'Fajyobore', '轟はじめ', '{"arts":[{"cost_types":["white","white"],"damage":50}],"card_sets":["スタートデッキ 白 轟はじめ"],"color_codes":["white"],"translations":{"en":{"arts":[{"effect":"During this turn, 1 of your Debut holomem with #ReGLOSS on your Stage gets +40 Arts.","name":"...I might be getting kinda boss-like!"}],"name":"Todoroki Hajime","tags":["#DEV_IS","#ReGLOSS","#Baby"]},"es":{"arts":[{"effect":"Durante este turno, los Artes de 1 holomem Debut de tu Escenario con #ReGLOSS +40.","name":"...¡Creo que me estoy poniendo como una jefa!"}],"name":"Todoroki Hajime","tags":["#DEV_IS","#ReGLOSS","#Baby"]},"id":{"arts":[{"effect":"Selama giliran ini, Arts 1 Debut holomen milikmu yang memiliki #ReGLOSS di Stage milikmu +40.","name":"...Kayaknya aku mulai mirip ketua geng, deh!"}],"name":"Todoroki Hajime","tags":["#DEV_IS","#ReGLOSS","#Bayi"]},"ja":{"arts":[{"effect":"このターンの間、自分のステージの#ReGLOSSを持つDebutホロメン1人のアーツ+40。","name":"……なんか、番長っぽくなってきたかも！"}],"name":"轟はじめ","tags":["#DEV_IS","#ReGLOSS","#ベイビー"]},"ko":{"arts":[{"effect":"이번 턴 동안, 자신의 스테이지의 #ReGLOSS를 가진 Debut 홀로멘 1명의 아츠 +40.","name":"……왠지, 반장 같아졌을지도!"}],"name":"토도로키 하지메","tags":["#DEV_IS","#ReGLOSS","#베이비"]},"tc":{"arts":[{"effect":"在本回合期間，自己舞台上1位持有#ReGLOSS的Debut Holo成員的藝術+40。","name":"……總覺得，我好像越來越有番長的感覺了！"}],"name":"轟初芽","tags":["#DEV_IS","#ReGLOSS","#嬰兒"]},"th":{"arts":[{"effect":"ในเทิร์นนี้ ศิลปะของ Debut โฮโลเมน 1 คนบนสเตจของคุณที่มี #ReGLOSS +40","name":"...ชักจะเหมือนลูกพี่ขึ้นมาแล้วแฮะ!"}],"name":"โทโดโรกิ ฮาจิเมะ","tags":["#DEV_IS","#ReGLOSS","#เบบี้"]}}}', '{}', '5770abfb964eadfd46e3af71b8cea1247d48cb8afa9cc997711c770383470ada', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
