INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (524, 'hSD05-008', 'hSD05-008 Fajyobore DEV_IS ReGLOSS ベイビー 轟はじめ #DEV_IS #ReGLOSS #ベイビー ……なんか、番長っぽくなってきたかも！ このターンの間、自分のステージの#ReGLOSSを持つDebutホロメン1人のアーツ+40。 Todoroki Hajime #DEV_IS #ReGLOSS #Baby ...I might be getting kinda boss-like! During this turn, 1 of your Debut holomem with #ReGLOSS on your Stage gets +40 Arts. 轟初芽 #DEV_IS #ReGLOSS #嬰兒 ……總覺得，我好像越來越有番長的感覺了！ 在本回合期間，自己舞台上1位持有#ReGLOSS的Debut Holo成員的藝術+40。 Todoroki Hajime #DEV_IS #ReGLOSS #Bayi ...Kayaknya aku mulai mirip ketua geng, deh! Selama giliran ini, Arts 1 Debut holomen milikmu yang memiliki #ReGLOSS di Stage milikmu +40. 토도로키 하지메 #DEV_IS #ReGLOSS #베이비 ……왠지, 반장 같아졌을지도! 이번 턴 동안, 자신의 스테이지의 #ReGLOSS를 가진 Debut 홀로멘 1명의 아츠 +40. โทโดโรกิ ฮาจิเมะ #DEV_IS #ReGLOSS #เบบี้ ...ชักจะเหมือนลูกพี่ขึ้นมาแล้วแฮะ! ในเทิร์นนี้ ศิลปะของ Debut โฮโลเมน 1 คนบนสเตจของคุณที่มี #ReGLOSS +40 Todoroki Hajime #DEV_IS #ReGLOSS #Baby ...¡Creo que me estoy poniendo como una jefa! Durante este turno, los Artes de 1 holomem Debut de tu Escenario con #ReGLOSS +40.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('525', 'hSD05-009', 'character', 'RR', 'second', 'hSD05/hSD05-009_RR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD05/hSD05-009_RR.png', 180, NULL, 2, '["null","null"]', 'BISAI', '轟はじめ', '{"arts":[{"cost_types":["white","white","null"],"damage":80,"is_plus":true,"special_targets":["purple"],"special_values":[50]}],"card_sets":["スタートデッキ 白 轟はじめ"],"color_codes":["white"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"When you have a holomem with #ReGLOSS other than 〈Todoroki Hajime〉 on your Stage, this Art gets +30.","name":"Violet-Ending Thunder"}],"keyword":{"effect":"Reveal 1 [Debut holomem or 1st holomem] with #ReGLOSS from your deck and add it to your hand. Then shuffle your deck.","name":"Let''s color this world with dance!"},"name":"Todoroki Hajime","tags":["#DEV_IS","#ReGLOSS","#Baby"]},"es":{"arts":[{"effect":"Si tienes en tu Escenario un holomem con #ReGLOSS que no sea 〈Todoroki Hajime〉, este Arte +30.","name":"Rayo violeta aniquilador"}],"keyword":{"effect":"Revela 1 [Debut holomember o 1st holomember] con #ReGLOSS de tu mazo y añádelo a tu mano. Después, baraja tu mazo.","name":"¡Coloreemos este mundo con danza!"},"name":"Todoroki Hajime","tags":["#DEV_IS","#ReGLOSS","#Baby"]},"id":{"arts":[{"effect":"Saat ada holomen milikmu yang memiliki #ReGLOSS selain 〈Todoroki Hajime〉 di Stage milikmu, Arts ini +30.","name":"Petir Ungu Pemusnah"}],"keyword":{"effect":"Buka 1 kartu [Debut holomen atau 1st holomen] yang memiliki #ReGLOSS dari dekmu, tambahkan ke tanganmu. Setelah itu, kocok dekmu.","name":"Warnai dunia ini dengan tarian!"},"name":"Todoroki Hajime","tags":["#DEV_IS","#ReGLOSS","#Bayi"]},"ja":{"arts":[{"effect":"自分のステージに〈轟はじめ〉以外の#ReGLOSSを持つホロメンがいる時、このアーツ+30。","name":"滅紫の雷"}],"keyword":{"effect":"自分のデッキから、#ReGLOSSを持つ[Debutホロメンか1stホロメン]1枚を公開し、手札に加える。そしてデッキをシャッフルする。","name":"ダンスでこの世界に彩を！"},"name":"轟はじめ","tags":["#DEV_IS","#ReGLOSS","#ベイビー"]},"ko":{"arts":[{"effect":"자신의 스테이지에 〈토도로키 하지메〉 이외의 #ReGLOSS를 가진 홀로멘이 있을 때, 이 아츠 +30.","name":"멸자의 번개"}],"keyword":{"effect":"자신의 덱에서 #ReGLOSS를 가진 [Debut 홀로멘 또는 1st 홀로멘] 1장을 공개하고, 패에 넣는다. 그리고 덱을 셔플한다.","name":"댄스로 이 세계를 물들여라!"},"name":"토도로키 하지메","tags":["#DEV_IS","#ReGLOSS","#베이비"]},"tc":{"arts":[{"effect":"當自己的舞台上有持有#ReGLOSS且不是〈轟初芽〉的Holo成員時，此藝術+30。","name":"滅紫之雷"}],"keyword":{"effect":"從自己的牌庫公開1張帶有#ReGLOSS的[Debut holomen或1st holomen]，加入手牌。然後將牌庫洗牌。","name":"用舞蹈為這個世界增添色彩！"},"name":"轟初芽","tags":["#DEV_IS","#ReGLOSS","#嬰兒"]},"th":{"arts":[{"effect":"เมื่อบนสเตจของคุณมีโฮโลเมนที่มี #ReGLOSS ซึ่งไม่ใช่〈โทโดโรกิ ฮาจิเมะ〉 ศิลปะนี้ +30","name":"อัสนีสีม่วงพิฆาต"}],"keyword":{"effect":"อวด [Debutโฮโลเมน หรือ 1stโฮロメン] 1 ใบที่มี #ReGLOSS จากเด็คของคุณ แล้วนำเข้ามือ จากนั้นสับเด็ค","name":"แต่งแต้มโลกนี้ด้วยการเต้น!"},"name":"โทโดโรกิ ฮาจิเมะ","tags":["#DEV_IS","#ReGLOSS","#เบบี้"]}}}', '{}', 'f25ccc3670dcd0db16cee3a374d2d174fcfc2064ce9fb36347659ef743c31e28', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
