INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (526, 'hSD05-010', 'hSD05-010 Watersnake DEV_IS ReGLOSS お酒 儒烏風亭らでん #DEV_IS #ReGLOSS #お酒 ちょいと一席 自分のアーカイブのエール1枚を、自分の#ReGLOSSを持つホロメンに送れる。 Juufuutei Raden #DEV_IS #ReGLOSS #Alcohol How About a Little Performance? You may send 1 Cheer from your Archive to your holomem with #ReGLOSS. 儒烏風亭らでん #DEV_IS #ReGLOSS #酒 且聽我說一段 可將自己存檔區的1張應援送給自己持有#ReGLOSS的Holo成員。 Juufuutei Raden #DEV_IS #ReGLOSS #Alkohol Mari duduk sebentar Kamu boleh mengirim 1 Cheer dari Archive-mu ke holomen milikmu yang memiliki #ReGLOSS. 쥬우후우테이 라덴 #DEV_IS #ReGLOSS #술 잠깐 한 자리 자신의 아카이브의 에일 1장을 자신의 #ReGLOSS를 가진 홀로멘에게 보낼 수 있다. จูอูฟุเทย ราเด็ง #DEV_IS #ReGLOSS #แอลกอฮอล์ ขอสักช่วงหนึ่งสิ คุณสามารถส่งเอิล 1 ใบจากอาร์ไคฟ์ของคุณไปยังโฮโลเมนของคุณที่มี #ReGLOSS ได้ Juufuutei Raden #DEV_IS #ReGLOSS #Alcohol Tomemos asiento un momento Puedes enviar 1 Cheer de tu archivo a un holomen tuyo que tenga #ReGLOSS.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('527', 'hSD05-011', 'character', 'U', 'debut', 'hSD05/hSD05-011_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD05/hSD05-011_U.png', 70, NULL, 1, '["null"]', 'Watersnake', '一条莉々華', '{"arts":[{"cost_types":["null"],"damage":20}],"card_sets":["スタートデッキ 白 轟はじめ"],"color_codes":["red"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"The President’s Oshi Work"}],"keyword":{"effect":"If your Center holomem has #ReGLOSS and you have 5 or fewer cards in hand, draw 1 card.","name":"Leave it to me!"},"name":"Ichijou Ririka","tags":["#DEV_IS","#ReGLOSS","#Cooking"]},"es":{"arts":[{"name":"El oshikatsu de la presidenta"}],"keyword":{"effect":"Si tu holomem central tiene #ReGLOSS y tienes 5 cartas o menos en tu mano, roba 1 carta.","name":"¡Déjamelo a mí!"},"name":"Ichijou Ririka","tags":["#DEV_IS","#ReGLOSS","#Cooking"]},"id":{"arts":[{"name":"Pekerjaan Oshi Sang Presiden"}],"keyword":{"effect":"Saat Center holomem milikmu memiliki #ReGLOSS, jika tanganmu berjumlah 5 kartu atau kurang, ambil 1 kartu dari dekmu.","name":"Serahkan saja padaku!"},"name":"Ichijou Ririka","tags":["#DEV_IS","#ReGLOSS","#Masakan"]},"ja":{"arts":[{"name":"社長の推し事"}],"keyword":{"effect":"自分のセンターホロメンが#ReGLOSSを持つ時、自分の手札が5枚以下なら、自分のデッキを1枚引く。","name":"任せておきなさい！"},"name":"一条莉々華","tags":["#DEV_IS","#ReGLOSS","#料理"]},"ko":{"arts":[{"name":"사장의 덕질"}],"keyword":{"effect":"자신의 센터 홀로멤이 #ReGLOSS를 가질 때, 자신의 패가 5장 이하라면, 자신의 덱을 1장 뽑는다.","name":"맡겨두라고!"},"name":"이치조 리리카","tags":["#DEV_IS","#ReGLOSS","#요리"]},"tc":{"arts":[{"name":"社長的推活"}],"keyword":{"effect":"當自己的Center Holo成員持有#ReGLOSS時，若自己的手牌為5張以下，則抽1張牌。","name":"交給我吧！"},"name":"一条莉莉華","tags":["#DEV_IS","#ReGLOSS","#料理"]},"th":{"arts":[{"name":"งานโอชิของประธานบริษัท"}],"keyword":{"effect":"เมื่อเซ็นเตอร์โฮโลเมนของคุณมี #ReGLOSS ถ้าในมือของคุณมี 5 ใบหรือน้อยกว่า ให้จั่วการ์ด 1 ใบจากเด็คของคุณ","name":"ฝากไว้กับฉันเถอะ!"},"name":"อิชิโจ ริริกะ","tags":["#DEV_IS","#ReGLOSS","#ทำอาหาร"]}}}', '{}', 'b6ed0a62f28921c233b60cd9b86a610a24624aa1fcff226e6b738c4475d17d8c', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
