INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (539, 'hSD06-006', 'hSD06-006 黒井ススム JP 秘密結社holoX 風真いろは #JP #秘密結社holoX 刀の錆になるでござる！ サムライ少女 自分のデッキから、[〈ﾁｬｷ丸〉か〈ぽこべぇ〉]1枚を公開し、手札に加える。そしてデッキをシャッフルする。 Kazama Iroha #JP #Secret Society holoX You''ll Rust My Blade, de gozaru! Samurai Girl Reveal 1 [〈Chaki-maru〉 or 〈Pokobe〉] from your deck and add it to your hand. Then shuffle your deck. 風真伊呂波 #JP #秘密結社holoX 成為刀下鏽吧，ござる！ 武士少女 從自己的牌庫中公開1張[〈恰奇丸〉或〈Pekofy〉]，加入手牌。然後將牌庫洗牌。 Kazama Iroha #JP #Organisasi Rahasia holoX Jadilah karat di pedangku, de gozaru! Gadis Samurai Ungkapkan 1 [〈Chaki-maru〉 atau 〈Pokobe〉] dari dekmu, lalu tambahkan ke tanganmu. Lalu kocok dekmu. 카자마 이로하 #JP #비밀결사 holoX 칼의 녹이 될 것이오! 사무라이 소녀 자신의 덱에서 [〈차키마루〉 또는 〈포코베〉] 1장을 공개하고, 손패에 넣는다. 그리고 덱을 셔플한다. คาซามะ อิโรฮะ #JP #องค์กรลับ holoX จะทำให้เป็นสนิมดาบเสียเลยขอรับ! สาวซามูไร เปิดเผย [〈ชากิมารุ〉 หรือ 〈โปโกะเบะ〉] 1 ใบจากเด็คของคุณ แล้วนำขึ้นมือ จากนั้นสับเด็ค Kazama Iroha #JP #Secret Society holoX ¡Serás óxido para mi espada, de gozaru! Chica samurái Revela 1 carta [〈Chaki-maru〉 o 〈Pokobe〉] de tu mazo y añádela a tu mano. Luego baraja tu mazo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('540', 'hSD06-007', 'character', 'RR', 'second', 'hSD06/hSD06-007_RR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD06/hSD06-007_RR.png', 180, NULL, 2, '["null","null"]', 'しろみにみ', '風真いろは', '{"arts":[{"cost_types":["green","null","null"],"damage":70,"is_plus":true,"special_targets":["blue"],"special_values":[50]}],"card_sets":["スタートデッキ 緑 風真いろは"],"color_codes":["green"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"If there are 5 or more Cheer on your Stage, this Art gets +50.","name":"A Genius, Perhaps?"}],"keyword":{"effect":"Heal 30 HP from 1 of your holomems with #Secret Society holoX.","name":"Delivering Cheer"},"name":"Kazama Iroha","tags":["#JP","#Secret Society holoX"]},"es":{"arts":[{"effect":"Si hay 5 o más Cheer en tu Escenario, este Arte +50.","name":"¿No soy una genio?"}],"keyword":{"effect":"Cura 30 HP a 1 de tus holomen con #Secret Society holoX.","name":"Te traigo energía"},"name":"Kazama Iroha","tags":["#JP","#Secret Society holoX"]},"id":{"arts":[{"effect":"Jika ada 5 Cheer atau lebih di Stage milikmu, Arts ini +50.","name":"Jenius, ya?"}],"keyword":{"effect":"Pulihkan 30 HP 1 holomen milikmu yang memiliki #Organisasi Rahasia holoX.","name":"Mengantarkan semangat"},"name":"Kazama Iroha","tags":["#JP","#Organisasi Rahasia holoX"]},"ja":{"arts":[{"effect":"自分のステージにエールが5枚以上ある時、このアーツ+50。","name":"天才では？"}],"keyword":{"effect":"自分の#秘密結社holoXを持つホロメン1人のHP30回復。","name":"元気をお届け"},"name":"風真いろは","tags":["#JP","#秘密結社holoX"]},"ko":{"arts":[{"effect":"자신의 스테이지에 에일이 5장 이상 있을 때, 이 아츠 +50.","name":"천재 아닌가?"}],"keyword":{"effect":"자신의 #비밀결사 holoX를 가진 홀로멘 1명의 HP를 30 회복한다.","name":"기운을 전해드려요"},"name":"카자마 이로하","tags":["#JP","#비밀결사 holoX"]},"tc":{"arts":[{"effect":"當自己的舞台上有5張以上應援時，此藝術+50。","name":"這不是天才嗎？"}],"keyword":{"effect":"自己的1位持有#秘密結社holoX的holomen回復HP30。","name":"為你送上元氣"},"name":"風真伊呂波","tags":["#JP","#秘密結社holoX"]},"th":{"arts":[{"effect":"ขณะที่บนสเตจของคุณมีเอิล 5 ใบขึ้นไป ศิลปะนี้ +50","name":"นี่มันอัจฉริยะชัดๆ?"}],"keyword":{"effect":"ฟื้นฟู HP 30 ให้โฮโลเมนของคุณ 1 คนที่มี #องค์กรลับ holoX","name":"ส่งต่อพลังใจ"},"name":"คาซามะ อิโรฮะ","tags":["#JP","#องค์กรลับ holoX"]}}}', '{}', 'c9bcfb2fca08923aa698808381fa7923681749cbd5c3c27e49b78fcdcd5e6402', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
