INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (541, 'hSD06-008', 'hSD06-008 広江礼威 JP 秘密結社holoX ケモミミ 博衣こより #JP #秘密結社holoX #ケモミミ どやぁ ずのー！ 自分のセンターホロメンが#秘密結社holoXを持つ時、自分の手札が5枚以下なら、自分のデッキを1枚引く。 Hakui Koyori #JP #Secret Society holoX #Animal Ears Hah! Braaains! If your Center holomem has #Secret Society holoX and you have 5 or fewer cards in hand, draw 1 card. 博衣こより #JP #秘密結社holoX #獸耳 得意吧 腦力！ 當自己的中心Holomen持有#秘密結社holoX時，若自己的手牌為5張以下，則抽1張牌。 Hakui Koyori #JP #Organisasi Rahasia holoX #Telinga Hewan Doyaa Otakkk! Saat Center holomen milikmu memiliki #Organisasi Rahasia holoX, jika tanganmu berjumlah 5 kartu atau kurang, ambil 1 kartu dari Dek milikmu. 하쿠이 코요리 #JP #비밀결사 holoX #수인귀 어때 뇌-! 자신의 센터 홀로멘이 #비밀결사 holoX을 가지고 있을 때, 자신의 패가 5장 이하라면, 자신의 덱을 1장 뽑는다. ฮากุย โคโยริ #JP #องค์กรลับ holoX #หูสัตว์ โดะยา~ สติปัญญาาา! เมื่อเซ็นเตอร์โฮโลเมนของคุณมี #องค์กรลับ holoX ถ้าคุณมีการ์ดในมือ 5 ใบหรือน้อยกว่า จั่วการ์ด 1 ใบจากเด็คของคุณ Hakui Koyori #JP #Secret Society holoX #Animal Ears Doyaa ¡Cerebrooo! Si tu holomen central tiene #Secret Society holoX y tienes 5 cartas o menos en tu mano, roba 1 carta de tu mazo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('542', 'hSD06-009', 'character', 'U', 'debut', 'hSD06/hSD06-009_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD06/hSD06-009_U.png', 80, NULL, 1, '["null"]', '広江礼威', '鷹嶺ルイ', '{"arts":[{"cost_types":["null"],"damage":20}],"card_sets":["スタートデッキ 緑 風真いろは"],"color_codes":["red"],"translations":{"en":{"arts":[{"effect":"You may return 1 Debut holomem with #Secret Society holoX from your Archive to your hand.","name":"A Dependable Lady Executive"}],"name":"Takane Lui","tags":["#JP","#Secret Society holoX","#Bird","#Alcohol"]},"es":{"arts":[{"effect":"Puedes devolver a tu mano 1 Debut holomen con #Secret Society holoX de tu Archivo.","name":"La lugarteniente de confianza"}],"name":"Takane Lui","tags":["#JP","#Secret Society holoX","#Bird","#Alcohol"]},"id":{"arts":[{"effect":"Kamu boleh mengembalikan 1 Debut holomen yang memiliki #Organisasi Rahasia holoX dari Archive milikmu ke tanganmu.","name":"Eksekutif wanita yang bisa diandalkan"}],"name":"Takane Lui","tags":["#JP","#Organisasi Rahasia holoX","#Burung","#Alkohol"]},"ja":{"arts":[{"effect":"自分のアーカイブの#秘密結社holoXを持つDebutホロメン1枚を手札に戻せる。","name":"頼れる女幹部"}],"name":"鷹嶺ルイ","tags":["#JP","#秘密結社holoX","#トリ","#お酒"]},"ko":{"arts":[{"effect":"자신의 아카이브의 #비밀결사 holoX를 가진 Debut 홀로멘 1장을 패로 되돌릴 수 있다.","name":"믿음직한 여간부"}],"name":"타카네 루이","tags":["#JP","#비밀결사 holoX","#새","#술"]},"tc":{"arts":[{"effect":"可以將自己存檔區的1張持有#秘密結社holoX的Debut Holomen返回手牌。","name":"可靠的女幹部"}],"name":"鷹嶺露依","tags":["#JP","#秘密結社holoX","#小鳥","#酒"]},"th":{"arts":[{"effect":"คุณสามารถนำ Debut โฮโลเมม 1 ใบที่มี #องค์กรลับ holoX จากอาร์ไคฟ์ของคุณกลับขึ้นมือได้","name":"รองหัวหน้าหญิงที่ไว้ใจได้"}],"name":"ทาคาเนะ รุย","tags":["#JP","#องค์กรลับ holoX","#นก","#แอลกอฮอล์"]}}}', '{}', '6fa1ebcc6684558139739415543c650ffc2f3d640295d6370648c6f422b47b78', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
