INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (542, 'hSD06-009', 'hSD06-009 広江礼威 JP 秘密結社holoX トリ お酒 鷹嶺ルイ #JP #秘密結社holoX #トリ #お酒 頼れる女幹部 自分のアーカイブの#秘密結社holoXを持つDebutホロメン1枚を手札に戻せる。 Takane Lui #JP #Secret Society holoX #Bird #Alcohol A Dependable Lady Executive You may return 1 Debut holomem with #Secret Society holoX from your Archive to your hand. 鷹嶺露依 #JP #秘密結社holoX #小鳥 #酒 可靠的女幹部 可以將自己存檔區的1張持有#秘密結社holoX的Debut Holomen返回手牌。 Takane Lui #JP #Organisasi Rahasia holoX #Burung #Alkohol Eksekutif wanita yang bisa diandalkan Kamu boleh mengembalikan 1 Debut holomen yang memiliki #Organisasi Rahasia holoX dari Archive milikmu ke tanganmu. 타카네 루이 #JP #비밀결사 holoX #새 #술 믿음직한 여간부 자신의 아카이브의 #비밀결사 holoX를 가진 Debut 홀로멘 1장을 패로 되돌릴 수 있다. ทาคาเนะ รุย #JP #องค์กรลับ holoX #นก #แอลกอฮอล์ รองหัวหน้าหญิงที่ไว้ใจได้ คุณสามารถนำ Debut โฮโลเมม 1 ใบที่มี #องค์กรลับ holoX จากอาร์ไคฟ์ของคุณกลับขึ้นมือได้ Takane Lui #JP #Secret Society holoX #Bird #Alcohol La lugarteniente de confianza Puedes devolver a tu mano 1 Debut holomen con #Secret Society holoX de tu Archivo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('543', 'hSD06-010', 'character', 'U', 'debut', 'hSD06/hSD06-010_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD06/hSD06-010_U.png', 60, NULL, 1, '["null"]', '広江礼威', 'ラプラス・ダークネス', '{"arts":[{"cost_types":["null"],"damage":30,"is_plus":true}],"card_sets":["スタートデッキ 緑 風真いろは"],"color_codes":["purple"],"translations":{"en":{"arts":[{"effect":"[Collab Position Only] While you used your SP Oshi Skill during your Main Step this turn, this Art gets +50.","name":"Feast of Madness"}],"name":"Laplus Darknesss","tags":["#JP","#Secret Society holoX","#Shooter"]},"es":{"arts":[{"effect":"[Solo Posición de Colaboración] Si usaste tu habilidad de oshi SP durante tu Paso Principal de este turno, este Arte +50.","name":"Banquete de locura"}],"name":"Laplus Darknesss","tags":["#JP","#Secret Society holoX","#Shooter"]},"id":{"arts":[{"effect":"[Khusus Posisi Collab] Saat kamu telah menggunakan Skill Oshi SP milikmu pada Main Step di giliran ini, Arts ini +50.","name":"Perjamuan Kegilaan"}],"name":"Laplus Darknesss","tags":["#JP","#Organisasi Rahasia holoX","#Penembak"]},"ja":{"arts":[{"effect":"[コラボポジション限定]このターンの自分のメインステップに自分のSP推しスキルを使っていた時、このアーツ+50。","name":"狂気の宴"}],"name":"ラプラス・ダークネス","tags":["#JP","#秘密結社holoX","#シューター"]},"ko":{"arts":[{"effect":"[콜라보 포지션 한정] 이번 턴 자신의 메인 스텝에 자신의 SP 오시 스킬을 사용했을 때, 이 아츠 +50.","name":"광기의 연회"}],"name":"라플라스 다크니스","tags":["#JP","#비밀결사 holoX","#슈터"]},"tc":{"arts":[{"effect":"[僅限合作位置]如果自己在這個回合的主要階段中曾使用過自己的SP推技能，則此藝術+50。","name":"狂氣之宴"}],"name":"Laplus Darknesss","tags":["#JP","#秘密結社holoX","#射手"]},"th":{"arts":[{"effect":"[เฉพาะตำแหน่งคอลแลบ]หากในเมนสเต็ปของคุณในเทิร์นนี้คุณได้ใช้ SP โอชิสกิล อาร์ตนี้ +50","name":"งานเลี้ยงแห่งความบ้าคลั่ง"}],"name":"ลาปลัส ดาร์กเนส","tags":["#JP","#องค์กรลับ holoX","#ชูตเตอร์"]}}}', '{}', '0956e7e542d8cc3b2ca4029a7ae508592a5abd3b05b4ab956b3876ba3a659697', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
