INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (545, 'hSD06-012', 'hSD06-012 JinArt こばやかわやまと ぽこべぇ このマスコットが付いているホロメンのHP+10。
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('546', 'hSD07-001', 'oshiCharacter', 'OC', NULL, 'hSD07/hSD07-001_OC', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD07/hSD07-001_OC.png', NULL, 5, NULL, NULL, '松尾 省吾', '不知火フレア', '{"card_sets":["スタートデッキ 黄 不知火フレア"],"color_codes":["yellow"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Shiranui Flare","oshi_skill":{"effect":"[Once per turn] Until end of turn, your Yellow Center holomem gets Arts +20.","name":"YELLOW MIC","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] Switch your Center holomem with 1 of your Back holomem that is not Resting. Additionally, heal 30 HP from the holomem moved to the Back position.","name":"I''ll take it from here!","timing":"Once per game"}},"es":{"name":"Shiranui Flare","oshi_skill":{"effect":"[Una vez por turno] Durante este turno, los Arts de tu holomen central amarillo +20.","name":"Micrófono Amarillo","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Haz que tu Centro holomen y 1 Back holomen que no esté Descansando se intercambien. Además, el holomen que se movió a la Back Position recupera 30 PS.","name":"¡Yo me encargo del resto!","timing":"Una vez por partida"}},"id":{"name":"Shiranui Flare","oshi_skill":{"effect":"[Sekali per giliran] Selama giliran ini, Arts Yellow Center Holomen milikmu +20.","name":"Mik Kuning","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per game] Tukarkan Center holomem milikmu dengan 1 Back holomem milikmu yang tidak dalam posisi Rest. Selain itu, pulihkan 30 HP holomem yang dipindahkan ke posisi Back.","name":"Sisanya serahkan padaku!","timing":"Sekali per permainan"}},"ja":{"name":"不知火フレア","oshi_skill":{"effect":"[ターンに1回]このターンの間、自分の黄センターホロメンのアーツ+20。","name":"イエローマイク","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]自分のセンターホロメンとお休みしていないバックホロメン1人を交代させる。さらに、バックポジションに移動したホロメンのHP30回復。","name":"後は引き受けた！","timing":"ゲームに1回"}},"ko":{"name":"시라누이 플레어","oshi_skill":{"effect":"[턴에 1번]이번 턴 동안, 자신의 황색 센터 홀로멤의 아츠 +20.","name":"옐로 마이크","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번] 자신의 센터 홀로멘과 쉬고 있지 않은 백 홀로멘 1명을 교대시킨다. 추가로, 백 포지션으로 이동한 홀로멘의 HP를 30 회복한다.","name":"나머지는 맡겨 둬!","timing":"게임에 1번"}},"tc":{"name":"不知火芙蕾雅","oshi_skill":{"effect":"[每回合1次]這個回合中，自己的黃色Center Holomen的Art+20。","name":"黃色麥克風","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場遊戲1次]使自己的中心Holo成員與1位沒有休息中的後台Holo成員交換。再者，將移動到後台位置的Holo成員回復HP30。","name":"之後就交給我吧！","timing":"每場對戰1次"}},"th":{"name":"ชิรานุย เฟลร์","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] ในเทิร์นนี้ อาร์ตของเซ็นเตอร์โฮโลเม็มเบอร์สีเหลืองของคุณ +20","name":"ไมค์สีเหลือง","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] สลับเซ็นเตอร์โฮโลเมนของคุณกับแบ็กโฮโลเมน 1 คนของคุณที่ไม่ได้พักอยู่ นอกจากนี้ ฟื้นฟู HP 30 ให้โฮโลเมนที่ย้ายไปยังตำแหน่งแบ็ก","name":"ที่เหลือฉันรับช่วงเอง!","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{}', '7b4fb3be6f8c49e8b7a2af8de00c814cc52daa3ac28989e418a502f91ebcaf32', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
INSERT INTO card_colors (color_code, card_id) VALUES ('yellow', '546');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ 黄 不知火フレア', '546');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (546, 'hSD07-001', 'hSD07-001 松尾 省吾 不知火フレア イエローマイク [ターンに1回]このターンの間、自分の黄センターホロメンのアーツ+20。 後は引き受けた！ [ゲームに1回]自分のセンターホロメンとお休みしていないバックホロメン1人を交代させる。さらに、バックポジションに移動したホロメンのHP30回復。 Shiranui Flare YELLOW MIC [Once per turn] Until end of turn, your Yellow Center holomem gets Arts +20. I''ll take it from here! [Once per game] Switch your Center holomem with 1 of your Back holomem that is not Resting. Additionally, heal 30 HP from the holomem moved to the Back position. 不知火芙蕾雅 黃色麥克風 [每回合1次]這個回合中，自己的黃色Center Holomen的Art+20。 之後就交給我吧！ [每場遊戲1次]使自己的中心Holo成員與1位沒有休息中的後台Holo成員交換。再者，將移動到後台位置的Holo成員回復HP30。 Shiranui Flare Mik Kuning [Sekali per giliran] Selama giliran ini, Arts Yellow Center Holomen milikmu +20. Sisanya serahkan padaku! [Sekali per game] Tukarkan Center holomem milikmu dengan 1 Back holomem milikmu yang tidak dalam posisi Rest. Selain itu, pulihkan 30 HP holomem yang dipindahkan ke posisi Back. 시라누이 플레어 옐로 마이크 [턴에 1번]이번 턴 동안, 자신의 황색 센터 홀로멤의 아츠 +20. 나머지는 맡겨 둬! [게임에 1번] 자신의 센터 홀로멘과 쉬고 있지 않은 백 홀로멘 1명을 교대시킨다. 추가로, 백 포지션으로 이동한 홀로멘의 HP를 30 회복한다. ชิรานุย เฟลร์ ไมค์สีเหลือง [ใช้ได้ 1 ครั้งต่อเทิร์น] ในเทิร์นนี้ อาร์ตของเซ็นเตอร์โฮโลเม็มเบอร์สีเหลืองของคุณ +20 ที่เหลือฉันรับช่วงเอง! [ใช้ได้ 1 ครั้งต่อเกม] สลับเซ็นเตอร์โฮโลเมนของคุณกับแบ็กโฮโลเมน 1 คนของคุณที่ไม่ได้พักอยู่ นอกจากนี้ ฟื้นฟู HP 30 ให้โฮโลเมนที่ย้ายไปยังตำแหน่งแบ็ก Shiranui Flare Micrófono Amarillo [Una vez por turno] Durante este turno, los Arts de tu holomen central amarillo +20. ¡Yo me encargo del resto! [Una vez por partida] Haz que tu Centro holomen y 1 Back holomen que no esté Descansando se intercambien. Además, el holomen que se movió a la Back Position recupera 30 PS.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('547', 'hSD07-002', 'character', 'C', 'debut', 'hSD07/hSD07-002_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD07/hSD07-002_C.png', 110, NULL, 1, '["null"]', NULL, '不知火フレア', '{"arts":[{"cost_types":["null"],"damage":20},{"cost_types":["null","null","null"],"damage":60}],"card_sets":["スタートデッキ 黄 不知火フレア","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["yellow"],"translations":{"en":{"arts":[{"name":"Konnui~!"},{"name":"It''s Shiranui Flare!"}],"name":"Shiranui Flare","tags":["#JP","#3rd Gen","#Half-Elf"]},"es":{"arts":[{"name":"¡Connuii!"},{"name":"¡Soy Shiranui Flare!"}],"name":"Shiranui Flare","tags":["#JP","#3rd Gen","#Half-Elf"]},"id":{"arts":[{"name":"Konnuii!"},{"name":"Aku Shiranui Flare!"}],"name":"Shiranui Flare","tags":["#JP","#Gen 3","#Setengah Elf"]},"ja":{"arts":[{"name":"こんぬいー！"},{"name":"不知火フレアだよ！"}],"name":"不知火フレア","tags":["#JP","#3期生","#ハーフエルフ"]},"ko":{"arts":[{"name":"콘누이~!"},{"name":"시라누이 플레어야!"}],"name":"시라누이 플레어","tags":["#JP","#3기생","#하프엘프"]},"tc":{"arts":[{"name":"konnuiー！"},{"name":"是不知火芙蕾雅唷！"}],"name":"不知火芙蕾雅","tags":["#JP","#3期生","#半精靈"]},"th":{"arts":[{"name":"คนนุย~!"},{"name":"คือชิรานุย เฟลร์ไง!"}],"name":"ชิรานุย เฟลร์","tags":["#JP","#รุ่น 3","#ฮาล์ฟเยลฟ์"]}}}', '{}', 'fdedcb8285f5bce10489d90e4f453c976fcd3ec07705008b2b3c46553a77d841', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
