INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (547, 'hSD07-002', 'hSD07-002 JP 3期生 ハーフエルフ 不知火フレア #JP #3期生 #ハーフエルフ こんぬいー！ 不知火フレアだよ！ Shiranui Flare #JP #3rd Gen #Half-Elf Konnui~! It''s Shiranui Flare! 不知火芙蕾雅 #JP #3期生 #半精靈 konnuiー！ 是不知火芙蕾雅唷！ Shiranui Flare #JP #Gen 3 #Setengah Elf Konnuii! Aku Shiranui Flare! 시라누이 플레어 #JP #3기생 #하프엘프 콘누이~! 시라누이 플레어야! ชิรานุย เฟลร์ #JP #รุ่น 3 #ฮาล์ฟเยลฟ์ คนนุย~! คือชิรานุย เฟลร์ไง! Shiranui Flare #JP #3rd Gen #Half-Elf ¡Connuii! ¡Soy Shiranui Flare!', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('548', 'hSD07-003', 'character', 'C', 'debut', 'hSD07/hSD07-003_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD07/hSD07-003_C.png', 50, NULL, 1, '["null"]', 'サクミチ', '不知火フレア', '{"arts":[{"cost_types":["yellow"],"damage":20}],"card_sets":["スタートデッキ 黄 不知火フレア"],"color_codes":["yellow"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Going Out Together with You"}],"keyword":{"effect":"If you have 5 or fewer holomems on your Stage, you may reveal 1 Debut holomem [〈Omaru Polka〉, 〈Sakura Miko〉, 〈Hoshimachi Suisei〉, or 〈Shirogane Noel〉] from your deck: Put the revealed holomem onto the Stage. Then shuffle your deck.","name":"With My Precious Companions"},"name":"Shiranui Flare","tags":["#JP","#3rd Gen","#Half-Elf"]},"es":{"arts":[{"name":"Salir contigo"}],"keyword":{"effect":"Si tienes 5 holomen o menos en tu escenario, puedes revelar 1 [〈Omaru Polka〉 o 〈Sakura Miko〉 o 〈Hoshimachi Suisei〉 o 〈Shirogane Noel〉] Debut holomen de tu mazo: pon el holomen revelado en tu escenario. Después, baraja el mazo.","name":"Junto a mis preciados compañeros"},"name":"Shiranui Flare","tags":["#JP","#3rd Gen","#Half-Elf"]},"id":{"arts":[{"name":"Pergi jalan-jalan bareng kamu"}],"keyword":{"effect":"Jika holomen di Stage milikmu berjumlah 5 atau kurang, kamu boleh mengungkapkan 1 kartu Debut holomen [〈Omaru Polka〉, 〈Sakura Miko〉, 〈Hoshimachi Suisei〉, atau 〈Shirogane Noel〉] dari Deck milikmu: keluarkan holomen yang diungkapkan itu ke Stage. Lalu, kocok Deck.","name":"Bersama rekan-rekan berharga"},"name":"Shiranui Flare","tags":["#JP","#Gen 3","#Setengah Elf"]},"ja":{"arts":[{"name":"キミといっしょにお出かけ"}],"keyword":{"effect":"自分のステージのホロメンが5人以下の時、自分のデッキから、Debutホロメンの[〈尾丸ポルカ〉か〈さくらみこ〉か〈星街すいせい〉か〈白銀ノエル〉]1枚を公開できる:公開したホロメンをステージに出す。そしてデッキをシャッフルする。","name":"大切な仲間たちと"},"name":"不知火フレア","tags":["#JP","#3期生","#ハーフエルフ"]},"ko":{"arts":[{"name":"너와 함께 외출"}],"keyword":{"effect":"자신의 스테이지의 홀로멤이 5명 이하일 때, 자신의 덱에서 Debut 홀로멤의 [〈오마루 폴카〉 또는 〈사쿠라 미코〉 또는 〈호시마치 스이세이〉 또는 〈시로가네 노엘〉] 1장을 공개할 수 있다: 공개한 홀로멤을 스테이지에 낸다. 그리고 덱을 셔플한다.","name":"소중한 동료들과"},"name":"시라누이 플레어","tags":["#JP","#3기생","#하프엘프"]},"tc":{"arts":[{"name":"和你一起出門"}],"keyword":{"effect":"當自己舞台上的Holomen為5位以下時，可以從自己的牌庫公開1張Debut Holomen的[〈尾丸Polka〉或〈櫻巫女〉或〈星街彗星〉或〈白銀諾艾爾〉]：將公開的Holomen登場到舞台。然後將牌庫洗牌。","name":"和重要的夥伴們一起"},"name":"不知火芙蕾雅","tags":["#JP","#3期生","#半精靈"]},"th":{"arts":[{"name":"ออกไปเที่ยวด้วยกันกับเธอ"}],"keyword":{"effect":"ถ้าบนสเตจของคุณมีโฮโลเมน 5 คนหรือน้อยกว่า คุณสามารถเปิดเผย Debutโฮโลเมน [〈โอมารุ โปลกะ〉 หรือ 〈ซากุระ มิโกะ〉 หรือ 〈โฮชิมาชิ สุยเซย〉 หรือ 〈ชิโรกาเนะ โนเอล〉] 1 ใบจากเด็คของคุณ: นำโฮโลเมนที่เปิดเผยนั้นลงสู่สเตจ จากนั้นสับเด็ค","name":"กับพวกพ้องคนสำคัญ"},"name":"ชิรานุย เฟลร์","tags":["#JP","#รุ่น 3","#ฮาล์ฟเยลฟ์"]}}}', '{}', 'c9c48541df527a73401746892d198535679393f6070ea7639078ebcf29ed2a97', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
