INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (550, 'hSD07-005', 'hSD07-005 サクミチ JP 3期生 ハーフエルフ 不知火フレア #JP #3期生 #ハーフエルフ 私からキミへ キミとティータイム Shiranui Flare #JP #3rd Gen #Half-Elf From Me to You Tea Time with You 不知火芙蕾雅 #JP #3期生 #半精靈 由我傳給你 與你共度下午茶 Shiranui Flare #JP #Gen 3 #Setengah Elf Dari Aku untukmu Tea Time Bersamamu 시라누이 플레어 #JP #3기생 #하프엘프 나에게서 너에게 너와 티타임 ชิรานุย เฟลร์ #JP #รุ่น 3 #ฮาล์ฟเยลฟ์ จากฉันถึงเธอ ช่วงน้ำชากับเธอ Shiranui Flare #JP #3rd Gen #Half-Elf De mí para ti La hora del té contigo', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('551', 'hSD07-006', 'character', 'C', 'first', 'hSD07/hSD07-006_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD07/hSD07-006_C.png', 120, NULL, 1, '["null"]', 'lack', '不知火フレア', '{"arts":[{"cost_types":["null"],"damage":30,"is_plus":true}],"card_sets":["スタートデッキ 黄 不知火フレア"],"color_codes":["yellow"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"While your Life is 3 or less, this Art gets +30.","name":"I’m the One Who Loves You Most~♡"}],"keyword":{"effect":"Reveal 1 〈Elf Friend〉 from your deck and add it to your hand. Then shuffle your deck.","name":"Elf Friend''s Chirping"},"name":"Shiranui Flare","tags":["#JP","#3rd Gen","#Half-Elf"]},"es":{"arts":[{"effect":"Mientras tu Vida sea 3 o menos, este Arte +30.","name":"La que más te quiere soy yooo～♡"}],"keyword":{"effect":"Revela 1 carta 〈Elf Friend〉 de tu mazo y añádela a tu mano. Después, baraja tu mazo.","name":"El trino de Elf Friend"},"name":"Shiranui Flare","tags":["#JP","#3rd Gen","#Half-Elf"]},"id":{"arts":[{"effect":"Saat Life kamu 3 atau kurang, Arts ini +30.","name":"Yang paling suka kamu itu aku～♡"}],"keyword":{"effect":"Ungkapkan 1 kartu 〈Elf Friend〉 dari dekmu, tambahkan ke tanganmu. Lalu, kocok deknya.","name":"Kicauan Elf Friend"},"name":"Shiranui Flare","tags":["#JP","#Gen 3","#Setengah Elf"]},"ja":{"arts":[{"effect":"自分のライフが3以下の時、このアーツ+30。","name":"キミを1番好きなのはわたしぃ～♡"}],"keyword":{"effect":"自分のデッキから、〈エルフレンド〉1枚を公開し、手札に加える。そしてデッキをシャッフルする。","name":"エルフレンドのさえずり"},"name":"不知火フレア","tags":["#JP","#3期生","#ハーフエルフ"]},"ko":{"arts":[{"effect":"자신의 라이프가 3 이하일 때, 이 아츠 +30.","name":"널 제일 좋아하는 건 나야~♡"}],"keyword":{"effect":"자신의 덱에서 〈엘프 프렌드〉 1장을 공개하고, 패에 넣는다. 그리고 덱을 셔플한다.","name":"엘프 프렌드의 지저귐"},"name":"시라