INSERT INTO card_tags (tag, card_id) VALUES ('ケモミミ', '557');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (557, 'hSD07-012', 'hSD07-012 JP 5期生 ケモミミ 尾丸ポルカ #JP #5期生 #ケモミミ 骨を埋める覚悟 僕らに水を 自分のセンターホロメンが〈不知火フレア〉の時、自分の手札の枚数が相手より少なければ、自分のデッキを1枚引く。 Omaru Polka #JP #5th Gen #Animal Ears Ready to Be Buried Here Give Us Water If your Center holomem is 〈Shiranui Flare〉 and you have fewer cards in hand than your opponent, draw 1 card from your deck. 尾丸Polka #JP #5期生 #獸耳 埋骨於此的覺悟 給我們水吧 當自己的中心holomen是〈不知火芙蕾雅〉時，若自己的手牌數量比對手少，則自己抽1張牌。 Omaru Polka #JP #Gen 5 #Telinga Hewan Siap Mengubur Tulang Berikan kami air Jika Center Holomen milikmu adalah 〈Shiranui Flare〉dan jumlah kartu di tanganmu lebih sedikit daripada lawan, tarik 1 kartu dari Deck milikmu. 오마루 폴카 #JP #5기생 #수인귀 뼈를 묻을 각오 우리에게 물을 자신의 센터 홀로멘이 〈시라누이 플레어〉일 때, 자신의 손패 수가 상대보다 적다면, 자신의 덱을 1장 뽑는다. โอมารุ โปลกะ #JP #รุ่น 5 #หูสัตว์ ความพร้อมที่จะฝากกระดูกไว้ที่นี่ มอบน้ำให้พวกเรา ถ้าเซ็นเตอร์โฮโลเมนของคุณเป็น〈ชิรานุย เฟลร์〉 และจำนวนการ์ดในมือของคุณน้อยกว่าคู่ต่อสู้ ให้จั่วการ์ดจากเด็คของคุณ 1 ใบ Omaru Polka #JP #5th Gen #Animal Ears Listo para echar raíces Agua para nosotros Si tu holomen central es 〈Shiranui Flare〉 y tienes menos cartas en la mano que tu oponente, roba 1 carta.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('558', 'hSD07-013', 'character', 'U', 'debut', 'hSD07/hSD07-013_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD07/hSD07-013_U.png', 70, NULL, 1, '["null"]', NULL, '星街すいせい', '{"arts":[{"cost_types":["null"],"damage":20}],"card_sets":["スタートデッキ 黄 不知火フレア"],"color_codes":["blue"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Please Hire Me!!"}],"keyword":{"effect":"If your Center holomem is 〈Shiranui Flare〉, you may send 1 Cheer from your archive to one of your holomem other than this holomem.","name":"We''re About to Run Out of Food..."},"name":"Hoshimachi Suisei","tags":["#JP","#0th Gen","#Singing"]},"es":{"arts":[{"name":"¡¡Contrátame!!"}],"keyword":{"effect":"Cuando tu holomen central sea 〈Shiranui Flare〉, puedes enviar 1 Cheer de tu archivo a uno de tus holomen que no sea este holomen.","name":"La comida está por acabarse..."},"name":"Hoshimachi Suisei","tags":["#JP","#0th Gen","#Singing"]},"id":{"arts":[{"name":"Tolong pekerjakan aku‼"}],"keyword":{"effect":"Saat Center Holomen milikmu adalah 〈Shiranui Flare〉, kamu boleh mengirim 1 Cheer dari Arsipmu ke Holomen milikmu selain Holomen ini.","name":"Makanannya hampir habis......"},"name":"Hoshimachi Suisei","tags":["#JP","#Gen 0","#Menyanyi"]},"ja":{"arts":[{"name":"雇ってください‼"}],"keyword":{"effect":"自分のセンターホロメンが〈不知火フレア〉の時、自分のアーカイブのエール1枚を、このホロメン以外の自分のホロメンに送れる。","name":"ご飯が底をつきそう……"},"name":"星街すいせい","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"name":"고용해 주세요‼"}],"keyword":{"effect":"자신의 센터 홀로멤이 〈시라누이 플레어〉일 때, 자신의 아카이브의 엘 1장을 이 홀로멤 이외의 자신의 홀로멤에게 보낼 수 있다.","name":"밥이 바닥나기 직전이야……"},"name":"호시마치 스이세이","tags":["#JP","#0기생","#노래"]},"tc":{"arts":[{"name":"請雇用我‼"}],"keyword":{"effect":"當自己的中心Holomen為〈不知火芙蕾雅〉時，可以將自己檔案區中的1張應援送給自己其他Holomen，但不能送給這位Holomen。","name":"飯快要見底了……"},"name":"星街彗星","tags":["#JP","#0期生","#歌唱"]},"th":{"arts":[{"name":"รับฉันเข้าทำงานที‼"}],"keyword":{"effect":"เมื่อเซ็นเตอร์โฮโลเมนของคุณคือ 〈ชิรานุย เฟลร์〉 คุณสามารถส่งเยล 1 ใบจากอาร์ไคฟ์ของคุณไปยังโฮโลเมนอีกคนของคุณที่ไม่ใช่โฮโลเมนนี้ได้","name":"ข้าวจะหมดก้นหม้อแล้ว......"},"name":"โฮชิมาชิ สุยเซย","tags":["#JP","#รุ่น 0","#เพลง"]}}}', '{}', '2fd10e882bb259f6a9dbe38924c76bd20622c99a63573cb320c585d12ea3c78b', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
