INSERT INTO card_tags (tag, card_id) VALUES ('ケモミミ', '562');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (562, 'hSD03-003', 'hSD03-003 はねこと JP ゲーマーズ ケモミミ 猫又おかゆ #JP #ゲーマーズ #ケモミミ 僕をお家に入れてください お家にお邪魔します…！ 自分のセンターホロメンが#ゲーマーズを持つ時、相手のセンターホロメンとバックホロメン1人に特殊ダメージ10を与える。ただし、ダウンしても相手のライフは減らない。 Nekomata Okayu #JP #Gamers #Animal Ears Please Let Me In Your Home Pardon me for visiting your home...! If your Center holomem has #Gamers, deal 10 special damage to your opponent''s Center holomem and 1 of their Back holomem. However, even if they are Downed, your opponent does not lose Life. 貓又小粥 #JP #Gamers #獸耳 請讓我進你家 打擾你家了…！ 當自己的中心Holomen持有#Gamers時，對對手的中心Holomen與1名後台Holomen造成特殊傷害10。但即使因此倒下，對手的生命值也不會減少。 Nekomata Okayu #JP #Gamers #Telinga Hewan Tolong biarkan aku masuk rumahmu Permisi mampir ke rumahmu…! Saat Center holomen milikmu memiliki #Gamers, berikan 10 damage spesial kepada Center holomen lawan dan 1 Back holomen lawan. Namun, meskipun Down, Life lawan tidak berkurang. 네코마타 오카유 #JP #게이머즈 #수인귀 저를 집에 들여보내 주세요 집에 실례할게요…! 자신의 센터 홀로멘이 #게이머즈을 가지고 있을 때, 상대의 센터 홀로멘과 백 홀로멘 1명에게 특수 대미지 10을 준다. 단, 다운되어도 상대의 라이프는 줄지 않는다. เนโกะมาตะ โอกายุ #JP #เกมเมอร์ส #หูสัตว์ ขอให้ผมเข้าบ้านทีเถอะ ขอรบกวนที่บ้านหน่อยนะ...! เมื่อเซ็นเตอร์โฮโลเมนของคุณมี #เกมเมอร์ส สร้างความเสียหายพิเศษ 10 ให้แก่เซ็นเตอร์โฮโลเมนของฝ่ายตรงข้ามและแบ็กโฮโลเมนของฝ่ายตรงข้าม 1 คน แต่ถึงถูกดาวน์ก็จะไม่ทำให้ไลฟ์ของฝ่ายตรงข้ามลดลง Nekomata Okayu #JP #Gamers #Animal Ears Por favor, déjame entrar a tu casa ¡Voy a molestar en tu casa...! Si tu holomen central tiene #Gamers, inflige 10 de daño especial al holomen central de tu oponente y a 1 de sus holomen de la retaguardia. Sin embargo, aunque queden noqueados, la Vida de tu oponente no disminuye.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('563', 'hBD24-007', 'oshiCharacter', 'P', NULL, 'hPR/hBD24-007_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBD24-007_P.png', NULL, 5, NULL, NULL, '林けゐ', 'ジジ・ムリン', '{"card_sets":["PRカード"],"color_codes":["yellow"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Gigi Murin","oshi_skill":{"effect":"[Once per turn] During this turn, 1 of your yellow holomem gets Arts +20.","name":"YELLOW ENHANCE","timing":"Once per turn"},"sp_oshi_skill":{"effect":"[Once per game] Reveal 1 yellow holomem from your deck and add it to your hand. Then shuffle your deck.","name":"Birthday Gift ~Yellow~","timing":"Once per game"}},"es":{"name":"Gigi Murin","oshi_skill":{"effect":"[Una vez por turno] Durante este turno, las Arts de 1 de tus holomen amarillos +20.","name":"Mejora Amarilla","timing":"Una vez por turno"},"sp_oshi_skill":{"effect":"[Una vez por partida] Revela 1 holomen amarillo de tu mazo y añádelo a tu mano. Luego baraja el mazo.","name":"Regalo de cumpleaños ~Amarillo~","timing":"Una vez por partida"}},"id":{"name":"Gigi Murin","oshi_skill":{"effect":"[Sekali per giliran] Selama giliran ini, Arts dari 1 holomem kuning milikmu +20.","name":"Peningkatan Kuning","timing":"Sekali per giliran"},"sp_oshi_skill":{"effect":"[Sekali per permainan] Ungkapkan 1 holomen kuning dari deckmu, lalu tambahkan ke tanganmu. Kemudian kocok deckmu.","name":"Hadiah Ulang Tahun ～Kuning～","timing":"Sekali per permainan"}},"ja":{"name":"ジジ・ムリン","oshi_skill":{"effect":"[ターンに1回]このターンの間、自分の黄ホロメン1人のアーツ+20。","name":"イエローエンハンス","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]自分のデッキから、黄ホロメン1枚を公開し、手札に加える。そしてデッキをシャッフルする。","name":"Birthday Gift ～Yellow～","timing":"ゲームに1回"}},"ko":{"name":"지지 무린","oshi_skill":{"effect":"[턴에 1번] 이 턴 동안, 자신의 노란색 홀로멘 1명의 아츠 +20.","name":"옐로 인핸스","timing":"턴에 1번"},"sp_oshi_skill":{"effect":"[게임에 1번]자신의 덱에서 노란 홀로멘 1장을 공개하고 패에 넣는다. 그리고 덱을 셔플한다.","name":"Birthday Gift ~Yellow~","timing":"게임에 1번"}},"tc":{"name":"ジジ・ムリン","oshi_skill":{"effect":"[每回合1次]在這個回合中，自己的1位黃色Holo成員的藝術+20。","name":"黃色強化","timing":"每回合1次"},"sp_oshi_skill":{"effect":"[每場對戰1次]從自己的牌庫公開1張黃色holomen，加入手牌。然後將牌庫洗牌。","name":"Birthday Gift ～Yellow～","timing":"每場對戰1次"}},"th":{"name":"จิจิ มุริน","oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเทิร์น] ในระหว่างเทิร์นนี้ อาร์ตของโฮโลเมนสีเหลืองของคุณ 1 คน +20","name":"เสริมพลังสีเหลือง","timing":"ใช้ได้ 1 ครั้งต่อเทิร์น"},"sp_oshi_skill":{"effect":"[ใช้ได้ 1 ครั้งต่อเกม] เปิดเผยโฮโลเมนสีเหลือง 1 ใบจากเด็คของคุณ แล้วนำขึ้นมือ จากนั้นสับเด็ค","name":"Birthday Gift ~Yellow~","timing":"ใช้ได้ 1 ครั้งต่อเกม"}}}}', '{}', '14e6cde36bb8b7aafe7ba94de9d70791d25f03f29493e639a3052122b1d604b8', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
