INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (576, 'hBP03-012', 'hBP03-012 JP 4期生 ベイビー 姫森ルーナ #JP #4期生 #ベイビー 約束なのら！ 一緒に最高のライブにしようね このターンの間、自分のファンが付いているホロメン1人のアーツ+20。 Himemori Luna #JP #4th Gen #Baby It''s a promise, nora! Let''s make this the best live ever together 1 of your holomems with a Fan gets Arts +20 for this turn. 姬森璐娜 #JP #4期生 #嬰兒 約好了的說！ 一起打造最棒的演唱會吧 在這個回合中，自己1位附有粉絲的holomen的藝術+20。 Himemori Luna #JP #Gen 4 #Bayi Janji ya, nora! Ayo jadikan ini live terbaik bersama Selama giliran ini, Arts 1 holomen milikmu yang memiliki Fan +20. 히메모리 루나 #JP #4기생 #베이비 약속이노라! 함께 최고의 라이브로 만들자 이번 턴 동안, 자신의 팬이 붙어 있는 홀로멘 1명의 아츠+20. ฮิเมโมริ ลูนะ #JP #รุ่น 4 #เบบี้ สัญญากันแล้วนะโนระ! มาสร้างไลฟ์ที่ดีที่สุดไปด้วยกันนะ ในเทิร์นนี้ อาร์ตของโฮโลเมน 1 คนของคุณที่มีแฟนติดอยู่ +20 Himemori Luna #JP #4th Gen #Baby ¡Es una promesa, nora! Hagamos juntos el mejor concierto Durante este turno, 1 de tus holomembers que tenga Fan obtiene +20 Arts.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('577', 'hBP03-013', 'character', 'R', 'first', 'hBP03/hBP03-013_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-013_R.png', 110, NULL, 1, '["null"]', 'かんざきひろ', '姫森ルーナ', '{"arts":[{"cost_types":["white"],"damage":20}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["white"],"keyword":{"type":"ギフト","type_code":"gift"},"translations":{"en":{"arts":[{"effect":"You may attach 1 〈Lunaito〉 from your Archive to your 〈Himemori Luna〉.","name":"Moon Galaxy"}],"keyword":{"effect":"[Collab Position only] The 〈Himemori Luna〉 Arts of your Center holomem with your Fans attached get +20.","name":"Going to space together with Nnatan~!"},"name":"Himemori Luna","tags":["#JP","#4th Gen","#Baby"]},"es":{"arts":[{"effect":"Puedes equipar 1 carta 〈Lunaito〉 de tu archivo a tu 〈Himemori Luna〉.","name":"Galaxia lunar"}],"keyword":{"effect":"[Solo posición de colaboración] Los Arts del 〈Himemori Luna〉 de tu holomen del centro que tiene tu Fan unido obtienen +20.","name":"¡Junto a Nnatan, iremos al espacio, noora~!"},"name":"Himemori Luna","tags":["#JP","#4th Gen","#Baby"]},"id":{"arts":[{"effect":"Kamu boleh memasang 1 kartu 〈Lunaito〉 dari Archive-mu pada 〈Himemori Luna〉 milikmu.","name":"Moon Galaxy"}],"keyword":{"effect":"[Hanya Posisi Collab] Arts 〈Himemori Luna〉 dari Center holomen milikmu yang dipasangi Fan +20.","name":"Pergi ke luar angkasa bareng Nnatān, nora~!"},"name":"Himemori Luna","tags":["#JP","#Gen 4","#Bayi"]},"ja":{"arts":[{"effect":"自分のアーカイブの〈ルーナイト〉1枚を自分の〈姫森ルーナ〉に付けられる。","name":"ムーンギャラクシー"}],"keyword":{"effect":"[コラボポジション限定]自分のファンが付いているセンターホロメンの〈姫森ルーナ〉のアーツ+20。","name":"んなたんと一緒に、宇宙に行くのら～！"},"name":"姫森ルーナ","tags":["#JP","#4期生","#ベイビー"]},"ko":{"arts":[{"effect":"자신의 아카이브의 〈루나이토〉 1장을 자신의 〈히메모리 루나〉에 붙일 수 있다.","name":"문 갤럭시"}],"keyword":{"effect":"[콜라보 포지션 한정] 자신의 팬이 붙어 있는 센터 홀로멤의 〈히메모리 루나〉의 아츠+20.","name":"응나탄과 함께 우주에 가는 거야~!"},"name":"히메모리 루나","tags":["#JP","#4기생","#베이비"]},"tc":{"arts":[{"effect":"可將自己存檔區的1張〈Lunaito〉附於自己的〈姬森璐娜〉。","name":"月之銀河"}],"keyword":{"effect":"[僅限合作位置]自己附有粉絲的中心Holomen之〈姬森璐娜〉的藝術+20。","name":"要和露娜炭一起去宇宙喔～！"},"name":"姬森璐娜","tags":["#JP","#4期生","#嬰兒"]},"th":{"arts":[{"effect":"คุณสามารถติด 〈ลูไนโต〉 1 ใบจากอาร์ไคฟ์ของคุณให้กับ 〈ฮิเมโมริ ลูนะ〉 ของคุณได้","name":"มูนกาแล็กซี"}],"keyword":{"effect":"[เฉพาะตำแหน่งโคแลบ] อาร์ตของ 〈ฮิเมโมริ ลูนะ〉 ของเซ็นเตอร์โฮโลเมนที่ติดแฟนของคุณอยู่ +20","name":"ไปอวกาศด้วยกันกับนานะตันโนร้า～!"},"name":"ฮิเมโมริ ลูนะ","tags":["#JP","#รุ่น 4","#เบบี้"]}}}', '{}', '6d32998b9e4bc807a6d8fb201002dbdd8d712f510d8baa2e055dcd45e44d171f', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
