INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (580, 'hBP03-016', 'hBP03-016 JP 5期生 ケモミミ シューター 獅白ぼたん #JP #5期生 #ケモミミ #シューター ららーいおん♪ Shishiro Botan #JP #5th Gen #Animal Ears #Shooter La-la-lion♪ 獅白牡丹 #JP #5期生 #獸耳 #射手 啦啦～獅子♪ Shishiro Botan #JP #Gen 5 #Telinga Hewan #Penembak Raraaion♪ 시시로 보탄 #JP #5기생 #수인귀 #슈터 라라~이온♪ ชิชิโระ โบตัง #JP #รุ่น 5 #หูสัตว์ #ชูตเตอร์ ลาล่าไลอ้อน♪ Shishiro Botan #JP #5th Gen #Animal Ears #Shooter Raraaión♪', '');
