INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (584, 'hBP03-020', 'hBP03-020 薫子 JP 5期生 ケモミミ シューター 獅白ぼたん #JP #5期生 #ケモミミ #シューター ショッピングカートで来た SSSSR 自分のエールデッキの上から1枚を、自分のバックホロメンの〈獅白ぼたん〉に送る。 Shishiro Botan #JP #5th Gen #Animal Ears #Shooter Came in a Shopping Cart SSSSR Send the top card of your Cheer Deck to your Back holomem 〈Shishiro Botan〉. 獅白牡丹 #JP #5期生 #獸耳 #射手 坐購物車來了 SSSSR 將自己應援牌庫頂端1張卡送給自己後排Holomen的〈獅白牡丹〉。 Shishiro Botan #JP #Gen 5 #Telinga Hewan #Penembak Datang Naik Troli Belanja SSSSR Kirim 1 kartu teratas dari Cheer Deck milikmu ke 〈Shishiro Botan〉 milik Back Holomenmu. 시시로 보탄 #JP #5기생 #수인귀 #슈터 쇼핑카트 타고 왔다 SSSSR 자신의 엘 덱 위에서부터 1장을 자신의 백 홀로멤의 〈시시로 보탄〉에게 보낸다. ชิชิโระ โบตัง #JP #รุ่น 5 #หูสัตว์ #ชูตเตอร์ มาด้วยรถเข็นช็อปปิง SSSSR ส่งการ์ดบนสุดของเยลเด็คของคุณ 1 ใบไปยัง 〈ชิชิโระ โบตัง〉 ของแบ็กโฮโลเมนของคุณ Shishiro Botan #JP #5th Gen #Animal Ears #Shooter Vino en carrito de compras SSSSR Envía la carta superior de tu mazo Cheer a tu 〈Shishiro Botan〉 entre tus holomen de atrás.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('585', 'hBP03-021', 'character', 'RR', 'second', 'hBP03/hBP03-021_RR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-021_RR.png', 190, NULL, 2, '["null","null"]', '江田藤', '獅白ぼたん', '{"arts":[{"cost_types":["green","null","null"],"damage":110,"special_targets":["blue"],"special_values":[50]}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["green"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"While your Oshi holomem is 〈Shishiro Botan〉, you may archive 1 Cheer from one of your Back holomem: Deal 40 special damage to the opponent''s Center holomem or Collab holomem.","name":"Godlike Aim"}],"keyword":{"effect":"You may send your Green Cheer from the Archive, 1 at a time, to 1 or 2 of your back holomem with #Shooter.","name":"Shishiro Botan Will Figure Something Out"},"name":"Shishiro Botan","tags":["#JP","#5th Gen","#Animal Ears","#Shooter"]},"es":{"arts":[{"effect":"Cuando tu holomen oshi es 〈Shishiro Botan〉, puedes archivar 1 Cheer de uno de tus holomen de la Retaguardia: inflige 40 de daño especial al holomen del Centro o al holomen de Colaboración de tu oponente.","name":"Puntería divina"}],"keyword":{"effect":"Puedes enviar 1 Green Cheer de tu archivo a cada uno de 1 o 2 holomen de atrás tuyos con #Shooter.","name":"Shishiro Botan se las arreglará"},"name":"Shishiro Botan","tags":["#JP","#5th Gen","#Animal Ears","#Shooter"]},"id":{"arts":[{"effect":"Saat Oshi holomen kamu adalah 〈Shishiro Botan〉, kamu boleh Archive 1 El dari Back holomen kamu: berikan Special Damage 40 kepada Center holomen lawan atau Collab holomen lawan.","name":"Aim Dewa"}],"keyword":{"effect":"Kamu boleh mengirim masing-masing 1 kartu Yell Hijau dari Archive-mu ke 1 sampai 2 Back holomen milikmu yang memiliki #Penembak.","name":"Shishiro Botan yang pasti beresin entah gimana caranya"},"name":"Shishiro Botan","tags":["#JP","#Gen 5","#Telinga Hewan","#Penembak"]},"ja":{"arts":[{"effect":"自分の推しホロメンが〈獅白ぼたん〉の時、自分のバックホロメンのエール1枚をアーカイブできる:相手のセンターホロメンかコラボホロメンに特殊ダメージ40を与える。","name":"神エイム"}],"keyword":{"effect":"自分のアーカイブの緑エール1枚ずつを、自分の#シューターを持つバックホロメン1～2人に送れる。","name":"なんとかしてくれる獅白ぼたん"},"name":"獅白ぼたん","tags":["#JP","#5期生","#ケモミミ","#シューター"]},"ko":{"arts":[{"effect":"자신의 오시 홀로멤이 〈시시로 보탄〉일 때, 자신의 백 홀로멤의 에일 1장을 아카이브할 수 있다: 상대의 센터 홀로멤 또는 콜라보 홀로멤에게 특수 대미지 40을 준다.","name":"신의 에임"}],"keyword":{"effect":"자신의 아카이브의 그린 옐를 1장씩, 자신의 #슈터를 가진 백 홀로멤 1~2명에게 보낼 수 있다.","name":"어떻게든 해주는 시시로 보탄"},"name":"시시로 보탄","tags":["#JP","#5기생","#수인귀","#슈터"]},"tc":{"arts":[{"effect":"當自己的推Holo成員為〈獅白牡丹〉時，可將自己1位後備Holo成員的1張應援存入存檔區：對對手的中心Holo成員或合作Holo成員造成特殊傷害40。","name":"神準瞄準"}],"keyword":{"effect":"可以將自己檔案區的綠色應援逐張送給自己1～2名持有#射手的後衛Holo成員。","name":"總會有辦法的獅白牡丹"},"name":"獅白牡丹","tags":["#JP","#5期生","#獸耳","#射手"]},"th":{"arts":[{"effect":"เมื่อโอชิโฮโลเมนของคุณคือ 〈ชิชิโระ โบตัง〉 คุณสามารถอาร์ไคฟ์เยล 1 ใบของแบ็คโฮโลเมนของคุณได้: สร้างความเสียหายพิเศษ 40 ให้แก่เซ็นเตอร์โฮโลเมนหรือคอลแลบโฮโลเมนของฝ่ายตรงข้าม","name":"เล็งเทพ"}],"keyword":{"effect":"สามารถส่ง เยลสีเขียว จากอาร์ไคฟ์ของตนเองทีละ 1 ใบ ไปยังแบ็กโฮโลเม็ม 1 ถึง 2 คนของตนเองที่มี #ชูตเตอร์","name":"ชิชิโระ โบตัง ที่จะหาทางจัดการให้จนได้"},"name":"ชิชิโระ โบตัง","tags":["#JP","#รุ่น 5","#หูสัตว์","#ชูตเตอร์"]}}}', '{}', '6eb89ac0f6fcecf653e76ceae57e112e655e99afc6db7f9e4820cd14bee3eecf', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
