INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (589, 'hBP03-025', 'hBP03-025 JP 0期生 ベイビー さくらみこ #JP #0期生 #ベイビー にゃっはろ～ Sakura Miko #JP #0th Gen #Baby Nyahallo~ 櫻巫女 #JP #0期生 #嬰兒 喵哈囉～ Sakura Miko #JP #Gen 0 #Bayi Nyahallo～ 사쿠라 미코 #JP #0기생 #베이비 냐하로~ ซากุระ มิโกะ #JP #รุ่น 0 #เบบี้ เนี๊ยะฮาโระ~ Sakura Miko #JP #0th Gen #Baby ¡Nyaharo~!', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('590', 'hBP03-026', 'character', 'U', 'debut', 'hBP03/hBP03-026_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-026_U.png', 80, NULL, 1, '["null"]', 'おるだん', 'さくらみこ', '{"arts":[{"cost_types":["red","null"],"damage":30}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["red"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"name":"Season of Sakura"}],"keyword":{"effect":"You may roll a die once: On 2, 4, or 6, deal 10 special damage to your opponent''s Center holomem. On 3 or 5, draw 1 card from your deck, and deal 10 special damage to your opponent''s Center holomem.","name":"Meeting Up with You"},"name":"Sakura Miko","tags":["#JP","#0th Gen","#Baby"]},"es":{"arts":[{"name":"Temporada de sakura"}],"keyword":{"effect":"Puedes lanzar un dado una vez: si sale 2, 4 o 6, inflige 10 de daño especial al holomember central de tu oponente. Si sale 3 o 5, roba 1 carta de tu mazo e inflige 10 de daño especial al holomember central de tu oponente.","name":"Quedar contigo"},"name":"Sakura Miko","tags":["#JP","#0th Gen","#Baby"]},"id":{"arts":[{"name":"Musim Sakura"}],"keyword":{"effect":"Kamu boleh melempar dadu 1 kali: jika hasilnya 2, 4, atau 6, berikan 10 Special Damage kepada Center holomen lawan. Jika hasilnya 3 atau 5, tarik 1 kartu dari dekmu, lalu berikan 10 Special Damage kepada Center holomen lawan.","name":"Janji bertemu denganmu"},"name":"Sakura Miko","tags":["#JP","#Gen 0","#Bayi"]},"ja":{"arts":[{"name":"さくらの季節"}],"keyword":{"effect":"サイコロを1回振れる:2か4か6の時、相手のセンターホロメンに特殊ダメージ10を与える。3か5の時、自分のデッキを1枚引き、相手のセンターホロメンに特殊ダメージ10を与える。","name":"君と待ち合わせ"},"name":"さくらみこ","tags":["#JP","#0期生","#ベイビー"]},"ko":{"arts":[{"name":"벚꽃의 계절"}],"keyword":{"effect":"주사위를 1번 굴릴 수 있다: 2, 4, 6이 나오면, 상대의 센터 홀로멘에게 특수 대미지 10을 준다. 3, 5가 나오면, 자신의 덱을 1장 뽑고, 상대의 센터 홀로멘에게 특수 대미지 10을 준다.","name":"너와의 약속 장소"},"name":"사쿠라 미코","tags":["#JP","#0기생","#베이비"]},"tc":{"arts":[{"name":"櫻花的季節"}],"keyword":{"effect":"可以擲1次骰子：擲出2、4或6時，對對手的Center holomen造成10點特殊傷害。擲出3或5時，自己抽1張牌，並對對手的Center holomen造成10點特殊傷害。","name":"和你碰面"},"name":"櫻巫女","tags":["#JP","#0期生","#嬰兒"]},"th":{"arts":[{"name":"ฤดูแห่งซากุระ"}],"keyword":{"effect":"คุณสามารถทอยลูกเต๋า 1 ครั้ง: ถ้าออก 2, 4 หรือ 6 ให้สร้างดาเมจพิเศษ 10 แก่เซ็นเตอร์โฮโลเมนของคู่ต่อสู้ ถ้าออก 3 หรือ 5 ให้จั่ว 1 ใบจากเด็คของคุณ แล้วสร้างดาเมจพิเศษ 10 แก่เซ็นเตอร์โฮโลเมนของคู่ต่อสู้","name":"นัดเจอกับเธอ"},"name":"ซากุระ มิโกะ","tags":["#JP","#รุ่น 0","#เบบี้"]}}}', '{}', '614a0dee01003ff73a9dfc810d9bf450897dc37fe0671b667d82ffcd99a2b089', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
