INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('592', 'hBP03-028', 'character', 'U', 'first', 'hBP03/hBP03-028_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-028_U.png', 130, NULL, NULL, NULL, NULL, 'さくらみこ', '{"arts":[{"cost_types":["null"],"damage":30},{"cost_types":["red","null"],"damage":50}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["red"],"translations":{"en":{"arts":[{"name":"I’m Counting on Your Support"},{"effect":"You may roll a die once: if it is 2, 4, or 6, deal 20 special damage to the opponent''s Center holomem. If it is 3 or 5, deal 20 special damage to the opponent''s Center holomem and Collab holomem.","name":"Mikopi! (｀・ω・´)🌸"}],"name":"Sakura Miko","tags":["#JP","#0th Gen","#Baby"]},"es":{"arts":[{"name":"Cuento con tu apoyo"},{"effect":"Puedes lanzar 1 dado: si sale 2, 4 o 6, inflige 20 de daño especial al holomen del Centro de tu oponente. Si sale 3 o 5, inflige 20 de daño especial al holomen del Centro y al holomen de Colaboración de tu oponente.","name":"¡Mikopi! (｀・ω・´)🌸"}],"name":"Sakura Miko","tags":["#JP","#0th Gen","#Baby"]},"id":{"arts":[{"name":"Aku andalkan dukunganmu"},{"effect":"Kamu boleh melempar dadu 1 kali: jika hasilnya 2, 4, atau 6, berikan 20 damage spesial kepada holomen Center lawan. Jika hasilnya 3 atau 5, berikan 20 damage spesial kepada holomen Center lawan dan holomen Collab lawan.","name":"Mikopi! (｀・ω・´)🌸"}],"name":"Sakura Miko","tags":["#JP","#Gen 0","#Bayi"]},"ja":{"arts":[{"name":"応援頼んだぞ"},{"effect":"サイコロを1回振れる:2か4か6の時、相手のセンターホロメンに特殊ダメージ20を与える。3か5の時、相手のセンターホロメンとコラボホロメンに特殊ダメージ20を与える。","name":"みこぴー！(｀・ω・´)🌸"}],"name":"さくらみこ","tags":["#JP","#0期生","#ベイビー"]},"ko":{"arts":[{"name":"응원 부탁한다"},{"effect":"주사위를 1회 굴릴 수 있다: 2, 4, 6이라면, 상대의 센터 홀로멘에게 특수 대미지 20을 준다. 3, 5라면, 상대의 센터 홀로멘과 콜라보 홀로멘에게 특수 대미지 20을 준다.","name":"미코삐! (｀・ω・´)🌸"}],"name":"사쿠라 미코","tags":["#JP","#0기생","#베이비"]},"tc":{"arts":[{"name":"應援就拜託你了"},{"effect":"可以擲1次骰子：若為2、4或6，對對手的中心Holomen造成特殊傷害20。若為3或5，對對手的中心Holomen與合作Holomen各造成特殊傷害20。","name":"巫女P！(｀・ω・´)🌸"}],"name":"櫻巫女","tags":["#JP","#0期生","#嬰兒"]},"th":{"arts":[{"name":"ฝากแรงเชียร์ด้วยล่ะ"},{"effect":"คุณสามารถทอยลูกเต๋า 1 ครั้งได้: ถ้าออก 2 หรือ 4 หรือ 6 ให้ความเสียหายพิเศษ 20 แก่โฮโลเมมตำแหน่งเซ็นเตอร์ของฝ่ายตรงข้าม ถ้าออก 3 หรือ 5 ให้ความเสียหายพิเศษ 20 แก่โฮโลเมมตำแหน่งเซ็นเตอร์และโฮโลเมมตำแหน่งคอลแลบของฝ่ายตรงข้าม","name":"มิโคะปี! (｀・ω・´)🌸"}],"name":"ซากุระ มิโกะ","tags":["#JP","#รุ่น 0","#เบบี้"]}}}', '{}', '959c6201b0bf8c7f430b51cd770ffed96817c451991f93595f84435ae9e5024b', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
