INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (593, 'hBP03-029', 'hBP03-029 おるだん JP 0期生 ベイビー さくらみこ #JP #0期生 #ベイビー 35Pと記念写真 このホロメンに〈35P〉が付いている時、このアーツ+30。 にぇ 自分のデッキから、〈35P〉1枚を公開し、手札に加える。そしてデッキをシャッフルする。 Sakura Miko #JP #0th Gen #Baby Commemorative Photo with 35P If this holomem has 〈35P〉 attached to it, this Art gets +30. Nye Reveal 1 〈35P〉 from your deck, put it into your hand, then shuffle your deck. 櫻巫女 #JP #0期生 #嬰兒 與35P的紀念合照 當此Holomen附有〈35P〉時，此藝術+30。 捏 從自己的牌庫公開1張〈35P〉，加入手牌。然後將牌庫洗牌。 Sakura Miko #JP #Gen 0 #Bayi Foto Kenangan bersama 35P Saat 〈35P〉 terpasang pada holomen ini, Arts ini +30. Nye Ungkapkan 1 kartu 〈35P〉 dari dekmu, tambahkan ke tanganmu. Lalu, kocok dekmu. 사쿠라 미코 #JP #0기생 #베이비 35P와 기념사진 이 홀로멘에 〈35P〉가 붙어 있으면, 이 아츠 +30. 니에 자신의 덱에서 〈35P〉 1장을 공개해 패에 넣는다. 그리고 덱을 셔플한다. ซากุระ มิโกะ #JP #รุ่น 0 #เบบี้ ถ่ายรูปที่ระลึกกับ 35P ขณะที่โฮโลเมมนี้ติด 〈35P〉 อยู่ ศิลปะนี้ +30 เนี่ย เปิดเผย 〈35P〉 1 ใบจากเด็คของคุณ แล้วนำขึ้นมือ จากนั้นสับเด็ค Sakura Miko #JP #0th Gen #Baby Foto conmemorativa con 35P Mientras este holomen tenga 〈35P〉, este Arte +30. Nye Revela 1 〈35P〉 de tu mazo, ponla en tu mano y luego baraja tu mazo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('594', 'hBP03-030', 'character', 'RR', 'second', 'hBP03/hBP03-030_RR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-030_RR.png', 200, NULL, 1, '["null"]', '黒兎', 'さくらみこ', '{"arts":[{"cost_types":["red","null","null"],"damage":120,"is_plus":true,"special_targets":["green"],"special_values":[50]}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["red"],"keyword":{"type":"ギフト","type_code":"gift"},"translations":{"en":{"arts":[{"effect":"This Art gets +20 for each 〈35P〉 attached to this holomem.","name":"Elite Miko"}],"keyword":{"effect":"[Center Position only] [Once per turn] During your Main Step, if this holomem has 〈35P〉 attached, you may roll a die once: If the result is 3 or 5, this holomem gets Arts +50 for this turn.","name":"Elite Gamble"},"name":"Sakura Miko","tags":["#JP","#0th Gen","#Baby"]},"es":{"arts":[{"effect":"Por cada 1 carta de 〈35P〉 unida a este holomen, este Arte +20.","name":"Miko de élite"}],"keyword":{"effect":"[Solo posición central][Una vez por turno] Durante tu Main Step, si este holomen tiene 〈35P〉, puedes lanzar un dado 1 vez: si sale 3 o 5, durante este turno las Arts de este holomen +50.","name":"Apuesta élite"},"name":"Sakura Miko","tags":["#JP","#0th Gen","#Baby"]},"id":{"arts":[{"effect":"Untuk setiap 1 kartu 〈35P〉 yang terpasang pada holomen ini, Arts ini +20.","name":"Miko Elit"}],"keyword":{"effect":"[Hanya Posisi Center][Sekali per giliran] Pada Main Step milikmu, saat holomen ini memiliki 〈35P〉, kamu boleh melempar dadu 1 kali: jika hasilnya 3 atau 5, selama giliran ini, Arts holomen ini +50.","name":"Judi Elite"},"name":"Sakura Miko","tags":["#JP","#Gen 0","#Bayi"]},"ja":{"arts":[{"effect":"このホロメンに付いている〈35P〉1枚につき、このアーツ+20。","name":"エリート巫女"}],"keyword":{"effect":"[センターポジション限定][ターンに1回]自分のメインステップで、このホロメンに〈35P〉が付いている時、サイコロを1回振れる:3か5の時、このターンの間、このホロメンのアーツ+50。","name":"エリートギャンブル"},"name":"さくらみこ","tags":["#JP","#0期生","#ベイビー"]},"ko":{"arts":[{"effect":"이 홀로멘에 붙어 있는 〈35P〉 1장당, 이 아츠 +20.","name":"엘리트 무녀"}],"keyword":{"effect":"[센터 포지션 한정][턴에 1번]자신의 메인 스텝에, 이 홀로멘에 〈35P〉가 붙어 있을 때, 주사위를 1번 굴릴 수 있다:3 또는 5이면, 이번 턴 동안, 이 홀로멘의 아츠+50.","name":"엘리트 갬블"},"name":"사쿠라 미코","tags":["#JP","#0기생","#베이비"]},"tc":{"arts":[{"effect":"此Holomen每附有1張〈35P〉，此藝術+20。","name":"菁英巫女"}],"keyword":{"effect":"[僅限中心位置][每回合1次]在自己的主要步驟中，當這名Holomen附有〈35P〉時，可擲1次骰子：若為3或5，則本回合中，這名Holomen的藝術+50。","name":"菁英賭博"},"name":"櫻巫女","tags":["#JP","#0期生","#嬰兒"]},"th":{"arts":[{"effect":"ต่อ 〈35P〉 1 ใบที่ติดอยู่กับโฮโลเมมนี้ ศิลปะนี้ +20","name":"มิโกะระดับอีลิท"}],"keyword":{"effect":"[เฉพาะตำแหน่งเซ็นเตอร์][เทิร์นละ 1 ครั้ง]ในเมนสเต็ปของคุณ เมื่อโฮโลเมนนี้มี 〈35P〉 ติดอยู่ คุณสามารถทอยลูกเต๋า 1 ครั้ง: ถ้าออก 3 หรือ 5 ในเทิร์นนี้ อาร์ตของโฮโลเมนนี้ +50","name":"การพนันฉบับเยลีต"},"name":"ซากุระ มิโกะ","tags":["#JP","#รุ่น 0","#เบบี้"]}}}', '{}', 'b8759bbeccb538f5c971710e806eb69d55def16102a96be43009e6d0da031852', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
