INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (595, 'hBP03-031', 'hBP03-031 JP 1期生 料理 赤井はあと #JP #1期生 #料理 おはるーじゅ！ Akai Haato #JP #1st Gen #Cooking Oharouge! 赤井心 #JP #1期生 #料理 Oharouge！ Akai Haato #JP #Gen 1 #Masakan Oharouge! 아카이 하토 #JP #1기생 #요리 오하루주! อากาย ฮาโต #JP #รุ่น 1 #ทำอาหาร โอฮารูจ! Akai Haato #JP #1st Gen #Cooking ¡Oharouge!', '');
