INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (596, 'hBP03-032', 'hBP03-032 はる雪 JP 1期生 料理 赤井はあと #JP #1期生 #料理 おつるーじゅ！ Akai Haato #JP #1st Gen #Cooking Otsurouge! 赤井心 #JP #1期生 #料理 Otsurouge！ Akai Haato #JP #Gen 1 #Masakan Otsurouge! 아카이 하토 #JP #1기생 #요리 오츠루주! อากาย ฮาโต #JP #รุ่น 1 #ทำอาหาร โอตสึรูจ! Akai Haato #JP #1st Gen #Cooking ¡Otsurouge!', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('597', 'hBP03-033', 'character', 'U', 'first', 'hBP03/hBP03-033_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-033_U.png', 120, NULL, 1, '["null"]', NULL, '赤井はあと', '{"arts":[{"cost_types":["null"],"damage":40}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["red"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"Haachamatchama~!"}],"keyword":{"effect":"Deal 10 special damage to your opponent''s Center holomem. If that opponent''s Center holomem has a Tool attached, deal 30 special damage to your opponent''s Center holomem instead.","name":"I''m going all outttt!"},"name":"Akai Haato","tags":["#JP","#1st Gen","#Cooking"]},"es":{"arts":[{"name":"¡Haachamatchama~!"}],"keyword":{"effect":"Inflige 10 de daño especial al holomen central del oponente. Si ese holomen central del oponente tiene una Tool adjunta, en su lugar, inflige 30 de daño especial al holomen central del oponente.","name":"¡Vamos con todooo!"},"name":"Akai Haato","tags":["#JP","#1st Gen","#Cooking"]},"id":{"arts":[{"name":"Haachamatchama～!"}],"keyword":{"effect":"Berikan 10 Special Damage kepada Center Holomen lawan. Jika Tool terpasang pada Center Holomen lawan itu, sebagai gantinya, berikan 30 Special Damage kepada Center Holomen lawan.","name":"Ayo habis-habisan goooo!"},"name":"Akai Haato","tags":["#JP","#Gen 1","#Masakan"]},"ja":{"arts":[{"name":"はあちゃまっちゃま～！"}],"keyword":{"effect":"相手のセンターホロメンに特殊ダメージ10を与える。その相手のセンターホロメンにツールが付いている時、かわりに、相手のセンターホロメンに特殊ダメージ30を与える。","name":"全力でいくぞおおお！"},"name":"赤井はあと","tags":["#JP","#1期生","#料理"]},"ko":{"arts":[{"name":"하아차맛차마~!"}],"keyword":{"effect":"상대의 센터 홀로멘에게 특수 대미지 10을 준다. 그 상대의 센터 홀로멘에 툴이 붙어 있을 때, 대신 상대의 센터 홀로멘에게 특수 대미지 30을 준다.","name":"전력으로 간다아아아!"},"name":"아카이 하토","tags":["#JP","#1기생","#요리"]},"tc":{"arts":[{"name":"哈洽瑪洽瑪～！"}],"keyword":{"effect":"對對手的中心holomen造成10點特殊傷害。當該對手的中心holomen附有工具時，則改為對對手的中心holomen造成30點特殊傷害。","name":"全力上啦啊啊啊！"},"name":"赤井心","tags":["#JP","#1期生","#料理"]},"th":{"arts":[{"name":"ฮาจามะจจามะ~!"}],"keyword":{"effect":"มอบแดเมจพิเศษ 10 ให้แก่เซ็นเตอร์โฮโลเมนของคู่ต่อสู้ ถ้าเซ็นเตอร์โฮโลเมนนั้นติด Tool อยู่ ให้มอบแดเมจพิเศษ 30 ให้แก่เซ็นเตอร์โฮโลเมนของคู่ต่อสู้แทน","name":"จะลุยสุดกำลังเลยยยย!"},"name":"อากาย ฮาโต","tags":["#JP","#รุ่น 1","#ทำอาหาร"]}}}', '{}', '72f5877082975f5f29a1b23a6ca64534342c496a573681d7422cb6ac730e5df0', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
