INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (599, 'hBP03-035', 'hBP03-035 かかげ JP 秘密結社holoX トリ お酒 鷹嶺ルイ #JP #秘密結社holoX #トリ #お酒 challenger 自分の推しホロメンが〈鷹嶺ルイ〉の時、自分の手札2枚をアーカイブできる:自分のデッキを3枚引く。 Takane Lui #JP #Secret Society holoX #Bird #Alcohol challenger While your oshi holomem is 〈Takane Lui〉, you may archive 2 cards from your hand: draw 3 cards. 鷹嶺露依 #JP #秘密結社holoX #小鳥 #酒 挑戰者 當自己的推Holomen為〈鷹嶺露依〉時，可以將自己的2張手牌存檔：抽3張自己的牌庫。 Takane Lui #JP #Organisasi Rahasia holoX #Burung #Alkohol challenger Saat oshi holomen milikmu adalah 〈Takane Lui〉, kamu boleh mengarsipkan 2 kartu dari tanganmu: ambil 3 kartu dari dekmu. 타카네 루이 #JP #비밀결사 holoX #새 #술 challenger 자신의 오시 홀로멘이 〈타카네 루이〉일 때, 자신의 패 2장을 아카이브할 수 있다: 자신의 덱을 3장 뽑는다. ทาคาเนะ รุย #JP #องค์กรลับ holoX #นก #แอลกอฮอล์ ผู้ท้าชิง ขณะที่โอชิโฮโลเมมของคุณคือ 〈ทาคาเนะ รุย〉 คุณสามารถอาร์ไคฟ์การ์ดในมือของคุณ 2 ใบได้: จั่วเด็คของคุณ 3 ใบ Takane Lui #JP #Secret Society holoX #Bird #Alcohol challenger Mientras tu oshi holomen sea 〈Takane Lui〉, puedes archivar 2 cartas de tu mano: roba 3 cartas de tu mazo.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('600', 'hBP03-036', 'character', 'R', 'first', 'hBP03/hBP03-036_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-036_R.png', 140, NULL, 1, '["null"]', 'huke', '小鳥遊キアラ', '{"arts":[{"cost_types":["red","null"],"damage":50}],"card_sets":["ブースターパック「エリートスパーク」","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["red"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"Wings of Steel"}],"keyword":{"effect":"Reveal 1 to 4 〈Takanashi Kiara〉 from your deck, and you may Archive them. Then shuffle your deck.","name":"Happy Time"},"name":"Takanashi Kiara","tags":["#EN","#Myth","#Bird"]},"es":{"arts":[{"name":"Alas de acero"}],"keyword":{"effect":"Puedes revelar de 1 a 4 cartas 〈Takanashi Kiara〉 de tu mazo y Archivarlas. Después, baraja el mazo.","name":"Happy Time"},"name":"Takanashi Kiara","tags":["#EN","#Myth","#Bird"]},"id":{"arts":[{"name":"Sayap Baja"}],"keyword":{"effect":"Dari Dek milikmu, ungkapkan 1 sampai 4 kartu 〈Takanashi Kiara〉, lalu kamu boleh mengarsipkannya. Lalu, kocok Dek.","name":"Waktu Bahagia"},"name":"Takanashi Kiara","tags":["#EN","#Myth","#Burung"]},"ja":{"arts":[{"name":"鋼の翼"}],"keyword":{"effect":"自分のデッキから、〈小鳥遊キアラ〉1～4枚を公開し、アーカイブできる。そしてデッキをシャッフルする。","name":"ハッピータイム"},"name":"小鳥遊キアラ","tags":["#EN","#Myth","#トリ"]},"ko":{"arts":[{"name":"강철의 날개"}],"keyword":{"effect":"자신의 덱에서, 〈타카나시 키아라〉 1~4장을 공개하고 아카이브할 수 있다. 그리고 덱을 셔플한다.","name":"해피 타임"},"name":"타카나시 키아라","tags":["#EN","#Myth","#새"]},"tc":{"arts":[{"name":"鋼鐵之翼"}],"keyword":{"effect":"從自己的牌庫公開1～4張〈小鳥遊琪亞拉〉，可以將其歸檔。然後洗牌庫。","name":"Happy Time"},"name":"小鳥遊琪亞拉","tags":["#EN","#Myth","#小鳥"]},"th":{"arts":[{"name":"ปีกเหล็กกล้า"}],"keyword":{"effect":"เปิดเผย 〈ทาคานาชิ คิอาระ〉 1 ถึง 4 ใบจากเด็คของคุณ และสามารถอาร์ไคฟ์การ์ดเหล่านั้นได้ แล้วสับเด็ค","name":"ช่วงเวลาแห่งความสุข"},"name":"ทาคานาชิ คิอาระ","tags":["#EN","#Myth","#นก"]}}}', '{}', 'f0f9f74543ced1926b07cd100c2c32b98a0f4b7b6c7178b0df3518eda8fbbb30', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
