INSERT INTO card_tags (tag, card_id) VALUES ('ケモミミ', '601');
INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (601, 'hBP03-037', 'hBP03-037 EN Advent ケモミミ モココ・アビスガード #EN #Advent #ケモミミ フワワじゃないよ、モココだよ このアーツは、自分のセンターホロメンが〈フワワ・アビスガード〉の時、エール1枚を必要とせずに使える。 Mococo Abyssgard #EN #Advent #Animal Ears Not Fuwawa, I''m Mococo! This Art can be used without requiring 1 Cheer if your Center holomem is 〈Fuwawa Abyssgard〉. Mococo Abyssguard #EN #Advent #獸耳 不是Fuwawa喔，是Mococo喔 當自己的中心Holo成員為〈Fuwawa Abyssguard〉時，此藝術可少1張應援需求來使用。 Mococo Abyssgard #EN #Advent #Telinga Hewan Bukan Fuwawa, ini Mococo Arts ini dapat digunakan tanpa memerlukan 1 El saat Center holomen kamu adalah 〈Fuwawa Abyssgard〉. 모코코 어비스가드 #EN #Advent #수인귀 후와와 아니야, 모코코야 이 아츠는, 자신의 센터 홀로멤이 〈후와와 어비스가드〉일 때, 에일 1장 없이 사용할 수 있다. โมโคโคะ อะบิสการ์ด #EN #Advent #หูสัตว์ ไม่ใช่ ฟุวาวะ นะ แต่เป็น โมโคโคะ ต่างหาก อาร์ตนี้สามารถใช้ได้โดยไม่ต้องใช้เยล 1 ใบ เมื่อเซ็นเตอร์โฮโลเมนของคุณเป็น 〈ฟุวาวา อะบิสการ์ด〉 Mococo Abyssgard #EN #Advent #Animal Ears No soy Fuwawa, soy Mococo Este Arte puede usarse sin requerir 1 Cheer cuando tu holomen del Centro es 〈Fuwawa Abyssgard〉.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('602', 'hBP03-038', 'character', 'C', 'first', 'hBP03/hBP03-038_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-038_C.png', 130, NULL, NULL, NULL, '蒼樹うめ', 'モココ・アビスガード', '{"arts":[{"cost_types":["null"],"damage":30}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["red"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"Donut Cooking with Mococo"}],"keyword":{"effect":"When this holomem Blooms from Debut, reveal 1 1st holomem that is 〈Fuwawa Abyssgard〉 from your deck and add it to your hand. Then shuffle your deck.","name":"It''s Playtime!"},"name":"Mococo Abyssgard","tags":["#EN","#Advent","#Animal Ears"]},"es":{"arts":[{"name":"Cocinando dónuts con Mococo"}],"keyword":{"effect":"Cuando hace Bloom desde Debut, revela 1 〈Fuwawa Abyssgard〉 1st holomember de tu mazo y añádelo a tu mano. Después, baraja tu mazo.","name":"¡Es hora de jugar!"},"name":"Mococo Abyssgard","tags":["#EN","#Advent","#Animal Ears"]},"id":{"arts":[{"name":"Masak Donat bersama Mococo"}],"keyword":{"effect":"Saat melakukan Bloom dari Debut, buka 1 kartu 1st holomen 〈Fuwawa Abyssgard〉 dari dekmu, tambahkan ke tanganmu. Setelah itu, kocok dekmu.","name":"Saatnya bermain!"},"name":"Mococo Abyssgard","tags":["#EN","#Advent","#Telinga Hewan"]},"ja":{"arts":[{"name":"モココとドーナツクッキング"}],"keyword":{"effect":"DebutからBloomした時、自分のデッキから、1stホロメンの〈フワワ・アビスガード〉1枚を公開し、手札に加える。そしてデッキをシャッフルする。","name":"遊びの時間だー！"},"name":"モココ・アビスガード","tags":["#EN","#Advent","#ケモミミ"]},"ko":{"arts":[{"name":"모코코와 도넛 쿠킹"}],"keyword":{"effect":"Debut에서 Bloom했을 때, 자신의 덱에서 1st 홀로멘인 〈후와와 어비스가드〉 1장을 공개하고, 패에 넣는다. 그리고 덱을 셔플한다.","name":"놀 시간이다~!"},"name":"모코코 어비스가드","tags":["#EN","#Advent","#수인귀"]},"tc":{"arts":[{"name":"和Mococo一起甜甜圈烘焙"}],"keyword":{"effect":"從Debut Bloom時，從自己的牌庫公開1張1st holomen的〈Fuwawa Abyssguard〉，加入手牌。然後將牌庫洗牌。","name":"玩樂時間到啦—！"},"name":"Mococo Abyssguard","tags":["#EN","#Advent","#獸耳"]},"th":{"arts":[{"name":"โมโคโคะ กับการทำโดนัท"}],"keyword":{"effect":"เมื่อ Bloom จาก Debut ให้อวด 1stโฮโลเมน 〈ฟุวาวา อะบิสการ์ด〉 1 ใบจากเด็คของคุณ แล้วนำเข้ามือ จากนั้นสับเด็ค","name":"ถึงเวลาเล่นแล้ว!"},"name":"โมโคโคะ อะบิสการ์ด","tags":["#EN","#Advent","#หูสัตว์"]}}}', '{}', '4a375329a6ca8c29330b680477bb7acc7e610cfb9c0f617c4c4cfd9f5a90cedb', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
