INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (605, 'hBP03-041', 'hBP03-041 茶椿 EN Advent ケモミミ フワワ・アビスガード #EN #Advent #ケモミミ 魔界乃番犬のまとめ役 ふわふわしてる方 Fuwawa Abyssgard #EN #Advent #Animal Ears The Hound of Makai''s Organizer The Fluffy One Fuwawa Abyssguard #EN #Advent #獸耳 魔界番犬的統籌者 比較軟綿綿的那位 Fuwawa Abyssgard #EN #Advent #Telinga Hewan Si pengatur barisan Anjing Penjaga Dunia Iblis Yang satunya fluffy 후와와 어비스가드 #EN #Advent #수인귀 마계의 번견 정리 담당 푹신푹신한 쪽 ฟุวาวา อะบิสการ์ด #EN #Advent #หูสัตว์ หัวหน้าทีมแห่งสุนัขเฝ้าประตูนรก คนที่ฟูฟ่องกว่า Fuwawa Abyssgard #EN #Advent #Animal Ears La que pone orden entre los perros guardianes del Makai La más esponjosita', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('606', 'hBP03-042', 'character', 'U', 'first', 'hBP03/hBP03-042_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-042_U.png', 140, NULL, 1, '["null"]', 'みわべさくら', 'フワワ・アビスガード', '{"arts":[{"cost_types":["null","null"],"damage":50}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["blue"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"A Walk in the Woods with Fuwawa"}],"keyword":{"effect":"If you have 〈Mococo Abyssgard〉 on your Stage, deal 20 special damage to your opponent''s Center holomem or 1 of their Back holomems. Your opponent does not lose Life even if it is Downed.","name":"Fuwa Flowers, Flowing Waters"},"name":"Fuwawa Abyssgard","tags":["#EN","#Advent","#Animal Ears"]},"es":{"arts":[{"name":"Paseo por el bosque con Fuwawa"}],"keyword":{"effect":"Si tienes 〈Mococo Abyssgard〉 en tu escenario, inflige 20 de daño especial al holomem central o a 1 holomem de la retaguardia de tu oponente. Sin embargo, aunque sea derribado, la vida de tu oponente no disminuye.","name":"Flores suaves y agua que fluye"},"name":"Fuwawa Abyssgard","tags":["#EN","#Advent","#Animal Ears"]},"id":{"arts":[{"name":"Jalan-jalan di Hutan bersama Fuwawa"}],"keyword":{"effect":"Saat ada 〈Mococo Abyssgard〉 di Stage milikmu, berikan 20 Damage Khusus kepada Center holomem lawan atau 1 Back holomem lawan. Namun, meskipun Knock Out, Life lawan tidak berkurang.","name":"Aliran bunga dan air Fuwa"},"name":"Fuwawa Abyssgard","tags":["#EN","#Advent","#Telinga Hewan"]},"ja":{"arts":[{"name":"フワワと森のお散歩"}],"keyword":{"effect":"自分のステージに〈モココ・アビスガード〉がいる時、相手のセンターホロメンかバックホロメン1人に特殊ダメージ20を与える。ただし、ダウンしても相手のライフは減らない。","name":"フワ花流水"},"name":"フワワ・アビスガード","tags":["#EN","#Advent","#ケモミミ"]},"ko":{"arts":[{"name":"후와와와 숲속 산책"}],"keyword":{"effect":"자신의 스테이지에 〈모코코 어비스가드〉가 있을 때, 상대의 센터 홀로멤 또는 백 홀로멤 1명에게 특수 대미지 20을 준다. 단, 다운되어도 상대의 라이프는 줄지 않는다.","name":"부와 화류수"},"name":"후와와 어비스가드","tags":["#EN","#Advent","#수인귀"]},"tc":{"arts":[{"name":"與Fuwawa在森林散步"}],"keyword":{"effect":"當自己的舞台上有〈Mococo Abyssguard〉時，對對手的Center Holo成員或1位Back Holo成員造成特殊傷害20。不過，即使倒下，對手的生命值也不會減少。","name":"輕飄花流水"},"name":"Fuwawa Abyssguard","tags":["#EN","#Advent","#獸耳"]},"th":{"arts":[{"name":"เดินเล่นในป่ากับ ฟุวาวะ"}],"keyword":{"effect":"เมื่อมี 〈โมโคโคะ อะบิสการ์ด〉 บนสเตจของคุณ ให้สร้างดาเมจพิเศษ 20 แก่เซ็นเตอร์โฮโลเมนหรือแบ็กโฮโลเมนของฝ่ายตรงข้าม 1 คน แต่ถึงจะดาวน์ ฝ่ายตรงข้ามก็จะไม่เสียไลฟ์","name":"บุปผาพริ้วสายน้ำไหล"},"name":"ฟุวาวา อะบิสการ์ด","tags":["#EN","#Advent","#หูสัตว์"]}}}', '{}', 'c9d5e79cf985e5f1ca646e5491916f2fea0ac767b693f366e4305531f28574ef', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
