INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (611, 'hBP03-047', 'hBP03-047 むっしゅ DEV_IS ReGLOSS 絵 火威青 #DEV_IS #ReGLOSS #絵 アフタヌーンティーデートのその後に… Kasei #DEV_IS #ReGLOSS #Art After the Afternoon Tea Date... 火威青 #DEV_IS #ReGLOSS #繪畫 午後茶約會之後… Kasei #DEV_IS #ReGLOSS #Seni Setelah kencan afternoon tea… 카세이 #DEV_IS #ReGLOSS #그림 애프터눈 티 데이트 그 후에… คาเซย #DEV_IS #ReGLOSS #ศิลปะ หลังเดตจิบน้ำชายามบ่าย... Kasei #DEV_IS #ReGLOSS #Art Y después de la cita de té de la tarde...', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('612', 'hBP03-048', 'character', 'U', 'first', 'hBP03/hBP03-048_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-048_U.png', 130, NULL, 1, '["null"]', NULL, '火威青', '{"arts":[{"cost_types":["null"],"damage":30},{"cost_types":["null","null"],"damage":40}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["blue"],"translations":{"en":{"arts":[{"name":"I''m Cool, Right?"},{"effect":"You may move 1 Cheer attached to this holomem to your Back holomem with #ReGLOSS.","name":"ReGLOSS''s Boyish Representative"}],"name":"Kasei","tags":["#DEV_IS","#ReGLOSS","#Art"]},"es":{"arts":[{"name":"¿A que estoy genial?"},{"effect":"Puedes mover 1 Cheer de este holomen a un holomen de Reserva tuyo que tenga #ReGLOSS.","name":"La parte más tomboy de ReGLOSS"}],"name":"Kasei","tags":["#DEV_IS","#ReGLOSS","#Art"]},"id":{"arts":[{"name":"Aku keren, kan?"},{"effect":"Kamu boleh memindahkan 1 Cheer dari holomen ini ke Back holomen milikmu yang memiliki #ReGLOSS.","name":"Jagoan boyish ReGLOSS"}],"name":"Kasei","tags":["#DEV_IS","#ReGLOSS","#Seni"]},"ja":{"arts":[{"name":"僕、カッコいいでしょ？"},{"effect":"このホロメンのエール1枚を、自分の#ReGLOSSを持つバックホロメンに付け替えられる。","name":"ReGLOSSのボーイッシュ担当"}],"name":"火威青","tags":["#DEV_IS","#ReGLOSS","#絵"]},"ko":{"arts":[{"name":"나, 멋있지?"},{"effect":"이 홀로멘의 에일 1장을 자신의 #ReGLOSS를 가진 백 홀로멘으로 갈아붙일 수 있다.","name":"ReGLOSS의 보이시 담당"}],"name":"카세이","tags":["#DEV_IS","#ReGLOSS","#그림"]},"tc":{"arts":[{"name":"我很帥吧？"},{"effect":"可將這位Holo成員的1張應援改附於自己持有#ReGLOSS的後台Holo成員。","name":"ReGLOSS的男孩子氣擔當"}],"name":"火威青","tags":["#DEV_IS","#ReGLOSS","#繪畫"]},"th":{"arts":[{"name":"ผมเท่ใช่ไหมล่ะ?"},{"effect":"คุณสามารถย้ายเอิล 1 ใบของโฮโลเมนนี้ไปติดกับแบ็กโฮโลเมนของคุณที่มี #ReGLOSS ได้","name":"สายบอยอิชของ ReGLOSS"}],"name":"คาเซย","tags":["#DEV_IS","#ReGLOSS","#ศิลปะ"]}}}', '{}', '72fd1be8068d594c7b8756c9b7a483b709b94efef3356c6a3d68737ff5b5a236', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
