INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (612, 'hBP03-048', 'hBP03-048 DEV_IS ReGLOSS 絵 火威青 #DEV_IS #ReGLOSS #絵 僕、カッコいいでしょ？ ReGLOSSのボーイッシュ担当 このホロメンのエール1枚を、自分の#ReGLOSSを持つバックホロメンに付け替えられる。 Kasei #DEV_IS #ReGLOSS #Art I''m Cool, Right? ReGLOSS''s Boyish Representative You may move 1 Cheer attached to this holomem to your Back holomem with #ReGLOSS. 火威青 #DEV_IS #ReGLOSS #繪畫 我很帥吧？ ReGLOSS的男孩子氣擔當 可將這位Holo成員的1張應援改附於自己持有#ReGLOSS的後台Holo成員。 Kasei #DEV_IS #ReGLOSS #Seni Aku keren, kan? Jagoan boyish ReGLOSS Kamu boleh memindahkan 1 Cheer dari holomen ini ke Back holomen milikmu yang memiliki #ReGLOSS. 카세이 #DEV_IS #ReGLOSS #그림 나, 멋있지? ReGLOSS의 보이시 담당 이 홀로멘의 에일 1장을 자신의 #ReGLOSS를 가진 백 홀로멘으로 갈아붙일 수 있다. คาเซย #DEV_IS #ReGLOSS #ศิลปะ ผมเท่ใช่ไหมล่ะ? สายบอยอิชของ ReGLOSS คุณสามารถย้ายเอิล 1 ใบของโฮโลเมนนี้ไปติดกับแบ็กโฮโลเมนของคุณที่มี #ReGLOSS ได้ Kasei #DEV_IS #ReGLOSS #Art ¿A que estoy genial? La parte más tomboy de ReGLOSS Puedes mover 1 Cheer de este holomen a un holomen de Reserva tuyo que tenga #ReGLOSS.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('613', 'hBP03-049', 'buzzCharacter', 'R', 'first', 'hBP03/hBP03-049_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-049_R.png', 230, NULL, 2, '["null","null"]', 'Qiu', '火威青', '{"arts":[{"cost_types":["blue","null","null"],"damage":50}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["blue"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"Deal 10 special damage to either 1 of your opponent''s center holomems or 1 of your opponent''s back holomems for each of your back holomems with #ReGLOSS that has a different card name.","name":"Leave It to the Handsome One"}],"keyword":{"effect":"Reveal 1 Cheer from your Cheer Deck that is the same color as your Center holomem with #ReGLOSS, and send it to one of your holomems with #ReGLOSS. Then shuffle your Cheer Deck.","name":"You troublesome princesses"},"name":"Kasei","tags":["#DEV_IS","#ReGLOSS","#Art"]},"es":{"arts":[{"effect":"Inflige 10 de daño especial al holomen Central o a 1 holomen de la Retaguardia del oponente por cada 1 de tus holomen de la Retaguardia con #ReGLOSS y con nombre de carta diferente.","name":"Déjalo en manos del guapo"}],"keyword":{"effect":"Revela 1 Cheer de tu mazo de Cheer del mismo color que tu holomen central con #ReGLOSS, y envíalo a uno de tus holomen con #ReGLOSS. Después, baraja el mazo de Cheer.","name":"Qué princesitas tan problemáticas"},"name":"Kasei","tags":["#DEV_IS","#ReGLOSS","#Art"]},"id":{"arts":[{"effect":"Berikan 10 damage spesial kepada salah satu dari 1 Pusat holomen atau 1 Back holomen lawan, untuk tiap 1 Back holomen milikmu yang memiliki #ReGLOSS dengan nama kartu berbeda.","name":"Serahkan pada si ganteng"}],"keyword":{"effect":"Dari Cheer Deck milikmu, buka 1 Cheer dengan warna yang sama dengan Center Holomen milikmu yang memiliki #ReGLOSS, lalu kirimkan ke holomen milikmu yang memiliki #ReGLOSS. Lalu kocok Cheer Deck.","name":"Putri-putri yang merepotkan ya"},"name":"Kasei","tags":["#DEV_IS","#ReGLOSS","#Seni"]},"ja":{"arts":[{"effect":"相手のセンターホロメンかバックホロメン1人どちらかに、自分の異なるカード名の#ReGLOSSを持つバックホロメン1人につき、特殊ダメージ10を与える。","name":"イケメンにお任せを"}],"keyword":{"effect":"自分のエールデッキから、自分の#ReGLOSSを持つセンターホロメンと同色のエール1枚を公開し、自分の#ReGLOSSを持つホロメンに送る。そしてエールデッキをシャッフルする。","name":"困ったお姫様たちだね"},"name":"火威青","tags":["#DEV_IS","#ReGLOSS","#絵"]},"ko":{"arts":[{"effect":"상대의 센터 홀로멘 또는 백 홀로멘 1명 중 하나에게, 자신의 서로 다른 카드명의 #ReGLOSS를 가진 백 홀로멘 1명당 특수 대미지 10을 준다.","name":"훈남에게 맡겨줘"}],"keyword":{"effect":"자신의 에일 덱에서 자신의 #ReGLOSS를 가진 센터 홀로멘과 같은 색의 에일 1장을 공개하고, 자신의 #ReGLOSS를 가진 홀로멘에게 보낸다. 그리고 에일 덱을 셔플한다.","name":"곤란한 공주님들이네"},"name":"카세이","tags":["#DEV_IS","#ReGLOSS","#그림"]},"tc":{"arts":[{"effect":"對對手的Center holomen或Back holomen其中1人，依自己每有1名持有不同卡名的#ReGLOSS的Back holomen，給予特殊傷害10。","name":"交給帥哥吧"}],"keyword":{"effect":"從自己的Cheers牌庫公開1張與自己持有#ReGLOSS的中心holomen同色的Cheers，送給自己持有#ReGLOSS的holomen。然後將Cheers牌庫洗牌。","name":"真是一群讓人傷腦筋的公主呢"},"name":"火威青","tags":["#DEV_IS","#ReGLOSS","#繪畫"]},"th":{"arts":[{"effect":"สร้างดาเมจพิเศษ 10 ให้เซ็นเตอร์โฮโลเมนหรือแบ็กโฮโลเมนของคู่ต่อสู้ 1 คนใดคนหนึ่ง ต่อแบ็กโฮโลเมน 1 คนของคุณที่มี #ReGLOSS ซึ่งมีชื่อการ์ดแตกต่างกัน","name":"ปล่อยให้หนุ่มหล่อคนนี้จัดการเอง"}],"keyword":{"effect":"เปิดเยล 1 ใบจากเด็คเยลของคุณที่มีสีเดียวกับเซ็นเตอร์โฮโลเมนของคุณที่มี #ReGLOSS แล้วส่งไปยังโฮโลเมนของคุณที่มี #ReGLOSS จากนั้นสับเด็คเยล","name":"เป็นเจ้าหญิงที่น่าปวดหัวกันจริงนะ"},"name":"คาเซย","tags":["#DEV_IS","#ReGLOSS","#ศิลปะ"]}}}', '{}', '7297fbc2b9c6b6e7502881ef3f6b3197606b51237caf441f316c1ef38bcbaa08', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
