INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (615, 'hBP03-051', 'hBP03-051 JP 4期生 歌 シューター 常闇トワ #JP #4期生 #歌 #シューター こんやっぴー Tokoyami Towa #JP #4th Gen #Singing #Shooter Konyappi~ 常闇永遠 #JP #4期生 #歌唱 #射手 空夜皮～ Tokoyami Towa #JP #Gen 4 #Menyanyi #Penembak Kon''yappi 토코야미 토와 #JP #4기생 #노래 #슈터 콘얏삐 โทโคยามิ โทวะ #JP #รุ่น 4 #เพลง #ชูตเตอร์ คงยัปปี้~ Tokoyami Towa #JP #4th Gen #Singing #Shooter Kon''yappi~', '');
