INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (617, 'hBP03-053', 'hBP03-053 Guchico JP 4期生 歌 シューター 常闇トワ #JP #4期生 #歌 #シューター おつやっぴー きゅりん Tokoyami Towa #JP #4th Gen #Singing #Shooter Otsuyappi Kyurin 常闇永遠 #JP #4期生 #歌唱 #射手 Otsuyappi 啾鈴 Tokoyami Towa #JP #Gen 4 #Menyanyi #Penembak Otsuyappi Kyurin 토코야미 토와 #JP #4기생 #노래 #슈터 오츠얍피 큐룽 โทโคยามิ โทวะ #JP #รุ่น 4 #เพลง #ชูตเตอร์ โอตสึยัปปี้ คิวริน Tokoyami Towa #JP #4th Gen #Singing #Shooter ¡Otsuyappi! Kyurin', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('618', 'hBP03-054', 'character', 'U', 'first', 'hBP03/hBP03-054_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-054_U.png', 140, NULL, 1, '["null"]', NULL, '常闇トワ', '{"arts":[{"cost_types":["null"],"damage":30}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["purple"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"effect":"You may archive 4 Purple Cheer from this holomem: Return 1 Cheer on the opponent''s Stage to the bottom of their Cheer Deck.","name":"I''m gonna blow it sky-high!"}],"keyword":{"effect":"Deal 20 special damage to your opponent''s Center holomem or Collab holomem.","name":"A Color Only Towa Can Bring Out"},"name":"Tokoyami Towa","tags":["#JP","#4th Gen","#Singing","#Shooter"]},"es":{"arts":[{"effect":"Puedes poner en el Archivo 4 cartas de Purple Cheer de este holomem: devuelve 1 Cheer del Escenario del oponente al fondo de su Mazo de Cheer.","name":"¡Lo haré explotar por los aires!"}],"keyword":{"effect":"Inflige 20 de daño especial al holomen central o al holomen de Colaboración de tu oponente.","name":"Un color que solo Towa puede dar"},"name":"Tokoyami Towa","tags":["#JP","#4th Gen","#Singing","#Shooter"]},"id":{"arts":[{"effect":"Kamu boleh mengarsipkan 4 kartu Yell Ungu dari holomen ini: kembalikan 1 Cheer di Stage lawan ke bawah Cheer Deck.","name":"Akan kubikin meledak besar!"}],"keyword":{"effect":"Berikan 20 damage spesial kepada Center holomen atau Kolab holomen lawan.","name":"Warna yang hanya bisa dikeluarkan oleh Towa"},"name":"Tokoyami Towa","tags":["#JP","#Gen 4","#Menyanyi","#Penembak"]},"ja":{"arts":[{"effect":"このホロメンの紫エール4枚をアーカイブできる:相手のステージのエール1枚をエールデッキの下に戻す。","name":"大爆発させちゃうぜ！"}],"keyword":{"effect":"相手のセンターホロメンかコラボホロメンに特殊ダメージ20を与える。","name":"トワにしか出せない色"},"name":"常闇トワ","tags":["#JP","#4期生","#歌","#シューター"]},"ko":{"arts":[{"effect":"이 홀로멘의 퍼플 옐 4장을 아카이브할 수 있다: 상대의 스테이지의 에일 1장을 에일 덱 아래로 되돌린다.","name":"대폭발시켜 버리겠어!"}],"keyword":{"effect":"상대의 센터 홀로멘 또는 콜라보 홀로멘에게 특수 대미지 20을 준다.","name":"토와만이 낼 수 있는 색"},"name":"토코야미 토와","tags":["#JP","#4기생","#노래","#슈터"]},"tc":{"arts":[{"effect":"可以將這位Holo成員的紫色應援4張放入存檔區：將對手舞台上的1張應援放回應援牌庫底。","name":"讓它大爆炸吧！"}],"keyword":{"effect":"對對手的中心Holomen或合作Holomen造成特殊傷害20。","name":"只有永遠才能展現的色彩"},"name":"常闇永遠","tags":["#JP","#4期生","#歌唱","#射手"]},"th":{"arts":[{"effect":"สามารถส่ง เยลสีม่วง 4 ใบของโฮโลเมนนี้เข้าอาร์ไคฟ์ได้: นำพลังงาน 1 ใบบนสเตจของฝ่ายตรงข้ามกลับไปไว้ใต้เด็คพลังงาน","name":"จะระเบิดให้ตูมเลยล่ะ!"}],"keyword":{"effect":"สร้างความเสียหายพิเศษ 20 ให้แก่เซ็นเตอร์โฮโลเมนหรือคอลแลบโฮโลเมนของฝ่ายตรงข้าม","name":"สีที่มีเพียง โทวะ เท่านั้นที่ปล่อยออกมาได้"},"name":"โทโคยามิ โทวะ","tags":["#JP","#รุ่น 4","#เพลง","#ชูตเตอร์"]}}}', '{}', 'eb7bc4939037f27b49c526dcaed9f81b7b2991c34aa7b56b94a35e357e5252ca', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
