INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (625, 'hBP03-061', 'hBP03-061 JP ゲーマーズ ケモミミ 戌神ころね #JP #ゲーマーズ #ケモミミ ぉぁよ～ ゆびゆび～ Inugami Korone #JP #Gamers #Animal Ears G''mornin~ FingerFinger~ 戌神沁音 #JP #Gamers #獸耳 喔啊唷～ 手指手指～ Inugami Korone #JP #Gamers #Telinga Hewan Pagiii～ JariJari～ 이누가미 코로네 #JP #게이머즈 #수인귀 오아요~ 손가락손가락~ อินุกามิ โคโรเนะ #JP #เกมเมอร์ส #หูสัตว์ โอ๊ะโย~ นิ้วนิ้ว~ Inugami Korone #JP #Gamers #Animal Ears Bueeenas～ DedoDedo~', '');
