INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (628, 'hBP03-064', 'hBP03-064 JP ゲーマーズ ケモミミ 戌神ころね #JP #ゲーマーズ #ケモミミ ぶるぁあああああ!!!!!!!!!!!!!! 自分の初期ライフから減っているライフ1につき、このアーツ+10。 おーしぇーい Inugami Korone #JP #Gamers #Animal Ears Buraaaaaaaah!!!!!!!!!!!!!! This Art gets +10 for each Life you have lost from your starting Life. O-shay! 戌神沁音 #JP #Gamers #獸耳 嗚啦啊啊啊啊啊!!!!!!!!!!!!!! 自己每有1點比初始生命值減少的生命值，此藝術+10。 喔謝— Inugami Korone #JP #Gamers #Telinga Hewan Buruaaaaaaah!!!!!!!!!!!!!! Untuk setiap 1 Life yang berkurang dari Life awalmu, Arts ini +10. O-shei 이누가미 코로네 #JP #게이머즈 #수인귀 브루아아아아아!!!!!!!!!!!!!! 자신의 초기 라이프에서 줄어든 라이프 1당, 이 아츠+10. 오ー셰ー이 อินุกามิ โคโรเนะ #JP #เกมเมอร์ส #หูสัตว์ บุรัวววววววว!!!!!!!!!!!!!! ศิลปะนี้ +10 ต่อไลฟ์ 1 ที่ลดลงจากไลฟ์เริ่มต้นของคุณ โอเช~ Inugami Korone #JP #Gamers #Animal Ears ¡¡¡¡¡¡¡¡¡¡¡¡Buruáááááááá!!!!!!!!!!!!!! Este Arte obtiene +10 por cada 1 de Vida que te falte respecto a tu Vida inicial. ¡Ooosheeei!', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('629', 'hBP03-065', 'character', 'R', 'first', 'hBP03/hBP03-065_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-065_R.png', 150, NULL, 2, '["null","null"]', 'フカヒレ', '戌神ころね', '{"arts":[{"cost_types":["null","null"],"damage":30}],"card_sets":["ブースターパック「エリートスパーク」","【使用可能カード】hGS 2026 大阪 セレクションロード"],"color_codes":["yellow"],"keyword":{"type":"ギフト","type_code":"gift"},"translations":{"en":{"arts":[{"effect":"Send the top card of your Cheer Deck to your holomem with #Gamers.","name":"Here Ya Go~"}],"keyword":{"effect":"[Collab Position Only] During your opponent''s Main Step, the HP of your Center holomem 〈Inugami Korone〉 cannot be reduced or changed by your opponent''s abilities.","name":"Boxing Style"},"name":"Inugami Korone","tags":["#JP","#Gamers","#Animal Ears"]},"es":{"arts":[{"effect":"Envía la carta superior de tu Mazo de Cheer a un holomem tuyo con #Gamers.","name":"Toma~"}],"keyword":{"effect":"[Solo en la posición de Colaboración] Durante el Main Step de tu oponente, el HP de tu 〈Inugami Korone〉 holomen central no se reduce ni cambia por habilidades de tu oponente.","name":"Estilo boxeo"},"name":"Inugami Korone","tags":["#JP","#Gamers","#Animal Ears"]},"id":{"arts":[{"effect":"Kirim 1 kartu teratas dari Cheer Deck milikmu kepada holomen milikmu yang memiliki #Gamers.","name":"Nih～"}],"keyword":{"effect":"[Hanya Posisi Kolaborasi] Selama Main Step lawan, HP 〈Inugami Korone〉 milik Center holomenmu tidak berkurang oleh kemampuan lawan dan tidak berubah.","name":"Gaya tinju"},"name":"Inugami Korone","tags":["#JP","#Gamers","#Telinga Hewan"]},"ja":{"arts":[{"effect":"自分のエールデッキの上から1枚を、自分の#ゲーマーズを持つホロメンに送る。","name":"ほらよ～"}],"keyword":{"effect":"[コラボポジション限定]相手のメインステップの間、自分のセンターホロメンの〈戌神ころね〉のHPは相手の能力で減らず、変動しない。","name":"ボクシングスタイル"},"name":"戌神ころね","tags":["#JP","#ゲーマーズ","#ケモミミ"]},"ko":{"arts":[{"effect":"자신의 에일 덱 맨 위에서 1장을 자신의 #게이머즈를 가진 홀로멘에게 보낸다.","name":"자 받아~"}],"keyword":{"effect":"[콜라보 포지션 한정] 상대의 메인 스텝 동안, 자신의 센터 홀로멤의 〈이누가미 코로네〉의 HP는 상대의 능력으로 줄어들지 않으며, 변동하지 않는다.","name":"복싱 스타일"},"name":"이누가미 코로네","tags":["#JP","#게이머즈","#수인귀"]},"tc":{"arts":[{"effect":"將自己應援牌庫頂的1張卡附加到自己持有#Gamers的Holo成員上。","name":"拿去啦～"}],"keyword":{"effect":"[限聯動位置]在對手的主要階段中，自己中衛Holo成員的〈戌神沁音〉的HP不會因對手的能力而減少，也不會變動。","name":"拳擊風格"},"name":"戌神沁音","tags":["#JP","#Gamers","#獸耳"]},"th":{"arts":[{"effect":"ส่งการ์ดใบบนสุดจากเด็คพลังงานของคุณไปให้โฮโลเมนของคุณที่มี #เกมเมอร์ส","name":"นี่ไง~"}],"keyword":{"effect":"[เฉพาะตำแหน่งคอลแลบ] ระหว่างเมนสเต็ปของคู่ต่อสู้ HP ของ 〈อินุกามิ โคโรเนะ〉 เซ็นเตอร์โฮโลเม็มของตนเองจะไม่ลดลงและไม่เปลี่ยนแปลงจากความสามารถของคู่ต่อสู้","name":"สไตล์มวย"},"name":"อินุกามิ โคโรเนะ","tags":["#JP","#เกมเมอร์ส","#หูสัตว์"]}}}', '{}', 'cc968d9334862ba4bfe25a88ac24329247d37cb3d886c5a8d971a07ec6caa99d', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
