INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (631, 'hBP03-067', 'hBP03-067 JP 4期生 ケモミミ 歌 角巻わため #JP #4期生 #ケモミミ #歌 こんばんドドド～！ Tsunomaki Watame #JP #4th Gen #Animal Ears #Singing Good evenin'' d-d-dodo~! 角卷綿芽 #JP #4期生 #獸耳 #歌唱 晚安哆哆哆～！ Tsunomaki Watame #JP #Gen 4 #Telinga Hewan #Menyanyi Konban dododo～! 츠노마키 와타메 #JP #4기생 #수인귀 #노래 굿밤도도도~! ซึโนมากิ วาตาเมะ #JP #รุ่น 4 #หูสัตว์ #เพลง คมบังโดโดโด~! Tsunomaki Watame #JP #4th Gen #Animal Ears #Singing ¡Buenas nochesss dododó～!', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('632', 'hBP03-068', 'character', 'U', 'debut', 'hBP03/hBP03-068_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-068_U.png', 90, NULL, 1, '["null"]', 'ふーみ', '角巻わため', '{"arts":[{"cost_types":["yellow"],"damage":20}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["yellow"],"translations":{"en":{"arts":[{"effect":"If you have a holomem with your 〈Watamate〉 attached, you may send 1 Cheer from your Archive to your Yellow holomem.","name":"Watame’s Song"}],"name":"Tsunomaki Watame","tags":["#JP","#4th Gen","#Animal Ears","#Singing"]},"es":{"arts":[{"effect":"Si tienes un holomen con 〈Watamate〉 equipado, puedes enviar 1 Cheer de tu archivo a uno de tus holomen amarillos.","name":"La canción de Watame"}],"name":"Tsunomaki Watame","tags":["#JP","#4th Gen","#Animal Ears","#Singing"]},"id":{"arts":[{"effect":"Saat kamu memiliki holomen yang dipasangi 〈Watamate〉, kamu boleh mengirim 1 Cheer dari Archive-mu ke holomen Kuning milikmu.","name":"Lagu Watame"}],"name":"Tsunomaki Watame","tags":["#JP","#Gen 4","#Telinga Hewan","#Menyanyi"]},"ja":{"arts":[{"effect":"自分の〈わためいと〉が付いているホロメンがいる時、自分のアーカイブのエール1枚を自分の黄ホロメンに送れる。","name":"わためのうた"}],"name":"角巻わため","tags":["#JP","#4期生","#ケモミミ","#歌"]},"ko":{"arts":[{"effect":"자신의 〈와타메이트〉가 붙어 있는 홀로멘이 있을 때, 자신의 아카이브의 에일 1장을 자신의 황 홀로멘에게 보낼 수 있다.","name":"와타메의 노래"}],"name":"츠노마키 와타메","tags":["#JP","#4기생","#수인귀","#노래"]},"tc":{"arts":[{"effect":"當自己有附著〈WataMate〉的Holo成員時，可將自己存檔區的1張應援送給自己的黃色Holo成員。","name":"Watame之歌"}],"name":"角卷綿芽","tags":["#JP","#4期生","#獸耳","#歌唱"]},"th":{"arts":[{"effect":"เมื่อคุณมีโฮโลเมนที่ติด 〈วาตะเมะโตะ〉 อยู่ คุณสามารถส่งเอิล 1 ใบจากอาร์ไคฟ์ของคุณไปยังโฮโลเมนสีเหลืองของคุณได้","name":"เพลงของวาตาเมะ"}],"name":"ซึโนมากิ วาตาเมะ","tags":["#JP","#รุ่น 4","#หูสัตว์","#เพลง"]}}}', '{}', '96f82afb23fc0789833b4ecaa3530418791bf86fbc27b98aa32d9ae27d1abd10', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
