INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (632, 'hBP03-068', 'hBP03-068 ふーみ JP 4期生 ケモミミ 歌 角巻わため #JP #4期生 #ケモミミ #歌 わためのうた 自分の〈わためいと〉が付いているホロメンがいる時、自分のアーカイブのエール1枚を自分の黄ホロメンに送れる。 Tsunomaki Watame #JP #4th Gen #Animal Ears #Singing Watame’s Song If you have a holomem with your 〈Watamate〉 attached, you may send 1 Cheer from your Archive to your Yellow holomem. 角卷綿芽 #JP #4期生 #獸耳 #歌唱 Watame之歌 當自己有附著〈WataMate〉的Holo成員時，可將自己存檔區的1張應援送給自己的黃色Holo成員。 Tsunomaki Watame #JP #Gen 4 #Telinga Hewan #Menyanyi Lagu Watame Saat kamu memiliki holomen yang dipasangi 〈Watamate〉, kamu boleh mengirim 1 Cheer dari Archive-mu ke holomen Kuning milikmu. 츠노마키 와타메 #JP #4기생 #수인귀 #노래 와타메의 노래 자신의 〈와타메이트〉가 붙어 있는 홀로멘이 있을 때, 자신의 아카이브의 에일 1장을 자신의 황 홀로멘에게 보낼 수 있다. ซึโนมากิ วาตาเมะ #JP #รุ่น 4 #หูสัตว์ #เพลง เพลงของวาตาเมะ เมื่อคุณมีโฮโลเมนที่ติด 〈วาตะเมะโตะ〉 อยู่ คุณสามารถส่งเอิล 1 ใบจากอาร์ไคฟ์ของคุณไปยังโฮโลเมนสีเหลืองของคุณได้ Tsunomaki Watame #JP #4th Gen #Animal Ears #Singing La canción de Watame Si tienes un holomen con 〈Watamate〉 equipado, puedes enviar 1 Cheer de tu archivo a uno de tus holomen amarillos.', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('633', 'hBP03-069', 'character', 'C', 'first', 'hBP03/hBP03-069_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-069_C.png', 190, NULL, 2, '["null","null"]', 'ふーみ', '角巻わため', '{"arts":[{"cost_types":["yellow"],"damage":30},{"cost_types":["null","null","null"],"damage":90}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["yellow"],"translations":{"en":{"arts":[{"name":"A Healing Moment"},{"name":"You’ll Cheer for Me, Right~?"}],"name":"Tsunomaki Watame","tags":["#JP","#4th Gen","#Animal Ears","#Singing"]},"es":{"arts":[{"name":"Un momento reconfortante"},{"name":"Me vas a apoyar, ¿verdad?"}],"name":"Tsunomaki Watame","tags":["#JP","#4th Gen","#Animal Ears","#Singing"]},"id":{"arts":[{"name":"Sejenak yang Menenangkan"},{"name":"Kamu bakal dukung aku, kan?"}],"name":"Tsunomaki Watame","tags":["#JP","#Gen 4","#Telinga Hewan","#Menyanyi"]},"ja":{"arts":[{"name":"癒しのひととき"},{"name":"応援してくれるよねぇ？"}],"name":"角巻わため","tags":["#JP","#4期生","#ケモミミ","#歌"]},"ko":{"arts":[{"name":"치유의 한때"},{"name":"응원해줄 거지이?"}],"name":"츠노마키 와타메","tags":["#JP","#4기생","#수인귀","#노래"]},"tc":{"arts":[{"name":"療癒片刻"},{"name":"你會為我應援的吧？"}],"name":"角卷綿芽","tags":["#JP","#4期生","#獸耳","#歌唱"]},"th":{"arts":[{"name":"ช่วงเวลาแห่งการเยียวยา"},{"name":"จะคอยเชียร์กันใช่ไหม~?"}],"name":"ซึโนมากิ วาตาเมะ","tags":["#JP","#รุ่น 4","#หูสัตว์","#เพลง"]}}}', '{}', '191ded9db303aee2aedc491fd151b16b73d3d765e0ef169e0c3eeb79214626c5', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
