INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (639, 'hBP03-075', 'hBP03-075 やとみ ID ID1期生 ケモミミ 歌 アユンダ・リス #ID #ID1期生 #ケモミミ #歌 おつリスー おやすみの思い出 Ayunda Risu #ID #ID 1st Gen #Animal Ears #Singing Otsurisu~ Goodnight Memories 阿悠妲・莉絲 #ID #ID1期生 #獸耳 #歌唱 Otsurisu 晚安的回憶 Ayunda Risu #ID #ID Gen 1 #Telinga Hewan #Menyanyi Otsurisuu Kenangan sebelum tidur 아윤다 리스 #ID #ID 1기생 #수인귀 #노래 오츠리스ー 잘 자의 추억 อายุนดา ริสุ #ID #ID รุ่น 1 #หูสัตว์ #เพลง โอตสึริสึ~ ความทรงจำก่อนนิทรา Ayunda Risu #ID #ID 1st Gen #Animal Ears #Singing ¡Otsurisu~! Recuerdos de buenas noches', '');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('640', 'hBP03-076', 'character', 'U', 'first', 'hBP03/hBP03-076_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-076_U.png', 150, NULL, 2, '["null","null"]', NULL, 'アユンダ・リス', '{"arts":[{"cost_types":["null"],"damage":20}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["yellow"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"name":"Shaky-shaky, OtsuRisu!!!"}],"keyword":{"effect":"Reveal 1 [Green Cheer or Yellow Cheer] from your Cheer Deck and send it to your holomem. Then shuffle your Cheer Deck.","name":"Yahhoo! How''s everyone doing?"},"name":"Ayunda Risu","tags":["#ID","#ID 1st Gen","#Animal Ears","#Singing"]},"es":{"arts":[{"name":"Tembleque, otsuRisu!!!"}],"keyword":{"effect":"Revela 1 [Green Cheer o Yellow Cheer] de tu mazo de Cheer y envíalo a uno de tus holomen. Después, baraja el mazo de Cheer.","name":"¡Yujuu! ¿Todos están bien?"},"name":"Ayunda Risu","tags":["#ID","#ID 1st Gen","#Animal Ears","#Singing"]},"id":{"arts":[{"name":"Purupuru, otsuRisu!!!"}],"keyword":{"effect":"Dari Cheer Deck milikmu, buka 1 kartu [Yell Hijau atau Yell Kuning] dan kirimkan ke holomen milikmu. Lalu kocok Cheer Deck.","name":"Yaho! Kalian semua sehat?"},"name":"Ayunda Risu","tags":["#ID","#ID Gen 1","#Telinga Hewan","#Menyanyi"]},"ja":{"arts":[{"name":"ぷるぷる、おつリス！！！"}],"keyword":{"effect":"自分のエールデッキから、[緑エールか黄エール]1枚を公開し、自分のホロメンに送る。そしてエールデッキをシャッフルする。","name":"いやっほー！ みんな元気？"},"name":"アユンダ・リス","tags":["#ID","#ID1期生","#ケモミミ","#歌"]},"ko":{"arts":[{"name":"부들부들, 오츠리스!!!"}],"keyword":{"effect":"자신의 에일 덱에서, [그린 옐か옐로우 옐] 1장을 공개하고, 자신의 홀로멘에게 보낸다. 그리고 에일 덱을 셔플한다.","name":"이얏호~! 다들 잘 지내?"},"name":"아윤다 리스","tags":["#ID","#ID 1기생","#수인귀","#노래"]},"tc":{"arts":[{"name":"抖抖的，辛苦莉絲啦！！！"}],"keyword":{"effect":"從自己的Cheers牌庫公開1張[綠色應援或黃色應援]，送給自己的holomen。然後將Cheers牌庫洗牌。","name":"呀呼—！大家有精神嗎？"},"name":"阿悠妲・莉絲","tags":["#ID","#ID1期生","#獸耳","#歌唱"]},"th":{"arts":[{"name":"ปุรุปุรุ โอสึริสุ!!!"}],"keyword":{"effect":"เปิด [เยลสีเขียวかเยลสีเหลือง] 1 ใบจากเด็คเยลของคุณ แล้วส่งไปยังโฮโลเมนของคุณ จากนั้นสับเด็คเยล","name":"ยาฮู้ー! ทุกคนสบายดีกันไหม?"},"name":"อายุนดา ริสุ","tags":["#ID","#ID รุ่น 1","#หูสัตว์","#เพลง"]}}}', '{}', '8d95bb94e1f01812bb3fd09e851b9343914f48fb2e108ba2337f062bb9382e60', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
