INSERT INTO cards_fts (rowid, card_number, text, qa) VALUES (642, 'hBP03-078', 'hBP03-078 ねづみどし ID ID1期生 ケモミミ 歌 アユンダ・リス #ID #ID1期生 #ケモミミ #歌 魔法の森のリスの女の子 ■このホロメンに緑エールが付いている時、このアーツ+50。
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('643', 'hBP03-079', 'buzzCharacter', 'RR', 'first', 'hBP03/hBP03-079_RR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-079_RR.png', 240, NULL, 2, '["null","null"]', '紅緒', '不知火フレア', '{"arts":[{"cost_types":["yellow","null"],"damage":50,"is_plus":true}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["yellow"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"When this holomem has 3 or more Cheer attached, this Art gets +30.","name":"Sunrise Ale"}],"keyword":{"effect":"Reveal 1 Yellow Cheer from your Cheer Deck and send it to this holomem. Then shuffle your Cheer Deck.","name":"Today Is a Wonderful Day"},"name":"Shiranui Flare","tags":["#JP","#3rd Gen","#Half-Elf"]},"es":{"arts":[{"effect":"Si este holomem tiene 3 o más Cheer unidos, este Arte +30.","name":"Alegría del amanecer"}],"keyword":{"effect":"Revela 1 Yellow Cheer de tu mazo de Cheer y envíalo a este holomen. Después, baraja tu mazo de Cheer.","name":"Hoy es un día maravilloso"},"name":"Shiranui Flare","tags":["#JP","#3rd Gen","#Half-Elf"]},"id":{"arts":[{"effect":"Saat holomen ini terpasang 3 atau lebih Cheer, Arts ini +30.","name":"Sunrise Yell"}],"keyword":{"effect":"Ungkapkan 1 kartu Yell Kuning dari Cheer Deck-mu, kirim ke holomen ini. Lalu, kocok Cheer Deck-mu.","name":"Hari ini hari yang indah"},"name":"Shiranui Flare","tags":["#JP","#Gen 3","#Setengah Elf"]},"ja":{"arts":[{"effect":"このホロメンにエールが3枚以上付いている時、このアーツ+30。","name":"サンライズエール"}],"keyword":{"effect":"自分のエールデッキから、黄エール1枚を公開し、このホロメンに送る。そしてエールデッキをシャッフルする。","name":"今日はステキな日"},"name":"不知火フレア","tags":["#JP","#3期生","#ハーフエルフ"]},"ko":{"arts":[{"effect":"이 홀로멘에 에일이 3장 이상 붙어 있을 때, 이 아츠 +30.","name":"선라이즈 에일"}],"keyword":{"effect":"자신의 에일 덱에서 옐로우 옐 1장을 공개하고, 이 홀로멤에게 보낸다. 그리고 에일 덱을 셔플한다.","name":"오늘은 멋진 날"},"name":"시라누이 플레어","tags":["#JP","#3기생","#하프엘프"]},"tc":{"arts":[{"effect":"當這位Holo成員附有3張以上應援時，此藝術+30。","name":"Sunrise Ale"}],"keyword":{"effect":"從自己的應援牌庫公開1張黃色應援，送給此Holo成員。然後將應援牌庫洗牌。","name":"今天是美好的一天"},"name":"不知火芙蕾雅","tags":["#JP","#3期生","#半精靈"]},"th":{"arts":[{"effect":"เมื่อโฮโลเมนนี้มีพลังงานติดอยู่ตั้งแต่ 3 ใบขึ้นไป ศิลปะนี้ +30","name":"ซันไรส์เยล"}],"keyword":{"effect":"เปิดเผย เยลสีเหลือง 1 ใบจากเยลเด็คของตนเอง แล้วส่งไปยังโฮโลเม็มนี้ จากนั้นสับเยลเด็ค","name":"วันนี้เป็นวันที่แสนวิเศษ"},"name":"ชิรานุย เฟลร์","tags":["#JP","#รุ่น 3","#ฮาล์ฟเยลฟ์"]}}}', '{}', '5b09f245eae32bc79ef8266e942ae3417ba1f241b7545b958d37a0c459d9009c', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
